// Suppress html2canvas "willReadFrequently" warning by patching getContext
(function () {
  const _orig = HTMLCanvasElement.prototype.getContext;
  HTMLCanvasElement.prototype.getContext = function (type, attrs) {
    if (type === '2d') attrs = Object.assign({ willReadFrequently: true }, attrs);
    return _orig.call(this, type, attrs);
  };
})();


let allPlays = [];
let currentPeriod = 'week';
let currentOffset = 0;
let weekStartDay = 0; // 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat

// Chart type toggle — Songs/Artists/Albums charts are split, only one renders at a time
let chartTypeView = (() => {
  try { return localStorage.getItem('dc_chart_type_view') || 'songs'; } catch (e) { return 'songs'; }
})();

function setChartTypeView(type) {
  if (chartTypeView === type) return;
  chartTypeView = type;
  try { localStorage.setItem('dc_chart_type_view', type); } catch (e) {}
  applyChartTypeView();
  // The "Inside your Top N" stats follow the chart on screen (insights.js)
  if (typeof atiRender === 'function') atiRender();
  // The All-Time banner's collage follows the chart on screen too
  if (currentPeriod === 'alltime' && typeof shRenderMosaic === 'function') shRenderMosaic();
}

function applyChartTypeView() {
  document.getElementById('songsChartGroup').style.display   = chartTypeView === 'songs'   ? '' : 'none';
  document.getElementById('artistsChartGroup').style.display = chartTypeView === 'artists' ? '' : 'none';
  document.getElementById('albumsChartGroup').style.display  = chartTypeView === 'albums'  ? '' : 'none';
  document.querySelectorAll('#chartTypeToggleBar .chart-type-toggle-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.type === chartTypeView);
  });
  // The album bucket filter shares the toolbar and only applies to the albums chart
  syncAlbumsFilterBar();
  // So do the layout buttons, which show the layout of the chart on screen
  syncChartLayoutBar();
  // A table drawn while hidden couldn't size its custom columns; it can now
  if (typeof _colwApply === 'function') _colwApply(chartTypeView);
  // Daily tab: the #1 line above the chart is about the chart on screen
  if (currentPeriod === 'day' && typeof dyRenderTop === 'function' && allPlays && allPlays.length) dyRenderTop(dyHistory(), dyViewedDay());
}

// ─── SUB-CHART TOGGLES (Normal / Bubbling Under / Off the Chart / New Entries) ──
// Each chart type (songs/artists/albums) has its own independent set of toggles —
// unlike the exclusive Songs/Artists/Albums toggle above, any combination of these
// four sub-charts can be active at once. They are the "Sections" rows at the end of
// each chart's ⋮ → Show (#subChartRows-<type>); until phase 6 they were a row of
// pills above the chart. Synced to the user's Firestore account via
// dc_subChartToggles (see SYNC_KEYS in firebase.js) so the choice follows them across devices.
const SUB_CHART_SECTION_IDS = {
  normal: { songs: 'songsSection',   artists: 'artistsSection',   albums: 'albumsSection' },
  bu:     { songs: 'buSongsSection', artists: 'buArtistsSection', albums: 'buAlbumsSection' },
  off:    { songs: 'offSongsSection', artists: 'offArtistsSection', albums: 'offAlbumsSection' },
  new:    { songs: 'newSongsSection', artists: 'newArtistsSection', albums: 'newAlbumsSection' }
};

const subChartToggleState = (() => {
  function withDefaults(s) { return Object.assign({ normal: true, bu: true, off: true, new: true }, s || {}); }
  try {
    const saved = JSON.parse(localStorage.getItem('dc_subChartToggles') || 'null');
    if (saved) return { songs: withDefaults(saved.songs), artists: withDefaults(saved.artists), albums: withDefaults(saved.albums) };
  } catch (e) {}
  return { songs: withDefaults(), artists: withDefaults(), albums: withDefaults() };
})();

// Which sub-charts even exist for the current period — mirrors the gating already used
// by renderSongs/renderArtists/renderAlbums (Bubbling Under + Off the Chart: weekly only)
// and renderNewEntries (New Entries: week/month/year, never alltime). The Show row
// for a sub-chart that doesn't exist this period is hidden entirely rather than left
// clickable with no effect.
const SUB_CHART_PERIOD_AVAILABILITY = {
  normal: () => true,
  bu:     () => currentPeriod === 'week',
  off:    () => currentPeriod === 'week',
  new:    () => currentPeriod === 'day' || currentPeriod === 'week' || currentPeriod === 'month' || currentPeriod === 'year'
};

function updateSubChartToggleBarAvailability() {
  // All-Time keeps only the Chart row: there is nothing else to switch there,
  // but a chart switched off elsewhere must still be switchable back on.
  ['songs', 'artists', 'albums'].forEach(type => {
    document.querySelectorAll('#subChartRows-' + type + ' .kebab-check-row').forEach(row => {
      const check = SUB_CHART_PERIOD_AVAILABILITY[row.dataset.sub];
      row.style.display = (!check || check()) ? '' : 'none';
    });
  });
}

function initSubChartToggles() {
  ['songs', 'artists', 'albums'].forEach(type => {
    document.querySelectorAll('#subChartRows-' + type + ' .kebab-check-row').forEach(row => {
      row.classList.toggle('active', Boolean(subChartToggleState[type][row.dataset.sub]));
    });
  });
}

function toggleSubChart(type, sub) {
  const state = subChartToggleState[type];
  if (!state) return;
  state[sub] = !state[sub];
  const btn = document.querySelector(`#subChartRows-${type} .kebab-check-row[data-sub="${sub}"]`);
  if (btn) btn.classList.toggle('active', state[sub]);
  try { localStorage.setItem('dc_subChartToggles', JSON.stringify(subChartToggleState)); } catch (e) {}
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  applySubChartToggles();
}

// Final visibility pass — runs after all the data-driven render logic (renderSongs/
// renderArtists/renderAlbums/renderNewEntries) has already decided which sub-charts
// have data to show this period. A toggle being off adds a CSS class that force-hides
// the section with !important; a toggle being on just removes that class, revealing
// whatever the data-driven inline style already set — never touch .style.display
// directly here, or turning the toggle back on would have nothing to restore it to
// without a full re-render. The main chart is the exception: its header holds the
// ⋮ menu with these very switches, so switching it off hides everything but that
// header (sub-chart-rows-off) instead of the whole section.
function applySubChartToggles() {
  for (const sub of Object.keys(SUB_CHART_SECTION_IDS)) {
    const cls = sub === 'normal' ? 'sub-chart-rows-off' : 'sub-chart-toggled-off';
    for (const type of ['songs', 'artists', 'albums']) {
      const el = document.getElementById(SUB_CHART_SECTION_IDS[sub][type]);
      if (el) el.classList.toggle(cls, !subChartToggleState[type][sub]);
    }
  }
  // The "Around the chart" box shows a tab for each sub-chart left visible
  if (typeof atcSyncAll === 'function') atcSyncAll();
}

initSubChartToggles();

// ─── TIMEZONE SUPPORT ──────────────────────────────────────────
const BROWSER_TZ = Intl.DateTimeFormat().resolvedOptions().timeZone;
let userTimezone = (() => {
  try { return localStorage.getItem('dc_timezone') || BROWSER_TZ; } catch(e) { return BROWSER_TZ; }
})();
let _tzFmt = null;

// Converts a real Date to a "fake-local" Date whose getDay/getDate/etc. reflect userTimezone.
// When userTimezone === BROWSER_TZ, returns d unchanged (no-op path for performance).
function tzDate(d) {
  if (userTimezone === BROWSER_TZ) return d;
  try {
    if (!_tzFmt) _tzFmt = new Intl.DateTimeFormat('en', {
      timeZone: userTimezone,
      year: 'numeric', month: 'numeric', day: 'numeric',
      hour: 'numeric', minute: 'numeric', second: 'numeric',
      hour12: false
    });
    const parts = _tzFmt.formatToParts(d);
    const get = type => parseInt(parts.find(p => p.type === type)?.value || '0');
    return new Date(get('year'), get('month') - 1, get('day'), get('hour') % 24, get('minute'), get('second'));
  } catch (e) { return d; }
}

function tzNow() { return tzDate(new Date()); }

/* ─── PER-PLAY DERIVED KEY CACHE ───────────────────────────────────────────
   Every chart builder used to recompute the same handful of pure functions of
   a single play — songKey(), albumArtist(), playWeekKey(), tzDate() — inside
   its own full pass over allPlays. Profiling a 100k-play library showed one
   renderAll() making 2.5M tzDate() calls, 1.2M songKey() calls and 1.1M
   playWeekKey() calls, because ~17 builders each walk the whole history.

   So we compute them once per play and stash them on the play object:

     _sk  song key            title|||artist, lowercased
     _aa  album artist        the credit albums are grouped by
     _ak  album key           album|||albumArtist
     _td  timezone-adjusted   tzDate(p.date) — identical object when no custom tz
     _ds  day string          YYYY-MM-DD in the user's timezone
     _wk  week key            the week-start day string
     _mk  month key           YYYY-MM
     _yk  year key            YYYY

   STALENESS IS THE DANGER, not absence. These values depend on settings the
   user can change at runtime: _wk/_ds/_mk/_yk move with the week start day and
   the timezone, _aa/_ak move with the compilations list, and _sk moves when an
   autocorrect rule rewrites a title. A stamp left over from before such a
   change would silently produce wrong charts, which is far worse than slow ones.

   So each stamp carries the epoch it was written under (_se). Every reader
   compares it against the current epoch and falls back to computing the value
   the old way when they differ. Bump the epoch via dcInvalidatePlayStamps()
   and the worst possible outcome is the pre-optimisation speed — never a wrong
   number. Re-stamping the whole library costs ~50ms at 100k plays, so the two
   load choke points (finalizeLoad / refreshAfterPoll) simply always re-stamp. */
let _stampEpoch = 1;

/* Bumped by stampPlays(), i.e. exactly when the play data changes. Caches that
   are derived from the whole history (see _crGeneration) key off this so they
   rebuild on new data but survive mere navigation. */
let _playsVersion = 0;

// Call after anything that changes how a play's derived keys are computed:
// week start day, timezone, compilation list, autocorrect rules.
function dcInvalidatePlayStamps() {
  _stampEpoch++;
}
window.dcInvalidatePlayStamps = dcInvalidatePlayStamps;

/* Interning keeps memory flat. A 400k-play library has only ~3k distinct song
   keys and ~200 week keys, so handing every play a pointer to one shared string
   costs a rounding error where 400k separately-built strings would not. */
function _intern(map, s) {
  const hit = map.get(s);
  if (hit !== undefined) return hit;
  map.set(s, s);
  return s;
}

// Stamps every play with its derived keys under the current epoch.
function stampPlays(plays) {
  _playsVersion++;   // the play data just changed — retire history-wide caches
  if (!plays || !plays.length) return;
  const iSk = new Map(), iAa = new Map(), iAk = new Map();
  const iDs = new Map(), iWk = new Map(), iMk = new Map(), iYk = new Map();
  // Week/day/month/year keys are a pure function of the timestamp, and a big
  // library has far more plays than distinct instants-that-matter — memoise on
  // the raw timestamp so repeat dates skip the Date maths entirely.
  const byTs = new Map();
  /* "Single, then album" releases rename their single-side plays before the
     album key is built (see _rsApply). A library without one skips it all,
     apart from plays a since-removed split had renamed, which go back. */
  const rsIdx = _rsIndex();
  const rsStarts = rsIdx.byParent.size ? _rsStartDays(plays, rsIdx) : null;
  for (const p of plays) {
    if (rsStarts || p._rsTo !== undefined) _rsApply(p, rsIdx, rsStarts || new Map());
    p._sk = _intern(iSk, p.title.toLowerCase().trim() + '|||' + p.artist.toLowerCase().trim());
    const aa = _intern(iAa, _albumArtistRaw(p));
    p._aa = aa;
    p._ak = _intern(iAk, p.album + '|||' + aa);

    const ts = +p.date;
    let d = byTs.get(ts);
    if (d === undefined) {
      // tzDate, never tzDateOf: re-stamping an already-stamped play (after an
      // in-place edit moved its date) must recompute, not read the old stamp.
      const td = tzDate(p.date);
      const dow = td.getDay();
      const wkStart = new Date(td.getFullYear(), td.getMonth(), td.getDate() - ((dow - weekStartDay + 7) % 7));
      d = {
        td,
        // The tz-adjusted instant as a number. Period filters compare against
        // fake-local Date bounds; doing that numerically avoids both a call and
        // a valueOf coercion per play, and there is one such filter per render.
        tdms: +td,
        ds: _intern(iDs, localDateStr(td)),
        wk: _intern(iWk, localDateStr(wkStart)),
        mk: _intern(iMk, td.getFullYear() + '-' + String(td.getMonth() + 1).padStart(2, '0')),
        yk: _intern(iYk, String(td.getFullYear())),
      };
      byTs.set(ts, d);
    }
    p._ts = ts;   // raw epoch ms, so date comparisons never coerce a Date
    p._td = d.td; p._tdms = d.tdms; p._ds = d.ds; p._wk = d.wk; p._mk = d.mk; p._yk = d.yk;
    p._se = _stampEpoch;
  }
}

/* ─── STAMP READERS ────────────────────────────────────────────────────────
   Each returns the cached value when the stamp is current, and otherwise
   computes it exactly as the pre-cache code did. */
function tzDateOf(p)      { return p._se === _stampEpoch ? p._td : tzDate(p.date); }
// The same instant as a number, for range comparisons in per-play loops.
function tzMsOf(p)        { return p._se === _stampEpoch ? p._tdms : +tzDate(p.date); }
// The play's real instant as a number — for ordering, where a timezone shift
// must not be applied (it is not guaranteed monotonic across a DST boundary).
function msOf(p)          { return p._se === _stampEpoch ? p._ts : +p.date; }

/* Earliest play date across the library. Replaces a reduce that compared Date
   objects — two valueOf coercions per play, over the whole history, and it ran
   on every load and every poll. Deliberately still a full scan rather than
   trusting allPlays[length-1]: the array is normally sorted newest-first, but
   editing a scrobble's timestamp can break that, so this stays order-agnostic. */
function _earliestPlayDate() {
  if (!allPlays.length) return undefined;
  const cur = _stampEpoch;
  const p0 = allPlays[0];
  let best = p0.date, bestMs = p0._se === cur ? p0._ts : +p0.date;
  for (let i = 1; i < allPlays.length; i++) {
    const p = allPlays[i];
    const ms = p._se === cur ? p._ts : +p.date;
    if (ms < bestMs) { bestMs = ms; best = p.date; }
  }
  return best;
}
function dayStrOf(p)      { return p._se === _stampEpoch ? p._ds : localDateStr(tzDate(p.date)); }
function playWeekKeyOf(p) { return p._se === _stampEpoch ? p._wk : playWeekKey(p.date); }
function albumKeyOf(p)    { return p._se === _stampEpoch ? p._ak : p.album + '|||' + _albumArtistRaw(p); }
function monthKeyOf(p) {
  if (p._se === _stampEpoch) return p._mk;
  const td = tzDate(p.date);
  return td.getFullYear() + '-' + String(td.getMonth() + 1).padStart(2, '0');
}
function yearKeyOf(p) {
  return p._se === _stampEpoch ? p._yk : String(tzDate(p.date).getFullYear());
}

const savedOffsets = { day: 0, week: 0, month: 0, year: 0, alltime: 0, records: 0 };
