// ─── ARTIST CHART: SONG RANKING TOOLTIP ────────────────────────
/* The "unique songs" count in the artist charts is a button. Clicking it
   pops a small ranking of that artist's songs played in the period on
   screen, most played first. The list is built on click from allPlays and
   the current date range, so it works the same for every data source and
   every period (week, month, year, all time) without the chart renderers
   having to carry per-song counts around. */
function artistSongsRankBtn(artist, nSongs) {
  return `<button type="button" class="ars-trigger" data-artist="${esc(artist)}" title="${esc(t('tooltip_artist_songs_rank'))}" onclick="event.stopPropagation();_arsToggle(this)">${tCount('songs', nSongs)}</button>`;
}

const _arsTooltip = (() => {
  const el = document.createElement('div');
  el.id = 'arsTooltip';
  el.className = 'ars-tooltip';
  el.style.display = 'none';
  document.body.appendChild(el);
  return el;
})();
let _arsTrigger = null;

// Songs of one artist in the current period, ranked by plays.
// Grouped by title, the same way the chart's "unique songs" count is.
function _arsRanking(artist) {
  const all = currentPeriod === 'alltime';
  const range = all ? null : getDateRange();
  const s = all ? 0 : +range.start, e = all ? 0 : +range.end;
  const byTitle = new Map();
  for (const p of allPlays) {
    if (!p.artists.includes(artist)) continue;
    if (!all) { const m = tzMsOf(p); if (m < s || m > e) continue; }
    let row = byTitle.get(p.title);
    if (!row) { row = { title: p.title, key: songKey(p), count: 0 }; byTitle.set(p.title, row); }
    row.count++;
  }
  return [...byTitle.values()].sort((a, b) => b.count - a.count || a.title.localeCompare(b.title));
}

function _arsHide() {
  _arsTooltip.style.display = 'none';
  if (_arsTrigger) _arsTrigger.classList.remove('open');
  _arsTrigger = null;
}

function _arsToggle(btn) {
  if (_arsTrigger === btn) { _arsHide(); return; }
  _arsHide();
  const artist = btn.dataset.artist;
  const rows = _arsRanking(artist);
  const label = currentPeriod === 'alltime' ? '' : getDateRange().label;
  // Ties share a rank (1, 2, 2, 4), like the charts themselves
  let rank = 0;
  _arsTooltip.innerHTML =
    `<div class="ars-head"><span class="ars-head-artist">${esc(artist)}</span>${label ? `<span class="ars-head-period">${esc(label)}</span>` : ''}</div>
    <ol class="ars-list">${rows.map((r, i) => {
      if (i === 0 || r.count !== rows[i - 1].count) rank = i + 1;
      return `<li class="ars-item">
        <span class="ars-rank">${rank}</span>
        <a href="javascript:void(0)" class="ars-title" onclick="_arsHide();openSongModal(${esc(JSON.stringify(r.key))})">${esc(r.title)}</a>
        <span class="ars-count">${r.count}</span>
      </li>`;
    }).join('')}</ol>`;
  _arsTooltip.style.display = 'block';
  _arsTrigger = btn;
  btn.classList.add('open');
  // Below the count, flipped above it when there is no room
  const rect = btn.getBoundingClientRect();
  const ttW = _arsTooltip.offsetWidth;
  let left = rect.left;
  let top = rect.bottom + 6;
  if (left + ttW > window.innerWidth - 8) left = window.innerWidth - ttW - 8;
  if (left < 8) left = 8;
  if (top + _arsTooltip.offsetHeight > window.innerHeight - 8) top = Math.max(8, rect.top - _arsTooltip.offsetHeight - 6);
  _arsTooltip.style.left = left + 'px';
  _arsTooltip.style.top = top + 'px';
}

// Close on a click elsewhere, on Escape, or when the page scrolls under it
document.addEventListener('click', e => {
  if (!_arsTrigger) return;
  if (e.target.closest('#arsTooltip') || e.target.closest('.ars-trigger')) return;
  _arsHide();
});
document.addEventListener('keydown', e => { if (e.key === 'Escape' && _arsTrigger) _arsHide(); });
window.addEventListener('scroll', e => {
  if (_arsTrigger && !(e.target instanceof Element && e.target.closest('#arsTooltip'))) _arsHide();
}, true);

// ─── ALBUM TRACKS TOOLTIP ──────────────────────────────────────
// The Tracks count on the album charts opens a list of the album's songs
// played in this period, most played first, each with a 30-second sample
// (the same ▶ as the charts: every <li> is a song entry, so _eaPlaySample and
// its painting work unchanged) and Spotify / Google / YouTube searches.
// Same look and closing rules as the artist songs tooltip above.
function albumTracksBtn(album, artist, nTracks) {
  return `<button type="button" class="ars-trigger alt-trigger" data-album="${esc(album)}" data-artist="${esc(artist)}" title="${esc(t('tooltip_album_tracks'))}" onclick="event.stopPropagation();_altToggle(this)">${tCount('tracks', nTracks)}</button>`;
}

const _altTooltip = (() => {
  const el = document.createElement('div');
  el.id = 'altTooltip';
  el.className = 'ars-tooltip alt-tooltip';
  el.style.display = 'none';
  document.body.appendChild(el);
  return el;
})();
let _altTrigger = null;

const _ALT_G_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21.6 12.2c0-.7-.1-1.4-.2-2H12v3.9h5.4a4.6 4.6 0 0 1-2 3v2.5h3.2c1.9-1.7 3-4.3 3-7.4zM12 22c2.7 0 5-.9 6.6-2.4l-3.2-2.5c-.9.6-2 1-3.4 1-2.6 0-4.8-1.8-5.6-4.1H3.1v2.6A10 10 0 0 0 12 22zM6.4 14a6 6 0 0 1 0-3.9V7.5H3.1a10 10 0 0 0 0 9zM12 6c1.5 0 2.8.5 3.8 1.5l2.9-2.9A10 10 0 0 0 3.1 7.5l3.3 2.6C7.2 7.8 9.4 6 12 6z"/></svg>';

// Songs of one album in the current period, ranked by plays. Grouped by
// title, like the chart's track count, and counted the same way the chart
// counts the album (a rolled-up single's plays go to its parent too).
// All-Time follows time travel (atPlays), the other periods their date range.
function _altRanking(album, artist) {
  const ak = album + '|||' + artist;
  const all = currentPeriod === 'alltime';
  const range = all ? null : getDateRange();
  const s = all ? 0 : +range.start, e = all ? 0 : +range.end;
  const roll = rollupAffectsCharts();
  const byTitle = new Map();
  for (const p of (all ? atPlays() : allPlays)) {
    if (albumKeyOf(p) !== ak && !(roll && rollupParentOf(p) === ak)) continue;
    if (!all) { const m = tzMsOf(p); if (m < s || m > e) continue; }
    let row = byTitle.get(p.title);
    if (!row) { row = { title: p.title, artist: p.artist, album: p.album, key: songKey(p), count: 0 }; byTitle.set(p.title, row); }
    row.count++;
  }
  return [...byTitle.values()].sort((a, b) => b.count - a.count || a.title.localeCompare(b.title));
}

function _altHide() {
  _altTooltip.style.display = 'none';
  if (_altTrigger) _altTrigger.classList.remove('open');
  _altTrigger = null;
}

function _altToggle(btn) {
  if (_altTrigger === btn) { _altHide(); return; }
  _altHide();
  _arsHide();
  const album = btn.dataset.album, artist = btn.dataset.artist;
  const rows = _altRanking(album, artist);
  const label = currentPeriod === 'alltime' ? '' : getDateRange().label;
  const lSp = esc(t('tm_action_spotify')), lG = esc(t('tm_action_google')), lYt = esc(t('awx_yt'));
  const link = (cls, href, lbl, svg) => `<a class="alt-link alt-link--${cls}" href="${href}" target="_blank" rel="noopener" title="${lbl}" aria-label="${lbl}">${svg}</a>`;
  // Ties share a rank (1, 2, 2, 4), like the charts themselves
  let rank = 0;
  _altTooltip.innerHTML =
    `<div class="ars-head"><span class="ars-head-artist">${esc(album)}</span>${label ? `<span class="ars-head-period">${esc(label)}</span>` : ''}</div>
    <ol class="ars-list">${rows.map((r, i) => {
      if (i === 0 || r.count !== rows[i - 1].count) rank = i + 1;
      const q = encodeURIComponent(r.title + ' ' + r.artist);
      return `<li class="ars-item alt-item"${_eaAttrs('songs', { title: r.title, artist: r.artist, album: r.album, key: r.key })}>
        <span class="ars-rank">${rank}</span>
        ${_eaSampleBtn('alt-sample')}
        <a href="javascript:void(0)" class="ars-title" onclick="_altHide();openSongModal(${esc(JSON.stringify(r.key))})">${esc(r.title)}</a>
        <span class="ars-count">${r.count}</span>
        <span class="alt-links">${link('sp', 'https://open.spotify.com/search/' + q, lSp, _EA_SP_SVG)}${link('g', 'https://www.google.com/search?q=' + q, lG, _ALT_G_SVG)}${link('yt', 'https://www.youtube.com/results?search_query=' + q, lYt, _ST_AM_YT_SVG)}</span>
      </li>`;
    }).join('')}</ol>`;
  _altTooltip.style.display = 'block';
  _altTrigger = btn;
  btn.classList.add('open');
  // A sample already playing from this album shows as on
  _eaPaintSamples();
  // Below the count, flipped above it when there is no room
  const rect = btn.getBoundingClientRect();
  const ttW = _altTooltip.offsetWidth;
  let left = rect.left;
  let top = rect.bottom + 6;
  if (left + ttW > window.innerWidth - 8) left = window.innerWidth - ttW - 8;
  if (left < 8) left = 8;
  if (top + _altTooltip.offsetHeight > window.innerHeight - 8) top = Math.max(8, rect.top - _altTooltip.offsetHeight - 6);
  _altTooltip.style.left = left + 'px';
  _altTooltip.style.top = top + 'px';
}

// Close on a click elsewhere, on Escape, or when the page scrolls under it.
// The sample keeps playing after it closes, like the chart's own ▶.
document.addEventListener('click', e => {
  if (!_altTrigger) return;
  if (e.target.closest('#altTooltip') || e.target.closest('.alt-trigger')) return;
  _altHide();
});
document.addEventListener('keydown', e => { if (e.key === 'Escape' && _altTrigger) _altHide(); });
window.addEventListener('scroll', e => {
  if (_altTrigger && !(e.target instanceof Element && e.target.closest('#altTooltip'))) _altHide();
}, true);

// ─── EVENTS CALENDAR MINI-CARD TOOLTIP ─────────────────────────
const _calEvTooltip = (() => {
  const el = document.createElement('div');
  el.id = 'calEvTooltip';
  el.className = 'cal-ev-tooltip';
  el.style.display = 'none';
  document.body.appendChild(el);
  return el;
})();

let _calEvHideTimer = null;

function _calTtPlaceholderHtml(artist) {
  const words = (artist || '').replace(/^The\s+/i, '').split(/\s+/).filter(Boolean);
  const inits = words.slice(0, 2).map(w => w[0].toUpperCase()).join('');
  const colors = ['#0d2137', '#1a1040', '#0d2e1f', '#2b1a0d', '#0d1e2b', '#1f0d0d'];
  const hash = (artist || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0);
  return `<div class="ctt-placeholder" style="background:${colors[hash % colors.length]}">${inits}</div>`;
}

async function _loadCalTtArtistImg(imgWrap, artist) {
  try {
    const url = await deezerArtistImage(artist);
    if (!imgWrap.isConnected || !url) return;
    const ph = imgWrap.querySelector('.ctt-placeholder');
    if (!ph) return;
    const img = document.createElement('img');
    img.className = 'ctt-img';
    img.alt = '';
    img.onerror = () => {};
    img.src = url;
    imgWrap.replaceChild(img, ph);
  } catch (e) {}
}

function _showCalEvTooltip(target) {
  // The pill's action menu is the popup that matters once it is open; the
  // hover mini-card would sit on top of it.
  if (_tmMenuEl) return;
  clearTimeout(_calEvHideTimer);
  const { ctk: kind = '', ctt: evType = '', cta: artist = '', ctl: title = '', ctm: mbid = '', ctd: detail = '', ctx: dtxt = '', ctf: dtf = '' } = target.dataset;

  const mainTitle = evType === 'birthday' ? artist : title;
  const artistLine = evType !== 'birthday' ? `<div class="ctt-artist">${esc(artist)}</div>` : '';
  const dateLine = dtxt ? `<div class="ctt-date${dtf ? ' ' + dtf : ''}">${esc(dtxt)}</div>` : '';

  _calEvTooltip.innerHTML = `
    <div class="ctt-img-wrap"></div>
    <div class="ctt-body">
      ${dateLine}
      <div class="ctt-title">${esc(mainTitle)}</div>
      ${artistLine}
      <div class="ctt-type">${_evTypeIco(kind)}<span>${esc(detail)}</span></div>
    </div>`;

  const imgWrap = _calEvTooltip.querySelector('.ctt-img-wrap');
  if (mbid) {
    const img = document.createElement('img');
    img.className = 'ctt-img';
    img.alt = '';
    img.onerror = () => { if (imgWrap.isConnected) imgWrap.innerHTML = _calTtPlaceholderHtml(artist); };
    img.src = `https://coverartarchive.org/release-group/${mbid}/front-250`;
    imgWrap.appendChild(img);
  } else {
    imgWrap.innerHTML = _calTtPlaceholderHtml(artist);
    if (evType === 'birthday' && artist) _loadCalTtArtistImg(imgWrap, artist);
  }

  _calEvTooltip.style.display = 'flex';
  const rect = target.getBoundingClientRect();
  const ttW = _calEvTooltip.offsetWidth || 220;
  const ttH = _calEvTooltip.offsetHeight || 90;
  let left = rect.right + 8;
  let top = rect.top - 4;
  if (left + ttW > window.innerWidth - 8) left = rect.left - ttW - 8;
  if (top + ttH > window.innerHeight - 8) top = window.innerHeight - ttH - 8;
  _calEvTooltip.style.left = `${Math.max(8, left)}px`;
  _calEvTooltip.style.top = `${Math.max(8, top)}px`;
}

function _hideCalEvTooltip() {
  _calEvHideTimer = setTimeout(() => { _calEvTooltip.style.display = 'none'; }, 130);
}

document.addEventListener('mouseover', e => {
  const ev = e.target.closest('.cal-ev[data-ctt]');
  if (ev) { _showCalEvTooltip(ev); return; }
  if (e.target.closest('#calEvTooltip')) clearTimeout(_calEvHideTimer);
});

document.addEventListener('mouseout', e => {
  if (!e.target.closest('.cal-ev[data-ctt]') && !e.target.closest('#calEvTooltip')) return;
  const to = e.relatedTarget;
  if (to && (to.closest('.cal-ev[data-ctt]') || to.closest('#calEvTooltip'))) return;
  _hideCalEvTooltip();
});

// ─── TIME MACHINE ──────────────────────────────────────────────
const tmToggles = (() => {
  const saved = localStorage.getItem('dc_tm_toggles');
  if (saved) { try { return JSON.parse(saved); } catch (e) {} }
  return { songs: true, artists: true, albums: true };
})();
let tmData = null;
let tmImgQueue = Promise.resolve();
let tmLoaderId = 0;

function buildTimeMachineData() {
  // "Today" and each play's day are both read in the user's chosen timezone
  // (tzNow / tzDateOf), so a late-night play lands on the same calendar day
  // here as it does on the charts.
  const today = tzNow();
  const todayMonth = today.getMonth();
  const todayDay = today.getDate();
  const todayYear = today.getFullYear();

  const pastPlays = allPlays.filter(p => {
    if (!(p.date instanceof Date)) return false;
    const d = tzDateOf(p);
    return d.getMonth() === todayMonth && d.getDate() === todayDay && d.getFullYear() < todayYear;
  });

  const songsSeen = new Set();
  const songs = [];
  for (const p of pastPlays) {
    const year = tzDateOf(p).getFullYear();
    const k = p.title + '\0' + p.artist + '\0' + year;
    if (!songsSeen.has(k)) {
      songsSeen.add(k);
      songs.push({ type: 'song', title: p.title, artist: p.artist, album: p.album || '—', year });
    }
  }

  const artistsSeen = new Set();
  const artists = [];
  for (const p of pastPlays) {
    const year = tzDateOf(p).getFullYear();
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    for (const ar of list) {
      const k = ar + '\0' + year;
      if (!artistsSeen.has(k)) {
        artistsSeen.add(k);
        artists.push({ type: 'artist', artist: ar, year });
      }
    }
  }

  const albumsSeen = new Set();
  const albums = [];
  for (const p of pastPlays) {
    if (!p.album || p.album === '—') continue;
    const year = tzDateOf(p).getFullYear();
    const aa = albumArtist(p);
    const k = p.album + '\0' + aa + '\0' + year;
    if (!albumsSeen.has(k)) {
      albumsSeen.add(k);
      albums.push({ type: 'album', album: p.album, artist: aa, year });
    }
  }

  return { songs, artists, albums };
}

function tmShuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function renderTimeMachine(forceRebuild) {
  const section = document.getElementById('timeMachineSection');
  const track = document.getElementById('tmTickerTrack');
  if (!section || !track || !allPlays.length) return;

  for (const type of ['songs', 'artists', 'albums']) {
    const btn = document.getElementById('tmToggle' + type.charAt(0).toUpperCase() + type.slice(1));
    if (btn) btn.classList.toggle('active', !!tmToggles[type]);
  }

  const newData = buildTimeMachineData();
  const newHash = newData.songs.length + '|' + newData.artists.length + '|' + newData.albums.length;

  // The section sits inside #eventsView, so that tab's own visibility
  // decides whether it is on screen; this only shows or hides it for data.
  if (!forceRebuild && tmData && tmData._hash === newHash && track.firstChild) {
    section.style.display = ''; // cached cards are still in the track
    return;
  }

  newData._hash = newHash;
  tmData = newData;

  let entries = [];
  if (tmToggles.songs) entries = entries.concat(tmData.songs);
  if (tmToggles.artists) entries = entries.concat(tmData.artists);
  if (tmToggles.albums) entries = entries.concat(tmData.albums);
  entries = tmShuffle(entries);

  const tickerOuter = document.getElementById('tmTickerOuter');
  const emptyEl = document.getElementById('tmEmpty');
  const hintEl = document.getElementById('tmHint');
  // Nothing on the reel means nothing to save — the header button goes with it.
  const plBtn = document.getElementById('tmPlBtn');
  if (plBtn) plBtn.style.display = entries.length ? '' : 'none';
  // Did this day happen at all in past years? That is a different question from
  // whether anything is on screen — the type toggles can empty a day that has
  // plenty of history behind it.
  const hasDayData = tmData.songs.length || tmData.artists.length || tmData.albums.length;

  if (entries.length === 0) {
    if (tickerOuter) tickerOuter.style.display = 'none';
    track.innerHTML = '';
    // Nothing was played on this date in any past year — there is genuinely
    // nothing to show, so the section stays out of the way.
    if (!hasDayData) { section.style.display = 'none'; return; }
    // Otherwise all three types are switched off. Keep the section on screen with
    // an empty state instead of vanishing: the Songs/Artists/Albums buttons live
    // in its own header, so hiding it strands the user with no way to switch one
    // back on — and the state rides along in Firestore, so neither a reload nor a
    // cache clear undoes it. The card hint would be nonsense with no cards.
    section.style.display = '';
    if (emptyEl) emptyEl.style.display = '';
    if (hintEl) hintEl.style.display = 'none';
    return;
  }
  section.style.display = '';
  if (tickerOuter) tickerOuter.style.display = '';
  if (emptyEl) emptyEl.style.display = 'none';
  if (hintEl) hintEl.style.display = '';

  tmImgQueue = Promise.resolve();
  const myLoaderId = ++tmLoaderId;

  const aSongItems = [], aArtistItems = [], aAlbumItems = [];
  const bSongItems = [], bArtistItems = [], bAlbumItems = [];

  /* The deck is rendered twice so the reel can wrap seamlessly (see
     dcMountReel). Copy B is tagged, because a deck short enough to fit on
     screen has nothing to wrap onto and would just show everything twice. */
  function buildCard(entry, i, suffix, songArr, artistArr, albumArr) {
    const imgId = 'tmimg-' + suffix + '-' + i;
    const dupe = suffix === 'b' ? ' dcreel-dupe' : '';
    if (entry.type === 'song') {
      const sub = entry.artist + (entry.album && entry.album !== '—' ? ' · ' + entry.album : '');
      const prefKey = 'song:' + entry.artist.toLowerCase() + '|||' + entry.title.toLowerCase();
      songArr.push({ imgId, title: entry.title, artist: entry.artist, album: entry.album, name: entry.title, prefKey });
      return '<div class="dc-card-inset tm-card tm-card-song' + dupe + '" data-type="song" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.title)) + ',' + esc(JSON.stringify(entry.artist)) + ',' + esc(JSON.stringify(entry.album)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.title)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.title) + '</div>' +
        '<div class="tm-card-sub">' + esc(sub) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    } else if (entry.type === 'artist') {
      const prefKey = 'artist:' + entry.artist.toLowerCase();
      artistArr.push({ imgId, name: entry.artist, artist: entry.artist, album: '', title: '', prefKey });
      return '<div class="dc-card-inset tm-card tm-card-search' + dupe + '" data-type="artist" onclick="_tmShowArtistMenu(event,' + esc(JSON.stringify(entry.artist)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.artist)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.artist) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    } else {
      const prefKey = 'album:' + entry.artist.toLowerCase() + '|||' + entry.album.toLowerCase();
      albumArr.push({ imgId, album: entry.album, artist: entry.artist, name: entry.album, title: '', prefKey });
      return '<div class="dc-card-inset tm-card tm-card-search' + dupe + '" data-type="album" onclick="_tmShowAlbumMenu(event,' + esc(JSON.stringify(entry.album)) + ',' + esc(JSON.stringify(entry.artist)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.album)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.album) + '</div>' +
        '<div class="tm-card-sub">' + esc(entry.artist) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    }
  }

  const firstCopy = entries.map((e, i) => buildCard(e, i, 'a', aSongItems, aArtistItems, aAlbumItems)).join('');
  const secondCopy = entries.map((e, i) => buildCard(e, i, 'b', bSongItems, bArtistItems, bAlbumItems)).join('');

  track.innerHTML = firstCopy + secondCopy;
  /* Was a CSS marquee; the pace is now the reel's drift and it can be grabbed
     and dragged. See dcMountReel(). 5s a card rather than the marquee's 4 —
     this is the reel that sits on the charts page all day, and it reads as
     something to browse rather than something going past. */
  dcMountReel(tickerOuter, track, Math.max(20, entries.length * 5));

  // Load images for a-copy in parallel batches; mirror results to b-copy (halves API calls)
  async function loadTmBatch(aPairs, type, loaderId) {
    const BATCH = 4;
    for (let i = 0; i < aPairs.length; i += BATCH) {
      if (tmLoaderId !== loaderId) return;
      await Promise.all(aPairs.slice(i, i + BATCH).map(async ([aItem, bItem]) => {
        if (tmLoaderId !== loaderId) return;
        const aEl = document.getElementById(aItem.imgId);
        if (!aEl) return;
        // Behind whatever the page is showing — see queueImg().
        await queueImg(() => aEl.isConnected && fetchAndInjectImage(aEl, aItem, type), true);
        const bEl = document.getElementById(bItem.imgId);
        if (bEl) bEl.innerHTML = aEl.innerHTML;
      }));
    }
  }

  const ldr = myLoaderId;
  const songPairs  = aSongItems.map((a, i) => [a, bSongItems[i]]);
  const artistPairs = aArtistItems.map((a, i) => [a, bArtistItems[i]]);
  const albumPairs  = aAlbumItems.map((a, i) => [a, bAlbumItems[i]]);

  tmImgQueue = tmImgQueue
    .then(() => loadTmBatch(songPairs,   'song',   ldr))
    .then(() => loadTmBatch(artistPairs, 'artist', ldr))
    .then(() => loadTmBatch(albumPairs,  'album',  ldr));
}

// Everything the reel is currently showing, straight into the picker. Artist and
// album cards have no track of their own, so each contributes its single most
// recent play — a deck of only artists still yields a playlist rather than
// nothing, and one entry each keeps the result the length of what's on screen.
function tmAddAllToPlaylist() {
  if (!tmData) return;
  const tracks = [];
  if (tmToggles.songs)   tmData.songs.forEach(e => tracks.push({ title: e.title, artist: e.artist, album: e.album }));
  if (tmToggles.artists) tmData.artists.forEach(e => { const s = _tmArtistLastSongs(e.artist, 1)[0]; if (s) tracks.push(s); });
  if (tmToggles.albums)  tmData.albums.forEach(e => { const s = _tmAlbumLastSongs(e.album, e.artist, 1)[0]; if (s) tracks.push(s); });
  const label = t('time_machine_title'); // a plain title since phase 9 part 4 step 8 (no ⏳ to drop)
  dcOpenPlaylistPicker(tracks, label, `${label} · ${_dcPlDateTag()}`);
}

function tmToggleType(type) {
  tmToggles[type] = !tmToggles[type];
  const id = 'tmToggle' + type.charAt(0).toUpperCase() + type.slice(1);
  const btn = document.getElementById(id);
  if (btn) btn.classList.toggle('active', tmToggles[type]);
  localStorage.setItem('dc_tm_toggles', JSON.stringify(tmToggles));
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  renderTimeMachine(true);
}

// ── Time Machine action menus — tooltip-style popups for song and artist cards ──
let _tmMenuEl = null;
// The reel this menu is parked on, if any. These menus are opened from the Time
// Machine, the Soundtrack reel and the Events reels alike, so which one to hold
// still is a question about the card that was clicked, not a fixed element.
let _tmPausedReel = null;
// The card the open menu is anchored to — see _tmScrollClose, which needs to
// know whether a scroll actually moved this card or happened somewhere else.
let _tmMenuCard = null;

function _tmCloseMenu() {
  if (_tmMenuEl) { _tmMenuEl.remove(); _tmMenuEl = null; }
  if (_tmPausedReel) { _tmPausedReel.dataset.reelPaused = '0'; _tmPausedReel = null; }
  _tmMenuCard = null;
  document.removeEventListener('click', _tmOutsideMenuClick, true);
  document.removeEventListener('keydown', _tmMenuKeydown, true);
  window.removeEventListener('scroll', _tmScrollClose, true);
  window.removeEventListener('resize', _tmCloseMenu, true);
}

function _tmOutsideMenuClick(e) {
  if (_tmMenuEl && !_tmMenuEl.contains(e.target)) _tmCloseMenu();
}

/* The menu is a tooltip pinned to a card, so a scroll that moves that card has
   to close it. Listening on window in capture phase is the only way to hear a
   scroll inside an arbitrary scroller — but it also hears every *other*
   scroller on the page, and the release reels rewrite their own scrollLeft on
   every animation frame. That fired a scroll a frame or two after the menu
   opened and closed it again instantly: on a page with more than one reel the
   options never appeared at all. So only a scroll that this card actually sits
   inside counts; the reel it is parked on is already held still. */
function _tmScrollClose(e) {
  const tgt = e.target;
  if (tgt === document || tgt === document.documentElement || tgt === document.body || tgt === window) { _tmCloseMenu(); return; }
  if (tgt === _tmPausedReel) return;
  if (tgt instanceof Element && _tmMenuCard && tgt.contains(_tmMenuCard)) _tmCloseMenu();
}

function _tmMenuKeydown(e) {
  if (e.key === 'Escape') _tmCloseMenu();
}

// Anchors an already-built (and already-appended) menu to its trigger card, as a tooltip:
// centered above by default, flipping below if there's no room. Re-run after content changes.
function _tmPositionMenu(menu, card) {
  menu.classList.remove('tm-action-menu--top', 'tm-action-menu--bottom');
  const r = card.getBoundingClientRect();
  const mr = menu.getBoundingClientRect();
  let placement = 'top';
  let top = r.top - mr.height - 8;
  if (top < 8) { top = r.bottom + 8; placement = 'bottom'; }
  menu.classList.add('tm-action-menu--' + placement);

  let left = r.left + r.width / 2 - mr.width / 2;
  left = Math.max(8, Math.min(left, window.innerWidth - mr.width - 8));
  menu.style.top = (top + window.scrollY) + 'px';
  menu.style.left = (left + window.scrollX) + 'px';

  const arrow = menu.querySelector('.tm-action-menu-arrow');
  if (arrow) {
    let arrowLeft = (r.left + r.width / 2) - left;
    arrowLeft = Math.max(12, Math.min(arrowLeft, mr.width - 12));
    arrow.style.left = arrowLeft + 'px';
  }
}

// Opens `menu` (already filled with its first view) as a tooltip on `card`, wiring up
// the shared dismiss handlers (outside click, Escape, scroll, resize) and pausing the ticker.
function _tmOpenMenu(menu, card) {
  document.body.appendChild(menu);
  _tmPositionMenu(menu, card);

  // A card that keeps drifting walks out from under its own menu, so whichever
  // reel this card belongs to parks until the menu closes.
  _tmPausedReel = card.closest('.dcreel');
  if (_tmPausedReel) _tmPausedReel.dataset.reelPaused = '1';

  // A calendar pill carries a hover mini-card as well; two popups over the same
  // cell is one too many, so the menu takes the place of the tooltip.
  const calTt = document.getElementById('calEvTooltip');
  if (calTt) calTt.style.display = 'none';

  _tmMenuEl = menu;
  _tmMenuCard = card;
  setTimeout(() => {
    document.addEventListener('click', _tmOutsideMenuClick, true);
    document.addEventListener('keydown', _tmMenuKeydown, true);
    window.addEventListener('scroll', _tmScrollClose, true);
    window.addEventListener('resize', _tmCloseMenu, true);
  }, 0);
}

function _tmShowSongMenu(ev, title, artist, album) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const q = encodeURIComponent(title + ' ' + artist);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';
  menu.innerHTML =
    '<div class="tm-action-menu-arrow"></div>' +
    '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="playlist">' + DC_PL_ICON + esc(t('tm_action_playlist')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="player">▶ ' + esc(t('tm_action_player')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';

  menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });
  // Saves the song to a playlist instead of the player queue — the menu closes
  // first so the picker isn't fighting the popup's outside-click handler.
  menu.querySelector('[data-act="playlist"]').addEventListener('click', (e) => {
    e.stopPropagation();
    _tmCloseMenu();
    dcOpenPlaylistPicker([{ title, artist, album }], title, title);
  });
  menu.querySelector('[data-act="player"]').addEventListener('click', (e) => {
    e.stopPropagation();
    _ytPlayOrQueue(title, artist, album);
    _tmCloseMenu();
  });
  menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://www.google.com/search?q=' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });

  _tmOpenMenu(menu, card);
}

// Most-recently-played songs by an artist, newest first (allPlays is sorted newest-first).
function _tmArtistLastSongs(artist, limit) {
  const seen = new Set();
  const out = [];
  for (const p of allPlays) {
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    if (!list.includes(artist)) continue;
    const key = p.title.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ title: p.title, artist, album: p.album || '' });
    if (out.length >= limit) break;
  }
  return out;
}

function _tmQueueToast(n) {
  const statusEl = document.getElementById('ytMiniStatus');
  if (!statusEl) return;
  const msg = t(n === 1 ? 'tm_action_queued_toast_one' : 'tm_action_queued_toast_other', { n });
  statusEl.textContent = msg;
  statusEl.className = 'yt-mini-status ok';
  setTimeout(() => { if (statusEl.textContent === msg) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2500);
}

// Shared popup for artist/album cards: Spotify search, a playlist option, a
// "last 10 songs" sub-view (add one-by-one or all at once), and a Google search.
// `searchQuery` drives both the Spotify and Google links; `fetchSongs(limit)`
// supplies the songs for the sub-view; `plLabel` names the entity in the
// playlist picker (the search query reads badly there — it's "Album Artist").
// `opts` carries what varies between the cards that use this menu:
//   plFallback  what the playlist option stages when there's no play history at
//               all, and the only reason that option can appear when the queue
//               ones don't.
//   googleQuery splits the two searches apart for the cards whose Google link
//               means something the music services would make nonsense of
//               ("<artist> birthday"); left out, both use `searchQuery`.
//   sourceLink  { url, icon, label } for a card built from a service that has
//               its own page for this release — New Music Friday comes from
//               Deezer, and that page is where the card used to go. It sits at
//               the top of the menu, above the searches.
function _tmShowEntityMenu(ev, searchQuery, fetchSongs, plLabel, opts) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const { plFallback, googleQuery, sourceLink } = opts || {};
  const q = encodeURIComponent(searchQuery);
  const gq = encodeURIComponent(googleQuery || searchQuery);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';

  function renderMain() {
    // Only offer the player queue if there's actually play history to queue from —
    // e.g. a Recent Release the user hasn't listened to yet shouldn't show it.
    const hasPlays = fetchSongs(1).length > 0;
    const canPlaylist = hasPlays || (plFallback && plFallback.length);
    menu.innerHTML =
      '<div class="tm-action-menu-arrow"></div>' +
      (sourceLink ? '<button class="tm-action-menu-item" data-act="source">' + esc(sourceLink.icon) + ' ' + esc(sourceLink.label) + '</button>' : '') +
      '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
      (canPlaylist ? '<button class="tm-action-menu-item" data-act="playlist">' + DC_PL_ICON + esc(t('tm_action_playlist')) + '</button>' : '') +
      (hasPlays ? '<button class="tm-action-menu-item" data-act="last10">🎵 ' + esc(t('tm_action_last10')) + '</button>' : '') +
      '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';
    if (sourceLink) {
      menu.querySelector('[data-act="source"]').addEventListener('click', (e) => {
        e.stopPropagation();
        window.open(sourceLink.url, '_blank', 'noopener');
        _tmCloseMenu();
      });
    }
    menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
      e.stopPropagation();
      window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
      _tmCloseMenu();
    });
    if (canPlaylist) {
      // Stages a deeper slice than the "last 10" sub-view offers — picking a
      // playlist is a deliberate act, so it's worth carrying more of the history.
      menu.querySelector('[data-act="playlist"]').addEventListener('click', (e) => {
        e.stopPropagation();
        const songs = hasPlays ? fetchSongs(DC_PL_ENTITY_LIMIT) : plFallback;
        _tmCloseMenu();
        dcOpenPlaylistPicker(songs, plLabel, plLabel);
      });
    }
    if (hasPlays) {
      menu.querySelector('[data-act="last10"]').addEventListener('click', (e) => {
        e.stopPropagation();
        renderSongs();
        _tmPositionMenu(menu, card);
      });
    }
    menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
      e.stopPropagation();
      window.open('https://www.google.com/search?q=' + gq, '_blank', 'noopener');
      _tmCloseMenu();
    });
  }

  function renderSongs() {
    const songs = fetchSongs(10);
    const backBtn = '<button class="tm-action-menu-back" data-act="back">‹ ' + esc(t('tm_action_last10')) + '</button>';
    if (!songs.length) {
      menu.innerHTML = '<div class="tm-action-menu-arrow"></div>' + backBtn +
        '<div class="tm-action-menu-empty">' + esc(t('tm_action_no_songs')) + '</div>';
      menu.querySelector('[data-act="back"]').addEventListener('click', (e) => { e.stopPropagation(); renderMain(); _tmPositionMenu(menu, card); });
      return;
    }
    menu.innerHTML =
      '<div class="tm-action-menu-arrow"></div>' + backBtn +
      '<button class="tm-action-menu-item" data-act="plall">' + DC_PL_ICON + esc(t('tm_action_pl_all')) + '</button>' +
      '<button class="tm-action-menu-item tm-action-menu-addall" data-act="addall">➕ ' + esc(t('tm_action_add_all')) + '</button>' +
      '<div class="tm-action-menu-songs">' +
      songs.map((s, i) => '<div class="tm-action-menu-song">' +
        '<span class="tm-action-menu-song-title">' + esc(s.title) + '</span>' +
        '<button class="tm-action-menu-song-add" data-i="' + i + '" title="' + esc(t('tm_action_add_one')) + '">+</button>' +
        '</div>').join('') +
      '</div>';

    menu.querySelector('[data-act="back"]').addEventListener('click', (e) => { e.stopPropagation(); renderMain(); _tmPositionMenu(menu, card); });
    // Same set the sub-view is showing, straight into a playlist rather than the queue.
    menu.querySelector('[data-act="plall"]').addEventListener('click', (e) => {
      e.stopPropagation();
      _tmCloseMenu();
      dcOpenPlaylistPicker(songs, plLabel, plLabel);
    });
    menu.querySelector('[data-act="addall"]').addEventListener('click', (e) => {
      e.stopPropagation();
      const playerEl = document.getElementById('ytMiniPlayer');
      const playerActive = _ytCurrentTrack && playerEl && playerEl.style.display !== 'none';
      let toQueue = songs;
      if (!playerActive) {
        // Nothing playing yet — open the player on the first song instead of silently queuing it.
        const [first, ...rest] = songs;
        openYtPlayer(first.title, first.artist, first.album, null);
        toQueue = rest;
      }
      toQueue.forEach(s => _ytQueue.push({ title: s.title, artist: s.artist, album: s.album, btn: null }));
      _ytUpdateQueueDisplay();
      _ytSaveQueue();
      _tmQueueToast(songs.length);
      _tmCloseMenu();
    });
    menu.querySelectorAll('.tm-action-menu-song-add').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const s = songs[+btn.dataset.i];
        _ytStreakPlay(s.title, s.artist);
      });
    });
  }

  renderMain();
  _tmOpenMenu(menu, card);
}

function _tmShowArtistMenu(ev, artist) {
  _tmShowEntityMenu(ev, artist, (limit) => _tmArtistLastSongs(artist, limit), artist);
}

// Birthday cards (Events tab). The same artist menu, except the Google option
// keeps the birthday search the card used to jump straight to — that is what
// the card is about, and it is the one query Spotify would make nothing of.
function _tmShowBirthdayMenu(ev, artist) {
  _tmShowEntityMenu(ev, artist, (limit) => _tmArtistLastSongs(artist, limit), artist,
    { googleQuery: artist + ' birthday' });
}

// Most-recently-played songs from an album (by this artist), newest first.
function _tmAlbumLastSongs(album, artist, limit) {
  const seen = new Set();
  const out = [];
  for (const p of allPlays) {
    if (!p.album || p.album.toLowerCase() !== album.toLowerCase()) continue;
    if (albumArtist(p).toLowerCase() !== artist.toLowerCase()) continue;
    const key = p.title.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ title: p.title, artist, album });
    if (out.length >= limit) break;
  }
  return out;
}

function _tmShowAlbumMenu(ev, album, artist) {
  // The playlist fallback is the release itself: an anniversary or a recent
  // release the user has never played has no tracks in history, but "Artist –
  // Release" is still a perfectly good thing to save. It stays out of
  // fetchSongs so the player-queue options keep their play-history-only rule.
  _tmShowEntityMenu(ev, album + ' ' + artist, (limit) => _tmAlbumLastSongs(album, artist, limit),
    album, { plFallback: [{ title: album, artist, album }] });
}

// New Music Friday cards. Deezer is where the release itself comes from — the
// cover, the title, the date and the album page — so the menu keeps a way back
// to that page as its first option, which is where the card used to go on its
// own. Everything under it is the ordinary release menu; a record that came out
// this morning has no play history, so in practice it offers Deezer, Spotify, a
// playlist and Google.
function _concertShowMenu(ev, artist, ticketUrl) {
  _tmShowEntityMenu(ev, artist, (limit) => _tmArtistLastSongs(artist, limit), artist, {
    sourceLink: ticketUrl ? { url: ticketUrl, icon: '🎟️', label: t('tm_action_tickets') } : null
  });
}

function _nmfShowMenu(ev, album, artist, deezerUrl) {
  _tmShowEntityMenu(ev, album + ' ' + artist, (limit) => _tmAlbumLastSongs(album, artist, limit),
    album, {
      plFallback: [{ title: album, artist, album }],
      sourceLink: deezerUrl ? { url: deezerUrl, icon: '🔗', label: t('tm_action_deezer') } : null
    });
}

// Tooltip popup for unreleased upcoming-release cards (the main Upcoming Releases section
// and the Events tab's Upcoming Releases). No "add to player" option — nothing to play yet.
function _relShowMenu(ev, title, artist) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const q = encodeURIComponent(title + ' ' + artist);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';
  menu.innerHTML =
    '<div class="tm-action-menu-arrow"></div>' +
    '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';

  menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });
  menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://www.google.com/search?q=' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });

  _tmOpenMenu(menu, card);
}

