const COLLAB_EXCEPTIONS = [
  'Tyler, The Creator', 'Earth, Wind & Fire', 'Simon & Garfunkel',
  'Of Monsters and Men', 'Panic! at the Disco', 'Portugal. The Man',
];

/* Each awards tab reopens on the year you last looked at, per browser, instead
   of jumping back to the default on every refresh. A saved year outside
   1959..this year is ignored; the tighter My Grammys floor (first play year)
   needs the plays loaded, so awardsInit applies it when the tab opens. */
function _awardsSavedYear(kind, fallback) {
  try {
    const y = parseInt(localStorage.getItem('dc_awards_year_' + kind), 10);
    if (y >= 1959 && y <= tzNow().getFullYear()) return y;
  } catch (e) {}
  return fallback;
}
function _awardsRememberYear(kind, year) {
  try { localStorage.setItem('dc_awards_year_' + kind, String(year)); } catch (e) {}
}

let _awardsYear     = _awardsSavedYear('mygrammys', tzNow().getFullYear() - 1);
let _awardsYearData = {};
let _awardsSubTab   = 'mygrammys';
/* Artist genre tags and album release years are both slow web lookups, and the
   nominee picker now asks for them on every row it shows. So the answers are
   kept in localStorage across visits: an album is looked up once, ever. Only
   real answers are saved — an empty tag list or a year nobody found may just be
   a dead key or a dropped connection, so those stay in memory for the session
   and get another try next visit. */
const AWARDS_GENRE_LS = 'dc_awards_genre_cache';
const AWARDS_YEAR_LS  = 'dc_awards_year_cache';
function _awardsLoadLookupCache(lsKey) {
  try { const v = JSON.parse(localStorage.getItem(lsKey) || '{}'); return v && typeof v === 'object' ? v : {}; }
  catch (e) { return {}; }
}
let _awardsGenreCache = _awardsLoadLookupCache(AWARDS_GENRE_LS);
let _awardsGenreQueue = {};
const _awardsAlbumYearCache = _awardsLoadLookupCache(AWARDS_YEAR_LS);
// Lookups land in bursts (a page of rows at a time), so the save waits for the burst to end
let _awardsLookupSaveTimer = null;
function _awardsSaveLookupCaches() {
  clearTimeout(_awardsLookupSaveTimer);
  _awardsLookupSaveTimer = setTimeout(() => {
    const genres = {}, years = {};
    for (const [k, v] of Object.entries(_awardsGenreCache))     if (Array.isArray(v) && v.length) genres[k] = v;
    for (const [k, v] of Object.entries(_awardsAlbumYearCache)) if (v) years[k] = v;
    try {
      localStorage.setItem(AWARDS_GENRE_LS, JSON.stringify(genres));
      localStorage.setItem(AWARDS_YEAR_LS, JSON.stringify(years));
    } catch (e) { /* storage full or blocked: the in-memory caches still work */ }
  }, 1500);
}
// --- Nominee picker state (all reset every time the modal opens) ---
let _awardsPickerSel      = [];        // ordered list of chosen nominees (order = display order)
let _awardsPickerSelKeys  = new Set(); // _awardItemKey() of everything in _awardsPickerSel, for O(1) lookups
let _awardsPickerCatType  = '';
let _awardsPickerCatFilter = '';
let _awardsPickerEligWin  = { start: '', end: '' };
let _awardsPickerAutoCands = [];
let _awardsPickerAllItems = [];        // every song/album/artist played in the eligibility window, built once per open
let _awardsPickerSuggKeys = new Set(); // keys of the auto-generated suggestions, so they can be pinned to the top
let _awardsPickerSort     = 'plays';   // plays | az | recent
let _awardsPickerShown    = 60;        // how many rows of the current list are rendered ("Show more" bumps this)
let _awardsPickerRows     = [];        // items currently rendered in the body, index-addressable for clicks/keyboard
let _awardsPickerActive   = -1;        // keyboard-highlighted row, -1 = none
let _awardsPickerCtx      = { year: 0, catId: '', typeLabel: '' };
let _awardsPickerKeyHandler = null;    // document keydown listener, removed on close
let _awardsPickerDragFrom = -1;        // index of the nominee chip being dragged
const AWARDS_PICKER_PAGE  = 60;        // rows added per "Show more"
let _realLifeYear   = _awardsSavedYear('reallife', tzNow().getFullYear());

function _awardsDefaultData(year) {
  const cats = {};
  for (const cat of AWARD_CATEGORIES) {
    cats[cat.id] = { enabled: cat.defaultOn, nominees: [], winner: null };
  }
  return { year, eligStart: `${year}-01-01`, eligEnd: `${year}-12-31`, categories: cats };
}

/* ─── Awards persistence ───────────────────────────────────────────────────────
   A year's ballot used to live only in Firestore plus this tab's memory. That
   made it the one piece of user-authored work in the app with no local copy, so
   anything that stopped the write landing — signed out, offline, or Android
   simply discarding the backgrounded tab before the request went out — lost the
   nominees silently. Now every save writes localStorage first (synchronous, so
   it survives the tab being killed the instant afterwards) and Firestore second,
   and the load picks whichever copy was written last.                          */
function _awardsLocalKey(year) { return 'dc_awards_' + year; }

function _awardsReadLocal(year) {
  try {
    const raw = JSON.parse(localStorage.getItem(_awardsLocalKey(year)) || 'null');
    return (raw && typeof raw === 'object' && raw.categories) ? raw : null;
  } catch (e) { return null; }   // corrupt payload — fall back to the remote copy
}

function _awardsWriteLocal(year, data) {
  try { localStorage.setItem(_awardsLocalKey(year), JSON.stringify(data)); } catch (e) {}
}

// Newly-added categories won't exist in a ballot saved by an older build.
function _awardsFillCats(data) {
  for (const cat of AWARD_CATEGORIES) {
    if (!data.categories[cat.id]) data.categories[cat.id] = { enabled: cat.defaultOn, nominees: [], winner: null };
  }
  return data;
}

async function _awardsLoad(year) {
  if (_awardsYearData[year]) return _awardsYearData[year];
  const remote = (typeof dcLoadAwards === 'function') ? await dcLoadAwards(year) : null;
  const local  = _awardsReadLocal(year);

  // savedAt is stamped by _awardsSave. A local copy that is newer than the
  // remote one is a write that never made it off the device — take it, and push
  // it up so the next device to look gets it too.
  let chosen = null, rescued = false;
  if (local && remote) {
    if ((local.savedAt || 0) > (remote.savedAt || 0)) { chosen = local; rescued = true; }
    else chosen = remote;
  } else {
    chosen = local || remote;
    rescued = !!local && !remote;
  }

  // A device copy holding nominees the cloud no longer has is the one thing
  // that can still bring back a ballot another device wiped — keep it as a
  // backup before mirroring the cloud copy over it below.
  if (local && remote && !rescued && _awardsHasMissingNoms(local, remote)) {
    _backupAwardsSnapshot(year, local, 'device-copy');
  }

  _awardsYearData[year] = chosen ? _awardsFillCats(chosen) : _awardsDefaultData(year);
  // The base is the version the cloud is known to hold. A rescued local copy
  // was never uploaded, so its base is the remote copy it is about to replace.
  // With no remote at all (signed out, or sign-in not finished yet) the device
  // copy is the base: if the cloud turns out newer, only what this session
  // changes on top of it will win the merge; if the device copy is newer, its
  // savedAt passes the check and it goes up whole.
  _awardsSetBase(year, (rescued && remote) ? remote : chosen);
  if (rescued) _awardsSave(year);
  else if (remote && chosen === remote) _awardsWriteLocal(year, remote);   // keep the device copy a true mirror
  return _awardsYearData[year];
}

/* ─── Awards: merging instead of overwriting ─────────────────────────────────
   Each device holds a year in memory for the whole session and writes the
   whole year back on every click. A phone left open on an older ballot used to
   push it straight over nominees picked since on another phone. Now each save
   is checked against the version this device started from (the "base"): if
   the cloud has moved on, the two are merged category by category — the
   categories this device changed win, every other category keeps the cloud's
   newer picks — and the result is saved instead.                             */
const _awardsBase      = {};   // year → stable JSON of the version the cloud is known to hold
const _awardsPushChain = {};   // year → promise, so one year's saves go up strictly in order

// JSON with sorted keys, so two copies of the same ballot compare equal even
// when Firestore hands the fields back in a different order.
function _stableJson(v) {
  if (Array.isArray(v)) return '[' + v.map(_stableJson).join(',') + ']';
  if (v && typeof v === 'object') {
    return '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + _stableJson(v[k])).join(',') + '}';
  }
  return JSON.stringify(v === undefined ? null : v);
}

function _awardsSetBase(year, data) { _awardsBase[year] = data ? _stableJson(data) : null; }
function _awardsGetBase(year) {
  try { return _awardsBase[year] ? JSON.parse(_awardsBase[year]) : null; } catch (e) { return null; }
}

// Fields that describe a save rather than the ballot itself.
const _AWARDS_META_KEYS = new Set(['savedAt', 'device']);

// Three-way merge. `theirs` is the newer cloud copy; anything in `mine` that
// differs from `base` is a change this device made, and wins.
function _awardsMerge(base, mine, theirs) {
  const out = JSON.parse(JSON.stringify(theirs));
  out.categories = out.categories || {};
  const b = base || { categories: {} };
  const bc = b.categories || {};
  for (const k of new Set([...Object.keys(mine), ...Object.keys(b)])) {
    if (k === 'categories' || _AWARDS_META_KEYS.has(k)) continue;
    if (_stableJson(mine[k]) === _stableJson(b[k])) continue;
    if (k in mine) out[k] = mine[k]; else delete out[k];
  }
  for (const [id, cat] of Object.entries(mine.categories || {})) {
    if (_stableJson(cat) !== _stableJson(bc[id])) out.categories[id] = JSON.parse(JSON.stringify(cat));
  }
  return _awardsFillCats(out);
}

// Same ballot, ignoring when and where it was saved?
function _awardsSameBallot(a, b) {
  const strip = d => { const c = Object.assign({}, d); _AWARDS_META_KEYS.forEach(k => delete c[k]); return _stableJson(c); };
  return strip(a) === strip(b);
}

// Does `a` have a nominee or winner that `b` doesn't?
function _awardsHasMissingNoms(a, b) {
  const keys = d => {
    const s = new Set();
    for (const [id, c] of Object.entries(d?.categories || {})) {
      for (const n of (c.nominees || [])) s.add(id + '|' + _awardItemKey(n));
      if (c.winner) s.add(id + '|win|' + _awardItemKey(c.winner));
    }
    return s;
  };
  const kb = keys(b);
  for (const k of keys(a)) if (!kb.has(k)) return true;
  return false;
}

// Callers keep a reference to the year object and re-render from it after a
// save, so a merge result is copied into that same object, never swapped in.
function _awardsReplaceInPlace(year, next) {
  const data = _awardsYearData[year];
  if (!data) { _awardsYearData[year] = next; return; }
  for (const k of Object.keys(data)) delete data[k];
  Object.assign(data, next);
}

function _awardsRerenderIfShown(year) {
  // The Soundtrack's Grammys chapter reads these ballots too
  if (document.getElementById('stGrammysBody')?.offsetParent && typeof stRefreshGrammys === 'function') stRefreshGrammys();
  if (+year !== +_awardsYear) return;
  if (!document.getElementById('awardsCatList')?.offsetParent) return;
  awardsRenderYear(+year);
}

function _awardsQueuePush(year) {
  _awardsPushChain[year] = (_awardsPushChain[year] || Promise.resolve())
    .then(() => _awardsPush(year))
    .catch(e => console.warn('[dankcharts] awards push:', e));
  return _awardsPushChain[year];
}

async function _awardsPush(year) {
  if (typeof dcSaveAwardsChecked !== 'function') return;
  // Three tries covers a merge followed by another device saving yet again
  // in the same second; past that, the next click simply tries again.
  for (let attempt = 0; attempt < 3; attempt++) {
    if (!_awardsYearData[year]) return;
    // Snapshot what is being sent, so an edit made while the request is in
    // flight isn't mistaken for part of what the cloud now holds.
    const sentJson = JSON.stringify(_awardsYearData[year]);
    const sent     = JSON.parse(sentJson);
    const base     = _awardsGetBase(year);
    const res = await dcSaveAwardsChecked(year, sent, base ? (base.savedAt || 0) : 0);

    if (res.status === 'ok' || res.status === 'queued') {
      _awardsSetBase(year, sent);
      // The cloud copy just replaced came from another device — worth keeping
      // a copy of, since this is exactly the hand-off where ballots got lost.
      if (res.replaced && res.replaced.device !== _dcDeviceId() && !_awardsSameBallot(res.replaced, sent)) {
        _backupAwardsSnapshot(year, res.replaced, 'other-device');
      }
      return;
    }
    if (res.status === 'signed-out') return;
    if (res.status === 'conflict') {
      const remote = res.remote;
      _backupAwardsSnapshot(year, remote, 'conflict');
      const merged = _awardsMerge(base, _awardsYearData[year], remote);
      merged.savedAt = Date.now();
      merged.device  = _dcDeviceId();
      _awardsReplaceInPlace(year, merged);
      _awardsSetBase(year, remote);
      _awardsWriteLocal(year, merged);
      _awardsRerenderIfShown(year);
      if (typeof dcPlToast === 'function') dcPlToast(t('awards_merged_other_device'));
      continue;   // save the merged ballot
    }
    // A real rejection for a signed-in user is worth saying out loud.
    if (typeof dcIsSignedIn === 'function' && dcIsSignedIn() && typeof dcPlToast === 'function') {
      dcPlToast(t('awards_save_local_only'));
    }
    return;
  }
}

/* Pull in changes made on another device while this one sat in the background
   (or before sign-in finished). Runs when the app comes back to the front, so
   switching phones shows the latest ballot before the next click, not after. */
let _awardsLastCloudCheck = 0;
async function _awardsRefreshFromCloud(force) {
  if (typeof dcIsSignedIn !== 'function' || !dcIsSignedIn()) return;
  if (!force && Date.now() - _awardsLastCloudCheck < 10000) return;
  _awardsLastCloudCheck = Date.now();
  for (const year of Object.keys(_awardsYearData)) {
    await _awardsPushChain[year];   // let an in-flight save land first
    const remote = await dcLoadAwards(year);
    if (!remote) continue;
    const base = _awardsGetBase(year);
    if ((remote.savedAt || 0) <= (base ? (base.savedAt || 0) : 0)) continue;
    const merged = _awardsMerge(base, _awardsYearData[year], remote);
    const unsaved = !_awardsSameBallot(merged, remote);   // this device has changes the cloud lacks
    if (unsaved) { merged.savedAt = Date.now(); merged.device = _dcDeviceId(); }
    _awardsReplaceInPlace(year, merged);
    _awardsSetBase(year, remote);
    _awardsWriteLocal(year, merged);
    if (unsaved) _awardsQueuePush(year);
    _awardsRerenderIfShown(year);
  }
}

document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') _awardsRefreshFromCloud();
});

/* ─── Backups ─────────────────────────────────────────────────────────────────
   Snapshots of everything the user has authored — synced settings, every
   awards year, ratings — kept in their account (see firebase.js for storage)
   and restorable from Settings → Profile. Made:
     • once a day, the first time the app is opened signed in
     • by hand ("Back up now")
     • right before a restore, so a restore can itself be undone
     • for one awards year, whenever a save replaces or merges over another
       device's ballot, and when this device holds nominees the cloud lost —
       the hand-offs between phones where ballots have gone missing.
   A downloadable JSON file covers signed-out use and off-site copies (save
   it to Google Drive from the phone's share sheet). Playlists are left out:
   they already merge per playlist across devices.                          */
let _dcDeviceIdCache = null;
function _dcDeviceId() {
  if (_dcDeviceIdCache) return _dcDeviceIdCache;
  try {
    let id = localStorage.getItem('dc_device_id');
    if (!id) { id = Math.random().toString(36).slice(2, 10); localStorage.setItem('dc_device_id', id); }
    _dcDeviceIdCache = id;
  } catch (e) { _dcDeviceIdCache = 'nostorage'; }
  return _dcDeviceIdCache;
}

// Human-readable, for the backup list: "iPhone", "Android (installed app)"…
function _dcDeviceLabel() {
  const ua = navigator.userAgent || '';
  const os = /iPhone/.test(ua) ? 'iPhone' : /iPad/.test(ua) ? 'iPad' : /Android/.test(ua) ? 'Android'
           : /Windows/.test(ua) ? 'Windows' : /Macintosh/.test(ua) ? 'Mac' : /Linux/.test(ua) ? 'Linux' : 'Browser';
  let app = false;
  try { app = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true; } catch (e) {}
  return os + (app ? ' (installed app)' : '');
}

function _backupCountNoms(awards) {
  let n = 0;
  for (const d of Object.values(awards || {})) {
    for (const c of Object.values(d?.categories || {})) n += (c.nominees || []).length;
  }
  return n;
}

function _backupSummary(p) {
  const years = Object.keys(p.awards || {}).filter(y => _backupCountNoms({ y: p.awards[y] }) > 0).sort();
  return {
    settings: Object.keys(p.config || {}).length,
    years,
    nominees: _backupCountNoms(p.awards),
    ratings: Object.keys(p.ratings?.songs || {}).length + Object.keys(p.ratings?.albums || {}).length
  };
}

// Everything restorable, freshest copy of each piece.
async function _backupCollect() {
  const config = {};
  if (typeof SYNC_KEYS !== 'undefined') {
    for (const k of SYNC_KEYS) { const v = localStorage.getItem(k); if (v !== null) config[k] = v; }
  }
  // Awards: this device's copies, then the cloud's, then this session's memory
  // — each replacing the previous only when it was saved later.
  const awards = {};
  const offer = (y, d) => { if (d && d.categories && (!awards[y] || (d.savedAt || 0) >= (awards[y].savedAt || 0))) awards[y] = d; };
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (/^dc_awards_\d{4}$/.test(k)) offer(k.slice(10), _awardsReadLocal(k.slice(10)));
    }
  } catch (e) {}
  if (typeof dcLoadAllAwards === 'function') {
    for (const [y, d] of Object.entries(await dcLoadAllAwards())) offer(y, d);
  }
  for (const [y, d] of Object.entries(_awardsYearData)) offer(String(y), d);
  const hasRatings = Object.keys(_ratings.songs).length || Object.keys(_ratings.albums).length || _ratings.cfgTs;
  // The Daily tab's moods and notes (daily.js)
  const diary = typeof _dyDiary !== 'undefined' && Object.keys(_dyDiary.days).length ? _dyDiary : null;
  return JSON.parse(JSON.stringify({
    app: 'dankcharts', v: 1, createdAt: Date.now(),
    config, awards, ratings: hasRatings ? _ratings : null, diary
  }));
}

// Full backup to the account. Returns the id, or null.
async function dcBackupNow(reason) {
  if (typeof dcBackupWrite !== 'function' || typeof dcIsSignedIn !== 'function' || !dcIsSignedIn()) return null;
  const p = await _backupCollect();
  const summary = _backupSummary(p);
  if (!summary.settings && !summary.nominees && !summary.ratings) return null;   // nothing worth keeping yet
  return dcBackupWrite({ createdAt: p.createdAt, reason, kind: 'full', device: _dcDeviceLabel(), summary }, JSON.stringify(p));
}

// One awards year, at a risky moment. Throttled so a back-and-forth editing
// session between two phones doesn't fill the list with near-identical copies.
function _backupAwardsSnapshot(year, data, reason) {
  if (!data || !_backupCountNoms({ y: data })) return;
  if (typeof dcBackupWrite !== 'function' || typeof dcIsSignedIn !== 'function' || !dcIsSignedIn()) return;
  let seen = {};
  try { seen = JSON.parse(localStorage.getItem('dc_backup_seen') || '{}') || {}; } catch (e) {}
  // A device copy is only worth keeping once per version; the others at most
  // every half hour per year.
  const key = reason === 'device-copy' ? `${year}|dc|${data.savedAt || 0}` : `${year}|${reason}`;
  if (reason === 'device-copy' ? seen[key] : (Date.now() - (seen[key] || 0) < 30 * 60 * 1000)) return;
  seen[key] = Date.now();
  // Forget throttle entries older than a month so the key can't grow forever.
  for (const k of Object.keys(seen)) if (Date.now() - seen[k] > 30 * 86400000) delete seen[k];
  try { localStorage.setItem('dc_backup_seen', JSON.stringify(seen)); } catch (e) {}
  const p = { app: 'dankcharts', v: 1, createdAt: Date.now(), awards: { [year]: JSON.parse(JSON.stringify(data)) } };
  dcBackupWrite({ createdAt: p.createdAt, reason, kind: 'awards', device: _dcDeviceLabel(), summary: _backupSummary(p) }, JSON.stringify(p));
}

async function dcAutoBackup() {
  if (typeof dcBackupList !== 'function') return;
  const list = await dcBackupList();
  const lastFull = list.find(e => (e.kind || 'full') === 'full');
  if (!lastFull || Date.now() - lastFull.createdAt > 20 * 3600 * 1000) await dcBackupNow('daily');
}

// Called by firebase.js once sign-in has settled.
async function dcAfterSignInSync() {
  try {
    await _awardsRefreshFromCloud(true);
    await dcAutoBackup();
  } catch (e) {
    console.warn('[dankcharts] post sign-in sync:', e);
  }
}
window.dcAfterSignInSync = dcAfterSignInSync;

// Resolves after `ms` at the latest — the writes it guards keep going in the
// background (Firestore queues them), the restore just stops waiting on them.
function _withTimeout(p, ms) {
  return Promise.race([p, new Promise(r => setTimeout(r, ms))]);
}

// Puts a backup's contents back — locally and in the cloud — then reloads.
// Only the pieces the backup holds are touched: a one-year awards snapshot
// restores that year and nothing else.
async function _backupApply(p) {
  const now = Date.now();
  if (p.config && typeof SYNC_KEYS !== 'undefined') {
    for (const [k, v] of Object.entries(p.config)) {
      if (SYNC_KEYS.includes(k) && typeof v === 'string') localStorage.setItem(k, v);
    }
    if (typeof dcSaveUserConfig === 'function') await _withTimeout(dcSaveUserConfig(), 10000);
  }
  for (const [y, d] of Object.entries(p.awards || {})) {
    if (!/^\d{4}$/.test(y) || !d || !d.categories) continue;
    // Stamped now, so every other device sees the restored ballot as the newest.
    const copy = Object.assign({}, d, { savedAt: now, device: _dcDeviceId() });
    _awardsWriteLocal(y, copy);
    if (typeof dcSaveAwards === 'function') await _withTimeout(dcSaveAwards(y, copy), 10000);
  }
  if (p.ratings && typeof p.ratings === 'object') {
    // Every entry re-stamped so the per-entry merge on other devices keeps the
    // restored scores rather than their own older ones.
    const r = JSON.parse(JSON.stringify(p.ratings));
    for (const b of ['songs', 'albums']) {
      r[b] = r[b] || {};
      for (const e of Object.values(r[b])) if (e && typeof e === 'object') e.ts = now;
    }
    r.cfg = Object.assign(_ratingsDefaultCfg(), r.cfg || {});
    r.cfgTs = now;
    _ratings = Object.assign({ v: 1 }, r);
    try { localStorage.setItem('dc_ratings', JSON.stringify(_ratings)); } catch (e) {}
    if (typeof dcSaveRatings === 'function') await _withTimeout(dcSaveRatings(_ratings), 10000);
  }
  if (p.diary && p.diary.days && typeof p.diary.days === 'object') {
    // Re-stamped like ratings, so other devices keep the restored notes
    const dd = JSON.parse(JSON.stringify(p.diary));
    for (const e of Object.values(dd.days)) if (e && typeof e === 'object') e.ts = now;
    try { localStorage.setItem('dc_daily_diary', JSON.stringify(dd)); } catch (e) {}
    if (typeof dcSaveDiary === 'function') await _withTimeout(dcSaveDiary(dd), 10000);
  }
  location.reload();
}

// Reason → translation key; read through t() at render time so it follows the language
const BACKUP_REASON_LABELS = {
  'daily':          'set_bk_daily',
  'manual':         'set_bk_manual',
  'before-restore': 'set_bk_before_restore',
  'other-device':   'set_bk_other_device',
  'conflict':       'set_bk_conflict',
  'device-copy':    'set_bk_device_copy'
};

function _backupSummaryText(e) {
  const s = e.summary || {};
  const parts = [];
  const noms = n => n === 1 ? t('set_bk_nominees_1') : t('set_bk_nominees_n', { n: n || 0 });
  if (e.kind === 'awards') {
    parts.push(t('set_bk_years_awards', { years: (s.years || []).join(', ') }), noms(s.nominees));
  } else {
    if (s.settings) parts.push(t('set_bk_settings'));
    if (s.years?.length) {
      const yrs = s.years.length > 1 ? `${s.years[0]}–${s.years[s.years.length - 1]}` : s.years[0];
      parts.push(`${t('set_bk_awards', { years: yrs })} (${noms(s.nominees)})`);
    }
    if (s.ratings) parts.push(s.ratings === 1 ? t('set_bk_ratings_1') : t('set_bk_ratings_n', { n: s.ratings }));
  }
  return parts.join(' · ');
}

// Draws the list in Settings → Profile. Called each time that tab opens.
async function renderBackupsPanel() {
  const el = document.getElementById('setBackupsList');
  const nowBtn = document.getElementById('setBackupNowBtn');
  if (!el) return;
  const signedIn = typeof dcIsSignedIn === 'function' && dcIsSignedIn();
  if (nowBtn) nowBtn.hidden = !signedIn;
  if (!signedIn) {
    el.innerHTML = `<p class="src-modal-hint">${esc(t('set_backups_signed_out'))}</p>`;
    return;
  }
  el.innerHTML = `<p class="src-modal-hint">${esc(t('set_backups_loading'))}</p>`;
  const list = await dcBackupList();
  if (!list.length) {
    el.innerHTML = `<p class="src-modal-hint">${esc(t('set_backups_none'))}</p>`;
    return;
  }
  const fmt = ts => new Date(ts).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
  el.innerHTML = list.map(e => `
    <div class="bk-row">
      <div class="bk-main">
        <span class="bk-when">${esc(fmt(e.createdAt))}</span>
        <span class="bk-what">${esc(BACKUP_REASON_LABELS[e.reason] ? t(BACKUP_REASON_LABELS[e.reason]) : (e.reason || ''))}${e.device ? ' · ' + esc(e.device) : ''}</span>
        <span class="bk-sum">${esc(_backupSummaryText(e))}</span>
      </div>
      <button type="button" class="cert-reset-btn" onclick="backupsRestore(${esc(JSON.stringify(e.id))})">${esc(t('set_backup_restore'))}</button>
    </div>`).join('');
}

async function backupsNow() {
  const btn = document.getElementById('setBackupNowBtn');
  if (btn) { btn.disabled = true; btn.textContent = t('set_backing_up'); }
  const id = await dcBackupNow('manual');
  if (btn) { btn.disabled = false; btn.textContent = t('set_backup_now'); }
  if (typeof dcPlToast === 'function') dcPlToast(id ? t('set_bk_saved') : t('set_bk_failed'));
  renderBackupsPanel();
}

async function backupsRestore(id) {
  const list = await dcBackupList();
  const e = list.find(x => x.id === id);
  if (!e) return;
  const when = new Date(e.createdAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
  const what = e.kind === 'awards' ? t('set_bk_what_awards', { years: (e.summary?.years || []).join(', ') }) : t('set_bk_what_all');
  if (!confirm(t('set_bk_confirm', { when, what }))) return;
  const p = await dcBackupRead(id);
  if (!p) { dcPlToast(t('set_bk_open_failed')); return; }
  dcPlToast(t('set_bk_restoring'));
  await dcBackupNow('before-restore');
  await _backupApply(p);
}

async function backupsDownload() {
  const p = await _backupCollect();
  const blob = new Blob([JSON.stringify(p, null, 1)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `dankcharts-backup-${new Date().toLocaleDateString('en-CA')}.json`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

async function backupsUpload(input) {
  const file = input.files && input.files[0];
  input.value = '';   // so picking the same file again still fires onchange
  if (!file) return;
  let p = null;
  try { p = JSON.parse(await file.text()); } catch (e) {}
  if (!p || p.app !== 'dankcharts') { dcPlToast(t('set_bk_not_backup')); return; }
  const when = p.createdAt ? new Date(p.createdAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : t('set_bk_unknown_date');
  if (!confirm(t('set_bk_confirm_file', { when }))) return;
  dcPlToast(t('set_bk_restoring'));
  await dcBackupNow('before-restore');
  await _backupApply(p);
}

async function _awardsEnsureAllYearsLoaded() {
  if (!allPlays.length) return;
  const minYear = tzDate(allPlays[allPlays.length - 1].date).getFullYear();
  const maxYear = tzNow().getFullYear();
  const toLoad = [];
  for (let y = minYear; y <= maxYear; y++) {
    if (!_awardsYearData[y]) toLoad.push(_awardsLoad(y));
  }
  if (toLoad.length) await Promise.all(toLoad);
}

/* ── Artist Awards tab (2026-10-29) ─────────────────────────────────────
   Was two numbers and a folded list of categories. Now, top to bottom
   (_renderModalGrammyStrip → awPaint):
     .aw-hero    win rate as a ring, a verdict, where they rank among every
                 artist on your ballots, and four numbers
     .aw-big     the general field (Artist, Album, Song, Record of the Year,
                 Best New Artist), lit when won, outlined when nominated
     .aw-years   ceremony by ceremony; a year narrows the ballot below and
                 the readout links to that ceremony in Awards
     .aw-shelf   every win as a card with its artwork; opens the song/album
     .aw-works   their most nominated songs and albums, one pip a race
     .aw-rivals  head to head with the artists they met most in a decided race
     .aw-ballot  every nomination: won, lost (and to whom) or undecided
   Credited like the Stats & records summary: one nomination per nominated
   work, the lead artist always, featured artists when the switch is on.
   _aw keeps what the year and result filters need. */
let _aw = null;
const AW_BIG = ['artist_of_year', 'album_of_year', 'song_of_year', 'record_of_year', 'new_artist'];
const AW_BALLOT_PAGE = 30;
// The general field first, in AW_BIG's order
function _awBigRank(e) { const i = AW_BIG.indexOf(e.cat.id); return i < 0 ? 99 : i; }

// Every year from the first play to this one is in _awardsYearData
function _awAllLoaded() {
  if (!allPlays.length) return true;
  const min = _awardsFirstPlayYear(), max = tzNow().getFullYear();
  for (let y = min; y <= max; y++) if (!_awardsYearData[y]) return false;
  return true;
}

// onclick for a nominee: its song or album panel, another artist's panel, or
// nothing for this artist (their panel is the one open)
function _awOpenJs(item, type, self) {
  if (!item) return '';
  if (type === 'song' && item.title) return `openSongModal(${esc(JSON.stringify(item.title.toLowerCase().trim() + '|||' + (item.artist || '').toLowerCase().trim()))})`;
  if (type === 'album' && item.album) return `openAlbumModal(${esc(JSON.stringify(item.album + '|||' + (item.artist || '')))})`;
  const lead = _awardsCredits(item, false)[0] || item.artist || '';
  return lead && lead.toLowerCase() !== self ? `openArtistModal(${esc(JSON.stringify(lead))})` : '';
}
function _awName(item) { return item ? (item.title || item.album || item.artist || '') : ''; }
// Artwork through the same source cascade as everywhere else
function _awArt(id, item, type) {
  const el = document.getElementById(id);
  if (!el || !item) return;
  if (type === 'song') fetchAndInjectImage(el, { imgId: id, name: item.title, title: item.title, artist: item.artist, album: item.album || '', prefKey: 'song:' + (item.artist || '').toLowerCase() + '|||' + item.title.toLowerCase() }, 'song');
  else if (type === 'album') fetchAndInjectImage(el, { imgId: id, name: item.album, title: item.album, artist: item.artist, album: item.album, prefKey: 'album:' + (item.artist || '').toLowerCase() + '|||' + item.album.toLowerCase() }, 'album');
  else {
    const name = _awardsCredits(item, false)[0] || item.artist;
    fetchAndInjectImage(el, { imgId: id, name, prefKey: 'artist:' + name.toLowerCase() }, 'artist');
  }
}
// "2023, 2024" or "2019 – 2024" for a long run
function _awYears(list) {
  const ys = [...new Set(list)].sort();
  return ys.length > 3 ? `${ys[0]} – ${ys[ys.length - 1]} (${ys.length})` : ys.join(', ');
}

function _awCollect(artistName) {
  const lc = artistName.toLowerCase();
  const known = Object.fromEntries(AWARD_CATEGORIES.map(c => [c.id, c]));
  const creditsOf = n => n ? _awardsCredits(n, _awardsCreditFeatures).map(a => a.toLowerCase()) : [];
  // Credited the same way as the Stats & records summary: the full credit
  // as written, the lead artist, and featured artists when the switch is on
  const isHis = n => !!n && (n.artist === artistName || creditsOf(n).includes(lc));
  const entries = [], board = {}, h2h = {}, bigOn = new Set(), ballotYears = new Set();
  const bump = (name, f) => { const k = name.toLowerCase(); (board[k] || (board[k] = { noms: 0, wins: 0 }))[f]++; };
  for (const [ys, yd] of Object.entries(_awardsYearData)) {
    const year = parseInt(ys, 10);
    if (!yd?.categories) continue;
    for (const [catId, cd] of Object.entries(yd.categories)) {
      const cat = known[catId];
      if (!cat || !cd?.enabled) continue;
      const noms = cd.nominees || [];
      const wk = cd.winner ? _awardItemKey(cd.winner) : null;
      // A winner missing from an old ballot's list still earned the nomination
      const field = (wk && !noms.some(n => _awardItemKey(n) === wk)) ? [...noms, cd.winner] : noms;
      if (!field.length) continue;
      ballotYears.add(year);
      if (AW_BIG.includes(catId)) bigOn.add(catId);
      for (const n of field) for (const a of _awardsCredits(n, _awardsCreditFeatures)) bump(a, 'noms');
      if (cd.winner) for (const a of _awardsCredits(cd.winner, _awardsCreditFeatures)) bump(a, 'wins');
      const mine = field.filter(isHis);
      if (!mine.length) continue;
      for (const n of mine) {
        entries.push({ year, cat, item: n, decided: !!wk, isWin: !!wk && _awardItemKey(n) === wk, winner: cd.winner || null, field: field.length });
      }
      // Head to head: everyone else on a decided ballot, when one of the two won
      if (!wk) continue;
      const theyWon = isHis(cd.winner), winners = creditsOf(cd.winner);
      const others = new Map();
      for (const n of field) if (!isHis(n)) for (const a of _awardsCredits(n, _awardsCreditFeatures)) if (a.toLowerCase() !== lc) others.set(a.toLowerCase(), a);
      for (const [k, name] of others) {
        if (!theyWon && !winners.includes(k)) continue;
        const r = h2h[k] || (h2h[k] = { name, w: 0, l: 0 });
        if (theyWon) r.w++; else r.l++;
      }
    }
  }
  return { lc, entries, board, h2h, bigOn, ballotYears };
}

function _renderModalGrammyStrip(artistName) {
  const el = document.getElementById('modalAwards');
  if (!el) return;
  // Two views under one switch: your ballots (#awMine) and real life (#awReal)
  if (!document.getElementById('awMine')) {
    el.innerHTML = `<div class="aw-switch" role="tablist"></div>
      <div class="aw-view" id="awMine" role="tabpanel"></div>
      <div class="aw-view" id="awReal" role="tabpanel" hidden></div>`;
    el.querySelector('.aw-switch').addEventListener('click', e => {
      const b = e.target.closest('[data-aw-view]');
      if (b) awSetView(b.dataset.awView);
    });
  }
  const c = _awCollect(artistName);
  const keep = _aw && _aw.name === artistName;
  _aw = { name: artistName, ...c, year: keep ? _aw.year : null, filter: keep ? _aw.filter : 'all', limit: AW_BALLOT_PAGE };
  if (!_awr || _awr.name !== artistName) _awr = { name: artistName, status: 'idle', year: null, show: null, filter: 'all', limit: AW_BALLOT_PAGE, allShows: false };
  awPaint();
  awSetView(_awView(), true);
  const sec = el.closest('.dp-sec');
  if (sec && sec.classList.contains('dp-on')) awrEnsure();
  if (sec && !sec._awShow) {
    sec._awShow = true;
    sec.addEventListener('dp-show', () => {
      awrEnsure();
      _rkCountUp(document.getElementById(_awView() === 'real' ? 'awReal' : 'awMine'));
    });
  }
}

// Which view the switch is on, remembered per browser
function _awView() {
  try { return localStorage.getItem(AW_VIEW_LS) === 'real' ? 'real' : 'mine'; } catch (e) { return 'mine'; }
}
function awSetView(v, quiet) {
  try { localStorage.setItem(AW_VIEW_LS, v); } catch (e) {}
  const mine = document.getElementById('awMine'), real = document.getElementById('awReal');
  if (!mine || !real) return;
  mine.hidden = v === 'real';
  real.hidden = v !== 'real';
  awPaintSwitch();
  if (v === 'real') { awrEnsure(); awrPaint(); }
  if (!quiet) _rkCountUp(v === 'real' ? real : mine);
}
function awPaintSwitch() {
  const box = document.querySelector('#modalAwards .aw-switch');
  if (!box || !_aw) return;
  const v = _awView();
  const mineWins = _aw.entries.filter(e => e.isWin).length;
  const realN = _awr && _awr.status === 'ok' ? _awr.rows.filter(r => r.res === 'w').length : null;
  const btn = (key, label, icon, n) => `<button type="button" role="tab" class="aw-sw${v === key ? ' is-on' : ''}" data-aw-view="${key}" aria-selected="${v === key}">
      ${_amIco(icon)}<span>${esc(label)}</span>${n == null ? (key === 'real' && _awr?.status === 'loading' ? '<i class="aw-sw-dots" aria-hidden="true"></i>' : '') : `<b title="${esc(tCount('aw_win', n))}">${_amIco('trophy')}${n.toLocaleString()}</b>`}
    </button>`;
  box.innerHTML = btn('mine', t('modal_grammies_title').replace(/^\W+/, ''), 'headphones', mineWins)
    + btn('real', t('aw_view_real'), 'globe', realN);
}

function awPaint() {
  const el = document.getElementById('awMine');
  if (!el || !_aw) return;
  const ic = _amIco;
  const { entries, board, h2h, bigOn, lc } = _aw;
  const pct = (n, of) => of ? Math.round(n / of * 100) : 0;

  if (!entries.length) {
    el.innerHTML = !_awAllLoaded()
      ? `<div class="modal-records-wait">${esc(t('aw_loading'))}</div>`
      : `<div class="aw-empty">
          <span class="aw-empty-ico">${ic('trophy')}</span>
          <b>${esc(t('aw_empty_t'))}</b>
          <p>${esc(t('aw_empty_d', { name: _aw.name }))}</p>
          <button type="button" class="dc-btn" onclick="awOpenCeremony(${_awardsYear})">${ic('trophy')}<span>${esc(t('aw_open_awards'))}</span></button>
        </div>`;
    return;
  }

  const noms = entries.length;
  const wins = entries.filter(e => e.isWin).length;
  const decided = entries.filter(e => e.decided).length;
  const pending = noms - decided;
  const byYear = {};
  for (const e of entries) {
    const y = byYear[e.year] || (byYear[e.year] = { noms: 0, wins: 0 });
    y.noms++; if (e.isWin) y.wins++;
  }
  const years = Object.keys(byYear).map(Number).sort((a, b) => a - b);
  const bestYear = years.reduce((b, y) => (byYear[y].wins > byYear[b].wins || (byYear[y].wins === byYear[b].wins && byYear[y].noms > byYear[b].noms)) ? y : b, years[0]);

  /* ── Hero ── */
  const others = Object.entries(board).filter(([k]) => k !== lc).map(([, v]) => v);
  const rankOf = (f, v) => 1 + others.filter(o => o[f] > v).length;
  const winRank = wins ? rankOf('wins', wins) : 0, nomRank = rankOf('noms', noms);
  const rate = pct(wins, decided);
  const verdict = winRank === 1 ? 'goat' : wins >= 3 && rate >= 50 ? 'sweep' : wins >= 10 ? 'hof'
    : wins >= 3 ? 'regular' : wins ? 'winner' : decided >= 5 ? 'bridesmaid' : 'ballot';
  const range = years[0] === years[years.length - 1] ? String(years[0]) : `${years[0]} – ${years[years.length - 1]}`;
  const story = t(decided ? 'aw_story' : 'aw_story_open', {
    noms: `<b>${esc(tCount('aw_nom', noms))}</b>`,
    ceremonies: `<b>${esc(tCount('aw_cer', years.length))}</b>`,
    range: esc(range),
    pct: `<b>${rate}%</b>`
  });
  const chip = (icon, txt, gold) => `<span class="ls-chip${gold ? ' aw-chip--gold' : ''}">${icon ? ic(icon) : ''}${esc(txt)}</span>`;
  const artists = Object.keys(board).length;
  const stat = (v, label, cap, count) => `<div class="ls-stat">
      <span class="ls-stat-v${count ? ' rk-count' : ''}">${typeof v === 'number' ? v.toLocaleString() : esc(v)}</span>
      <span class="ls-stat-l">${esc(label)}</span>
      ${cap ? `<span class="ls-stat-c"><small>${esc(cap)}</small></span>` : ''}
    </div>`;
  const hero = `<div class="aw-hero${wins ? ' aw-hero--won' : ''}">
      <div class="aw-hero-top">
        <div class="aw-ring" style="--p:${decided ? rate : 0}" role="img" aria-label="${esc(t('aw_rate'))}: ${decided ? rate + '%' : '—'}">
          <span class="aw-ring-v">${decided ? rate + '<small>%</small>' : '—'}</span>
          <span class="aw-ring-l">${esc(t('aw_rate'))}</span>
        </div>
        <div class="aw-hero-txt">
          <span class="aw-kicker">${ic(wins ? 'trophy' : 'medal')}${esc(t('modal_grammies_title').replace(/^\W+/, ''))}</span>
          <b class="aw-verdict">${esc(t('aw_v_' + verdict))}</b>
          <p class="aw-story">${story}</p>
          <div class="aw-chips">
            ${wins ? chip(winRank === 1 ? 'crown' : 'trophy', t('aw_rank_wins', { n: winRank, of: artists.toLocaleString() }), winRank <= 3) : ''}
            ${chip(nomRank === 1 ? 'crown' : 'medal', t('aw_rank_noms', { n: nomRank }), nomRank === 1 && !wins)}
            ${pending ? chip('hourglass', t('aw_pending', { n: pending })) : ''}
          </div>
        </div>
      </div>
      <div class="ls-stats">
        ${stat(noms, t('aw_s_noms'), '', true)}
        ${stat(wins, t('aw_s_wins'), '', true)}
        ${stat(years.length, t('aw_s_cers'), '', true)}
        ${stat(String(bestYear), t('aw_s_best'), byYear[bestYear].wins ? tCount('aw_win', byYear[bestYear].wins) : tCount('aw_nom', byYear[bestYear].noms), false)}
      </div>
    </div>`;

  /* ── The big ones ── */
  const bigIds = AW_BIG.filter(id => bigOn.has(id));
  let bigHTML = '';
  if (bigIds.length) {
    let bigWon = 0;
    const tiles = bigIds.map((id, i) => {
      const cat = AWARD_CATEGORIES.find(c => c.id === id);
      const mine = entries.filter(e => e.cat.id === id);
      const wonY = mine.filter(e => e.isWin).map(e => e.year);
      const state = wonY.length ? 'won' : mine.length ? 'nom' : 'none';
      if (wonY.length) bigWon++;
      const line = state === 'won' ? t('aw_big_won', { years: _awYears(wonY) })
        : state === 'nom' ? t('aw_big_nom', { years: _awYears(mine.map(e => e.year)) }) : t('aw_big_none');
      return `<div class="aw-big-t aw-big-t--${state}" style="--i:${i}">
          <span class="aw-big-emo" aria-hidden="true">${cat.emoji}</span>
          <span class="aw-big-name">${esc(_ceremonyCatName(cat))}</span>
          <span class="aw-big-st">${state === 'won' ? ic('trophy') : ''}${esc(line)}</span>
        </div>`;
    }).join('');
    const sweep = bigWon === bigIds.length && bigIds.length >= 3;
    bigHTML = `<div class="ao-head rk-head">${esc(t('aw_h_big'))}<span>${sweep ? `<b class="aw-sweep">${ic('crown')}${esc(t('aw_big_sweep'))}</b>` : esc(t('aw_big_hint', { n: bigWon, m: bigIds.length }))}</span></div>
      <div class="aw-big">${tiles}</div>`;
  }

  /* ── Ceremony by ceremony ── */
  const allYears = [..._aw.ballotYears].sort((a, b) => a - b);
  const span = allYears.length ? Array.from({ length: allYears[allYears.length - 1] - allYears[0] + 1 }, (_, i) => allYears[0] + i) : years;
  const maxN = Math.max(...years.map(y => byYear[y].noms));
  const yearBars = span.map((y, i) => {
    const d = byYear[y] || { noms: 0, wins: 0 };
    const h = d.noms ? Math.max(8, d.noms / maxN * 100) : 0;
    return `<button type="button" class="aw-yr${d.noms ? '' : ' is-zero'}${y === bestYear ? ' is-best' : ''}${_aw.year === y ? ' is-on' : ''}" data-aw-year="${y}" style="--i:${i}" aria-pressed="${_aw.year === y}" aria-label="${y}: ${esc(tCount('aw_nom', d.noms))}, ${esc(tCount('aw_win', d.wins))}">
        <span class="aw-yr-n">${d.noms ? d.noms : ''}</span>
        <span class="aw-yr-col" style="--h:${h.toFixed(1)}"><span class="aw-yr-win" style="--w:${d.noms ? (d.wins / d.noms * 100).toFixed(1) : 0}%"></span></span>
        <span class="aw-yr-y">${y === bestYear ? ic('crown') : ''}${String(y).slice(span.length > 8 ? 2 : 0)}</span>
      </button>`;
  }).join('');
  const yearsHTML = `<div class="ao-head rk-head">${esc(t('aw_h_years'))}<span>${esc(t('aw_years_hint'))}</span></div>
    <div class="aw-years">
      <div class="aw-yrs" style="--n:${span.length}">${yearBars}</div>
      <div class="aw-legend"><span><i class="aw-key aw-key--nom"></i>${esc(t('aw_s_noms'))}</span><span><i class="aw-key aw-key--win"></i>${esc(t('aw_s_wins'))}</span></div>
      <div class="ls-read aw-read" aria-live="polite"></div>
    </div>`;

  /* ── Trophy shelf ── */
  const won = entries.filter(e => e.isWin).sort((a, b) => (b.year - a.year) || (_awBigRank(a) - _awBigRank(b)));
  const shelfHTML = !won.length ? '' : `
    <div class="ao-head rk-head">${esc(t('aw_h_shelf'))}<span>${esc(t('aw_shelf_hint'))}</span></div>
    <div class="aw-shelf" tabindex="0" role="list" aria-label="${esc(t('aw_h_shelf'))}">
      ${won.map((e, i) => {
        const js = _awOpenJs(e.item, e.cat.type, lc);
        const tag = js ? 'button type="button"' : 'div';
        return `<${tag} role="listitem" class="aw-tro${_awBigRank(e) < 99 ? ' is-big' : ''}" style="--i:${i}"${js ? ` onclick="${js}"` : ''}>
          <span class="aw-tro-art${e.cat.type === 'artist' ? ' is-round' : ''}" id="awTro-${i}"><span class="thumb-initials">${esc(initials(_awName(e.item)))}</span></span>
          <span class="aw-tro-badge" aria-hidden="true">${ic('trophy')}<b>${e.year}</b></span>
          <span class="aw-tro-cat"><i aria-hidden="true">${e.cat.emoji || '🏆'}</i>${esc(_ceremonyCatName(e.cat))}</span>
          <span class="aw-tro-name">${esc(_awName(e.item))}</span>
        </${tag.split(' ')[0]}>`;
      }).join('')}
    </div>`;

  /* ── Most decorated songs and albums ── */
  const works = {};
  for (const e of entries) {
    if (e.cat.type === 'artist') continue;
    const k = e.cat.type + ':' + _awName(e.item).toLowerCase();
    const w = works[k] || (works[k] = { type: e.cat.type, item: e.item, noms: 0, wins: 0, list: [] });
    w.noms++; if (e.isWin) w.wins++;
    w.list.push(e);
  }
  const topWorks = Object.values(works).sort((a, b) => (b.wins - a.wins) || (b.noms - a.noms)).slice(0, 5);
  const worksHTML = !topWorks.length ? '' : `
    <div class="ao-head rk-head">${esc(t('aw_h_works'))}<span>${esc(t('aw_works_hint'))}</span></div>
    <div class="aw-works">
      ${topWorks.map((w, i) => {
        w.list.sort((a, b) => (a.year - b.year) || (b.isWin - a.isWin));
        const pips = w.list.map(e => `<i class="aw-pip aw-pip--${e.isWin ? 'won' : e.decided ? 'lost' : 'open'}" title="${e.year} · ${esc(_ceremonyCatName(e.cat))}"></i>`).join('');
        return `<button type="button" class="aw-work" style="--i:${i}" onclick="${_awOpenJs(w.item, w.type, lc)}">
          <span class="aw-work-n">${i + 1}</span>
          <span class="aw-work-art" id="awWork-${i}"><span class="thumb-initials">${esc(initials(_awName(w.item)))}</span></span>
          <span class="aw-work-main">
            <span class="aw-work-name">${esc(_awName(w.item))}</span>
            <span class="aw-work-meta">${esc(t(w.type === 'album' ? 'aw_album' : 'aw_song'))} · ${esc(tCount('aw_nom', w.noms))}${w.wins ? ` · <b>${esc(tCount('aw_win', w.wins))}</b>` : ''}</span>
          </span>
          <span class="aw-pips">${pips}</span>
        </button>`;
      }).join('')}
    </div>`;

  /* ── Head to head ── */
  const rivals = Object.values(h2h).sort((a, b) => (b.w + b.l - a.w - a.l) || (b.l - a.l) || a.name.localeCompare(b.name)).slice(0, 5);
  const rivalsHTML = !rivals.length ? '' : `
    <div class="ao-head rk-head">${esc(t('aw_h_rivals'))}<span>${esc(t('aw_rivals_hint'))}</span></div>
    <div class="aw-rivals">
      ${rivals.map((r, i) => {
        const tone = r.w > r.l ? 'own' : r.l > r.w ? 'nemesis' : 'even';
        return `<button type="button" class="aw-rv aw-rv--${tone}" style="--i:${i}" onclick="openArtistModal(${esc(JSON.stringify(r.name))})">
          <span class="aw-rv-art" id="awRv-${i}"><span class="thumb-initials">${esc(initials(r.name))}</span></span>
          <span class="aw-rv-main">
            <span class="aw-rv-top"><span class="aw-rv-name">${esc(r.name)}</span><span class="aw-rv-tag">${esc(t('aw_rv_' + tone))}</span></span>
            <span class="aw-rv-bar"><span style="--w:${pct(r.w, r.w + r.l)}%"></span></span>
            <span class="aw-rv-cap">${esc(t('aw_rv_cap', { w: r.w, l: r.l }))}</span>
          </span>
          <span class="aw-rv-score"><b>${r.w}</b><i>–</i><span>${r.l}</span></span>
        </button>`;
      }).join('')}
    </div>`;

  el.innerHTML = `${hero}${bigHTML}${yearsHTML}${shelfHTML}${worksHTML}${rivalsHTML}
    <div class="ao-head rk-head">${esc(t('aw_h_ballot'))}<span id="awBallotHint"></span></div>
    <div class="aw-filters" role="group" aria-label="${esc(t('aw_h_ballot'))}"></div>
    <div class="aw-ballot"></div>`;

  won.forEach((e, i) => _awArt('awTro-' + i, e.item, e.cat.type));
  topWorks.forEach((w, i) => _awArt('awWork-' + i, w.item, w.type));
  rivals.forEach((r, i) => _awArt('awRv-' + i, { artist: r.name }, 'artist'));

  if (!el._awWired) {
    el._awWired = true;
    el.addEventListener('click', e => {
      const y = e.target.closest('[data-aw-year]');
      if (y) { _aw.year = _aw.year === +y.dataset.awYear ? null : +y.dataset.awYear; _aw.limit = AW_BALLOT_PAGE; awPaintBallot(); return; }
      const f = e.target.closest('[data-aw-filter]');
      if (f) { _aw.filter = f.dataset.awFilter; _aw.limit = AW_BALLOT_PAGE; awPaintBallot(); return; }
      if (e.target.closest('[data-aw-clear]')) { _aw.year = null; awPaintBallot(); return; }
      if (e.target.closest('[data-aw-more]')) { _aw.limit = Infinity; awPaintBallot(); }
    });
  }
  awPaintBallot();
  const sec = el.closest('.dp-sec');
  if (sec && sec.classList.contains('dp-on')) _rkCountUp(el);
}

// The parts a year or a filter changes: the bars' state, the readout, the ballot
function awPaintBallot() {
  const el = document.getElementById('awMine');
  if (!el || !_aw) return;
  const ic = _amIco;
  const { entries, lc } = _aw;
  el.querySelectorAll('.aw-yr').forEach(b => {
    const on = +b.dataset.awYear === _aw.year;
    b.classList.toggle('is-on', on);
    b.setAttribute('aria-pressed', on);
  });
  el.querySelector('.aw-yrs')?.classList.toggle('has-pick', _aw.year != null);

  // Readout: the year picked, or every ceremony
  const read = el.querySelector('.aw-read');
  if (read) {
    const pool = _aw.year == null ? entries : entries.filter(e => e.year === _aw.year);
    const w = pool.filter(e => e.isWin);
    const star = w.slice().sort((a, b) => _awBigRank(a) - _awBigRank(b))[0];
    read.innerHTML = `<span class="ls-read-when">${_aw.year == null ? esc(t('aw_read_all')) : _aw.year}</span>
      <span class="ls-read-n">${pool.length ? `<b>${pool.length}</b> ${esc(tUnit('aw_nom', pool.length))} · <b>${w.length}</b> ${esc(tUnit('aw_win', w.length))}` : esc(t('aw_read_none'))}</span>
      ${star ? `<span class="aw-read-star">${star.cat.emoji || '🏆'} ${esc(_ceremonyCatName(star.cat))}</span>` : ''}
      ${_aw.year != null ? `<button type="button" class="ls-read-song" onclick="awOpenCeremony(${_aw.year})">${esc(t('aw_open_year', { year: _aw.year }))}<span>→</span></button>` : ''}`;
  }

  // Filter chips, with counts for the year picked
  const inYear = _aw.year == null ? entries : entries.filter(e => e.year === _aw.year);
  const test = { all: () => true, won: e => e.isWin, lost: e => e.decided && !e.isWin, pending: e => !e.decided };
  const counts = Object.fromEntries(Object.keys(test).map(k => [k, inYear.filter(test[k]).length]));
  if (_aw.filter !== 'all' && !counts[_aw.filter]) _aw.filter = 'all';
  const filters = el.querySelector('.aw-filters');
  if (filters) filters.innerHTML = Object.keys(test).filter(k => k === 'all' || counts[k]).map(k =>
      `<button type="button" class="aw-f aw-f--${k}${_aw.filter === k ? ' is-on' : ''}" data-aw-filter="${k}" aria-pressed="${_aw.filter === k}">${esc(t('aw_f_' + k))}<b>${counts[k]}</b></button>`).join('')
    + (_aw.year != null ? `<button type="button" class="aw-f aw-f--year" data-aw-clear>${_aw.year}<span aria-label="${esc(t('aw_clear_year'))}">✕</span></button>` : '');

  // The ballot, newest ceremony first, wins then the big categories first
  const list = inYear.filter(test[_aw.filter])
    .sort((a, b) => (b.year - a.year) || (b.isWin - a.isWin) || (b.decided - a.decided) || (_awBigRank(a) - _awBigRank(b)));
  const shown = list.slice(0, _aw.limit);
  let html = '', lastYear = null;
  for (const e of shown) {
    if (e.year !== lastYear) {
      lastYear = e.year;
      const ye = inYear.filter(x => x.year === e.year);
      html += `<div class="aw-bl-year"><b>${e.year}</b><span>${esc(t('aw_year_tally', { wins: ye.filter(x => x.isWin).length, noms: ye.length }))}</span></div>`;
    }
    const js = _awOpenJs(e.item, e.cat.type, lc);
    const work = e.cat.type === 'artist' ? '' : (js
      ? `<button type="button" class="aw-bl-work" onclick="${js}">${esc(_awName(e.item))}</button>`
      : `<span class="aw-bl-work">${esc(_awName(e.item))}</span>`);
    let res;
    if (e.isWin) res = `<span class="aw-res aw-res--won">${ic('trophy')}${esc(t('aw_won'))}</span>`;
    else if (!e.decided) res = `<span class="aw-res aw-res--open">${ic('hourglass')}${esc(t('aw_undecided'))}</span>`;
    else {
      const wjs = _awOpenJs(e.winner, e.cat.type, lc);
      const by = e.cat.type === 'artist' ? '' : (_awardsCredits(e.winner, false)[0] || e.winner.artist || '');
      res = `<span class="aw-res aw-res--lost"><small>${esc(t('aw_lost_to'))}</small>${wjs
        ? `<button type="button" onclick="${wjs}">${esc(_awName(e.winner))}</button>` : `<span>${esc(_awName(e.winner))}</span>`}${by ? `<small class="aw-res-by">${esc(by)}</small>` : ''}</span>`;
    }
    html += `<div class="aw-bl aw-bl--${e.isWin ? 'won' : e.decided ? 'lost' : 'open'}">
        <span class="aw-bl-emo" aria-hidden="true">${e.cat.emoji || '🏆'}</span>
        <span class="aw-bl-main"><span class="aw-bl-cat">${esc(_ceremonyCatName(e.cat))}</span>${work}</span>
        ${res}
      </div>`;
  }
  if (list.length > shown.length) html += `<button type="button" class="aw-more" data-aw-more>${esc(t('aw_show_more', { n: list.length - shown.length }))}</button>`;
  const box = el.querySelector('.aw-ballot');
  if (box) box.innerHTML = html || `<div class="aw-none">${esc(t('aw_read_none'))}</div>`;
  const hint = document.getElementById('awBallotHint');
  if (hint) hint.textContent = _aw.year == null ? '' : String(_aw.year);
}

// The ceremony itself, in Awards → My Grammys, on that year
function awOpenCeremony(year) {
  document.getElementById('artistModal').classList.remove('open');
  _awardsRememberYear('mygrammys', year);
  _awardsYear = year;
  _awardsSubTab = 'mygrammys';
  document.querySelector('#periodNav button[data-period="awards"]')?.click();
}

/* ── Real-life awards (2026-10-29) ──────────────────────────────────────
   The Awards tab's second view: the artist's real awards and nominations,
   read from Wikipedia's "List of awards and nominations received by …"
   page, or from the awards part of their article when they have no list
   of their own. One or two requests, then kept on the device for a week.
     .aw-hero    real wins, nominations, win rate, shows, Grammys
     .awr-vs     you against the industry: what you both crowned, what only
                 you did, what only the industry did
     .awr-shows  the award shows they were up at most, Grammys first; a
                 show narrows everything below it
     .aw-years   year by year, as in My Grammies; a year narrows the list
     .aw-works   their most nominated work (opens it when it's in your library)
     .aw-ballot  every row, filtered by result, show and year
   _awr holds the rows and the filters. */
let _awr = null;
const AW_VIEW_LS = 'dc_aw_view';
const AWR_LS = 'dc_awr_cache';
const AWR_TTL = 7 * 86400000;
const AWR_KEEP = 20;   // artists kept on the device, most recently looked up
const AWR_SHOWS = 8;   // award shows shown before "Show all"

function _awrCacheAll() {
  try { return JSON.parse(localStorage.getItem(AWR_LS) || '{}') || {}; } catch (e) { return {}; }
}
function _awrCacheRead(name) {
  const c = _awrCacheAll()[name.toLowerCase()];
  return c && Date.now() - c.at < AWR_TTL ? c : null;
}
// Rows are kept as [show, year, category, work, result] to stay small; a
// full device drops the oldest half and tries once more
function _awrCacheWrite(name, val) {
  const all = _awrCacheAll();
  all[name.toLowerCase()] = { at: Date.now(), title: val.title, rows: val.rows.map(r => [r.show, r.year, r.cat, r.work, r.res]) };
  let keys = Object.keys(all).sort((a, b) => all[b].at - all[a].at);
  for (const k of keys.slice(AWR_KEEP)) delete all[k];
  try { localStorage.setItem(AWR_LS, JSON.stringify(all)); }
  catch (e) {
    keys = Object.keys(all).sort((a, b) => all[b].at - all[a].at);
    for (const k of keys.slice(Math.max(1, keys.length >> 1))) delete all[k];
    try { localStorage.setItem(AWR_LS, JSON.stringify(all)); } catch (e2) {}
  }
}

async function _awrWiki(params) {
  const url = 'https://en.wikipedia.org/w/api.php?' + new URLSearchParams({ ...params, format: 'json', formatversion: '2', redirects: '1', origin: '*' });
  // Same as _rlWikiFetchPage: one short wait and a second try on a 429
  let r = await fetch(url);
  if (r.status === 429 || r.status >= 500) {
    await new Promise(res => setTimeout(res, 1500));
    r = await fetch(url);
  }
  if (!r.ok) throw new Error('wikipedia ' + r.status);
  return r.json();
}
async function _awrParsePage(title) {
  const j = await _awrWiki({ action: 'parse', page: title, prop: 'text' });
  if (!j || j.error || !j.parse) return null;
  return { title: j.parse.title, doc: new DOMParser().parseFromString(j.parse.text || '', 'text/html') };
}
// The artist's article: the search hit named like them (a "(singer)" suffix
// is fine) that describes a music act, as wikiArtistImage does
async function _awrFindArticle(name) {
  const j = await _awrWiki({ action: 'query', generator: 'search', gsrsearch: name + ' music', gsrlimit: '5', prop: 'description' });
  const pages = (j?.query?.pages || []).slice().sort((a, b) => (a.index || 0) - (b.index || 0));
  const want = _artNorm(name);
  const hit = pages.find(p => _artNorm(p.title.replace(/\s*\(.*\)$/, '')) === want &&
    /singer|rapper|band|musician|music|dj|producer|songwriter|group|duo|composer|vocalist|artist/i.test(p.description || ''));
  return hit ? hit.title : null;
}

// → { rows, title } — rows is empty when Wikipedia has nothing to go on
async function _awrFetch(name) {
  const LIST = 'List of awards and nominations received by ';
  const page = await _awrParsePage(LIST + name);
  if (page && page.title.startsWith('List of awards')) return { rows: _awrRows(page.doc, name, false), title: page.title };
  // No list under that name. A list title can also redirect to the article's
  // awards section; otherwise find the article by search.
  const article = page ? page.title : await _awrFindArticle(name);
  if (!article) return { rows: [], title: null };
  const art = page || await _awrParsePage(article);
  if (!art) return { rows: [], title: null };
  // "Main article: List of awards…" under another spelling of the name
  const base = _artNorm(article.replace(/\s*\(.*\)$/, ''));
  for (const a of art.doc.querySelectorAll('a[href*="/wiki/List_of_awards_and_nominations_received_by_"]')) {
    const t = decodeURIComponent(a.getAttribute('href').split('/wiki/')[1].split('#')[0]).replace(/_/g, ' ');
    const who = _artNorm(t.slice(LIST.length).replace(/\s*\(.*\)$/, ''));
    if (who !== base && who !== _artNorm(name)) continue;
    const lp = await _awrParsePage(t);
    const rows = lp ? _awrRows(lp.doc, name, false) : [];
    if (rows.length) return { rows, title: lp.title };
    break;
  }
  return { rows: _awrRows(art.doc, name, true), title: art.title };
}

// A cell's text without footnote marks, edit links or hidden sort keys
const _awrTextCache = new WeakMap();
function _awrText(el) {
  if (!el) return '';
  if (_awrTextCache.has(el)) return _awrTextCache.get(el);
  const c = el.cloneNode(true);
  c.querySelectorAll('sup, .reference, .mw-editsection, style, .sortkey, [style*="display:none"]').forEach(x => x.remove());
  const s = c.textContent.replace(/\[(?:\d+|[a-z]|edit)\]/gi, '').replace(/\s+/g, ' ').trim();
  _awrTextCache.set(el, s);
  return s;
}
// A table as a grid with rowspans and colspans filled in: grid[row][col] = cell
function _awrGrid(table) {
  const grid = [];
  const trs = [...table.querySelectorAll('tr')].filter(tr => tr.closest('table') === table);
  trs.forEach((tr, r) => {
    grid[r] = grid[r] || [];
    let c = 0;
    for (const cell of tr.children) {
      if (cell.tagName !== 'TD' && cell.tagName !== 'TH') continue;
      while (grid[r][c]) c++;
      const rs = Math.min(parseInt(cell.getAttribute('rowspan'), 10) || 1, 600);
      const cs = Math.min(parseInt(cell.getAttribute('colspan'), 10) || 1, 12);
      for (let i = 0; i < rs; i++) for (let k = 0; k < cs; k++) (grid[r + i] = grid[r + i] || [])[c + k] = cell;
      c += cs;
    }
  });
  return grid.slice(0, trs.length);
}

/* Every awards table on a page → [{ show, year, cat, work, res }]. Columns
   are found by their headings, since lists order them differently. A table
   with no award column takes the show from the heading above it. Rows that
   are not a result (a world record, a ranking) are left out. With
   sectionOnly, only tables under an awards heading of an article count. */
function _awrRows(doc, name, sectionOnly) {
  const out = [], seen = new Set(), self = _artNorm(name);
  const SKIP_H2 = /listicle|record|guinness|honorary|other accolades|ranking|notes|references|see also|external links/i;
  let inAwards = !sectionOnly, heading = '';
  for (const node of doc.querySelectorAll('h2, h3, h4, table.wikitable')) {
    if (node.tagName !== 'TABLE') {
      const txt = _awrText(node);
      if (node.tagName === 'H2') {
        inAwards = sectionOnly ? /award|accolade|nomination/i.test(txt) && !SKIP_H2.test(txt) : !SKIP_H2.test(txt);
        heading = /^(awards?( and nominations)?|accolades|nominations)$/i.test(txt) ? '' : txt;
      } else heading = txt;
      continue;
    }
    if (!inAwards) continue;
    const grid = _awrGrid(node);
    const hr = grid.findIndex(row => row && row.length && row.every(c => c.tagName === 'TH'));
    if (hr < 0) continue;
    const heads = grid[hr].map(c => _awrText(c).toLowerCase());
    const col = re => heads.findIndex(h => re.test(h));
    const resCol = col(/^(results?|outcome)\b/);
    let catCol = col(/^(categor|award category|nominated category)/);
    let awardCol = col(/^(awards?|ceremon(?:y|ies)|organi[sz]ations?|associations?|events?|award shows?|awarding bod(?:y|ies))\b(?! category)/);
    const yearCol = col(/^(year|date)/);
    const workCol = col(/(nominee|nominated work|recipient|work|honoree|title)/);
    const caption = _awrText(node.querySelector('caption'));
    // "Year | Nominee | Award | Result" under a show's heading: Award is the category
    if (catCol < 0 && awardCol >= 0 && (heading || caption)) { catCol = awardCol; awardCol = -1; }
    if (resCol < 0 || catCol < 0) continue;
    for (let r = hr + 1; r < grid.length; r++) {
      const row = grid[r];
      if (!row || !row[resCol] || row.every(c => c.tagName === 'TH')) continue;
      const get = i => i < 0 ? '' : _awrText(row[i]);
      const rc = row[resCol], rt = get(resCol), cls = rc.className || '';
      const res = /table-yes|\byes\b/.test(cls) || /^(won|winner|win|inducted|honou?red|recipient)\b/i.test(rt) ? 'w'
        : /table-tba|pending|\btba\b|upcoming/i.test(cls + ' ' + rt) ? 'p'
        : /table-no|\bno\b|nominat|shortlist|longlist|runner|finalist|place|\d(st|nd|rd|th)\b/i.test(cls + ' ' + rt) ? 'n' : null;
      if (!res) continue;
      let show = awardCol >= 0 ? get(awardCol) : (heading || caption);
      const year = +((get(yearCol) || show || get(catCol)).match(/\b(19[5-9]\d|20\d\d)\b/) || [])[1] || 0;
      show = show.replace(/^(19|20)\d\d\s+/, '').replace(/\s*\((?:19|20)\d\d\)$/, '').trim();
      const cat = get(catCol);
      // "I Like It" (with Cardi B and J Balvin) → I Like It
      let work = get(workCol);
      const quoted = work.match(/^["“]([^"”]+)["”]/);
      work = (quoted ? quoted[1] : work.replace(/^["“”'‘’]+|["“”'‘’]+$/g, '')).trim();
      // The artist themselves: Herself, their own name ("Muse (with …)"), or
      // their surname alone ("Swift")
      const bare = _artNorm(work.replace(/\s*\(.*\)$/, ''));
      if (/^(her|him|them|it|your|one)sel(f|ves)$|^self$/i.test(work) || bare === self || (bare && !bare.includes(' ') && self.split(' ').includes(bare))) work = '';
      if (!show || !cat || !year) continue;
      const key = [show, year, cat, work].join('|').toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ show, year, cat, work, res });
    }
  }
  return out;
}

// Start the lookup once per artist: the device copy if it is fresh, else Wikipedia
async function awrEnsure(force) {
  const st = _awr;
  if (!st || (!force && st.status !== 'idle')) return;
  const cached = !force && _awrCacheRead(st.name);
  if (cached) {
    Object.assign(st, { status: cached.rows.length ? 'ok' : 'none', title: cached.title,
      rows: cached.rows.map(([show, year, cat, work, res]) => ({ show, year, cat, work, res })) });
    awPaintSwitch(); awrPaint();
    return;
  }
  st.status = 'loading';
  awPaintSwitch(); awrPaint();
  try {
    const got = await _awrFetch(st.name);
    if (_awr !== st) return;   // another artist opened meanwhile
    _awrCacheWrite(st.name, got);
    Object.assign(st, { status: got.rows.length ? 'ok' : 'none', title: got.title, rows: got.rows });
  } catch (e) {
    if (_awr !== st) return;
    st.status = 'error';
  }
  awPaintSwitch(); awrPaint();
  const real = document.getElementById('awReal');
  if (real && !real.hidden) _rkCountUp(real);
}

function awrPaint() {
  const el = document.getElementById('awReal');
  if (!el || !_awr || el.hidden) return;
  const ic = _amIco, st = _awr;
  if (!el._awrWired) {
    el._awrWired = true;
    el.addEventListener('click', awrClick);
  }
  if (st.status === 'idle' || st.status === 'loading') {
    el.innerHTML = `<div class="awr-wait"><span class="aw-empty-ico">${ic('globe')}</span><span>${esc(t('awr_loading'))}</span></div>`;
    return;
  }
  if (st.status !== 'ok') {
    const err = st.status === 'error';
    el.innerHTML = `<div class="aw-empty">
        <span class="aw-empty-ico">${ic(err ? 'cloud' : 'globe')}</span>
        <b>${esc(t(err ? 'awr_error_t' : 'awr_none_t'))}</b>
        <p>${esc(t(err ? 'awr_error_d' : 'awr_none_d', { name: st.name }))}</p>
        <button type="button" class="dc-btn" data-awr-refresh>${ic('refresh')}<span>${esc(t('awr_retry'))}</span></button>
      </div>`;
    return;
  }

  const rows = st.rows;
  const pct = (n, of) => of ? Math.round(n / of * 100) : 0;
  const noms = rows.length, wins = rows.filter(r => r.res === 'w').length;
  const decided = rows.filter(r => r.res !== 'p').length, pending = noms - decided;
  const rate = pct(wins, decided);
  const byYear = {}, byShow = {};
  for (const r of rows) {
    const y = byYear[r.year] || (byYear[r.year] = { n: 0, w: 0 });
    const s = byShow[r.show] || (byShow[r.show] = { name: r.show, n: 0, w: 0 });
    y.n++; s.n++;
    if (r.res === 'w') { y.w++; s.w++; }
  }
  const years = Object.keys(byYear).map(Number).sort((a, b) => a - b);
  const bestYear = years.reduce((b, y) => (byYear[y].w > byYear[b].w || (byYear[y].w === byYear[b].w && byYear[y].n > byYear[b].n)) ? y : b, years[0]);
  const isGrammy = s => /^grammy awards?$/i.test(s);
  const shows = Object.values(byShow).sort((a, b) => (isGrammy(b.name) - isGrammy(a.name)) || (b.n - a.n) || (b.w - a.w));
  const grammy = shows.find(s => isGrammy(s.name));

  /* ── Hero ── */
  const verdict = wins >= 100 ? 'legend' : wins >= 25 ? 'heavy' : wins >= 5 ? 'decorated' : wins ? 'winner' : decided ? 'chasing' : 'pending';
  const range = years[0] === years[years.length - 1] ? String(years[0]) : `${years[0]} – ${years[years.length - 1]}`;
  const story = t(decided ? 'awr_story' : 'awr_story_open', {
    noms: `<b>${esc(tCount('aw_nom', noms))}</b>`,
    shows: `<b>${esc(tCount('awr_show', shows.length))}</b>`,
    range: esc(range),
    pct: `<b>${rate}%</b>`
  });
  const chip = (icon, txt, gold) => `<span class="ls-chip${gold ? ' aw-chip--gold' : ''}">${icon ? ic(icon) : ''}${esc(txt)}</span>`;
  const stat = (v, label, cap, count) => `<div class="ls-stat">
      <span class="ls-stat-v${count ? ' rk-count' : ''}">${typeof v === 'number' ? v.toLocaleString() : esc(v)}</span>
      <span class="ls-stat-l">${esc(label)}</span>
      ${cap ? `<span class="ls-stat-c"><small>${esc(cap)}</small></span>` : ''}
    </div>`;
  const src = st.title ? `https://en.wikipedia.org/wiki/${encodeURIComponent(st.title.replace(/ /g, '_'))}` : 'https://en.wikipedia.org/';
  const hero = `<div class="aw-hero aw-hero--real${wins ? ' aw-hero--won' : ''}">
      <div class="aw-hero-top">
        <div class="aw-ring" style="--p:${decided ? rate : 0}" role="img" aria-label="${esc(t('aw_rate'))}: ${decided ? rate + '%' : '—'}">
          <span class="aw-ring-v">${decided ? rate + '<small>%</small>' : '—'}</span>
          <span class="aw-ring-l">${esc(t('aw_rate'))}</span>
        </div>
        <div class="aw-hero-txt">
          <span class="aw-kicker">${ic('globe')}${esc(t('aw_view_real'))}</span>
          <b class="aw-verdict">${esc(t('awr_v_' + verdict))}</b>
          <p class="aw-story">${story}</p>
          <div class="aw-chips">
            ${grammy ? chip('trophy', t('awr_grammys', { w: grammy.w, n: grammy.n }), grammy.w > 0) : ''}
            ${pending ? chip('hourglass', t('awr_pending_n', { n: pending })) : ''}
          </div>
        </div>
      </div>
      <div class="ls-stats">
        ${stat(noms, t('aw_s_noms'), '', true)}
        ${stat(wins, t('aw_s_wins'), '', true)}
        ${stat(shows.length, t('awr_s_shows'), '', true)}
        ${stat(String(bestYear), t('aw_s_best'), byYear[bestYear].w ? tCount('aw_win', byYear[bestYear].w) : tCount('aw_nom', byYear[bestYear].n), false)}
      </div>
    </div>`;

  /* ── Your library, to open what they were nominated for ── */
  const nrm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/\s*[\(\[](feat|ft|with)\.?\s[^\)\]]*[\)\]]/gi, '').replace(/[^\p{L}\p{N}]+/gu, '');
  const lib = {};
  for (const p of allPlays) {
    if (!p.artists || !p.artists.includes(st.name)) continue;
    const tk = nrm(p.title);
    if (tk && !lib[tk]) lib[tk] = { js: `openSongModal(${esc(JSON.stringify(songKey(p)))})`, type: 'song', item: { title: p.title, artist: p.artist, album: p.album } };
    const ak = nrm(p.album);
    if (ak && p.album !== '—' && !lib[ak]) lib[ak] = { js: `openAlbumModal(${esc(JSON.stringify(p.album + '|||' + albumArtist(p)))})`, type: 'album', item: { album: p.album, artist: albumArtist(p) } };
  }

  /* ── You vs the industry ── */
  let vsHTML = '';
  const realWon = new Map(), realAny = new Set();
  for (const r of rows) {
    if (!r.work) continue;
    realAny.add(nrm(r.work));
    if (r.res === 'w' && !realWon.has(nrm(r.work))) realWon.set(nrm(r.work), r.work);
  }
  const myWon = new Map();
  for (const e of _aw.entries) if (e.isWin && e.cat.type !== 'artist') { const k = nrm(_awName(e.item)); if (k && !myWon.has(k)) myWon.set(k, e); }
  const myWins = _aw.entries.filter(e => e.isWin).length;
  if (_aw.entries.length || realWon.size) {
    const both = [...myWon.keys()].filter(k => realWon.has(k));
    const onlyYou = [...myWon.keys()].filter(k => !realWon.has(k));
    const onlyThem = [...realWon.keys()].filter(k => !myWon.has(k));
    const pill = (k, label) => {
      const hit = lib[k];
      return hit ? `<button type="button" class="awr-pill" onclick="${hit.js}">${esc(label)}</button>` : `<span class="awr-pill">${esc(label)}</span>`;
    };
    const col = (key, list, label) => `<div class="awr-vs-col awr-vs-col--${key}">
        <span class="awr-vs-h">${esc(t('awr_vs_' + key))}<b>${list.length}</b></span>
        <span class="awr-pills">${list.length ? list.slice(0, 5).map(k => pill(k, label(k))).join('') + (list.length > 5 ? `<span class="awr-pill awr-pill--more">+${list.length - 5}</span>` : '') : `<span class="awr-vs-none">${esc(t('awr_vs_none'))}</span>`}</span>
      </div>`;
    const lead = myWins > wins ? 'you' : wins > myWins ? 'them' : 'even';
    vsHTML = `<div class="ao-head rk-head">${esc(t('awr_h_vs'))}<span>${esc(t('awr_vs_hint'))}</span></div>
      <div class="awr-vs">
        <div class="awr-vs-score">
          <span class="awr-vs-side${lead === 'them' ? ' is-lead' : ''}"><b class="rk-count">${wins.toLocaleString()}</b><small>${esc(t('awr_vs_real'))}</small></span>
          <span class="awr-vs-mid">${esc(t('awr_vs_' + (lead === 'even' ? 'tie' : lead === 'you' ? 'more_you' : 'more_them')))}</span>
          <span class="awr-vs-side${lead === 'you' ? ' is-lead' : ''}"><b class="rk-count">${myWins.toLocaleString()}</b><small>${esc(t('awr_vs_mine'))}</small></span>
        </div>
        <div class="awr-vs-cols">
          ${col('both', both, k => _awName(myWon.get(k).item))}
          ${col('you', onlyYou, k => _awName(myWon.get(k).item))}
          ${col('them', onlyThem, k => realWon.get(k))}
        </div>
      </div>`;
  }

  /* ── Award shows ── */
  const shownShows = st.allShows ? shows : shows.slice(0, AWR_SHOWS);
  const showsHTML = `<div class="ao-head rk-head">${esc(t('awr_h_shows'))}<span>${esc(t('awr_shows_hint'))}</span></div>
    <div class="awr-shows">
      ${shownShows.map((s, i) => `<button type="button" class="awr-show${s.w ? ' is-won' : ''}${isGrammy(s.name) ? ' is-grammy' : ''}" data-awr-show="${esc(s.name)}" style="--i:${Math.min(i, 12)}" aria-pressed="false">
          <span class="awr-show-name">${isGrammy(s.name) ? ic('trophy') : ''}${esc(s.name)}</span>
          <span class="awr-show-n"><b>${s.w}</b>/${s.n}<small>${esc(tUnit('aw_win', s.w))}</small></span>
          <span class="ao-meter"><span style="width:${pct(s.w, s.n)}%"></span></span>
        </button>`).join('')}
    </div>
    ${shows.length > AWR_SHOWS ? `<button type="button" class="aw-more" data-awr-allshows>${esc(t(st.allShows ? 'awr_shows_less' : 'awr_shows_all', { n: shows.length }))}</button>` : ''}`;

  /* ── Year by year ── */
  const span = Array.from({ length: years[years.length - 1] - years[0] + 1 }, (_, i) => years[0] + i);
  const yearsHTML = `<div class="ao-head rk-head">${esc(t('awr_h_years'))}<span>${esc(t('aw_years_hint'))}</span></div>
    <div class="aw-years">
      <div class="aw-yrs" style="--n:${span.length}"></div>
      <div class="aw-legend"><span><i class="aw-key aw-key--nom"></i>${esc(t('aw_s_noms'))}</span><span><i class="aw-key aw-key--win"></i>${esc(t('aw_s_wins'))}</span></div>
      <div class="ls-read aw-read" aria-live="polite"></div>
    </div>`;

  /* ── Most nominated work ── */
  const works = {};
  for (const r of rows) {
    if (!r.work) continue;
    const k = nrm(r.work);
    const w = works[k] || (works[k] = { k, name: r.work, n: 0, w: 0, list: [] });
    w.n++; if (r.res === 'w') w.w++;
    w.list.push(r);
  }
  const topWorks = Object.values(works).sort((a, b) => (b.w - a.w) || (b.n - a.n)).slice(0, 5);
  const worksHTML = !topWorks.length ? '' : `
    <div class="ao-head rk-head">${esc(t('aw_h_works'))}<span>${esc(t('awr_works_hint'))}</span></div>
    <div class="aw-works">
      ${topWorks.map((w, i) => {
        const hit = lib[w.k];
        w.list.sort((a, b) => a.year - b.year);
        const pips = w.list.slice(0, 40).map(r => `<i class="aw-pip aw-pip--${r.res === 'w' ? 'won' : r.res === 'p' ? 'open' : 'lost'}" title="${r.year} · ${esc(r.show)} · ${esc(r.cat)}"></i>`).join('');
        return `<${hit ? `button type="button" onclick="${hit.js}"` : 'div'} class="aw-work${hit ? '' : ' is-flat'}" style="--i:${i}">
          <span class="aw-work-n">${i + 1}</span>
          <span class="aw-work-art" id="awrWork-${i}"><span class="thumb-initials">${esc(initials(w.name))}</span></span>
          <span class="aw-work-main">
            <span class="aw-work-name">${esc(w.name)}</span>
            <span class="aw-work-meta">${esc(tCount('aw_nom', w.n))}${w.w ? ` · <b>${esc(tCount('aw_win', w.w))}</b>` : ''}${hit ? ` · <span class="awr-inlib">${esc(t('awr_in_lib'))}</span>` : ''}</span>
          </span>
          <span class="aw-pips">${pips}</span>
        </${hit ? 'button' : 'div'}>`;
      }).join('')}
    </div>`;

  el.innerHTML = `${hero}${vsHTML}${showsHTML}${yearsHTML}${worksHTML}
    <div class="ao-head rk-head">${esc(t('awr_h_list'))}<span></span></div>
    <div class="aw-filters" role="group" aria-label="${esc(t('awr_h_list'))}"></div>
    <div class="aw-ballot"></div>
    <div class="awr-credit">${ic('globe')}<span>${t('awr_source', { link: `<a href="${esc(src)}" target="_blank" rel="noopener">Wikipedia</a>` })}</span>
      <button type="button" data-awr-refresh>${ic('refresh')}${esc(t('awr_refresh'))}</button></div>`;

  topWorks.forEach((w, i) => { const hit = lib[w.k]; if (hit) _awArt('awrWork-' + i, hit.item, hit.type); });
  st.span = span;
  awrPaintList();
}

// What the show, year and result filters change: the year bars, the
// readout, the show tiles' state and the list
function awrPaintList() {
  const el = document.getElementById('awReal');
  const st = _awr;
  if (!el || !st || st.status !== 'ok' || !st.span) return;
  const ic = _amIco;
  const inShow = st.show ? st.rows.filter(r => r.show === st.show) : st.rows;
  el.querySelectorAll('.awr-show').forEach(b => {
    const on = b.dataset.awrShow === st.show;
    b.classList.toggle('is-on', on);
    b.setAttribute('aria-pressed', on);
  });
  el.querySelector('.awr-shows')?.classList.toggle('has-pick', !!st.show);

  // Year columns for the show picked (or every show)
  const by = {};
  for (const r of inShow) { const y = by[r.year] || (by[r.year] = { n: 0, w: 0 }); y.n++; if (r.res === 'w') y.w++; }
  const maxN = Math.max(1, ...Object.values(by).map(y => y.n));
  const best = Object.keys(by).map(Number).reduce((b, y) => b == null || by[y].w > by[b].w || (by[y].w === by[b].w && by[y].n > by[b].n) ? y : b, null);
  const yrs = el.querySelector('.aw-yrs');
  if (yrs) {
    yrs.classList.toggle('has-pick', st.year != null);
    yrs.innerHTML = st.span.map((y, i) => {
      const d = by[y] || { n: 0, w: 0 };
      const h = d.n ? Math.max(8, d.n / maxN * 100) : 0;
      return `<button type="button" class="aw-yr${d.n ? '' : ' is-zero'}${y === best ? ' is-best' : ''}${st.year === y ? ' is-on' : ''}" data-awr-year="${y}" style="--i:${Math.min(i, 30)}" aria-pressed="${st.year === y}" aria-label="${y}: ${esc(tCount('aw_nom', d.n))}, ${esc(tCount('aw_win', d.w))}">
          <span class="aw-yr-n">${d.n || ''}</span>
          <span class="aw-yr-col" style="--h:${h.toFixed(1)}"><span class="aw-yr-win" style="--w:${d.n ? (d.w / d.n * 100).toFixed(1) : 0}%"></span></span>
          <span class="aw-yr-y">${y === best ? ic('crown') : ''}${String(y).slice(st.span.length > 8 ? 2 : 0)}</span>
        </button>`;
    }).join('');
  }

  const pool = st.year == null ? inShow : inShow.filter(r => r.year === st.year);
  const read = el.querySelector('.aw-read');
  if (read) {
    const w = pool.filter(r => r.res === 'w');
    const star = w.find(r => /^grammy/i.test(r.show)) || w[0];
    read.innerHTML = `<span class="ls-read-when">${st.year == null ? esc(t('awr_read_all')) : st.year}${st.show ? ' · ' + esc(st.show) : ''}</span>
      <span class="ls-read-n">${pool.length ? `<b>${pool.length}</b> ${esc(tUnit('aw_nom', pool.length))} · <b>${w.length}</b> ${esc(tUnit('aw_win', w.length))}` : esc(t('aw_read_none'))}</span>
      ${star ? `<span class="aw-read-star">${ic('trophy')} ${esc(star.cat)}</span>` : ''}`;
  }

  const test = { all: () => true, won: r => r.res === 'w', nom: r => r.res === 'n', pending: r => r.res === 'p' };
  const counts = Object.fromEntries(Object.keys(test).map(k => [k, pool.filter(test[k]).length]));
  if (st.filter !== 'all' && !counts[st.filter]) st.filter = 'all';
  const label = { all: t('aw_f_all'), won: t('aw_f_won'), nom: t('awr_nominated'), pending: t('awr_pending') };
  const filters = el.querySelector('.aw-filters');
  if (filters) filters.innerHTML = Object.keys(test).filter(k => k === 'all' || counts[k]).map(k =>
      `<button type="button" class="aw-f aw-f--${k}${st.filter === k ? ' is-on' : ''}" data-awr-filter="${k}" aria-pressed="${st.filter === k}">${esc(label[k])}<b>${counts[k]}</b></button>`).join('')
    + (st.show ? `<button type="button" class="aw-f aw-f--year" data-awr-clearshow>${esc(st.show)}<span aria-label="${esc(t('awr_all_shows'))}">✕</span></button>` : '')
    + (st.year != null ? `<button type="button" class="aw-f aw-f--year" data-awr-clearyear>${st.year}<span aria-label="${esc(t('aw_clear_year'))}">✕</span></button>` : '');

  const order = { w: 0, n: 1, p: 2 };
  const list = pool.filter(test[st.filter]).sort((a, b) => (b.year - a.year) || (order[a.res] - order[b.res]) || a.show.localeCompare(b.show));
  const shown = list.slice(0, st.limit);
  let html = '', lastYear = null;
  for (const r of shown) {
    if (r.year !== lastYear) {
      lastYear = r.year;
      const ye = pool.filter(x => x.year === r.year);
      html += `<div class="aw-bl-year"><b>${r.year}</b><span>${esc(t('aw_year_tally', { wins: ye.filter(x => x.res === 'w').length, noms: ye.length }))}</span></div>`;
    }
    const res = r.res === 'w' ? `<span class="aw-res aw-res--won">${ic('trophy')}${esc(t('aw_won'))}</span>`
      : r.res === 'p' ? `<span class="aw-res aw-res--open">${ic('hourglass')}${esc(t('awr_pending'))}</span>`
      : `<span class="aw-res aw-res--nom">${esc(t('awr_nominated'))}</span>`;
    html += `<div class="aw-bl aw-bl--${r.res === 'w' ? 'won' : r.res === 'p' ? 'open' : 'lost'}">
        <span class="aw-bl-emo" aria-hidden="true">${r.res === 'w' ? '🏆' : '🎖️'}</span>
        <span class="aw-bl-main"><span class="aw-bl-cat">${esc(r.cat)}</span><span class="aw-bl-work">${esc(r.show)}${r.work ? ' · ' + esc(r.work) : ''}</span></span>
        ${res}
      </div>`;
  }
  if (list.length > shown.length) html += `<button type="button" class="aw-more" data-awr-more>${esc(t('aw_show_more', { n: list.length - shown.length }))}</button>`;
  const box = el.querySelector('.aw-ballot');
  if (box) box.innerHTML = html || `<div class="aw-none">${esc(t('aw_read_none'))}</div>`;
}

function awrClick(e) {
  const st = _awr;
  if (!st) return;
  const at = sel => e.target.closest(sel);
  let b;
  if ((b = at('[data-awr-show]'))) { st.show = st.show === b.dataset.awrShow ? null : b.dataset.awrShow; st.year = null; st.limit = AW_BALLOT_PAGE; return awrPaintList(); }
  if ((b = at('[data-awr-year]'))) { st.year = st.year === +b.dataset.awrYear ? null : +b.dataset.awrYear; st.limit = AW_BALLOT_PAGE; return awrPaintList(); }
  if ((b = at('[data-awr-filter]'))) { st.filter = b.dataset.awrFilter; st.limit = AW_BALLOT_PAGE; return awrPaintList(); }
  if (at('[data-awr-clearshow]')) { st.show = null; return awrPaintList(); }
  if (at('[data-awr-clearyear]')) { st.year = null; return awrPaintList(); }
  if (at('[data-awr-more]')) { st.limit = Infinity; return awrPaintList(); }
  if (at('[data-awr-allshows]')) { st.allShows = !st.allShows; return awrPaint(); }
  if (at('[data-awr-refresh]')) { Object.assign(st, { year: null, show: null, filter: 'all' }); awrEnsure(true); }
}

async function _awardsSave(year) {
  const data = _awardsYearData[year];
  if (!data) return;
  data.savedAt = Date.now();
  data.device  = _dcDeviceId();   // lets the next save tell a hand-off between devices apart
  // Local first and synchronously: whatever happens to the network request after
  // this line, the ballot is already safe on the device.
  _awardsWriteLocal(year, data);
  // The cloud save is checked and, if another device got there first, merged
  // (see _awardsPush). Not awaited — offline, a transaction can take a while to
  // give up, and the click that triggered this shouldn't wait on it.
  _awardsQueuePush(year);
}

function _isCollab(play) {
  return _collabArtists(play).length > 1;
}

// Every artist credited on a play: the structured list when the source has one,
// otherwise the artist string split on commas, &, feat., ft. and x (band names
// with a comma in them, like "Tyler, The Creator", held together)
function _collabArtists(play) {
  if (Array.isArray(play.artists) && play.artists.length > 1) return play.artists.slice();
  const artist = play.artist || '';
  // Commas and ampersands inside a protected name are swapped for invisible
  // stand-ins while splitting, then put back
  const cleaned = COLLAB_EXCEPTIONS.reduce((s, ex) => s.replace(ex, ex.replace(/,/g, '​').replace(/&/g, '‌')), artist);
  return cleaned.split(/,|(?:\s+(?:&|feat\.?|ft\.?|x)\s+)/i)
    .map(s => s.replace(/​/g, ',').replace(/‌/g, '&').trim()).filter(Boolean);
}

/* What an artist brings to a collaboration, for Best Collaboration:
   'group'  — MusicBrainz types them as a group, orchestra or choir
   'dj'     — a DJ or producer who mostly doesn't sing: MusicBrainz's note
              beside the name says so ("Dutch DJ and record producer"), or
              the artist is steeped in DJ genres (see below)
   'singer' — a person MusicBrainz knows, with neither sign
   null     — not looked up, or not found
   Genre tags alone are a weak signal: MusicBrainz tags Lady Gaga "edm" and
   "electro house" and Katy Perry "house". A real DJ carries several DJ-genre
   tags (David Guetta has ten) and no vocal ones, so it takes three distinct DJ
   genres and no "female vocals" / "singer-songwriter" style tag. Tags come
   from MusicBrainz plus whatever Last.fm or Gemini gave the genre awards. */
const MB_GROUP_TYPES = new Set(['Group', 'Orchestra', 'Choir']);
const DJ_ROLE_RE = /\b(?:dj|disc jockey|producer|production|beatmaker)\b/i;
// Genres made almost entirely by DJs and producers. Not "dance" or
// "electronic", which take in plenty of singers.
const DJ_GENRE_RE = /\b(?:house|edm|techno|trance|dubstep|future bass|drum and bass|big room|future rave|hardstyle|trap edm)\b/;
const VOCAL_TAG_RE = /\b(?:vocals?|vocalist|singer|singer-songwriter|rapper)\b/;
const AWARDS_DJ_MIN_GENRES = 3;
function _awardsCollabRole(name) {
  const mb = _mbArtistInfoCache[name];
  if (mb && MB_GROUP_TYPES.has(mb.type)) return 'group';
  if (DJ_ROLE_RE.test(mb?.dis || '')) return 'dj';
  const tags = new Set([...(mb?.tags || []), ...(_awardsGenreCache[String(name).toLowerCase()] || [])]);
  if (tags.has('dj')) return 'dj';
  const djGenres = [...tags].filter(t => DJ_GENRE_RE.test(t)).length;
  if (djGenres >= AWARDS_DJ_MIN_GENRES && ![...tags].some(t => VOCAL_TAG_RE.test(t))) return 'dj';
  return mb ? 'singer' : null;
}

function _isDuo(play) {
  if (Array.isArray(play.artists)) return play.artists.length === 2;
  const artist = play.artist || '';
  const cleaned = COLLAB_EXCEPTIONS.reduce((s, ex) => s.replace(ex, ex.replace(/,/g, '​')), artist);
  const parts = cleaned.split(/,|(?:\s+(?:&|feat\.?|ft\.?|x)\s+)/i).map(s => s.trim()).filter(Boolean);
  return parts.length === 2;
}

function _isRemix(play) {
  return /\b(remix|remaster|edit|version|cover)\b/i.test(play.title || '');
}

function _hasNonLatinScript(str) {
  return /[Ѐ-ӿ؀-ۿऀ-ॿ぀-ヿ㐀-䶿一-鿿가-힯฀-๿ᄀ-ᇿ]/.test(str || '');
}

// Matches the app-wide songKey() convention (title+full-artist, trimmed) so a song's
// play count in Awards never splits from its count on the main Songs chart due to
// stray whitespace from CSV/Sheets imports.
function _sk(p) { return `${(p.title||'').toLowerCase().trim()}|||${(p.artist||'').toLowerCase().trim()}`; }
function _pa(p)  { return (Array.isArray(p.artists) && p.artists.length) ? p.artists[0] : (p.artist || ''); }
function _pk(p)  { return _pa(p).toLowerCase(); }
// Album/artist keys use the primary artist (via _pk), matching _awardsCountMaps and the
// app-wide albumArtist() convention — keeps every Awards category consistent so a collab
// track's album/artist isn't treated as a different entity depending on which category built it.
function _ak(p) { return `${(p.album||'').toLowerCase()}|||${_pk(p)}`; }
function _rk(p) { return _pk(p); }

function _awardsCountMaps(plays) {
  const songs = {}, albums = {}, artists = {};
  for (const p of plays) {
    const sk = _sk(p), pk = _pk(p);
    const albumKey = `${(p.album||'').toLowerCase()}|||${pk}`;
    if (!songs[sk])   songs[sk]   = { title: p.title,  artist: p.artist, album: p.album, plays: 0 };
    if (!albums[albumKey] && p.album) albums[albumKey] = { album: p.album, artist: _pa(p), plays: 0 };
    if (!artists[pk]) artists[pk] = { artist: _pa(p), plays: 0 };
    songs[sk].plays++;
    if (p.album) albums[albumKey].plays++;
    artists[pk].plays++;
  }
  return { songs, albums, artists };
}

/* Set above 1 while a "base+genre:x" category runs its base (_awardsSplitGenre),
   so the base hands back a bigger field and the genre cut still leaves a full one */
let _awardsPoolScale = 1;
function _awardsTopN(map, n, cap) {
  cap = cap || 3;
  n *= _awardsPoolScale;
  const sorted = Object.values(map).sort((a, b) => b.plays - a.plays);
  const result = [], ac = {};
  for (const item of sorted) {
    const key = (item.artist || '').toLowerCase();
    ac[key] = (ac[key] || 0);
    if (ac[key] >= cap) continue;
    ac[key]++;
    result.push(item);
    if (result.length >= n) break;
  }
  return result;
}

/* Auto categories: everything level with the top score, not just the first of
   them. When two songs share the most plays, which one "wins" was an accident
   of sort order; returning the whole tie lets the user break it themselves.
   Capped so a pile of 2-day streaks doesn't turn into a 200-way tie. */
const AWARDS_MAX_TIES = 12;
function _awardsTopTied(map) {
  const sorted = Object.values(map).sort((a, b) => b.plays - a.plays);
  if (!sorted.length) return [];
  const top = sorted[0].plays;
  return sorted.filter(x => x.plays === top).slice(0, AWARDS_MAX_TIES);
}

async function _awardsGetArtistGenre(artist) {
  const key = (artist || '').toLowerCase();
  if (_awardsGenreCache[key] !== undefined) return _awardsGenreCache[key];
  if (_awardsGenreQueue[key]) return _awardsGenreQueue[key];
  const apiKey = localStorage.getItem('dc_lfm_api_key') || 'a8a5bfd6f2e57c45c4bdf6b5c58e1cd5';
  _awardsGenreQueue[key] = fetch(
    `https://ws.audioscrobbler.com/2.0/?method=artist.gettoptags&artist=${encodeURIComponent(artist)}&api_key=${encodeURIComponent(apiKey)}&format=json`
  ).then(r => r.json()).then(d => {
    const tags = (d?.toptags?.tag || []).map(t => t.name.toLowerCase()).slice(0, 10);
    _awardsGenreCache[key] = tags;
    delete _awardsGenreQueue[key];
    _awardsSaveLookupCaches();
    return tags;
  }).catch(() => { _awardsGenreCache[key] = []; delete _awardsGenreQueue[key]; return []; });
  return _awardsGenreQueue[key];
}

async function _awardsGetAlbumYear(album, artist) {
  const key = album.toLowerCase() + '|||' + artist.toLowerCase();
  if (key in _awardsAlbumYearCache) return _awardsAlbumYearCache[key];
  const albumL      = album.toLowerCase();
  const artistW     = artist.toLowerCase().split(/[\s,&]/)[0];
  const searchArtist = artist.split(',')[0].trim(); // drop collab artists for API queries

  // 1. iTunes
  try {
    const q = encodeURIComponent(searchArtist + ' ' + album);
    const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=album&limit=10`);
    const d = await r.json();
    const results = d?.results || [];
    const match = results.find(x =>
      x.collectionName?.toLowerCase().includes(albumL) &&
      x.artistName?.toLowerCase().includes(artistW)
    );
    if (match?.releaseDate) {
      const year = new Date(match.releaseDate).getFullYear();
      _awardsAlbumYearCache[key] = year;
      _awardsSaveLookupCaches();
      return year;
    }
  } catch (e) {}

  // 2. Deezer
  try {
    const r = await deezerFetch(`search/album?q=${encodeURIComponent(searchArtist + ' ' + album)}&limit=10`);
    if (r.ok) {
      const d = await r.json();
      const items = d?.data || [];
      const match = items.find(x =>
        x.title?.toLowerCase().includes(albumL) &&
        x.artist?.name?.toLowerCase().includes(artistW)
      );
      const year = match?.release_date ? parseInt(match.release_date.slice(0, 4), 10) : null;
      if (year) {
        _awardsAlbumYearCache[key] = year;
        _awardsSaveLookupCaches();
        return year;
      }
    }
  } catch (e) {}

  // 3. MusicBrainz
  try {
    const mbid = await searchArtistMBID(searchArtist);
    if (mbid) {
      const groups = await fetchAllReleasesRaw(mbid);
      const match = groups.find(g => g.title?.toLowerCase() === albumL)
        || groups.find(g => g.title?.toLowerCase().includes(albumL));
      const year = match?.['first-release-date'] ? parseInt(match['first-release-date'].slice(0, 4), 10) : null;
      if (year) {
        _awardsAlbumYearCache[key] = year;
        _awardsSaveLookupCaches();
        return year;
      }
    }
  } catch (e) {}

  _awardsAlbumYearCache[key] = null;
  return null;
}

// Which tags count as each genre. Shared by _genreMatch (does it fit?) and
// _genreFitScore (how strongly?) so the two never disagree.
const _GENRE_ALIASES = {
    'pop':         ['pop','dance pop','electropop','synth-pop','teen pop','pop rock','indie pop'],
    'rock':        ['rock','classic rock','hard rock','indie rock','punk rock','alternative rock','metal','emo','post-rock'],
    'alternative': ['alternative','indie','indie rock','alternative rock','post-punk','dream pop','shoegaze'],
    'hip-hop':     ['hip-hop','hip hop','rap','trap','conscious hip hop'],
    'rnb':         ['r&b','soul','neo soul','contemporary r&b','rnb','rhythm and blues'],
    'latin':       ['latin','reggaeton','latin pop','salsa','cumbia','bachata','latin rap','regional mexicano'],
    'electronic':  ['electronic','edm','house','techno','dance','electro','synth-pop','trance','ambient'],
    'k-pop':       ['k-pop','kpop','korean pop','k pop','korean'],
    'country':     ['country','country pop','country rock','americana','bluegrass','alt-country','outlaw country','nashville'],
    'reggae':      ['reggae','dancehall','roots reggae','ska','dub','reggae fusion'],
    // Dance pop is its own award, so it gets its own list rather than leaning on
    // 'pop' (which would let any ballad in) or 'electronic' (which would not).
    'dance-pop':   ['dance pop','dance-pop','dancepop','electropop','eurodance','disco','nu-disco'],
    // Folk-pop acts (Myles Smith, Noah Kahan, Hozier) are tagged folk or acoustic
    // far more often than pop, so both halves of the name count.
    'folk':        ['folk','folk pop','folk-pop','indie folk','contemporary folk','folk rock','acoustic','stomp and holler'],
    // Broader than folk on purpose: catches acoustic and piano writers (Ed Sheeran,
    // Lewis Capaldi, Gracie Abrams) that are never tagged folk.
    'singer-songwriter': ['singer-songwriter','singer songwriter','songwriter','acoustic','acoustic pop','piano','soft rock'],
    'indie-pop':   ['indie pop','indie-pop','bedroom pop','dream pop','chamber pop','twee pop','indietronica'],
    'metal':       ['metal','heavy metal','metalcore','nu metal','alternative metal','thrash metal','death metal','progressive metal','black metal','doom metal'],
    'punk':        ['punk','punk rock','pop punk','pop-punk','emo','emo pop','midwest emo','post-hardcore','hardcore punk','skate punk'],
    'afrobeats':   ['afrobeats','afrobeat','afropop','afro pop','afroswing','amapiano','naija','alte'],
    'j-pop':       ['j-pop','jpop','j pop','japanese','anime','j-rock','jrock','city pop','vocaloid','anison'],
    'jazz':        ['jazz','smooth jazz','vocal jazz','jazz fusion','bebop','contemporary jazz','jazz pop','swing','cool jazz'],
    // Instrumental music rides along with classical: film scores and modern
    // piano records are tagged either way and nobody splits them by hand.
    'classical':   ['classical','instrumental','orchestral','neoclassical','modern classical','contemporary classical','baroque','opera','piano','score'],
    // Rock, finer grained. Each list stays inside its own sound, so a band can
    // sit in two (hard rock and grunge) but a pop act never reaches classic rock.
    'pop-rock':    ['pop rock','pop-rock','power pop','soft rock','piano rock'],
    // Pop, finer grained, for the Pop group's style awards
    'synth-pop':   ['synth-pop','synthpop','synth pop','electropop','electro-pop','electro pop','synthwave','chillwave','new wave'],
    'latin-pop':   ['latin pop','latin-pop','pop latino','urbano latino','latin urban','pop en espanol','tropical pop'],
    'alt-pop':     ['alt-pop','alternative pop','alt pop','bedroom pop','dark pop','sad pop','indie pop'],
    'hyperpop':    ['hyperpop','hyper pop','pc music','glitchcore','digicore','bubblegum bass','deconstructed club'],
    'art-pop':     ['art pop','art-pop','artpop','experimental pop','avant-pop','baroque pop','chamber pop'],
    // Gospel and Christian. 'christian' is all of them together, for the
    // artist and collaboration awards that span every style
    'gospel':      ['gospel','gospel music','black gospel','urban gospel','contemporary gospel','southern gospel','traditional gospel','choir'],
    'ccm':         ['ccm','contemporary christian','christian contemporary','christian','christian pop','christian rock','christian music'],
    'worship':     ['worship','praise & worship','praise and worship','christian worship','worship music'],
    'christian-hip-hop': ['christian hip hop','christian hip-hop','christian rap','gospel rap','holy hip hop','chh'],
    'christian':   ['christian','gospel','ccm','contemporary christian','worship','praise & worship','praise and worship','christian pop','christian rock',
                    'christian hip hop','christian rap','gospel rap','southern gospel','black gospel','urban gospel','christian alternative','christian metal'],
    // Instrumental, split by sound
    'instrumental': ['instrumental','instrumental hip hop','instrumental rock','post-rock','beats','lo-fi beats','solo piano','instrumental pop'],
    'lo-fi':       ['lo-fi hip hop','lofi hip hop','lo-fi beats','chillhop','jazzhop','chill beats','study beats'],
    'piano':       ['solo piano','neoclassical','modern classical','contemporary classical','piano ambient'],
    'video-game':  ['video game music','video game','vgm','game music','game soundtrack','video game soundtrack','ost (video game)'],
    'pop-punk':    ['pop punk','pop-punk','emo pop','easycore'],
    'indie-rock':  ['indie rock','indie-rock','garage rock','garage rock revival','post-punk revival','lo-fi','slacker rock'],
    'classic-rock': ['classic rock','album rock','arena rock','blues rock','southern rock','heartland rock','glam rock'],
    'hard-rock':   ['hard rock','heavy rock','post-grunge','stoner rock','glam metal'],
    'post-punk':   ['post-punk','new wave','gothic rock','darkwave','coldwave','no wave'],
    'grunge':      ['grunge','post-grunge','britpop','90s alternative','90s rock','seattle'],
    'prog':        ['progressive rock','prog rock','prog','psychedelic rock','psychedelic','neo-psychedelia','art rock','krautrock','space rock'],
    'shoegaze':    ['shoegaze','dream pop','noise pop','dreampop','nu gaze','slowcore'],
    // Goth keeps "gothic rock" shared with post-punk, where the genre started
    'goth':        ['gothic rock','goth rock','goth','gothic','deathrock','darkwave','dark wave','ethereal wave','gothic metal','gothic post-punk'],
};

// Spelling-blind: "Dance-Pop", "dance pop" and "dancepop" are one genre, so a tag
// typed into the sheet doesn't have to match Last.fm's punctuation to count.
const _genreNorm = t => String(t).toLowerCase().replace(/[\s\-_]+/g, '');
function _genreAliasList(filterStr) {
  const g = filterStr.replace('genre:', '');
  return (_GENRE_ALIASES[g] || [g]).map(_genreNorm);
}

function _genreMatch(tags, filterStr) {
  const list = _genreAliasList(filterStr);
  return tags.some(t => list.includes(_genreNorm(t)));
}

/* How strongly a tag list belongs to a genre, 0 – 100, for the nominee picker's
   fit tag. Tags arrive in order — the sheet's Genre 1–5 as typed, Last.fm's by
   how many listeners used them — so the first matching tag sets the score by
   its position. The genre's own name (the head of its alias list) counts in
   full; a related tag (metal for Rock, indie for Alternative) counts a little
   less. Each further matching tag adds a few points, up to 100. */
const GENRE_FIT_BY_POS = [100, 85, 72, 62, 54, 48, 43, 39, 36, 33];
const GENRE_FIT_RELATED = 0.85;   // a related tag, not the genre itself
const GENRE_FIT_EXTRA = 5;        // per extra matching tag
function _genreFitScore(tags, filterStr) {
  const list = _genreAliasList(filterStr);
  let best = 0, hits = 0;
  tags.slice(0, GENRE_FIT_BY_POS.length).forEach((t, i) => {
    const at = list.indexOf(_genreNorm(t));
    if (at < 0) return;
    hits++;
    best = Math.max(best, GENRE_FIT_BY_POS[i] * (at === 0 ? 1 : GENRE_FIT_RELATED));
  });
  return hits ? Math.min(100, Math.round(best + (hits - 1) * GENRE_FIT_EXTRA)) : 0;
}

/* Genres typed into the sheet (Genre 1–5), by song and by album. The sheet is
   the user's own call, so wherever it has an answer it wins over the Last.fm /
   Gemini artist tags, which only ever fill in for songs the sheet leaves blank.
   A song takes its newest tagged play (allPlays is newest-first), so editing the
   genres on the latest rows is enough. Rebuilt whenever allPlays is replaced. */
let _awardsSheetGenreCache = null;
function _awardsSheetGenres() {
  const c = _awardsSheetGenreCache;
  if (c && c.plays === allPlays && c.n === allPlays.length) return c;
  const songs = new Map(), albums = new Map(), artists = new Map();
  for (const p of allPlays) {
    if (!p.genres) continue;
    const sk = _sk(p);
    if (songs.has(sk)) continue;
    songs.set(sk, p.genres);
    if (p.album && p.album !== '—') {
      const ak = _ak(p);
      if (!albums.has(ak)) albums.set(ak, []);
      albums.get(ak).push(p.genres);
    }
    // Every tagged song by an artist, so artist awards can use the sheet too
    const pk = _pk(p);
    if (!artists.has(pk)) artists.set(pk, []);
    artists.get(pk).push(p.genres);
  }
  return (_awardsSheetGenreCache = { plays: allPlays, n: allPlays.length, songs, albums, artists });
}

// A song's tags: the sheet's, else the artist's (undefined = artist not looked up yet)
function _awardsSongTags(p) {
  return _awardsSheetGenres().songs.get(_sk(p)) || _awardsGenreCache[_pa(p).toLowerCase()];
}

// An album fits a genre when at least half its sheet-tagged tracks do; null = no sheet data
function _awardsAlbumSheetFits(p, f) {
  const tracks = _awardsSheetGenres().albums.get(_ak(p));
  if (!tracks) return null;
  return tracks.filter(tags => _genreMatch(tags, f)).length * 2 >= tracks.length;
}

// An artist's most common sheet genres across their songs; undefined = none tagged
function _awardsArtistSheetTags(p) {
  const tracks = _awardsSheetGenres().artists.get(_pk(p));
  if (!tracks) return undefined;
  const n = {};
  for (const tags of tracks) for (const t of tags) n[t] = (n[t] || 0) + 1;
  return Object.keys(n).sort((a, b) => n[b] - n[a]);
}
// An artist's tags: the sheet's (their top five, so one stray song doesn't
// make a rapper pop), else the Last.fm / Gemini ones
function _awardsArtistTags(p) {
  const sheet = _awardsArtistSheetTags(p);
  return sheet ? sheet.slice(0, 5) : _awardsGenreCache[_pa(p).toLowerCase()];
}

// An album's most common sheet genres across its tracks, for the picker row
function _awardsAlbumSheetTags(p) {
  const tracks = _awardsSheetGenres().albums.get(_ak(p));
  if (!tracks) return undefined;
  const n = {};
  for (const tags of tracks) for (const t of tags) n[t] = (n[t] || 0) + 1;
  return Object.keys(n).sort((a, b) => n[b] - n[a]);
}

/* Warm the genre cache for every artist in the window: Gemini first (one call
   for the lot, if a key is set), then Last.fm tags for whatever it left unknown.
   Both are capped — a window can hold thousands of artists and the awards only
   ever rank the top of the pile. */
async function _awardsEnsureGenres(plays) {
  const uniq = [...new Set(plays.map(p => _pa(p)))];
  await _awardsGeminiClassifyArtists(uniq.slice(0, 150));
  await Promise.all(uniq.filter(a => _awardsGenreCache[a.toLowerCase()] === undefined).slice(0, 60).map(a => _awardsGetArtistGenre(a)));
}

async function _awardsGeminiClassifyArtists(artists) {
  const apiKey = localStorage.getItem('dc_gemini_api_key');
  if (!apiKey) return;
  const needed = artists.filter(a => _awardsGenreCache[a.toLowerCase()] === undefined);
  if (!needed.length) return;
  const tags = 'rock, classic rock, hard rock, indie rock, punk rock, alternative rock, metal, emo, post-rock, alternative, indie, indie rock, post-punk, dream pop, shoegaze, hip-hop, hip hop, rap, trap, conscious hip hop, r&b, soul, neo soul, contemporary r&b, rnb, rhythm and blues, pop, dance pop, indie pop, pop rock, teen pop, synth-pop, electropop, latin, reggaeton, latin pop, salsa, cumbia, bachata, latin rap, regional mexicano, electronic, edm, house, techno, dance, electro, trance, ambient, k-pop, kpop, korean pop, k pop, korean, country, country pop, country rock, americana, bluegrass, alt-country, outlaw country, nashville, reggae, dancehall, roots reggae, ska, dub, reggae fusion, eurodance, disco, nu-disco, folk, folk pop, indie folk, contemporary folk, folk rock, acoustic, singer-songwriter, acoustic pop, piano, soft rock, indie pop, bedroom pop, chamber pop, heavy metal, metalcore, nu metal, alternative metal, pop punk, midwest emo, post-hardcore, afrobeats, afropop, amapiano, j-pop, japanese, anime, j-rock, city pop, jazz, smooth jazz, vocal jazz, jazz fusion, classical, instrumental, orchestral, neoclassical, modern classical, opera, pop rock, power pop, garage rock, post-punk revival, classic rock, album rock, arena rock, blues rock, southern rock, glam rock, heavy rock, post-grunge, stoner rock, new wave, gothic rock, darkwave, grunge, britpop, progressive rock, psychedelic rock, art rock, noise pop, goth rock, goth, deathrock, gothic metal, synthpop, alternative pop, alt-pop, dark pop, hyperpop, pc music, glitchcore, art pop, experimental pop, baroque pop, urbano latino, gospel, contemporary christian, ccm, christian, worship, christian hip hop, christian rap, instrumental hip hop, lo-fi hip hop, chillhop, solo piano, video game music';
  const prompt = `Classify each music artist using ONLY these genre tags (use multiple per artist if applicable):\n${tags}\n\nReturn a JSON object: { "Artist Name": ["tag1", "tag2"] }. Include every artist listed, even if unsure — guess based on your knowledge.\n\nArtists to classify:\n${needed.join('\n')}`;
  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${encodeURIComponent(apiKey)}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { responseMimeType: 'application/json', temperature: 0 }
      })
    });
    if (!res.ok) throw new Error('Gemini ' + res.status);
    const d = await res.json();
    const text = d?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) throw new Error('empty response');
    const map = JSON.parse(text);
    for (const [artist, artistTags] of Object.entries(map)) {
      const key = artist.toLowerCase();
      if (needed.some(a => a.toLowerCase() === key)) {
        _awardsGenreCache[key] = Array.isArray(artistTags) ? artistTags.map(t => String(t).toLowerCase()) : [];
      }
    }
    _awardsSaveLookupCaches();
  } catch (e) { /* fall through to Last.fm */ }
}

// Play-level tests for the categories that are just "plays that pass a test".
// Each one answers false (never throws) for a play with no fields, which is how
// the nominee picker probes whether a category can rank its browse list.
const _AWARDS_PLAY_TESTS = {
  'rt:ep':     p => _isReleaseTypePlay(p, 'ep'),
  'rt:live':   p => _isReleaseTypePlay(p, 'live'),
  reissue:     p => _isReissueAlbum(p.album),
  compilation: p => _isCompilationPlay(p),
  cover:       p => _isCoverSong(p),
  acoustic:    p => _isAcousticVersion(p),
  deep_cut:    p => _isDeepCut(p),
  feat:        p => _isCollab(p),
  instr_ver:   p => /\b(instrumental|karaoke version|backing track)\b/i.test(p.title || ''),
};

// How many artists Best Rock Duo/Group Song asks MusicBrainz about (~1s each)
const AWARDS_MB_TYPE_CHECKS = 20;
// …and Best Collaboration, which has two or more artists per song
const AWARDS_MB_COLLAB_CHECKS = 45;

// A deep cut has at least this many songs on its album better known than it
const AWARDS_DEEP_CUT_MIN_POS = 3;

/* Best Holiday Season Song. A song is in the running two ways: its title (or
   its album's, for Christmas albums) mentions Christmas, New Year's and the
   like, or you played it in the holiday season — the last three weeks of
   December (11th – 31st) and the first two weeks of January (1st – 14th).
   A holiday-titled song counts every play in the year; any other song counts
   only the plays that fell in the season. Best Holiday Season Album adds up
   the same plays per album, so a Christmas album counts all year. Bare "holiday" is left out on
   purpose (Madonna, Green Day), and so are the Santa place names. */
const AWARDS_HOLIDAY_RE = /\b(christmas|xmas|x-mas|navidad|nochebuena|natal|no[eë]l|santa(?! (monica|fe|cruz|barbara|clara|ana|rosa|maria|marta|catarina))|sleigh|mistletoe|jingle|reindeer|rudolph|snowman|happy holidays?|holidays|new year'?s?|a[nñ]o nuevo|ano novo|auld lang syne|silent night|holy night|winter wonderland|let it snow|deck the halls|feliz navidad|hanukk?ah|chanukah|yuletide|yule|nutcracker|kwanzaa)\b/i;
function _isHolidayTitled(p) {
  return AWARDS_HOLIDAY_RE.test(p.title || '') || AWARDS_HOLIDAY_RE.test(p.album || '');
}
// Dec 11 – Jan 14, in your timezone
function _awardsInHolidaySeason(p) {
  const d = tzDateOf(p), m = d.getMonth(), day = d.getDate();
  return (m === 11 && day >= 11) || (m === 0 && day <= 14);
}
// Does this play count toward a song's holiday score?
function _awardsHolidayPlay(p) {
  return _isHolidayTitled(p) || _awardsInHolidaySeason(p);
}

// Night runs 10pm – 4am, morning 5am – 11am
function _awardsHourFits(f, h) {
  return f === 'night' ? (h >= 22 || h < 4) : (h >= 5 && h < 11);
}

// Runs fn over items a few at a time, so a long list of lookups doesn't fire
// dozens of requests at once
async function _awardsBatched(items, size, fn) {
  for (let i = 0; i < items.length; i += size) await Promise.all(items.slice(i, i + size).map(fn));
}

// Deezer's entry for a song: { id, rank, albumId }, where rank is its
// popularity (0 – 1,000,000, higher is better known). null when it can't be
// found. Memoized for the session.
const AWARDS_UNDERRATED_MAX_RANK = 500000;
const _awardsDzTrackCache = {};
async function _awardsDeezerTrack(title, artist) {
  const k = (artist + '|||' + title).toLowerCase();
  if (k in _awardsDzTrackCache) return _awardsDzTrackCache[k];
  let hit = null;
  try {
    const r = await deezerFetch(`search/track?q=${encodeURIComponent(artist + ' ' + title)}&limit=10`);
    if (r.ok) {
      const items = (await r.json())?.data || [];
      const tl = title.toLowerCase(), aw = artist.toLowerCase().split(/[\s,&]/)[0];
      const x = items.find(x => x.title?.toLowerCase().includes(tl) && x.artist?.name?.toLowerCase().includes(aw));
      if (x) hit = { id: x.id, rank: x.rank || 0, albumId: x.album?.id || null };
    }
  } catch (e) {}
  return (_awardsDzTrackCache[k] = hit);
}
async function _awardsDeezerTrackRank(title, artist) {
  return (await _awardsDeezerTrack(title, artist))?.rank || null;
}

// Every track id on a Deezer album, best known first; null when it can't be read
const _awardsDzAlbumCache = {};
function _awardsDeezerAlbumOrder(albumId) {
  if (albumId in _awardsDzAlbumCache) return _awardsDzAlbumCache[albumId];
  return (_awardsDzAlbumCache[albumId] = (async () => {
    try {
      const r = await deezerFetch(`album/${albumId}/tracks?limit=100`);
      if (!r.ok) return null;
      const items = (await r.json())?.data || [];
      return items.length ? items.sort((a, b) => (b.rank || 0) - (a.rank || 0)).map(x => x.id) : null;
    } catch (e) { return null; }
  })());
}

// "1st", "2nd", "3rd", "11th"…
function _awardsOrdinal(n) {
  const t = n % 100, o = n % 10;
  return n + ((t >= 11 && t <= 13) ? 'th' : o === 1 ? 'st' : o === 2 ? 'nd' : o === 3 ? 'rd' : 'th');
}

/* ── Most Growth: this year against the one before ────────────────────────────
   The comparison window is the twelve months right before the eligibility
   window starts, so a Jan–Dec year compares against the previous calendar year.
   Computed from the plays whenever a card is drawn, rather than stored with
   the nominee, so hand-picked nominees and ones saved before this existed get
   it too. Cached per year until the plays or the window change. */
function _awardsGrowthWindows(start) {
  const prevS = new Date(start); prevS.setFullYear(prevS.getFullYear() - 1);
  const prevE = new Date(start.getTime() - 1);   // the last millisecond before the window
  return { prevS, prevE };
}

const _awardsGrowthCache = {};
function _awardsGrowthCounts(eligStart, eligEnd) {
  const sig = eligStart + '|' + eligEnd + '|' + allPlays.length;
  if (_awardsGrowthCache[sig]) return _awardsGrowthCache[sig];
  const start = new Date(eligStart + 'T00:00:00');
  const end   = new Date(eligEnd   + 'T23:59:59');
  const { prevS, prevE } = _awardsGrowthWindows(start);
  const cur = {}, prev = {};
  for (const p of allPlays) {
    if (p.date >= start && p.date <= end) { const k = _pk(p); cur[k] = (cur[k] || 0) + 1; }
    else if (p.date >= prevS && p.date <= prevE) { const k = _pk(p); prev[k] = (prev[k] || 0) + 1; }
  }
  // "vs 2024" for a calendar year, "vs the year before" for a custom window
  const vs = (start.getMonth() === 0 && start.getDate() === 1) ? String(prevS.getFullYear()) : 'the year before';
  return (_awardsGrowthCache[sig] = { cur, prev, vs });
}

// { cur, prev, diff, pct, vs } for an artist; pct is null when there were no
// plays the year before (growth from nothing has no percentage)
function _awardsGrowthDelta(artist, eligStart, eligEnd) {
  const c = _awardsGrowthCounts(eligStart, eligEnd);
  const k = (artist || '').toLowerCase();
  const cur = c.cur[k] || 0, prev = c.prev[k] || 0;
  return { cur, prev, diff: cur - prev, pct: prev ? (cur - prev) / prev * 100 : null, vs: c.vs };
}

function _awardsSigned(n) { return (n > 0 ? '+' : n < 0 ? '−' : '±') + Math.abs(n).toLocaleString(); }

// "+85% · +142 plays vs 2024", or "new · +142 plays vs 2024"
function _awardsGrowthLabel(d) {
  const pct = d.pct === null ? 'new' : _awardsSigned(Math.round(d.pct)) + '%';
  return `${pct} · ${_awardsSigned(d.diff)} plays vs ${d.vs}`;
}

// The Most Growth delta for a nominee on a card, or null for any other category
function _awardsGrowthFor(cat, year, item) {
  if (!cat || cat.filter !== 'growth' || !item?.artist) return null;
  const data = _awardsYearData[year] || {};
  return _awardsGrowthDelta(item.artist, data.eligStart || `${year}-01-01`, data.eligEnd || `${year}-12-31`);
}

// The user's own score for a nominee, when "Show my scores on nominee cards"
// is on. Uses the same lookup as the nominee picker (_awardsPickerItemScore).
function _awardsRatingChip(item) {
  if (!_awardsShowRating) return '';
  const s = _awardsPickerItemScore(item);
  return Number.isFinite(s) ? ratingChip(s, 'rt-chip--row aw-rt') : '';
}

/* ♪ on a nominee card ("Play samples from nominee cards"). One sample at a
   time through the ceremony's audio slot, like the picker's ♪. The buttons
   carry the nominee's key so a play/stop repaints them without a rebuild; a
   rebuild draws them from the state below anyway. */
let _awardsCardClipKey = null;          // key of the nominee whose sample is loading/playing
let _awardsCardClipLoading = false;
const _awardsCardClipMiss = new Set();  // keys neither store had a preview for

function _awardsCardClipUi(k) {
  if (_awardsCardClipKey === k) return _awardsCardClipLoading
    ? { icon: '◌', cls: ' is-on is-loading', title: t('awx_clip_finding') }
    : { icon: '❚❚', cls: ' is-on', title: t('awx_clip_stop') };
  if (_awardsCardClipMiss.has(k)) return { icon: '♪', cls: ' is-miss', title: t('awx_clip_none') };
  return { icon: '♪', cls: '', title: t('awx_clip_play') };
}

function _awardsClipBtn(cat, item) {
  if (!_awardsSamples || !item) return '';
  const k  = _awardItemKey(item);
  const ui = _awardsCardClipUi(k);
  // stopPropagation: a click on the entry itself crowns it
  return `<button type="button" class="aw-clip${ui.cls}" data-clipkey="${esc(k)}" onclick="event.stopPropagation();awardsCardPlayClip('${esc(cat.type || 'song')}',${esc(JSON.stringify(item))})" title="${ui.title}" aria-label="${ui.title}">${ui.icon}</button>`;
}

// Only the ♪ buttons change, so the cards aren't rebuilt
function _awardsCardPaintClips() {
  document.querySelectorAll('.aw-clip[data-clipkey]').forEach(btn => {
    const ui = _awardsCardClipUi(btn.dataset.clipkey);
    btn.className = 'aw-clip' + ui.cls;
    btn.textContent = ui.icon;
    btn.title = ui.title;
    btn.setAttribute('aria-label', ui.title);
  });
}

function _awardsCardStopClip() {
  if (!_awardsCardClipKey) return;
  _ceremonyStopAudio();
  _awardsCardClipKey = null;
  _awardsCardClipLoading = false;
  _awardsCardPaintClips();
}

async function awardsCardPlayClip(type, item) {
  const k = _awardItemKey(item);
  if (_awardsCardClipKey === k) { _awardsCardStopClip(); return; }   // second click stops it
  _ceremonyStopAudio();
  try { if (_ytPlayer && _ytPlayer.getPlayerState() === YT.PlayerState.PLAYING) _ytPlayer.pauseVideo(); } catch (e) {}
  _awardsCardClipKey = k;
  _awardsCardClipLoading = true;
  _awardsCardClipMiss.delete(k);
  _awardsCardPaintClips();
  const token = _ceremonyAudioToken;   // any later stop or play bumps it

  let takes = [];
  try { takes = await _ceremonyPreviewTakes(item, type); } catch (e) {}
  if (token !== _ceremonyAudioToken || _awardsCardClipKey !== k) return;
  if (!takes.length) {
    _awardsCardClipMiss.add(k);
    _awardsCardClipKey = null;
    _awardsCardClipLoading = false;
    _awardsCardPaintClips();
    return;
  }
  const audio = _ceremonyAudio = new Audio(takes[0].url);
  audio.volume = 0.8;
  audio.addEventListener('ended', () => {
    if (_ceremonyAudio !== audio) return;
    _ceremonyAudio = null;
    _awardsCardClipKey = null;
    _awardsCardPaintClips();
  });
  try {
    await audio.play();
    if (token !== _ceremonyAudioToken) { audio.pause(); return; }
    _awardsCardClipLoading = false;
  } catch (e) {
    if (_ceremonyAudio === audio) _ceremonyAudio = null;
    _awardsCardClipKey = null;
    _awardsCardClipLoading = false;
  }
  _awardsCardPaintClips();
}

// A small up/down chip for the views that don't print a score line
function _awardsGrowthChip(cat, year, item, cls) {
  if (_awardsHidePlays) return '';   // "Hide plays on nominee cards" is on
  const d = _awardsGrowthFor(cat, year, item);
  if (!d) return '';
  const dir = d.diff > 0 ? 'up' : d.diff < 0 ? 'down' : 'flat';
  const pct = d.pct === null ? 'new' : _awardsSigned(Math.round(d.pct)) + '%';
  const tip = `${d.prev.toLocaleString()} → ${d.cur.toLocaleString()} plays (${_awardsSigned(d.diff)}) vs ${d.vs}`;
  return `<span class="aw-growth aw-growth-${dir}${cls ? ' ' + cls : ''}" title="${esc(tip)}">${esc(pct)} · ${esc(_awardsSigned(d.diff))}</span>`;
}

/* "base+genre:x" categories (Best New Pop Artist is "new+genre:pop"): the
   base category's own field, kept to the entries whose genre fits. Genre is
   judged the way the plain genre awards judge it: the sheet's tags first, then
   the artist's Last.fm / Gemini tags. */
async function _awardsSplitGenre(catDef, eligStart, eligEnd, log) {
  const [base, g] = catDef.filter.split('+');
  _awardsPoolScale = 4;
  let pool;
  try { pool = await _awardsGetCandidates({ ...catDef, filter: base }, eligStart, eligEnd, log); }
  finally { _awardsPoolScale = 1; }
  await _awardsEnsureGenres(pool);
  return pool.filter(c => _awardsItemGenreFits(c, catDef.type, g)).slice(0, 20);
}
function _awardsItemGenreFits(item, type, g) {
  const artistTags = _awardsGenreCache[(item.artist || '').toLowerCase()] || [];
  if (type === 'song') return _genreMatch(_awardsSongTags(item) || [], g);
  if (type === 'album') return _awardsAlbumSheetFits(item, g) ?? _genreMatch(artistTags, g);
  return _genreMatch(_awardsArtistTags(item) || [], g);
}

async function _awardsGetCandidates(catDef, eligStart, eligEnd, log) {
  if (catDef.filter.includes('+genre:')) return _awardsSplitGenre(catDef, eligStart, eligEnd, log);
  const start = new Date(eligStart + 'T00:00:00');
  const end   = new Date(eligEnd   + 'T23:59:59');
  const inWin = allPlays.filter(p => p.date >= start && p.date <= end);
  if (!inWin.length) return [];
  const { songs, albums, artists } = _awardsCountMaps(inWin);
  const f = catDef.filter;

  if (f === 'stat') {
    if (catDef.type === 'song')   return _awardsTopTied(songs);
    if (catDef.type === 'album')  return _awardsTopTied(albums);
    if (catDef.type === 'artist') return _awardsTopTied(artists);
    return [];
  }
  if (f === 'all') {
    if (catDef.type === 'song')   return _awardsTopN(songs,   20, 3);
    if (catDef.type === 'album')  return _awardsTopN(albums,  20, 3);
    if (catDef.type === 'artist') return _awardsTopN(artists, 20, 1);
    return [];
  }
  /* Best Collaboration isn't every song with two names on it (two singers
     trading lines is a duet, and Best Duo's): it's a team-up where only one
     artist really sings, because the other is a DJ or producer, or where one
     side is a group. Each artist on the leading songs is looked up on
     MusicBrainz, one at a time (its rate limit), and a song with an artist it
     couldn't check stays in rather than being dropped on a guess. */
  if (f === 'collab') {
    const m = {};
    for (const p of inWin) {
      if (!_isCollab(p)) continue;
      const k = _sk(p);
      if (!m[k]) m[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0, names: _collabArtists(p) };
      m[k].plays++;
    }
    const pool = _awardsTopN(m, 40, 4);
    const names = [...new Set(pool.flatMap(c => c.names))];
    const toCheck = names.filter(n => _mbArtistInfoCache[n] === undefined && _mbidCache[n] === undefined).slice(0, AWARDS_MB_COLLAB_CHECKS);
    if (log && toCheck.length) log(`Checking ${toCheck.length} artist${toCheck.length !== 1 ? 's' : ''} for DJs, producers and groups…`);
    for (const n of toCheck) {
      await searchArtistMBID(n);
      // A failed request (MusicBrainz answers 503 when busy) leaves no info
      // behind, unlike "no such artist"; give it one more go after a pause
      if (_mbArtistInfoCache[n] === undefined) {
        delete _mbidCache[n];
        await new Promise(r => setTimeout(r, 2000));
        await searchArtistMBID(n);
      }
    }
    const out = [];
    for (const { names: artists, ...item } of pool) {
      const roles = artists.map(_awardsCollabRole);
      const why = roles.includes('dj') ? 'dj' : roles.includes('group') ? 'group' : roles.includes(null) ? 'unknown' : null;
      if (!why) continue;   // every artist a known solo singer
      if (why !== 'unknown') item.playLabel = `${item.plays.toLocaleString()} plays · ${why === 'dj' ? 'with a DJ/producer' : 'with a group'}`;
      out.push(item);
    }
    return out.slice(0, 20);
  }
  if (f === 'duo') {
    const m = {};
    for (const p of inWin) { if (!_isDuo(p)) continue; const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++; }
    return _awardsTopN(m, 20, 4);
  }
  if (f === 'remix') {
    const m = {};
    for (const p of inWin) { if (!_isRemix(p)) continue; const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++; }
    return _awardsTopN(m, 20, 3);
  }
  if (f === 'summer') {
    const sp = inWin.filter(p => { const m = tzDateOf(p).getMonth(); return m >= 5 && m <= 7; });
    const { songs: ss } = _awardsCountMaps(sp);
    return _awardsTopN(ss, 20, 3);
  }
  // Holiday songs and albums ranked on their holiday plays (see _awardsHolidayPlay)
  if (f === 'holiday') {
    const { songs: hs, albums: ha } = _awardsCountMaps(inWin.filter(_awardsHolidayPlay));
    const m = catDef.type === 'album' ? ha : hs;
    for (const v of Object.values(m)) v.playLabel = `${v.plays.toLocaleString()} holiday plays`;
    return _awardsTopN(m, 20, catDef.type === 'album' ? 2 : 3);
  }
  // Songs by artists you first played this year (Best New Artist Video)
  if (f === 'new_song') {
    if (!firstSeenMaps) firstSeenMaps = buildFirstSeenMaps();
    const m = {};
    for (const p of inWin) {
      const first = firstSeenMaps.artistFirst[_pa(p)];
      if (!first || first < start) continue;
      const k = _sk(p);
      m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 2);
  }
  if (f === 'new' || f === 'discovery') {
    if (!firstSeenMaps) firstSeenMaps = buildFirstSeenMaps();
    const m = {};
    for (const p of inWin) {
      const pa = _pa(p);
      const k  = pa.toLowerCase();
      const first = firstSeenMaps.artistFirst[pa];
      if (!first || first < start) continue;
      m[k] = m[k] || { artist: pa, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'comeback') {
    // Gap: 2 years before the selected year's start
    const gapS = new Date(start); gapS.setFullYear(gapS.getFullYear() - 2);
    const gapE = new Date(start); gapE.setDate(gapE.getDate() - 1);
    // Before-gap: anything played before the 2-year gap
    const beforeGapE = new Date(gapS); beforeGapE.setDate(beforeGapE.getDate() - 1);
    const gapSet    = new Set(allPlays.filter(p => p.date >= gapS && p.date <= gapE).map(p => _pk(p)));
    const historySet = new Set(allPlays.filter(p => p.date <= beforeGapE).map(p => _pk(p)));
    const m = {};
    for (const p of inWin) {
      const k = _pk(p);
      if (gapSet.has(k)) continue;     // played within the 2-year gap → not a comeback
      if (!historySet.has(k)) continue; // never played before the gap → new artist, not a comeback
      m[k] = m[k] || { artist: _pa(p), plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'growth') {
    const { prevS, prevE } = _awardsGrowthWindows(start);
    const { artists: prev } = _awardsCountMaps(allPlays.filter(p => p.date >= prevS && p.date <= prevE));
    const m = {};
    for (const [k, d] of Object.entries(artists)) {
      const delta = d.plays - (prev[k]?.plays || 0);
      // Ranked on the gain in plays; the label carries the percentage too
      if (delta > 0) m[k] = { artist: d.artist, plays: delta, playLabel: _awardsGrowthLabel(_awardsGrowthDelta(d.artist, eligStart, eligEnd)) };
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'spike') {
    const weekPeak = {};
    for (const p of inWin) {
      const d = tzDateOf(p);
      const wk = `${d.getFullYear()}-${Math.floor((d.getDate() - 1) / 7)}`;
      const k = _sk(p) + '|||' + wk;
      weekPeak[k] = weekPeak[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0, sk: _sk(p) };
      weekPeak[k].plays++;
    }
    const best = {};
    for (const v of Object.values(weekPeak)) { if (!best[v.sk] || v.plays > best[v.sk].plays) best[v.sk] = v; }
    return _awardsTopN(best, 20, 3);
  }
  /* Two day-based ladders off one pass: 'streak' is the longest unbroken run of
     days, 'days' is simply how many days of the window the item was played at
     all. Both answer song / album / artist, so the category's type picks the key.
     A single day is neither a streak nor a record, so the floor is two. */
  if (f === 'streak' || f === 'days') {
    const dayMap = {};
    for (const p of inWin) {
      const d = tzDateOf(p);
      const day = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      let k, seed;
      if (catDef.type === 'album') {
        if (!p.album) continue;
        k = _ak(p); seed = { album: p.album, artist: _pa(p) };
      } else if (catDef.type === 'artist') {
        k = _pk(p); seed = { artist: _pa(p) };
      } else {
        k = _sk(p); seed = { title: p.title, artist: p.artist, album: p.album };
      }
      if (!dayMap[k]) dayMap[k] = Object.assign({ days: new Set() }, seed);
      dayMap[k].days.add(day);
    }
    const m = {};
    for (const [k, v] of Object.entries(dayMap)) {
      const n = f === 'streak' ? longestConsecutiveDays(v.days) : v.days.size;
      if (n < 2) continue;
      // Rebuilt field by field rather than copied: the Set never reaches Firestore,
      // and `plays` is what _awardsTopN and every nominee row already rank on.
      const item = { plays: n, playLabel: f === 'streak' ? `${n}-day streak` : `${n} days played` };
      if (v.title)  item.title  = v.title;
      if (v.album)  item.album  = v.album;
      if (v.artist) item.artist = v.artist;
      m[k] = item;
    }
    // Auto categories crown the top score outright — with every item tied on it
    return catDef.auto ? _awardsTopTied(m) : _awardsTopN(m, 20, 3);
  }
  // Songs and albums that belong to a release marked as a soundtrack.
  if (f === 'soundtrack') {
    const m = {};
    for (const p of inWin) {
      if (!p.album || releaseTypeOfPlay(p) !== 'soundtrack') continue;
      const k = catDef.type === 'album' ? _ak(p) : _sk(p);
      if (!m[k]) m[k] = catDef.type === 'album'
        ? { album: p.album, artist: _pa(p), plays: 0 }
        : { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, catDef.type === 'album' ? 2 : 3);
  }
  /* Best Deep Cut: album tracks that were never singles. The library can only
     rule out songs you played off a single or EP, and most people play the
     singles from the album, so Deezer settles the rest: a track is a deep cut
     when at least three songs on its album are better known. A song Deezer
     can't place stays in on the library's word alone. */
  if (f === 'deep_cut') {
    const m = {};
    for (const p of inWin) {
      if (!_isDeepCut(p)) continue;
      const k = _sk(p);
      if (!m[k]) m[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      m[k].plays++;
    }
    const pool = _awardsTopN(m, 60, 3);
    if (log) log(`Checking which of ${pool.length} album track${pool.length !== 1 ? 's were' : ' was'} singles…`);
    await _awardsBatched(pool, 8, async c => {
      const tr = await _awardsDeezerTrack(c.title, c.artist);
      if (!tr?.albumId) return;
      const order = await _awardsDeezerAlbumOrder(tr.albumId);
      const pos = order ? order.indexOf(tr.id) : -1;
      if (pos >= 0) c.albumPos = pos + 1;
    });
    return pool
      .filter(c => !c.albumPos || c.albumPos > AWARDS_DEEP_CUT_MIN_POS)
      .slice(0, 20)
      .map(({ albumPos, ...c }) => albumPos
        ? Object.assign(c, { playLabel: `${c.plays.toLocaleString()} plays · ${_awardsOrdinal(albumPos)} best known on the album` })
        : c);
  }
  /* Awards whose field is simply "the plays that pass a test": the format
     awards on albums, and song versions told apart by their titles. */
  const playTest = _AWARDS_PLAY_TESTS[f];
  if (playTest) {
    const m = {};
    for (const p of inWin) {
      if (!playTest(p)) continue;
      const k = catDef.type === 'album' ? _ak(p) : _sk(p);
      if (!m[k]) m[k] = catDef.type === 'album'
        ? { album: p.album, artist: _pa(p), plays: 0 }
        : { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, catDef.type === 'album' ? 2 : 3);
  }
  // Songs ranked on the plays that fell in one part of the day, in your timezone
  if (f === 'night' || f === 'morning') {
    const { songs: ss } = _awardsCountMaps(inWin.filter(p => _awardsHourFits(f, tzDateOf(p).getHours())));
    for (const v of Object.values(ss)) v.playLabel = `${v.plays.toLocaleString()} ${f} plays`;
    return _awardsTopN(ss, 20, 3);
  }
  /* Most Loyal Artist: played in every month of the window (up to today, for
     the year still running), most plays first. Artists one month short follow,
     labelled as such, so a year with few perfect runs still has a field. */
  if (f === 'loyal') {
    const now  = new Date();
    const last = end < now ? end : now;
    let need = 0;
    for (let d = new Date(start.getFullYear(), start.getMonth(), 1); d <= last; d.setMonth(d.getMonth() + 1)) need++;
    const m = {};
    for (const p of inWin) {
      const d = tzDateOf(p), k = _pk(p);
      if (!m[k]) m[k] = { artist: _pa(p), plays: 0, months: new Set() };
      m[k].plays++;
      m[k].months.add(d.getFullYear() * 12 + d.getMonth());
    }
    return Object.values(m)
      .map(v => ({ artist: v.artist, plays: v.plays, n: v.months.size }))
      .filter(v => v.n >= Math.max(2, need - 1))
      .sort((a, b) => b.n - a.n || b.plays - a.plays)
      .slice(0, 20)
      // Rebuilt without the month count, which only ranked them
      .map(v => ({ artist: v.artist, plays: v.plays,
        playLabel: (v.n >= need ? 'every month' : `${v.n} of ${need} months`) + ` · ${v.plays.toLocaleString()} plays` }));
  }
  /* Best Throwback: the year's most played songs whose album came out at least
     ten years before it. Release years come from the same lookups as the late
     discovery award; a song whose year can't be found is left out. */
  if (f === 'throwback') {
    const awardsYear = start.getFullYear();
    const withAlbum = {};
    for (const [k, v] of Object.entries(songs)) if (v.album && v.album !== '—') withAlbum[k] = v;
    // Throwbacks rarely top the year, so the pool reaches well down the list;
    // the lookups are per album, and most of a year's songs share a few albums
    const pool = _awardsTopN(withAlbum, 200, 5);
    const albumsToCheck = [...new Map(pool.map(c => [c.album.toLowerCase() + '|||' + c.artist.toLowerCase(), c])).values()];
    if (log) log(`Fetching release years for ${albumsToCheck.length} album${albumsToCheck.length !== 1 ? 's' : ''}…`);
    await _awardsBatched(albumsToCheck, 10, c => _awardsGetAlbumYear(c.album, c.artist));
    const m = {};
    for (const c of pool) {
      const yr = _awardsAlbumYearCache[c.album.toLowerCase() + '|||' + c.artist.toLowerCase()];
      if (!yr || yr > awardsYear - 10) continue;
      m[_sk(c)] = { title: c.title, artist: c.artist, album: c.album, plays: c.plays, releaseYear: yr,
        playLabel: `from ${yr} · ${c.plays.toLocaleString()} plays` };
    }
    return _awardsTopN(m, 20, 3);
  }
  /* Most Underrated Song: songs you played a lot that the wider world mostly
     hasn't. "The wider world" is Deezer's popularity rank (0 – 1,000,000, no
     API key needed, so it works for every data source). Scored as plays times
     how obscure the song is; big hits drop out entirely. If Deezer can't be
     reached, the field falls back to the year's top songs to pick from. */
  if (f === 'underrated') {
    const pool = _awardsTopN(songs, 60, 3).map(c => Object.assign({}, c));
    if (log) log(`Checking how well known ${pool.length} song${pool.length !== 1 ? 's are' : ' is'}…`);
    await _awardsBatched(pool, 10, async c => { c.rank = await _awardsDeezerTrackRank(c.title, c.artist); });
    const known = pool.filter(c => c.rank);
    if (!known.length) return pool.slice(0, 20).map(({ rank, ...c }) => c);
    return known
      .filter(c => c.rank < AWARDS_UNDERRATED_MAX_RANK)
      .sort((a, b) => b.plays * (1 - b.rank / 1e6) - a.plays * (1 - a.rank / 1e6))
      .slice(0, 20)
      .map(c => ({ title: c.title, artist: c.artist, album: c.album, plays: c.plays,
        playLabel: `${c.plays.toLocaleString()} plays · popularity ${Math.round(c.rank / 10000)}/100` }));
  }
  /* Best Debut Album: an artist's first studio album to reach your library,
     first played in this window, and released this year or last. The release
     year is what keeps out an artist new to you with a long back catalogue;
     an album whose year can't be found stays in. */
  if (f === 'debut') {
    const awardsYear = start.getFullYear();
    const albumFirst = {}, artistFirst = {};
    for (const p of allPlays) {
      if (!_isStudioAlbumPlay(p)) continue;
      const ak = _ak(p), pk = _pk(p);
      if (!albumFirst[ak] || p.date < albumFirst[ak].date) albumFirst[ak] = { date: p.date, pk };
      if (!artistFirst[pk] || p.date < artistFirst[pk].date) artistFirst[pk] = { date: p.date, ak };
    }
    const m = {};
    for (const p of inWin) {
      if (!p.album) continue;
      const ak = _ak(p), a = albumFirst[ak];
      if (!a || a.date < start || artistFirst[a.pk].ak !== ak) continue;
      if (!m[ak]) m[ak] = { album: p.album, artist: _pa(p), plays: 0 };
      m[ak].plays++;
    }
    const pool = _awardsTopN(m, 30, 1);
    if (log) log(`Fetching release years for ${pool.length} album${pool.length !== 1 ? 's' : ''}…`);
    await _awardsBatched(pool, 8, c => _awardsGetAlbumYear(c.album, c.artist));
    return pool.filter(c => {
      const yr = _awardsAlbumYearCache[c.album.toLowerCase() + '|||' + c.artist.toLowerCase()];
      if (yr) c.releaseYear = yr;
      return !yr || yr >= awardsYear - 1;
    }).slice(0, 20 * _awardsPoolScale);
  }
  // Albums whose title marks them as a deluxe / expanded / anniversary edition.
  if (f === 'deluxe') {
    const m = {};
    for (const p of inWin) {
      if (!p.album || !_isDeluxeAlbum(p.album)) continue;
      const k = _ak(p);
      if (!m[k]) m[k] = { album: p.album, artist: _pa(p), plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 2);
  }
  /* Best Rock Duo/Group Song: rock songs by bands and duos. A song credited to
     two or more artists is a duo on its face; for a single credit, MusicBrainz
     says whether the artist is a person or a group. Its rate limit means one
     lookup at a time, so only the leading artists are checked, and an artist it
     can't place stays in rather than wrongly dropping a band. */
  if (f === 'rock_group') {
    await _awardsEnsureGenres(inWin);
    const m = {};
    for (const p of inWin) {
      if (!_genreMatch(_awardsSongTags(p) || [], 'genre:rock')) continue;
      const k = _sk(p);
      if (!m[k]) m[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0, lead: _pa(p), collab: _isCollab(p) };
      m[k].plays++;
    }
    const pool = _awardsTopN(m, 40, 3);
    const leads = [...new Set(pool.filter(c => !c.collab).map(c => c.lead))]
      .filter(a => _mbArtistInfoCache[a] === undefined).slice(0, AWARDS_MB_TYPE_CHECKS);
    if (log && leads.length) log(`Checking which of ${leads.length} rock artist${leads.length !== 1 ? 's are bands' : ' is a band'}…`);
    for (const a of leads) if (_mbArtistInfoCache[a] === undefined && _mbidCache[a] === undefined) await searchArtistMBID(a);
    return pool
      .filter(c => c.collab || _mbArtistInfoCache[c.lead]?.type !== 'Person')
      .slice(0, 20)
      .map(({ lead, collab, ...c }) => c);
  }
  /* Pop split by billing: solo songs on one side, duos and groups on the other.
     _isDuo is a subset of _isCollab, so the one test sorts both sides. */
  if (f === 'pop_solo' || f === 'pop_duo') {
    await _awardsEnsureGenres(inWin);
    const m = {};
    for (const p of inWin) {
      const tags = _awardsSongTags(p) || [];
      if (!_genreMatch(tags, 'genre:pop')) continue;
      if (f === 'pop_solo' ? _isCollab(p) : !_isCollab(p)) continue;
      const k = _sk(p);
      if (!m[k]) m[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 3);
  }
  if (f === 'one_hit') {
    const as = {};
    for (const p of inWin) { const k = _pk(p); const sk = _sk(p); if (!as[k]) as[k] = { artist: _pa(p), songPlays: {}, songTitles: {} }; as[k].songPlays[sk] = (as[k].songPlays[sk] || 0) + 1; as[k].songTitles[sk] = p.title; }
    const m = {};
    for (const [k, v] of Object.entries(as)) { const hits = Object.entries(v.songPlays).filter(([, c]) => c >= 10); if (hits.length === 1) { const [sk, plays] = hits[0]; m[k] = { artist: v.artist, song: v.songTitles[sk], plays }; } }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'late_disc') {
    // Count plays per album strictly before the awards year window.
    const priorPlays = {};
    for (const p of allPlays) {
      if (p.date >= start || !p.album) continue;
      const k = _ak(p);
      priorPlays[k] = (priorPlays[k] || 0) + 1;
    }
    const m = {};
    for (const p of inWin) {
      if (!p.album) continue;
      const k = _ak(p);
      // Allow albums the user barely knew before (≤20 prior plays) — covers both
      // true first-time discoveries and slow burns that finally clicked this year.
      if ((priorPlays[k] || 0) > 20) continue;
      m[k] = m[k] || { album: p.album, artist: p.artist, plays: 0 };
      m[k].plays++;
    }
    // Exclude albums released during the awards year — those aren't late discoveries.
    // (Only needed for the zero-prior-plays case; any prior play proves an earlier release.)
    const awardsYear = start.getFullYear();
    const candidates = Object.entries(m).map(([k, v]) => ({ k, ...v }));
    if (log) log(`Fetching release years for ${candidates.length} album${candidates.length !== 1 ? 's' : ''}…`);
    await Promise.all(candidates.map(c => _awardsGetAlbumYear(c.album, c.artist)));
    for (const { k, album, artist } of candidates) {
      const releaseYear = _awardsAlbumYearCache[album.toLowerCase() + '|||' + artist.toLowerCase()];
      const prior = priorPlays[k] || 0;
      // Exclude if release year is known and falls within the awards year.
      // Also exclude if year is unknown AND prior plays = 0: any prior play proves an older
      // release, but zero prior plays with no API result almost certainly means a new release.
      if ((releaseYear !== null && releaseYear >= awardsYear) || (releaseYear === null && prior === 0)) {
        delete m[k];
      } else if (m[k]) {
        m[k].releaseYear = releaseYear;
      }
    }
    return _awardsTopN(m, 20, 2);
  }
  if (f === 'nonenglish') {
    const m = {};
    for (const p of inWin) {
      if (!_hasNonLatinScript(p.title) && !_hasNonLatinScript(p.artist)) continue;
      const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++;
    }
    return _awardsTopN(m, 20, 3);
  }
  if (f.startsWith('genre:')) {
    await _awardsEnsureGenres(inWin);
    const gs = {}, ga = {}, gr = {};
    for (const p of inWin) {
      const artistTags = _awardsGenreCache[_pa(p).toLowerCase()] || [];
      const sk = _sk(p), ak = _ak(p), rk = _rk(p);
      if (_genreMatch(_awardsSongTags(p) || [], f)) {
        if (!gs[sk]) gs[sk] = { title: p.title, artist: p.artist, album: p.album, plays: 0 };
        gs[sk].plays++;
      }
      // An album is judged as a whole (its tagged tracks), not track by track
      const albumFits = _awardsAlbumSheetFits(p, f);
      if (p.album && (albumFits ?? _genreMatch(artistTags, f))) {
        if (!ga[ak]) ga[ak] = { album: p.album, artist: p.artist, plays: 0 };
        ga[ak].plays++;
      }
      if (_genreMatch(_awardsArtistTags(p) || [], f)) {
        if (!gr[rk]) gr[rk] = { artist: _pa(p), plays: 0 };
        gr[rk].plays++;
      }
    }
    if (catDef.type === 'song')   return _awardsTopN(gs, 20, 3);
    if (catDef.type === 'album')  return _awardsTopN(ga, 20, 2);
    if (catDef.type === 'artist') return _awardsTopN(gr, 20, 1);
  }
  return [];
}

// ── UI Rendering ──────────────────────────────────────────────────────────────

async function awardsInit() {
  // The remembered year was checked before the plays loaded; now they have, pull
  // it inside the real range so it never opens on a year before your first play.
  // With no plays yet the bounds fall back to "last year only", which would
  // throw the remembered year away, so leave it alone until there is a library.
  if (_awardsFirstPlayYear() != null) {
    const { min, max } = _awardsYearBounds('mygrammys');
    _awardsYear = Math.max(min, Math.min(max, _awardsYear));
  }
  _awardsSyncYearUI('mygrammys');
  _awardsSyncYearUI('reallife');
  awardsSubTab(_awardsSubTab);
}

function awardsSubTab(tab) {
  _awardsSubTab = tab;
  _awardsCloseYearPicker();
  document.querySelectorAll('.awards-subnav-btn').forEach(b => b.classList.toggle('active', b.dataset.awardsTab === tab));
  document.getElementById('awardsMyGrammys').style.display = tab === 'mygrammys' ? '' : 'none';
  document.getElementById('awardsRealLife').style.display  = tab === 'reallife'  ? '' : 'none';
  if (tab === 'mygrammys') awardsRenderYear(_awardsYear);
  if (tab === 'reallife')  loadRealLifeAwards(_realLifeYear);
}

/* Year of the oldest play in the library (any source), cached until the data
   changes. allPlays isn't guaranteed to be sorted, so scan instead of peeking. */
let _awardsFirstYearCache = null;
function _awardsFirstPlayYear() {
  if (!allPlays.length) return null;
  const c = _awardsFirstYearCache;
  if (c && c.n === allPlays.length && c.head === allPlays[0]) return c.year;
  let min = allPlays[0].date;
  for (const p of allPlays) if (p.date < min) min = p.date;
  const year = tzDate(min).getFullYear();
  _awardsFirstYearCache = { n: allPlays.length, head: allPlays[0], year };
  return year;
}

/* The years each tab can show.
   My Grammys: from the year of your first play to this year.
   Real-Life: the show's first ceremony (Grammys 1959, VMAs 1984) to this year —
   the most recent one that has actually happened, so we never land on an empty
   future page. A show with a fixed list of years (the World Music Awards, which
   ended in 2014 and skipped plenty before that) spans just that list. */
function _awardsYearBounds(kind) {
  const max = tzNow().getFullYear();
  if (kind === 'reallife') {
    const list = _realLifeYearList();
    if (list) return { min: list[0], max: list[list.length - 1] };
    return { min: RL_WIKI_SHOWS[_realLifeShow]?.first || GRAMMY_FIRST_CEREMONY_YEAR, max };
  }
  const first = _awardsFirstPlayYear();
  return { min: first == null ? max - 1 : Math.min(first, max), max };
}

// Label text, plus the arrows greyed out at either end of the range
function _awardsSyncYearUI(kind) {
  const year  = kind === 'reallife' ? _realLifeYear : _awardsYear;
  const label = document.getElementById(kind === 'reallife' ? 'realLifeYearLabel' : 'awardsYearLabel');
  if (!label) return;
  label.textContent = year;
  const { min, max } = _awardsYearBounds(kind);
  const [prev, next] = label.parentElement.querySelectorAll('.awards-year-nav-btn');
  if (prev) prev.disabled = year <= min;
  if (next) next.disabled = year >= max;
}

// The years the current Real-Life show can show, oldest first, when it's a
// fixed list rather than every year from its first — or null
function _realLifeYearList() {
  return RL_WIKI_SHOWS[_realLifeShow]?.years || null;
}
// The listed year closest to `year` (the later one on a tie), or `year` itself
// when the show has no list
function _realLifeSnapYear(year) {
  const list = _realLifeYearList();
  if (!list || list.includes(year)) return year;
  return list.reduce((best, y) => Math.abs(y - year) <= Math.abs(best - year) ? y : best, list[0]);
}

// Single entry point for both the arrows and the picker
function _awardsSetYear(kind, year) {
  const { min, max } = _awardsYearBounds(kind);
  year = Math.max(min, Math.min(max, year));
  if (kind === 'reallife') year = _realLifeSnapYear(year);
  _awardsRememberYear(kind, year);
  if (kind === 'reallife') {
    _realLifeYear = year;
    _awardsSyncYearUI(kind);
    loadRealLifeAwards(year);
  } else {
    _awardsYear = year;
    _awardsSyncYearUI(kind);
    awardsRenderYear(year);
  }
}

function awardsChangeYear(delta)         { _awardsSetYear('mygrammys', _awardsYear + delta); }
function realLifeAwardsChangeYear(delta) {
  // With a fixed list of years, the arrows jump to the next one that has a show
  const list = _realLifeYearList();
  if (!list) return _awardsSetYear('reallife', _realLifeYear + delta);
  const next = delta > 0 ? list.find(y => y > _realLifeYear) : list.slice().reverse().find(y => y < _realLifeYear);
  if (next != null) _awardsSetYear('reallife', next);
}

/* Year picker: clicking the year opens a grid of every year in range, newest
   first, so you can jump straight to one instead of stepping through them all.
   Lives on <body> with fixed positioning so no parent's overflow can clip it. */
function awardsOpenYearPicker(kind) {
  const label = document.getElementById(kind === 'reallife' ? 'realLifeYearLabel' : 'awardsYearLabel');
  const existing = document.getElementById('awardsYearPicker');
  if (existing) {
    const wasSame = existing.dataset.kind === kind;
    _awardsCloseYearPicker();
    if (wasSame) return;   // a second click on the year closes it
  }
  const { min, max } = _awardsYearBounds(kind);
  const current = kind === 'reallife' ? _realLifeYear : _awardsYear;
  let chips = '';
  const list = kind === 'reallife' ? _realLifeYearList() : null;
  for (let y = max; y >= min; y--) {
    if (list && !list.includes(y)) continue;   // only years that had a show
    chips += `<button type="button" class="awards-year-chip${y === current ? ' is-current' : ''}" data-year="${y}">${y}</button>`;
  }
  const pop = document.createElement('div');
  pop.id = 'awardsYearPicker';
  pop.className = 'awards-year-picker';
  pop.dataset.kind = kind;
  pop.setAttribute('role', 'dialog');
  pop.setAttribute('aria-label', 'Pick a year');
  pop.innerHTML = `<div class="awards-year-picker-grid">${chips}</div>`;
  document.body.appendChild(pop);

  // Under the stepper pill, left edges aligned, kept inside the viewport
  const r = label.parentElement.getBoundingClientRect();
  pop.style.top  = `${r.bottom + 8}px`;
  pop.style.left = `${Math.max(8, Math.min(r.left, window.innerWidth - pop.offsetWidth - 8))}px`;
  label.classList.add('is-open');
  label.setAttribute('aria-expanded', 'true');

  pop.addEventListener('click', e => {
    const chip = e.target.closest('.awards-year-chip');
    if (!chip) return;
    _awardsCloseYearPicker();
    _awardsSetYear(kind, +chip.dataset.year);
    label.focus();
  });
  const cur = pop.querySelector('.is-current');
  if (cur) { cur.scrollIntoView({ block: 'nearest' }); cur.focus({ preventScroll: true }); }

  // Outside click / Escape / page scroll / resize close it (deferred so the
  // click that opened it doesn't immediately close it)
  setTimeout(() => {
    document.addEventListener('pointerdown', _awardsYearPickerOutside, true);
    document.addEventListener('keydown', _awardsYearPickerKey, true);
    window.addEventListener('scroll', _awardsCloseYearPicker, { passive: true });
    window.addEventListener('resize', _awardsCloseYearPicker);
  }, 0);
}

function _awardsYearPickerOutside(e) {
  const pop = document.getElementById('awardsYearPicker');
  if (!pop || pop.contains(e.target) || e.target.closest('.awards-year-label')) return;
  _awardsCloseYearPicker();
}
function _awardsYearPickerKey(e) {
  if (e.key !== 'Escape') return;
  const kind = document.getElementById('awardsYearPicker')?.dataset.kind;
  _awardsCloseYearPicker();
  // the Soundtrack's period picker borrows this popover too
  const labelId = kind === 'soundtrack' ? 'stNavLabel' : kind === 'reallife' ? 'realLifeYearLabel' : 'awardsYearLabel';
  document.getElementById(labelId)?.focus();
}
function _awardsCloseYearPicker() {
  document.getElementById('awardsYearPicker')?.remove();
  document.querySelectorAll('.awards-year-label.is-open').forEach(l => {
    l.classList.remove('is-open');
    l.setAttribute('aria-expanded', 'false');
  });
  document.removeEventListener('pointerdown', _awardsYearPickerOutside, true);
  document.removeEventListener('keydown', _awardsYearPickerKey, true);
  window.removeEventListener('scroll', _awardsCloseYearPicker);
  window.removeEventListener('resize', _awardsCloseYearPicker);
}

// View Ceremony + Share appear in two places once a category has a winner:
// beside the year at the top, and under the cards (phase 9 part 5 step 2)
function _awardsShowCeremonyBtns(show) {
  const bar = document.getElementById('awardsCeremonyBar');
  if (bar) bar.style.display = show ? '' : 'none';
  document.querySelectorAll('.awards-top-ceremony').forEach(el => { el.style.display = show ? '' : 'none'; });
}

/* A language switch (setLanguage) draws the Awards page again in the new
   language: the cards, the stats block and the category list on My Grammys,
   the open show on Real-Life Awards, and an open ceremony or nominee picker.
   Nothing is fetched again; every piece redraws from what is already loaded.
   (Phase 9 part 5 step 10: before this, the cards kept the old language.) */
function awardsOnLanguageChange() {
  const view = document.getElementById('awardsView');
  const shown = view && view.style.display !== 'none';
  const data = _awardsYearData?.[_awardsYear];
  if (shown && _awardsSubTab === 'mygrammys' && data) {
    _awardsRenderCatList(data);
    _awardsRenderCatToggles(data);
    _awardsRenderSummary(_awardsYear);
    _awardsSyncYearUI('mygrammys');
  }
  if (shown && _awardsSubTab === 'reallife') loadRealLifeAwards(_realLifeYear);
  if (document.getElementById('awardsCeremonyOverlay')?.style.display === 'flex' && _ceremonyData) {
    _ceremonyDrawSidebar(_ceremonyData);
    _ceremonyRender();
    _ceremonyPaintSoundBtn();
  }
  if (document.getElementById('awardsPickerOverlay')) _awardsPickerRefresh(false);
}

async function awardsRenderYear(year) {
  const statusEl = document.getElementById('awardsStatus');
  statusEl.textContent = '';
  if (!allPlays.length) {
    statusEl.textContent = t('awx_need_data');
    document.getElementById('awardsCatList').innerHTML = '';
    _awardsRenderViewBar(false);
    document.getElementById('awardsSummary').innerHTML = '';
    _awardsShowCeremonyBtns(false);
    return;
  }
  statusEl.textContent = t('awx_loading');
  const data = await _awardsLoad(year);
  statusEl.textContent = '';
  _awardsRenderCatToggles(data);
  document.getElementById('awardsEligStart').value = data.eligStart;
  document.getElementById('awardsEligEnd').value   = data.eligEnd;
  _awardsRenderCatList(data);
}

/* ─── Configure Year: the category browser ─────────────────────────────────────
   Eighty-odd categories in one flat grid of checkboxes was a wall of text, so
   they are grouped into sections, each card says in a line what the category
   is built from, and the list can be searched and narrowed by type (song /
   album / artist), by on/off, and by group. Enable All / Disable All act on
   whatever is showing, so "search rock, Enable All" turns on every rock award.
   The filters are per session and never saved: they're a way of looking, not
   part of the year. */
const AWARD_GROUPS = [
  { id: 'core',      icon: '🏆', ids: ['song_of_year', 'album_of_year', 'artist_of_year', 'record_of_year', 'new_artist', 'video_of_year', 'best_collab', 'best_duo'] },
  // Rock first, so its awards gather here instead of in the long Genres list
  { id: 'rock',      icon: '🎸', ids: ['best_rock_song', 'best_rock_album', 'best_alt_song', 'best_alt_album', 'best_metal_song', 'best_metal_album',
                                       'best_punk_song', 'best_punk_album', 'best_poprock_song', 'best_poppunk_song', 'best_indierock_song', 'best_indierock_album',
                                       'best_classicrock_song', 'best_hardrock_song', 'best_postpunk_song', 'best_grunge_song', 'best_prog_album', 'best_shoegaze_song', 'best_goth_song', 'best_goth_album',
                                       'best_rock_performance', 'best_rock_ballad', 'best_guitar_moment', 'best_rock_group'] },
  { id: 'pop',       icon: '🎀', ids: ['best_pop_song', 'best_pop_album', 'best_pop_vocal_album', 'best_pop_solo', 'best_pop_duo', 'best_dancepop_rec', 'best_indiepop_song',
                                       'pop_artist_of_year', 'best_new_pop_artist', 'best_pop_debut_album', 'best_pop_ep', 'best_pop_remix', 'best_pop_ballad', 'best_pop_vocal',
                                       'best_pop_hook', 'best_synthpop_song', 'best_latinpop_song', 'best_altpop_song', 'best_hyperpop_song', 'best_artpop_album'] },
  // Every music video award, Video of the Year aside (it stays with the majors)
  { id: 'video',     icon: '📹', test: c => c.id !== 'video_of_year' && ((c.hint || '').startsWith('video_') || ['best_live_performance', 'best_music_film'].includes(c.id)) },
  { id: 'gospel',    icon: '🙏', ids: ['best_gospel_song', 'best_ccm_song', 'best_worship_song', 'best_gospel_album', 'best_ccm_album', 'christian_artist_of_year',
                                       'best_christian_hiphop_song', 'best_gospel_collab'] },
  { id: 'instrumental', icon: '🎹', ids: ['best_instrumental_song', 'best_instrumental_version', 'best_lofi_song', 'best_piano_piece', 'best_game_music',
                                       'best_instrumental_composition', 'best_jazz_album', 'best_classical_album'] },
  { id: 'genre',     icon: '🎼', test: c => c.filter.startsWith('genre:') || ['best_pop_solo', 'best_pop_duo', 'best_nonenglish'].includes(c.id) },
  { id: 'format',    icon: '💿', ids: ['best_album_cover', 'best_album_concept', 'best_holiday_album', 'best_deluxe_album', 'best_deluxe_cover', 'best_ep', 'best_live_album', 'best_debut_album', 'best_reissue', 'best_compilation', 'best_soundtrack_album', 'late_discovery'] },
  { id: 'songtype',  icon: '🎵', ids: ['song_summer', 'best_holiday_song', 'most_viral_song', 'best_remix', 'best_remixed_rec', 'best_soundtrack_song', 'best_cover_song', 'best_acoustic_version', 'best_breakup_song', 'best_throwback', 'best_deep_cut'] },
  { id: 'listening', icon: '🎧', ids: ['best_discovery', 'best_comeback', 'most_growth', 'obsessive_play', 'one_hit_wonder', 'best_night_song', 'best_morning_song', 'most_loyal_artist', 'best_concert_song'] },
  { id: 'fun',       icon: '🎉', ids: ['guilty_pleasure', 'most_underrated_song'] },
  { id: 'stats',     icon: '📊', test: c => !!c.auto },
];
// Anything added later without a group still shows up, under "More"
const AWARD_GROUP_OTHER = { id: 'other', icon: '✨' };

let _awcQ = '', _awcType = 'all', _awcStatus = 'all', _awcGroup = 'all';

function _awardsCatGroup(cat) {
  return AWARD_GROUPS.find(g => g.ids ? g.ids.includes(cat.id) : g.test(cat)) || AWARD_GROUP_OTHER;
}

// One line on what the category is built from, keyed on its filter
function _awardsCatHint(cat) {
  // A hand-written line on what to look for (awards_desc_<id>) wins over the
  // filter-based ones, for categories that share a filter (Song vs Record of
  // the Year, the rock ballad / riff awards) and would otherwise read the same
  const dKey = 'awards_desc_' + cat.id;
  const desc = t(dKey);
  if (desc && desc !== dKey) return desc;
  // A category can name its own hint when its filter alone would mislead
  // (the ceremony-style rock awards share Best Rock Song's filter)
  if (cat.hint) return t('awards_hint_' + cat.hint);
  // Genre awards describe what the genre sounds like (awards_hint_genre_<slug>,
  // '-' becomes '_'); a genre without its own line falls back to the generic one
  if (cat.filter.startsWith('genre:')) {
    const gKey = 'awards_hint_genre_' + cat.filter.slice(6).replace(/-/g, '_');
    const line = t(gKey);
    return line && line !== gKey ? line : t('awards_hint_genre');
  }
  return t('awards_hint_' + cat.filter.replace(':', '_'));
}

function _awcEnabled(data, cat) { return data.categories[cat.id]?.enabled ?? cat.defaultOn; }

/* Favourite categories: a ★ on a category, kept across years (not per year) so
   a new year can be set up with just the favourites ("Favorites only" in
   Configure Year). Starred from the Configure Year cards, the nominee card
   headers and the nominee picker. Synced like the other awards settings, as a
   JSON array of category ids. */
const AWARDS_FAV_CATS_KEY = 'dc_awards_fav_cats';
function _awardsReadFavCats() {
  try { const a = JSON.parse(localStorage.getItem(AWARDS_FAV_CATS_KEY) || '[]'); return new Set(Array.isArray(a) ? a : []); }
  catch (e) { return new Set(); }
}
let _awardsFavCats = _awardsReadFavCats();

// The star button, shared by every surface. data-fav-cat lets a flip repaint
// every copy of it in place (card header and picker can both be on screen).
function _awardsFavBtn(catId, cls) {
  const on = _awardsFavCats.has(catId);
  const tip = t(on ? 'awards_fav_remove' : 'awards_fav_add');
  return `<button type="button" class="awards-fav-btn${cls ? ' ' + cls : ''}${on ? ' is-fav' : ''}" data-fav-cat="${esc(catId)}" aria-pressed="${on}" title="${esc(tip)}" aria-label="${esc(tip)}" onclick="awardsToggleFavCat(event,'${esc(catId)}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.9l-5.2 2.7 1-5.8-4.3-4.1 5.9-.9z"/></svg></button>`;
}

function awardsToggleFavCat(e, catId) {
  // The Configure Year card is a <label>; don't let the click reach its switch
  if (e) { e.preventDefault(); e.stopPropagation(); }
  const on = !_awardsFavCats.has(catId);
  if (on) _awardsFavCats.add(catId); else _awardsFavCats.delete(catId);
  const val = JSON.stringify([..._awardsFavCats]);
  localStorage.setItem(AWARDS_FAV_CATS_KEY, val);
  // Targeted write, same as awardsSetCreditFeatures
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_FAV_CATS_KEY, val);
  _awardsPaintFavBtns();
  const data = _awardsYearData[_awardsYear];
  if (data) _awcUpdateCounts(data);
}

// Repaint every star on screen from _awardsFavCats (also after a cloud sync)
function _awardsPaintFavBtns() {
  document.querySelectorAll('.awards-fav-btn[data-fav-cat]').forEach(b => {
    const on = _awardsFavCats.has(b.dataset.favCat);
    const tip = t(on ? 'awards_fav_remove' : 'awards_fav_add');
    b.classList.toggle('is-fav', on);
    b.setAttribute('aria-pressed', String(on));
    b.title = tip;
    b.setAttribute('aria-label', tip);
    b.closest('.awc-card')?.classList.toggle('is-fav', on);
  });
}

// "Favorites only": the favourites on, every other category off, whatever the
// filters show. Nominees already picked are kept, so it can be undone.
function awardsCatFavsOnly() {
  const data = _awardsYearData[_awardsYear];
  if (!data || !_awardsFavCats.size) return;
  for (const cat of AWARD_CATEGORIES) {
    const enabled = _awardsFavCats.has(cat.id);
    if (!data.categories[cat.id]) data.categories[cat.id] = { enabled, nominees: [], winner: null };
    data.categories[cat.id].enabled = enabled;
  }
  _awardsRenderCatToggles(data);
  _awardsSave(_awardsYear);
  _awardsRenderCatList(data);
}

// Lower-cased with accents dropped, so "album" finds "Álbum" in Spanish
function _awcNorm(str) { return String(str || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }

// Does a category pass the search and filters? The group filter can be left
// out, which is how each group chip counts what it would show.
function _awcMatches(cat, data, withGroup = true) {
  if (_awcType !== 'all' && cat.type !== _awcType) return false;
  if (_awcStatus === 'fav') { if (!_awardsFavCats.has(cat.id)) return false; }
  else if (_awcStatus !== 'all' && _awcEnabled(data, cat) !== (_awcStatus === 'on')) return false;
  if (withGroup && _awcGroup !== 'all' && _awardsCatGroup(cat).id !== _awcGroup) return false;
  if (!_awcQ) return true;
  const hay = _awcNorm([t('awards_cat_' + cat.id), cat.label, _awardsCatHint(cat),
    t('awards_group_' + _awardsCatGroup(cat).id), cat.type, cat.filter.replace('genre:', '')].join(' '));
  // Every word has to match somewhere, in any order: "rock album", "album rock"
  return _awcNorm(_awcQ).split(/\s+/).filter(Boolean).every(w => hay.includes(w));
}

function _awcFiltering() { return !!_awcQ || _awcType !== 'all' || _awcStatus !== 'all' || _awcGroup !== 'all'; }

// The name with the searched words picked out
function _awcMark(text) {
  const words = _awcQ ? _awcNorm(_awcQ).split(/\s+/).filter(Boolean) : [];
  if (!words.length) return esc(text);
  const norm = _awcNorm(text);
  // Mark by position on the normalised copy; stripping accents keeps lengths
  const hit = new Array(text.length).fill(false);
  for (const w of words) {
    let i = norm.indexOf(w);
    while (i !== -1) { for (let k = i; k < i + w.length && k < hit.length; k++) hit[k] = true; i = norm.indexOf(w, i + w.length); }
  }
  let out = '', open = false;
  for (let k = 0; k < text.length; k++) {
    if (hit[k] !== open) { out += hit[k] ? '<mark>' : '</mark>'; open = hit[k]; }
    out += esc(text[k]);
  }
  return out + (open ? '</mark>' : '');
}

function _awcCardHtml(cat, data) {
  const on = _awcEnabled(data, cat);
  const name = t('awards_cat_' + cat.id);
  // for= names the switch: without it the label's control is the first
  // labelable thing inside it, the ☆ button, so a click on the card starred
  // nothing and switched nothing
  return `<label class="dc-card-inset awc-card${on ? ' is-on' : ''}${_awardsFavCats.has(cat.id) ? ' is-fav' : ''}" data-cat="${esc(cat.id)}" for="awcIn_${esc(cat.id)}">
    <span class="awc-emoji" aria-hidden="true">${cat.emoji || '🏆'}</span>
    <span class="awc-text">
      <span class="awc-name">${_awcMark(name)}</span>
      <span class="awc-hint">${esc(_awardsCatHint(cat))}</span>
    </span>
    <span class="awc-tags">
      <span class="awards-type-badge awards-type-${cat.type}">${esc(t('awards_cat_type_' + cat.type))}</span>
      ${cat.auto ? `<span class="dc-chip dc-chip-warn awards-auto-badge">${esc(t('awards_cat_auto'))}</span>` : ''}
    </span>
    ${_awardsFavBtn(cat.id, 'awc-fav')}
    <span class="src-switch">
      <input type="checkbox" id="awcIn_${esc(cat.id)}" ${on ? 'checked' : ''} onchange="awardsToggleCat('${esc(cat.id)}',this.checked)" aria-label="${esc(name)}">
      <span class="src-switch-slider"></span>
    </span>
  </label>`;
}

function _awardsRenderCatToggles(data) {
  const el = document.getElementById('awardsCatToggles');
  if (!el || !data) return;
  // Filter buttons and the clear ✕ follow the state (they live in the static bar)
  document.querySelectorAll('#awardsCatTypeSeg button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === _awcType)));
  document.querySelectorAll('#awardsCatStatusSeg button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === _awcStatus)));
  const clr = document.getElementById('awardsCatSearchClear');
  if (clr) clr.hidden = !_awcQ;

  // Group chips: what each group would show under the other filters
  const groups = [...AWARD_GROUPS, AWARD_GROUP_OTHER];
  const chipsEl = document.getElementById('awardsCatGroups');
  if (chipsEl) {
    const pool = AWARD_CATEGORIES.filter(c => _awcMatches(c, data, false));
    const chip = (id, icon, label, n) =>
      `<button type="button" class="dc-chip awc-chip" data-g="${id}" aria-pressed="${_awcGroup === id}" onclick="awardsCatFilter('group','${id}')"${n === 0 && _awcGroup !== id ? ' disabled' : ''}>${icon ? `<span aria-hidden="true">${icon}</span>` : ''}${esc(label)}<span class="awc-chip-n">${n}</span></button>`;
    chipsEl.innerHTML = chip('all', '', t('awards_group_all'), pool.length)
      + groups.map(g => {
        const n = pool.filter(c => _awardsCatGroup(c).id === g.id).length;
        return (g.id === 'other' && !AWARD_CATEGORIES.some(c => _awardsCatGroup(c).id === 'other')) ? '' : chip(g.id, g.icon, t('awards_group_' + g.id), n);
      }).join('');
  }

  const shown = AWARD_CATEGORIES.filter(c => _awcMatches(c, data));
  if (!shown.length) {
    el.innerHTML = `<div class="awc-empty">
      <span>${esc(_awcQ ? t('awards_cat_none_q', { q: _awcQ }) : t('awards_cat_none'))}</span>
      <button type="button" class="dc-btn dc-btn-normal dc-btn-sm awc-bulk-btn" onclick="awardsCatClearFilters()">${esc(t('awards_cat_clear'))}</button>
    </div>`;
  } else {
    el.innerHTML = groups.map(g => {
      let cats = shown.filter(c => _awardsCatGroup(c).id === g.id);
      if (!cats.length) return '';
      // Genres are the long list, so they go A–Z, which also pairs each
      // genre's song and album awards
      if (g.id === 'genre' || g.id === 'rock') cats = cats.slice().sort((a, b) => t('awards_cat_' + a.id).localeCompare(t('awards_cat_' + b.id)));
      return `<section class="awc-group" data-g="${g.id}">
        <header class="awc-group-head">
          <span class="awc-group-icon" aria-hidden="true">${g.icon}</span>
          <h4>${esc(t('awards_group_' + g.id))}</h4>
          <span class="awc-group-n" data-awc-gcount="${g.id}"></span>
          <span class="awc-group-acts">
            <button type="button" onclick="awardsCatGroupSet('${g.id}',true)">${esc(t('awards_cat_all_on'))}</button>
            <button type="button" onclick="awardsCatGroupSet('${g.id}',false)">${esc(t('awards_cat_all_off'))}</button>
          </span>
        </header>
        <div class="awc-grid">${cats.map(c => _awcCardHtml(c, data)).join('')}</div>
      </section>`;
    }).join('');
  }
  _awcUpdateCounts(data);
}

// Counts and bulk-button labels, patched in place after a single switch flips
// so the list doesn't redraw under the pointer (and a card switched off while
// "On" is the filter stays put until the filters change)
function _awcUpdateCounts(data) {
  const on = AWARD_CATEGORIES.filter(c => _awcEnabled(data, c)).length;
  const cnt = document.getElementById('awardsCatCount');
  if (cnt) cnt.textContent = t('awards_cat_count', { on, total: AWARD_CATEGORIES.length });
  const shown = AWARD_CATEGORIES.filter(c => _awcMatches(c, data));
  const filtering = _awcFiltering();
  const allOn = document.getElementById('awardsCatAllOn'), allOff = document.getElementById('awardsCatAllOff');
  if (allOn)  allOn.textContent  = filtering ? t('awards_enable_shown',  { n: shown.length }) : t('awards_enable_all');
  if (allOff) allOff.textContent = filtering ? t('awards_disable_shown', { n: shown.length }) : t('awards_disable_all');
  // Favorites only needs at least one star; the status button shows how many
  const favN = AWARD_CATEGORIES.filter(c => _awardsFavCats.has(c.id)).length;
  const favOnly = document.getElementById('awardsCatFavsOnly');
  if (favOnly) {
    favOnly.disabled = !favN;
    favOnly.textContent = t('awards_cat_favs_only', { n: favN });
    favOnly.title = t(favN ? 'awards_cat_favs_only_tip' : 'awards_cat_favs_none');
  }
  const favSeg = document.querySelector('#awardsCatStatusSeg button[data-v="fav"] .awc-seg-n');
  if (favSeg) favSeg.textContent = favN;
  document.querySelectorAll('#awardsCatToggles [data-awc-gcount]').forEach(el => {
    const cats = AWARD_CATEGORIES.filter(c => _awardsCatGroup(c).id === el.dataset.awcGcount);
    el.textContent = t('awards_cat_group_count', { on: cats.filter(c => _awcEnabled(data, c)).length, total: cats.length });
  });
}

function awardsCatFilter(kind, value) {
  if (kind === 'q') _awcQ = String(value || '').trim();
  else if (kind === 'type') _awcType = value;
  else if (kind === 'status') _awcStatus = value;
  else if (kind === 'group') _awcGroup = (value === _awcGroup && value !== 'all') ? 'all' : value;  // a second click lets go
  _awardsRenderCatToggles(_awardsYearData[_awardsYear]);
}

function awardsCatClearFilters() {
  _awcQ = ''; _awcType = 'all'; _awcStatus = 'all'; _awcGroup = 'all';
  const i = document.getElementById('awardsCatSearch');
  if (i) i.value = '';
  _awardsRenderCatToggles(_awardsYearData[_awardsYear]);
}

// A section's All on / All off: the section's cards that are showing
function awardsCatGroupSet(groupId, enabled) {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  _awardsSetCats(data, AWARD_CATEGORIES.filter(c => _awardsCatGroup(c).id === groupId && _awcMatches(c, data)), enabled);
}

function _awardsSetCats(data, cats, enabled) {
  for (const cat of cats) {
    if (!data.categories[cat.id]) data.categories[cat.id] = { enabled, nominees: [], winner: null };
    data.categories[cat.id].enabled = enabled;
  }
  _awardsRenderCatToggles(data);
  _awardsSave(_awardsYear);
  _awardsRenderCatList(data);
}

function _awardsRenderCatList(data) {
  const el = document.getElementById('awardsCatList');
  if (!el) return;
  const activeCats = AWARD_CATEGORIES.filter(c => data.categories[c.id]?.enabled ?? c.defaultOn);
  // "Hide decided" leaves out the categories that already have a winner
  const shownCats = _awardsHideDecided
    ? activeCats.filter(c => !_awardsCatDecided(c, data.categories[c.id]))
    : activeCats;
  const seq = ++_awardsViewSeq;
  _awardsRenderViewBar(activeCats.length > 0, {
    hidden:  activeCats.length - shownCats.length,
    // Still waiting on a winner, whether or not "Hide decided" is on
    pending: activeCats.filter(c => !_awardsCatDecided(c, data.categories[c.id])).length,
    total:   activeCats.length,
  });
  if (!activeCats.length) {
    el.innerHTML = `<div class="awards-empty">${t('awards_no_categories')}</div>`;
    _awardsShowCeremonyBtns(false);
    _awardsRenderSummary(data.year);
    return;
  }
  const view  = _awardsView;
  const queue = [];
  el.dataset.view = view;
  el.innerHTML = !shownCats.length
    // Every category is decided and they're all hidden: say so, with a way back
    ? `<div class="awards-empty">${esc(t('awards_all_decided'))}
        <button class="dc-btn dc-btn-normal dc-btn-sm awards-cat-action-btn" onclick="awardsSetHideDecided(false)">${esc(t('awards_show_decided'))}</button></div>`
    : shownCats.map((cat, i) => {
    const cd = data.categories[cat.id] || { enabled: true, nominees: [], winner: null };
    return view === 'ballot'
      ? _awardsRenderCatCard(cat, cd, data.year, i)
      : _awardsRenderArtCard(cat, cd, data.year, i, view, `awv${seq}_${i}`, queue);
  }).join('');
  if (queue.length) _awardsViewLoadArt(queue, seq);
  // Art-view entries are role="button" divs; Enter and Space should crown them too
  if (!el.dataset.keys) {
    el.dataset.keys = '1';
    el.addEventListener('keydown', e => {
      if ((e.key === 'Enter' || e.key === ' ') && e.target.matches?.('[data-pick]')) { e.preventDefault(); e.target.click(); }
    });
    _awardsBindDrag(el);
  }
  const hasWinner = activeCats.some(c => data.categories[c.id]?.winner);
  _awardsShowCeremonyBtns(hasWinner);
  // Every change to the ballot comes through here, so the stats block above the
  // cards stays in step with a new nominee or a freshly crowned winner.
  _awardsRenderSummary(data.year);
}

/* ─── Stats & records summary ──────────────────────────────────────────────────
   The block at the top of a year's nominees (and the opening slide of the
   ceremony): the all-time leaders in nominations and wins as they stood that
   year, for artists, albums and songs, plus that year's nomination ranking.

   Everything is counted from the saved ballots, not from plays, so it reads the
   same for Last.fm, Google Sheets and CSV libraries alike.

   Counting rules:
   • Only enabled categories count, the same as the artist modal's Grammy strip.
   • Every nominee entry is one nomination (two songs in one category = two).
   • An artist is credited for every nominee they lead: songs and albums as
     well as artist categories. Featured artists are credited too when the
     "Count featured artists" switch is on (_awardsCreditFeatures); otherwise
     only the first name gets it. Either way the album and song records are
     unchanged, since a feature never splits the record itself.
   • Albums and songs only count in categories of their own type.
   • "All time" means every year up to and including the one on screen, so
     flipping back to 2021 shows the records as they stood in 2021.

   spoilerFree (the ceremony) leaves out this year's wins, and this year's auto
   categories entirely, because their only nominee is the winner. The summary
   is shown before any envelope is opened, so it must not give a result away. */
const AWARDS_SUMMARY_RANK_N = 10;   // rows in the "most nominations this year" list
let _awardsSummarySeq = 0;          // guards the tab's async render against fast year flips

/* Featured artists get award credit only when the user asks for it. Global,
   not per year, and synced across devices like the other settings. */
const AWARDS_CREDIT_FEATURES_KEY = 'dc_awards_credit_features';
let _awardsCreditFeatures = localStorage.getItem(AWARDS_CREDIT_FEATURES_KEY) === '1';

/* Hides the play counts (and play-based labels like "+85% · +142") on the
   nominee cards, for a ballot that reads as a pure opinion rather than a stats
   sheet. Display only: the picker still ranks and shows plays, and suggestions
   are unchanged. Global and synced, like the switch above. */
const AWARDS_HIDE_PLAYS_KEY = 'dc_awards_hide_plays';
let _awardsHidePlays = localStorage.getItem(AWARDS_HIDE_PLAYS_KEY) === '1';

/* Shows the user's own score (0–10, from the ratings system) as a chip on the
   nominee cards. Off by default; global and synced, like the switches above.
   Unrated nominees simply show no chip. */
const AWARDS_SHOW_RATING_KEY = 'dc_awards_show_rating';
let _awardsShowRating = localStorage.getItem(AWARDS_SHOW_RATING_KEY) === '1';

/* Puts a ♪ on each nominee that plays its 30-second store preview, the same
   sample the nominee picker and the ceremony play. Off by default; global and
   synced, like the switches above. */
const AWARDS_SAMPLES_KEY = 'dc_awards_samples';
let _awardsSamples = localStorage.getItem(AWARDS_SAMPLES_KEY) === '1';

/* "Hide decided" switch in the view bar: leaves out every category that already
   has a winner (auto categories always do), so only the ones still to vote on
   are on screen. Display only; global and synced, like the switches above. */
const AWARDS_HIDE_DECIDED_KEY = 'dc_awards_hide_decided';
let _awardsHideDecided = localStorage.getItem(AWARDS_HIDE_DECIDED_KEY) === '1';

/* Categories folded down to their header with the card's chevron. Kept on this
   device only (not synced), by category id, so a fold sticks across years and
   reloads until it's opened again. */
const AWARDS_COLLAPSED_KEY = 'dc_awards_collapsed';
const _awardsCollapsed = (() => {
  try { return new Set(JSON.parse(localStorage.getItem(AWARDS_COLLAPSED_KEY) || '[]')); }
  catch (e) { return new Set(); }
})();

// "A feat. B", "A ft. B", "A featuring B" and "A with B" inside one artist string
const _AWARDS_FEAT_SPLIT = /\s+(?:feat\.?|ft\.?|featuring|with)\s+/i;
// "A & B", "A x B", "A and B", "A vs B": a collaboration, or a duo's own name
const _AWARDS_COLLAB_SPLIT = /\s+(?:&|x|and|vs\.?)\s+/i;
// "(feat. B & C)" / "[ft. B]" in a song title, where many libraries keep features
const _AWARDS_TITLE_FEAT = /[(\[]\s*(?:feat\.?|ft\.?|featuring|with)\s+([^)\]]+)[)\]]/i;

/* Every artist a nominee credits, lead first, no repeats. The artist string is
   split the same way as the rest of the app (commas, via splitArtists, which
   honours the comma exceptions and the "keep as one artist" setting) and then
   on feat./ft. With the switch on, "&" / "x" / "and" / "vs" split too, but
   only when every name is an artist in its own right in the library, so duos
   like Simon & Garfunkel stay whole. Inside a title's "(feat. …)" the list is
   only ever names, so it always splits. */
/* Every artist name in the library, lowercased, to tell a collaboration from a
   duo: "Lady Gaga & Bruno Mars" splits because both play on their own, while
   "Simon & Garfunkel" stays whole because nobody called "Simon" does. Rebuilt
   whenever the library changes size. */
let _awardsKnownArtists = null, _awardsKnownArtistsN = -1;
function _awardsIsKnownArtist(name) {
  if (_awardsKnownArtistsN !== allPlays.length) {
    _awardsKnownArtists = new Set();
    for (const p of allPlays) for (const a of splitArtists(p.artist || '')) _awardsKnownArtists.add(a.trim().toLowerCase());
    _awardsKnownArtistsN = allPlays.length;
  }
  return _awardsKnownArtists.has(name.trim().toLowerCase());
}

function _awardsCredits(n, withFeatures) {
  const out = [], seen = new Set();
  const add = name => {
    const nm = (name || '').trim();
    const k = nm.toLowerCase();
    if (nm && !seen.has(k)) { seen.add(k); out.push(nm); }
  };
  for (const part of splitArtists(n.artist || '')) {
    for (const name of part.split(_AWARDS_FEAT_SPLIT)) {
      // With the switch on, "A & B" credits both, but only when every name in it
      // is an artist of its own in the library (see _awardsIsKnownArtist)
      const pieces = withFeatures ? name.split(_AWARDS_COLLAB_SPLIT) : [name];
      if (pieces.length > 1 && pieces.every(_awardsIsKnownArtist)) pieces.forEach(add);
      else add(name);
    }
  }
  if (!withFeatures) return out.slice(0, 1);
  const m = (n.title || '').match(_AWARDS_TITLE_FEAT);
  if (m) m[1].split(/\s*,\s*|\s+&\s+|\s+and\s+/i).forEach(add);
  return out;
}

// The switch in the My Grammys settings panel
function awardsSetCreditFeatures(on) {
  _awardsCreditFeatures = !!on;
  localStorage.setItem(AWARDS_CREDIT_FEATURES_KEY, on ? '1' : '0');
  // The same switch lives in Settings and in Configure Year; keep both in step
  for (const id of ['awardsCreditFeatures', 'srcAwardsCreditFeatures']) {
    const el = document.getElementById(id);
    if (el) el.checked = _awardsCreditFeatures;
  }
  // Targeted write, like the other one-click settings, so a racing full-config
  // save can't push a stale value back up
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_CREDIT_FEATURES_KEY, on ? '1' : '0');
  if (_awardsYearData[_awardsYear]) _awardsRenderSummary(_awardsYear);
}

// The "Hide plays on nominee cards" switch in Configure Year
function awardsSetHidePlays(on) {
  _awardsHidePlays = !!on;
  localStorage.setItem(AWARDS_HIDE_PLAYS_KEY, on ? '1' : '0');
  const el = document.getElementById('awardsHidePlays');
  if (el) el.checked = _awardsHidePlays;
  // Targeted write, same as awardsSetCreditFeatures
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_HIDE_PLAYS_KEY, on ? '1' : '0');
  const data = _awardsYearData[_awardsYear];
  if (data) _awardsRenderCatList(data);
}

// The "Play samples from nominee cards" switch in Configure Year
function awardsSetSamples(on) {
  _awardsSamples = !!on;
  localStorage.setItem(AWARDS_SAMPLES_KEY, on ? '1' : '0');
  const el = document.getElementById('awardsSamples');
  if (el) el.checked = _awardsSamples;
  // Turning it off mid-sample stops the sample, since its button is going away
  if (!on) _awardsCardStopClip();
  // Targeted write, same as awardsSetCreditFeatures
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_SAMPLES_KEY, on ? '1' : '0');
  const data = _awardsYearData[_awardsYear];
  if (data) _awardsRenderCatList(data);
}

// The "Show my scores on nominee cards" switch in Configure Year
function awardsSetShowRating(on) {
  _awardsShowRating = !!on;
  localStorage.setItem(AWARDS_SHOW_RATING_KEY, on ? '1' : '0');
  const el = document.getElementById('awardsShowRating');
  if (el) el.checked = _awardsShowRating;
  // Targeted write, same as awardsSetCreditFeatures
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_SHOW_RATING_KEY, on ? '1' : '0');
  const data = _awardsYearData[_awardsYear];
  if (data) _awardsRenderCatList(data);
}

function _awardsSummary(year, opts) {
  const spoilerFree = !!(opts && opts.spoilerFree);
  const withFeatures = _awardsCreditFeatures;
  const known = Object.fromEntries(AWARD_CATEGORIES.map(c => [c.id, c]));
  // key → { item, noms, wins }; item is the shape _cerArtHtml/_cerImgItem expect
  const all  = { artist: {}, album: {}, song: {} };
  const yr   = {};                    // this year's artists only
  const yrWins = {};                  // this year's wins per credited artist: key → [win]
  let yearNoms = 0, yearCats = 0;

  const bump = (bucket, key, item, field) => {
    const e = bucket[key] || (bucket[key] = { item, noms: 0, wins: 0 });
    e[field]++;
  };
  // One nominee (or winner) credits its lead artist (and, when the switch is on,
  // everyone featured on it), plus the album or song itself
  const credit = (n, type, field, isThisYear) => {
    const credits = _awardsCredits(n, withFeatures);
    if (!credits.length) return;
    for (const artist of credits) {
      const k = artist.toLowerCase();
      bump(all.artist, k, { artist }, field);
      if (isThisYear) bump(yr, k, { artist }, field);
    }
    const ak = credits[0].toLowerCase();
    if (type === 'album' && n.album) {
      bump(all.album, `${n.album.toLowerCase()}|||${ak}`, { album: n.album, artist: n.artist }, field);
    }
    if (type === 'song' && n.title) {
      bump(all.song, `${n.title.toLowerCase()}|||${(n.artist || '').toLowerCase()}`,
        { title: n.title, artist: n.artist, album: n.album || '' }, field);
      // Also noted against the song's album, keyed like the album records, so an
      // album card can say "+3 from its songs". Kept apart so it never changes
      // who holds an album record.
      if (n.album) bump(fromSongs, `${n.album.toLowerCase()}|||${ak}`, null, field);
    }
  };
  const fromSongs = {};               // album key → { noms, wins } its songs earned

  for (const [ys, yd] of Object.entries(_awardsYearData)) {
    const y = parseInt(ys, 10);
    if (!(y <= year) || !yd?.categories) continue;
    const isThisYear = y === year;
    for (const [catId, cd] of Object.entries(yd.categories)) {
      const cat = known[catId];
      if (!cat || !cd?.enabled) continue;
      if (spoilerFree && isThisYear && cat.auto) continue;
      const noms = cd.nominees || [];
      const wk = cd.winner ? _awardItemKey(cd.winner) : null;
      // A winner is always one of the field; if an old ballot somehow has it
      // missing from the list, it still earned the nomination.
      const field = (wk && !noms.some(n => _awardItemKey(n) === wk)) ? [...noms, cd.winner] : noms;
      if (isThisYear && field.length) yearCats++;
      for (const n of field) {
        credit(n, cat.type, 'noms', isThisYear);
        if (isThisYear) yearNoms++;
      }
      if (cd.winner && !(spoilerFree && isThisYear)) {
        credit(cd.winner, cat.type, 'wins', isThisYear);
        // Remember what each artist won tonight, for the roll call's "Most wins" list.
        // Only fields that exist are written: Firestore refuses undefined.
        if (isThisYear) {
          const w = cd.winner;
          const win = { catId: cat.id, cat: _ceremonyCatName(cat), type: cat.type, artist: w.artist || '' };
          if (w.title) win.title = w.title;
          if (w.album) win.album = w.album;
          for (const a of _awardsCredits(w, withFeatures)) {
            (yrWins[a.toLowerCase()] = yrWins[a.toLowerCase()] || []).push(win);
          }
        }
      }
    }
  }

  const nameOf = e => (e.item.title || e.item.album || e.item.artist || '').toLowerCase();
  // Top three for one measure; the other measure breaks ties, then the name
  const top = (bucket, field) => {
    const other = field === 'noms' ? 'wins' : 'noms';
    return Object.entries(bucket)
      .filter(([, e]) => e[field] > 0)
      .sort(([, a], [, b]) => (b[field] - a[field]) || (b[other] - a[other]) || nameOf(a).localeCompare(nameOf(b)))
      .slice(0, 3)
      .map(([k, e]) => {
        const out = { ...e.item, count: e[field] };
        // Albums carry what their songs earned on the side. Only written when
        // there is some: Firestore refuses undefined in a shared summary.
        const songs = bucket === all.album ? fromSongs[k]?.[field] : 0;
        if (songs) out.fromSongs = songs;
        return out;
      });
  };
  const records = [];
  for (const field of ['noms', 'wins']) {
    // Nothing to show for wins when the only ceremony so far is tonight's
    for (const type of ['artist', 'album', 'song']) records.push({ field, type, items: top(all[type], field) });
  }

  // Standard competition ranking: two artists on 5 share #2 and the next is #4
  const ranked = Object.values(yr)
    .filter(e => e.noms > 0)
    .sort((a, b) => (b.noms - a.noms) || (b.wins - a.wins) || nameOf(a).localeCompare(nameOf(b)));
  const ranking = [];
  ranked.slice(0, AWARDS_SUMMARY_RANK_N).forEach((e, i) => {
    const prev = ranked[i - 1];
    const rank = (prev && prev.noms === e.noms && (spoilerFree || prev.wins === e.wins)) ? ranking[i - 1].rank : i + 1;
    const row = { artist: e.item.artist, noms: e.noms, rank };
    if (!spoilerFree) row.wins = e.wins;   // Firestore refuses undefined, so leave it out entirely
    ranking.push(row);
  });

  // Every artist who won this year, most wins first, each with the list of what
  // they won. Nominations break ties. Ranked the same way as the list above.
  const winners = [];
  if (!spoilerFree) {
    const byWins = Object.values(yr)
      .filter(e => e.wins > 0)
      .sort((a, b) => (b.wins - a.wins) || (b.noms - a.noms) || nameOf(a).localeCompare(nameOf(b)));
    byWins.forEach((e, i) => {
      const prev = byWins[i - 1];
      const rank = (prev && prev.wins === e.wins) ? winners[i - 1].rank : i + 1;
      winners.push({ artist: e.item.artist, wins: e.wins, noms: e.noms, rank,
        items: yrWins[e.item.artist.toLowerCase()] || [] });
    });
  }

  return { year, spoilerFree, yearNoms, yearCats, artistCount: ranked.length, records, ranking, winners };
}

// "Song" / "Album" / "Artist" in the language on screen (awx_type_*)
const AWARDS_SUMMARY_TYPE_LABEL = new Proxy({}, { get: (_, type) => t('awx_type_' + String(type)) });

// "3 nominations" in the language on screen: key_one / key_other with {{n}}
function _awPl(key, n) {
  return t(key + (n === 1 ? '_one' : '_other'), { n: Number(n).toLocaleString(currentLang) });
}

/* A score is saved on the ballot in English ("173 plays · with a DJ/producer",
   "94 summer plays", "12-day streak"…), so it is put into the language on
   screen when shown, one " · " part at a time. A part it doesn't know is left
   as it is. Numbers are written the language's way (1,895 → 1.895). */
const _AW_SCORE_RULES = [
  [/^([\d,.]+) plays?$/,              m => tCount('plays', _awNum(m[1]))],
  [/^with a DJ\/producer$/,           () => t('awx_s_dj')],
  [/^with a group$/,                   () => t('awx_s_group')],
  [/^([\d,.]+) summer plays$/,        m => t('awx_s_summer',  { n: _awFmt(m[1]) })],
  [/^([\d,.]+) holiday plays$/,       m => t('awx_s_holiday', { n: _awFmt(m[1]) })],
  [/^([\d,.]+) morning plays$/,       m => t('awx_s_morning', { n: _awFmt(m[1]) })],
  [/^([\d,.]+) night plays$/,         m => t('awx_s_night',   { n: _awFmt(m[1]) })],
  [/^([\d,.]+)-day streak$/,          m => t('awx_s_streak',  { n: _awFmt(m[1]) })],
  [/^([\d,.]+) days played$/,         m => t('awx_s_days',    { n: _awFmt(m[1]) })],
  [/^every month$/,                    () => t('awx_s_every_month')],
  [/^(\d+) of (\d+) months$/,         m => t('awx_s_months', { n: m[1], m: m[2] })],
  [/^from (\d{4})$/,                   m => t('awx_s_from', { y: m[1] })],
  [/^popularity (\d+)\/100$/,          m => t('awx_s_popularity', { n: m[1] })],
  [/^((\d+)(st|nd|rd|th)) best known on the album$/, m => t('awx_s_best_known', { o: m[1], n: m[2] })],
  [/^([−+±][\d,.]+) plays vs (.+)$/,   m => t('awx_s_vs', { d: m[1], y: m[2] })],
  [/^new$/,                            () => t('awx_s_new')],
];
function _awNum(s) { return Number(String(s).replace(/,/g, '')) || 0; }
function _awFmt(s) { return _awNum(s).toLocaleString(currentLang); }
function _awScoreText(score) {
  if (!score || currentLang === 'en') return score || '';
  return String(score).split(' · ').map(part => {
    for (const [re, fn] of _AW_SCORE_RULES) { const m = part.match(re); if (m) return fn(m); }
    return part;
  }).join(' · ');
}

// A shared link's summary comes from someone else's document, so check its shape
function _awardsSummaryOk(sum) {
  return !!(sum && sum.yearNoms && Array.isArray(sum.records) && Array.isArray(sum.ranking));
}

// Who holds a record, as a comparable string
function _awardsRecKey(item) {
  return item ? `${(item.title || item.album || item.artist || '').toLowerCase()}|||${(item.artist || '').toLowerCase()}` : '';
}

/* Shared by the tab, the ceremony's opening slide and its roll call. queue
   collects the artwork jobs; idp keeps image ids unique between them (and
   between renders). opts:
     kicker, title — override the header wording
     before        — an earlier summary (the ceremony's opening one); a record
                     whose holder has changed since then is marked "New". */
function _awardsSummaryHtml(sum, queue, idp, opts) {
  opts = opts || {};
  if (!_awardsSummaryOk(sum)) return '';
  const before = _awardsSummaryOk(opts.before) ? opts.before : null;
  const plural = (key, n) => _awPl(key, n);
  const hasWins = sum.records.some(r => r.field === 'wins' && r.items?.length);

  const recordCard = (rec, ri) => {
    const items = Array.isArray(rec.items) ? rec.items : [];
    const lead = items[0];
    const kind = rec.field === 'noms' ? 'nomination' : 'win';
    if (!lead) {
      return `<div class="aw-sum-rec is-empty" data-awtype="${rec.type}">
        <div class="aw-sum-rec-type">${AWARDS_SUMMARY_TYPE_LABEL[rec.type]}</div>
        <div class="aw-sum-rec-none">${esc(t(rec.field === 'noms' ? 'awx_none_noms' : 'awx_none_wins'))}</div>
      </div>`;
    }
    const imgId = `${idp}_rec_${ri}`;
    queue.push({ imgId, item: lead, type: rec.type });
    const name = lead.title || lead.album || lead.artist || '';
    const sub  = (lead.title || lead.album) ? (lead.artist || '') : '';
    // A runner-up level with the leader is a shared record, so say so
    const tied = items.slice(1).filter(x => x.count === lead.count).length;
    // Compared with the opening slide: a different holder means tonight broke
    // or claimed the record. No badge where there was no record to break.
    const prevLead = before && (before.records.find(r => r.field === rec.field && r.type === rec.type)?.items || [])[0];
    // A previous holder still level at the top shares the record, so that is not a change.
    const prevStillTop = !!prevLead && items.some(x => x.count === lead.count && _awardsRecKey(x) === _awardsRecKey(prevLead));
    const isNew = !!(prevLead && !prevStillTop) || !!(before && !prevLead && rec.field === 'wins');
    /* Runners-up as their own ranked rows: place, name (+ artist for songs and
       albums), a bar showing how close they came to the leader, and the count.
       Places are competition ranks, so a runner-up level with the leader is 1. */
    const rest = items.slice(1).map(x => {
      const place = 1 + items.filter(y => y.count > x.count).length;
      const xName = x.title || x.album || x.artist || '';
      const xBy   = (x.title || x.album) ? (x.artist || '') : '';
      const pct   = Math.max(4, Math.round(x.count / (lead.count || 1) * 100));
      return `<li class="aw-sum-rec-next">
        <span class="aw-sum-rec-next-no">${place}</span>
        <span class="aw-sum-rec-next-main">
          <span class="aw-sum-rec-next-name" title="${esc(xBy ? `${xName} · ${xBy}` : xName)}">${esc(xName)}${xBy ? `<span class="aw-sum-rec-next-by"> · ${esc(xBy)}</span>` : ''}</span>
          <span class="aw-sum-rec-next-bar"><span style="width:${pct}%"></span></span>
        </span>
        <b>${x.count}</b>
      </li>`;
    }).join('');
    return `<div class="aw-sum-rec${rec.field === 'wins' ? ' is-wins' : ''}" data-awtype="${rec.type}">
      <div class="aw-sum-rec-head">
        ${_cerArtHtml(lead, rec.type, imgId, 'aw-sum-rec-art')}
        <div class="aw-sum-rec-body">
          <div class="aw-sum-rec-type">${AWARDS_SUMMARY_TYPE_LABEL[rec.type]}${tied ? ' · ' + esc(t('awx_tied')) : ''}${isNew ? ` <span class="aw-sum-new">${esc(t('awx_new'))}</span>` : ''}</div>
          <div class="aw-sum-rec-name" title="${esc(name)}">${esc(name)}</div>
          ${sub ? `<div class="aw-sum-rec-sub" title="${esc(sub)}">${esc(sub)}</div>` : ''}
          <div class="aw-sum-rec-count"><b>${lead.count}</b> ${esc(t((kind === 'nomination' ? 'awx_w_nom' : 'awx_w_win') + (lead.count === 1 ? '_one' : '_other')))}${lead.fromSongs > 0
            ? `<span class="aw-sum-rec-songs" title="${esc(t('awx_from_songs_tip', { what: plural(kind === 'nomination' ? 'awx_noms' : 'awx_wins', lead.fromSongs) }))}">${esc(t('awx_from_songs', { n: lead.fromSongs }))}</span>` : ''}</div>
        </div>
      </div>
      ${rest ? `<ol class="aw-sum-rec-rest">${rest}</ol>` : ''}
    </div>`;
  };

  const group = (field, title) => {
    const recs = sum.records.map((r, i) => ({ r, i })).filter(x => x.r.field === field);
    return `<div class="aw-sum-group">
      <div class="aw-sum-group-title">${field === 'wins' ? '🏆' : '🏅'} ${title}</div>
      <div class="aw-sum-recs">${recs.map(x => recordCard(x.r, x.i)).join('')}</div>
    </div>`;
  };

  // The roll call swaps the nominations list for the wins list. A link shared
  // before the wins list existed has no winners in it, so it keeps the old list.
  const winsView = !!opts.winsView && !sum.spoilerFree && Array.isArray(sum.winners);
  const maxNoms = sum.ranking[0]?.noms || 1;
  const rows = winsView ? '' : sum.ranking.map((r, i) => {
    const imgId = `${idp}_rank_${i}`;
    queue.push({ imgId, item: r, type: 'artist' });
    // Always emitted (empty when none) so every row has the same columns and the bars line up
    const wins = sum.spoilerFree ? '' : (r.wins
      ? `<span class="aw-sum-rank-wins" title="${esc(plural('awx_wins', r.wins))}"><span class="aw-sum-rank-wins-ico">🏆</span>${r.wins}</span>`
      : `<span class="aw-sum-rank-wins is-empty"></span>`);
    return `<div class="aw-sum-rank-row${r.rank === 1 ? ' is-top' : ''}" style="--i:${i}">
      <span class="aw-sum-rank-no">${String(r.rank).padStart(2, '0')}</span>
      ${_cerArtHtml(r, 'artist', imgId, 'aw-sum-rank-art')}
      <span class="aw-sum-rank-main">
        <span class="aw-sum-rank-name" title="${esc(r.artist)}">${esc(r.artist)}</span>
        <span class="aw-sum-rank-bar"><span style="width:${Math.max(6, Math.round(r.noms / maxNoms * 100))}%"></span></span>
      </span>
      <span class="aw-sum-rank-noms"><b>${r.noms}</b><small>${esc(t(r.noms === 1 ? 'awx_w_nom_one' : 'awx_w_nom_other'))}</small></span>
      ${wins}
    </div>`;
  }).join('');
  const more = sum.artistCount > sum.ranking.length
    ? `<div class="aw-sum-rank-more">${esc(plural('awx_more_artists', sum.artistCount - sum.ranking.length))}</div>` : '';

  /* Roll-call view (opts.winsView): the results are out, so the year's list is
     who won the most, and each artist carries every award they took home, with
     the song, album or artist picture beside the award's name. */
  const winnersHtml = () => {
    const list = sum.winners;
    if (!list.length) return `<div class="aw-sum-rec-none">${esc(t('awx_no_winners'))}</div>`;
    return list.map((w, i) => {
      const imgId = `${idp}_win_${i}`;
      queue.push({ imgId, item: { artist: w.artist }, type: 'artist' });
      const items = (Array.isArray(w.items) ? w.items : []).map((it, j) => {
        const artId = `${idp}_win_${i}_${j}`;
        queue.push({ imgId: artId, item: it, type: it.type });
        const work = it.title || it.album || it.artist || '';
        // A featured credit names who led the record, so it is clear why it is here
        const leadName = _awardsCredits(it, false)[0] || '';
        const lead = (it.artist && (it.title || it.album) && leadName.toLowerCase() !== (w.artist || '').toLowerCase()) ? it.artist : '';
        return `<div class="aw-sum-win">
          <span class="aw-sum-win-trophy">🏆</span>
          ${_cerArtHtml(it, it.type, artId, 'aw-sum-win-art' + (it.type === 'artist' ? ' is-round' : ''))}
          <span class="aw-sum-win-text">
            <span class="aw-sum-win-work" title="${esc(work)}">${esc(work)}${lead ? ` <span class="aw-sum-win-lead">· ${esc(lead)}</span>` : ''}</span>
            <span class="aw-sum-win-cat">${esc(it.cat || '')}</span>
          </span>
        </div>`;
      }).join('');
      return `<div class="aw-sum-winner${w.rank === 1 ? ' is-top' : ''}" style="--i:${i}">
        <div class="aw-sum-winner-head">
          <span class="aw-sum-rank-no">${String(w.rank).padStart(2, '0')}</span>
          ${_cerArtHtml(w, 'artist', imgId, 'aw-sum-winner-art')}
          <span class="aw-sum-winner-name" title="${esc(w.artist)}">${esc(w.artist)}</span>
          <span class="aw-sum-winner-count"><b>${w.wins}</b> ${esc(t(w.wins === 1 ? 'awx_w_win_one' : 'awx_w_win_other'))}<span class="aw-sum-winner-noms"> · ${esc(plural('awx_noms', w.noms))}</span></span>
        </div>
        <div class="aw-sum-win-list">${items}</div>
      </div>`;
    }).join('');
  };
  const yearGroup = winsView
    ? `<div class="aw-sum-group">
        <div class="aw-sum-group-title">🏆 ${esc(t('awx_g_year_wins', { y: sum.year }))}</div>
        <div class="aw-sum-winners">${winnersHtml()}</div>
      </div>`
    : `<div class="aw-sum-group">
        <div class="aw-sum-group-title">📊 ${esc(t('awx_g_year_noms', { y: sum.year }))}</div>
        <div class="aw-sum-rank">${rows}</div>
        ${more}
      </div>`;

  const kicker = opts.kicker || t(sum.spoilerFree ? 'awx_going_into' : 'awx_glance', { y: sum.year });
  const title  = opts.title || t('awx_title');
  /* opts.foldable (the tab's copy only): the block folds to its header, with
     the year's leader added to the numbers line and an Open / Close button.
     The ceremony's opening and closing slides always show the whole block. */
  const fold   = !!opts.foldable;
  const folded = fold && !_awardsSumOpen;
  const top    = sum.ranking[0];
  const leader = fold && top ? `<span class="aw-sum-leader"> · ${esc(t('awx_leader', { a: top.artist, n: top.noms }))}</span>` : '';
  const bodyId = `${idp}_body`;
  const toggle = fold
    ? `<button type="button" class="dc-btn dc-btn-normal dc-btn-sm aw-sum-toggle" aria-expanded="${!folded}" aria-controls="${bodyId}" onclick="awardsToggleSummary()">${esc(t(folded ? 'awx_open' : 'awx_close'))}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button>`
    : '';
  return `<section class="aw-sum${fold ? ' is-foldable' : ''}${folded ? ' is-folded' : ''}">
    <header class="aw-sum-head">
      <div class="aw-sum-head-text">
        <div class="aw-sum-kicker">${esc(kicker)}</div>
        <div class="aw-sum-title">${esc(title)}</div>
        <div class="aw-sum-meta">${esc(plural('awx_noms', sum.yearNoms))} · ${esc(plural('awx_cats', sum.yearCats))} · ${esc(plural('awx_artists', sum.artistCount))}${leader}</div>
      </div>
      ${toggle}
    </header>
    <div class="aw-sum-body" id="${bodyId}">
    ${group('noms', esc(t('awx_g_alltime_noms')))}
    ${hasWins ? group('wins', esc(t(sum.spoilerFree ? 'awx_g_alltime_wins_before' : 'awx_g_alltime_wins'))) : ''}
    ${yearGroup}
    </div>
  </section>`;
}

/* Stats & records above the ballot starts folded to one row (phase 9 part 5
   step 3); whether it was left open is remembered on this device. */
const AWARDS_SUM_OPEN_KEY = 'dc_awards_sum_open';
let _awardsSumOpen = (() => { try { return localStorage.getItem(AWARDS_SUM_OPEN_KEY) === '1'; } catch (e) { return false; } })();
function awardsToggleSummary() {
  _awardsSumOpen = !_awardsSumOpen;
  try { localStorage.setItem(AWARDS_SUM_OPEN_KEY, _awardsSumOpen ? '1' : '0'); } catch (e) {}
  // In place: the block's pictures are already loaded, so nothing is rebuilt
  const sec = document.querySelector('#awardsSummary .aw-sum');
  if (!sec) return;
  sec.classList.toggle('is-folded', !_awardsSumOpen);
  const btn = sec.querySelector('.aw-sum-toggle');
  if (btn) {
    btn.setAttribute('aria-expanded', String(_awardsSumOpen));
    btn.firstChild.textContent = t(_awardsSumOpen ? 'awx_close' : 'awx_open');
  }
}

// The tab's copy. All-time records need every year's ballot, which only the
// year on screen has loaded until now, so this waits for the rest first.
async function _awardsRenderSummary(year) {
  const el = document.getElementById('awardsSummary');
  if (!el) return;
  const seq = ++_awardsSummarySeq;
  await _awardsEnsureAllYearsLoaded();
  if (seq !== _awardsSummarySeq || year !== _awardsYear) return;   // the user moved on
  const queue = [];
  el.innerHTML = _awardsSummaryHtml(_awardsSummary(year), queue, `awSum${seq}`, { foldable: true });
  _awardsLoadArtQueue(queue, () => seq === _awardsSummarySeq);
}

function _awardItemKey(item) {
  return JSON.stringify({ t: item.title || '', al: item.album || '', ar: item.artist || '' });
}

function _awardsRenderCatCard(cat, catData, year, idx) {
  const nominees  = catData.nominees || [];
  const winner    = catData.winner   || null;
  const winnerKey = winner ? _awardItemKey(winner) : null;
  const emoji     = cat.emoji || { song: '🎵', album: '💿', artist: '🎤' }[cat.type] || '🏆';

  let bodyHtml = '';
  if (cat.auto && nominees.length) {
    // Auto-awarded categories have no ballot to vote on, so their single result
    // reuses the same gold winner band the picked categories use.
    const w   = nominees[0];
    const lbl = w.title || w.album || w.artist || '';
    const sub = (w.title || w.album) && w.artist ? w.artist : '';
    bodyHtml = `<div class="awards-nominee-row is-winner awards-auto-winner">
      <span class="awards-nominee-icon">🏆</span>
      ${_awardsClipBtn(cat, w)}
      <span class="awards-nominee-label" title="${esc(lbl)}">${esc(lbl)}</span>
      ${sub ? `<span class="awards-nominee-sub" title="${esc(sub)}">${esc(sub)}</span>` : ''}
      ${_awardsRatingChip(w)}
    </div>`;
    // A tie at the top: the rest of the tied field sits under the winner, and
    // clicking one hands it the award.
    const ties = catData.ties || [];
    if (ties.length > 1) {
      const wk = _awardItemKey(w);
      const score = w.playLabel || `${w.plays} plays`;
      bodyHtml += `<div class="awards-tie-hint">${esc(t('awards_tie_hint', { score }))}</div>`
        + ties.map((item, i) => {
          if (_awardItemKey(item) === wk) return '';
          const tl  = item.title || item.album || item.artist || '';
          const ts  = (item.title || item.album) && item.artist ? item.artist : '';
          return `<div class="awards-nominee-row awards-tie-row" onclick="awardsPickTieWinner(${year},'${esc(cat.id)}',${i})" title="${esc(t('awx_make_winner'))}">
            <span class="awards-nominee-icon">=</span>
            <span class="awards-nominee-label" title="${esc(tl)}">${esc(tl)}</span>
            ${ts ? `<span class="awards-nominee-sub" title="${esc(ts)}">${esc(ts)}</span>` : ''}
          </div>`;
        }).join('');
    }
  } else if (nominees.length) {
    bodyHtml = nominees.map((item, i) => {
      const ik  = _awardItemKey(item);
      const isW = ik === winnerKey;
      const lbl = item.title || item.album || item.artist || '';
      const sub = item.title ? item.artist : (item.album ? item.artist : (item.song || ''));
      // Rank number instead of a bullet: the list is an ordered ballot and the
      // number is what the ceremony counts down. The winner swaps it for a trophy.
      const mark = isW ? '🏆' : String(i + 1).padStart(2, '0');
      const reordering = _awardsReordering.has(cat.id);
      const pick = reordering ? '' : ` onclick="awardsPickWinner(${year},'${esc(cat.id)}',${esc(JSON.stringify(item))})"`;
      return `<div class="awards-nominee-row${isW ? ' is-winner' : ''}" style="--i:${i}" data-nom-i="${i}" draggable="true"${pick}>
        <span class="awards-nominee-icon">${mark}</span>
        ${_awardsClipBtn(cat, item)}
        <span class="awards-nominee-label" title="${esc(lbl)}">${esc(lbl)}</span>
        ${sub ? `<span class="awards-nominee-sub" title="${esc(sub)}">${esc(sub)}</span>` : ''}
        ${_awardsRatingChip(item)}
        ${_awardsGrowthChip(cat, year, item)}
        ${_awardsMoveCtl(year, cat, { i, n: nominees.length }, 'y')}
        <button class="awards-nominee-remove" onclick="awardsRemoveNominee(event,${year},'${esc(cat.id)}',${esc(JSON.stringify(item))})" title="${esc(t('awx_remove'))}" aria-label="${esc(t('awx_remove'))}">✕</button>
      </div>`;
    }).join('') + _awardsReorderHint(cat);   // "Click a nominee to crown the winner" is said once, in the toolbar
  } else {
    bodyHtml = `<div class="awards-no-nominees">${t('awards_no_nominees')}</div>`;
  }

  // data-awtype picks the card's --cat-hue (song / album / artist); --i staggers
  // the reveal so the grid fills in as a wave instead of all at once.
  return `<div class="awards-cat-card${winner ? ' has-winner' : ''}${_awardsReordering.has(cat.id) ? ' is-reordering' : ''}${_awardsCollapsed.has(cat.id) ? ' is-collapsed' : ''}" id="awardsCat_${cat.id}" data-year="${year}" data-awtype="${esc(cat.type || '')}" style="--i:${idx || 0}">
    ${_awardsCatHeadHtml(cat, nominees.length)}
    <div class="awards-cat-body">${bodyHtml}</div>
    <div class="awards-cat-footer">${_awardsCatActionsHtml(cat, year, nominees.length)}</div>
  </div>`;
}

// Card header, shared by every nominee view. `extra` lands at the right-hand end
// (the reel view puts its buttons there instead of in a footer).
function _awardsCatHeadHtml(cat, count, extra) {
  const emoji = cat.emoji || { song: '🎵', album: '💿', artist: '🎤' }[cat.type] || '🏆';
  return `<div class="awards-cat-header">
      <span class="awards-cat-emoji">${emoji}</span>
      <span class="awards-cat-heading">
        <span class="awards-cat-kicker">${esc(cat.type ? t('awards_cat_type_' + cat.type) : '')}${count ? ' · ' + count : ''}</span>
        <span class="awards-cat-name">${esc(t('awards_cat_' + cat.id))}</span>
        <span class="awards-cat-desc">${esc(_awardsCatHint(cat))}</span>
      </span>
      ${cat.auto ? '<span class="dc-chip dc-chip-warn awards-auto-tag">auto</span>' : ''}${extra || ''}
      ${_awardsFavBtn(cat.id, 'awards-cat-fav')}
      ${_awardsCollapseBtn(cat)}
    </div>`;
}

// The fold chevron at the end of every card header (awardsToggleCollapse)
function _awardsCollapseBtn(cat) {
  const folded = _awardsCollapsed.has(cat.id);
  return `<button class="awards-cat-collapse" onclick="awardsToggleCollapse('${esc(cat.id)}')" aria-expanded="${!folded}" title="${esc(t(folded ? 'awards_expand' : 'awards_collapse'))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button>`;
}

// Change / Pick nominees, plus the playlist button once there is a field to hear
function _awardsCatActionsHtml(cat, year, count) {
  const genBtn = cat.auto ? '' : `<button class="dc-btn dc-btn-normal dc-btn-sm awards-cat-action-btn" onclick="awardsGenerateCatCandidates(${year},'${esc(cat.id)}')" data-catid="${esc(cat.id)}">${count ? t('awards_change_btn') : t('awards_pick_nominees_btn')}</button>`;
  // Listen to the whole field before choosing. Auto categories have nothing to decide.
  const plBtn = (!cat.auto && count)
    ? `<button class="dc-btn dc-btn-normal dc-btn-sm awards-cat-action-btn awards-cat-pl-btn" onclick="awardsCatPlaylist(${year},'${esc(cat.id)}')" title="${esc(t('awx_pl_tip'))}">♫ ${esc(t('awx_playlist'))}</button>`
    : '';
  // Reorder mode, for touch and keyboard (a mouse can just drag)
  const on = _awardsReordering.has(cat.id);
  const roBtn = (!cat.auto && count > 1)
    ? `<button class="dc-btn dc-btn-normal dc-btn-sm awards-cat-action-btn awards-cat-reorder-btn${on ? ' is-on' : ''}" onclick="awardsToggleReorder(${year},'${esc(cat.id)}')" aria-pressed="${on}" title="${esc(t(on ? 'awx_reorder_done_tip' : 'awx_reorder_tip'))}">${on ? '✓ ' + esc(t('awards_reorder_done')) : '⇅ ' + esc(t('awards_reorder'))}</button>`
    : '';
  return genBtn + plBtn + roBtn;
}

// Replaces the "click to crown" hint while a card is in reorder mode
function _awardsReorderHint(cat) {
  return _awardsReordering.has(cat.id) ? `<div class="awards-pick-hint aw-reorder-hint">${esc(t('awards_reorder_hint'))}</div>` : '';
}

/* ─── Nominee views ────────────────────────────────────────────────────────────
   The category cards come in five layouts, picked from the switcher above the
   grid and remembered on this device:
   • ballot    — the text ballot above, no artwork (the default)
   • spotlight — the winner large over a blur of its own artwork, then the field
                 as rows with thumbnails and play counts
   • tiles     — the field as a grid of square covers
   • collage   — an edge-to-edge mosaic, the winner at double size
   • reel      — one full-width row per category, the field as scrolling posters
   They all call the same awardsPickWinner / awardsRemoveNominee /
   awardsPickTieWinner handlers, so crowning and removing work the same in all
   of them. Artwork goes through fetchAndInjectImage with the charts' prefKeys,
   so a picture pinned in a profile modal shows up here too. */
const AWARDS_VIEWS = ['ballot', 'spotlight', 'tiles', 'collage', 'reel'];
const AWARDS_VIEW_ICONS = {
  ballot:    '<path d="M9 6h11M9 12h11M9 18h11M4 6h1M4 12h1M4 18h1"/>',
  spotlight: '<rect x="3" y="3" width="18" height="8" rx="2"/><path d="M3 15h18M3 19h12"/>',
  tiles:     '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  collage:   '<rect x="3" y="3" width="11" height="11" rx="1.5"/><rect x="17" y="3" width="4" height="4.5" rx="1"/><rect x="17" y="9.5" width="4" height="4.5" rx="1"/><rect x="3" y="17" width="5" height="4" rx="1"/><rect x="10" y="17" width="11" height="4" rx="1"/>',
  reel:      '<rect x="2" y="5" width="6" height="14" rx="1.5"/><rect x="10" y="5" width="6" height="14" rx="1.5"/><rect x="18" y="5" width="6" height="14" rx="1.5"/>',
};
let _awardsView = (() => {
  try { const v = localStorage.getItem('dc_awards_view'); return AWARDS_VIEWS.includes(v) ? v : 'ballot'; }
  catch (e) { return 'ballot'; }
})();
let _awardsViewSeq = 0;         // bumped per render, so a replaced render stops fetching art
const _awardsArtSrc = {};       // prefKey → a picture that has already loaded this session

// A category counts as decided once it has a winner; an auto category is
// decided as soon as it has its result, since nobody votes on it
function _awardsCatDecided(cat, cd) {
  if (!cd) return false;
  return !!cd.winner || !!(cat.auto && (cd.nominees || []).length);
}

// The "Hide decided" switch in the view bar
function awardsSetHideDecided(on) {
  _awardsHideDecided = !!on;
  localStorage.setItem(AWARDS_HIDE_DECIDED_KEY, on ? '1' : '0');
  // Targeted write, same as awardsSetCreditFeatures
  if (typeof dcSaveConfigKey === 'function') dcSaveConfigKey(AWARDS_HIDE_DECIDED_KEY, on ? '1' : '0');
  const data = _awardsYearData[_awardsYear];
  if (data) _awardsRenderCatList(data);
}

// The chevron on a category card: folds it down to its header (or opens it).
// Flips the class in place rather than re-rendering, so artwork isn't refetched.
function awardsToggleCollapse(catId) {
  const folded = !_awardsCollapsed.has(catId);
  if (folded) _awardsCollapsed.add(catId); else _awardsCollapsed.delete(catId);
  try { localStorage.setItem(AWARDS_COLLAPSED_KEY, JSON.stringify([..._awardsCollapsed])); } catch (e) {}
  const card = document.getElementById('awardsCat_' + catId);
  if (!card) return;
  card.classList.toggle('is-collapsed', folded);
  const btn = card.querySelector('.awards-cat-collapse');
  if (btn) {
    btn.setAttribute('aria-expanded', String(!folded));
    btn.title = t(folded ? 'awards_expand' : 'awards_collapse');
  }
}

function awardsSetView(view) {
  if (!AWARDS_VIEWS.includes(view) || view === _awardsView) return;
  _awardsView = view;
  try { localStorage.setItem('dc_awards_view', view); } catch (e) {}
  const data = _awardsYearData[_awardsYear];
  if (data) _awardsRenderCatList(data);
}

/* What Expand all / Collapse all act on: 'all' cards on screen, or only the
   'pending' ones still without a winner. Picked with the All / No winner
   switch in front of the two buttons; remembered on this device. */
const AWARDS_FOLD_SCOPE_KEY = 'dc_awards_fold_scope';
let _awardsFoldScope = (() => {
  try { return localStorage.getItem(AWARDS_FOLD_SCOPE_KEY) === 'pending' ? 'pending' : 'all'; }
  catch (e) { return 'all'; }
})();

// The All / No winner switch. Updated in place: nothing on the cards changes
// until Expand or Collapse is pressed.
function awardsSetFoldScope(scope) {
  _awardsFoldScope = scope === 'pending' ? 'pending' : 'all';
  try { localStorage.setItem(AWARDS_FOLD_SCOPE_KEY, _awardsFoldScope); } catch (e) {}
  document.querySelectorAll('#awardsViewBar .awards-fold-scope').forEach(b =>
    b.setAttribute('aria-checked', String(b.dataset.scope === _awardsFoldScope)));
}

// Expand all / Collapse all in the view bar: folds or opens every card on
// screen at once (or only those without a winner, per _awardsFoldScope),
// in place like the per-card chevron
function awardsCollapseAll(fold) {
  const data  = _awardsYearData[_awardsYear];
  const byId  = Object.fromEntries(AWARD_CATEGORIES.map(c => [c.id, c]));
  document.querySelectorAll('#awardsCatList .awards-cat-card').forEach(card => {
    const catId = card.id.replace(/^awardsCat_/, '');
    // "No winner" scope leaves decided cards exactly as they are
    if (_awardsFoldScope === 'pending' && byId[catId] && _awardsCatDecided(byId[catId], data?.categories[catId])) return;
    if (fold) _awardsCollapsed.add(catId); else _awardsCollapsed.delete(catId);
    card.classList.toggle('is-collapsed', fold);
    const btn = card.querySelector('.awards-cat-collapse');
    if (btn) {
      btn.setAttribute('aria-expanded', String(!fold));
      btn.title = t(fold ? 'awards_expand' : 'awards_collapse');
    }
  });
  try { localStorage.setItem(AWARDS_COLLAPSED_KEY, JSON.stringify([..._awardsCollapsed])); } catch (e) {}
}

/* counts: { hidden, pending, total }
     hidden  = decided categories "Hide decided" is leaving out right now
     pending = categories still waiting on a winner
     total   = enabled categories this year */
function _awardsRenderViewBar(show, counts) {
  const bar = document.getElementById('awardsViewBar');
  if (!bar) return;
  bar.style.display = show ? '' : 'none';
  if (!show) return;
  const { hidden = 0, pending = 0, total = 0 } = counts || {};
  const hdName = t('awards_hide_decided');
  // Progress chip: "3/12 left to decide", or a gold "all decided" once done
  const pendLbl = pending ? t('awards_pending') : t('awards_none_pending');
  const ico = d => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`;
  // Said once here instead of on every card; hidden once everything is decided
  const hint = pending ? `<div class="awards-bar-hint">${esc(t('awards_pick_hint'))}</div>` : '';
  bar.innerHTML = `<div class="awards-bar-tools">
      <span class="awards-pending-chip${pending ? '' : ' is-done'}" role="status">${pending ? `<b>${pending}/${total}</b>` : '✓'}<span>${esc(pendLbl)}</span></span>
      <div class="awards-view-seg">
        <button class="awards-view-opt awards-hide-decided" aria-pressed="${_awardsHideDecided}" onclick="awardsSetHideDecided(${!_awardsHideDecided})" title="${esc(t('awards_hide_decided_tip'))}" aria-label="${esc(hdName)}">${ico('M3 3l18 18M10.6 5.1A10 10 0 0 1 12 5c5 0 9 4.5 10 7-0.4 1-1.2 2.3-2.4 3.5M6.6 6.6C4.4 8 2.8 10.2 2 12c1 2.5 5 7 10 7 1.9 0 3.6-0.6 5.1-1.6M9.9 9.9a3 3 0 0 0 4.2 4.2')}<span>${esc(hdName)}${_awardsHideDecided && hidden ? ` · ${hidden}` : ''}</span></button>
      </div>
      <div class="awards-view-seg">
        <div class="awards-fold-scopes" role="radiogroup" aria-label="${esc(t('awards_fold_scope'))}">${['all', 'pending'].map(sc =>
          `<button class="awards-view-opt awards-fold-scope" role="radio" data-scope="${sc}" aria-checked="${_awardsFoldScope === sc}" onclick="awardsSetFoldScope('${sc}')" title="${esc(t('awards_fold_scope_' + sc + '_tip'))}">${esc(t('awards_fold_scope_' + sc))}</button>`).join('')}</div>
        <button class="awards-view-opt awards-expand-all" onclick="awardsCollapseAll(false)" title="${esc(t('awards_expand_all'))}" aria-label="${esc(t('awards_expand_all'))}">${ico('M7 8l5-5 5 5M7 16l5 5 5-5')}<span>${esc(t('awards_expand_all'))}</span></button>
        <button class="awards-view-opt awards-collapse-all" onclick="awardsCollapseAll(true)" title="${esc(t('awards_collapse_all'))}" aria-label="${esc(t('awards_collapse_all'))}">${ico('M7 3l5 5 5-5M7 21l5-5 5 5')}<span>${esc(t('awards_collapse_all'))}</span></button>
      </div>
    </div>
    <div class="awards-view-pick">
    <span class="awards-view-bar-label">${esc(t('awards_view_label'))}</span>
    <div class="awards-view-seg" role="radiogroup" aria-label="${esc(t('awards_view_label'))}">${AWARDS_VIEWS.map(v => {
      const name = t('awards_view_' + v);
      return `<button class="awards-view-opt" role="radio" aria-checked="${v === _awardsView}" onclick="awardsSetView('${v}')" title="${esc(name)}" aria-label="${esc(name)}"><svg viewBox="0 0 24 24" aria-hidden="true">${AWARDS_VIEW_ICONS[v]}</svg><span>${esc(name)}</span></button>`;
    }).join('')}</div>
    </div>${hint}`;
}

// What a view can show without a lookup: a picture pinned in a profile modal, or
// one that already loaded this session. '' = pinned to no picture (initials);
// null = unknown, so it has to be fetched.
function _awardsArtKnown(item, type) {
  const key = _cerImgItem(item, type, '').prefKey;
  const pin = imgChoicePrefs[key];
  if (pin) return (pin.source === 'off' || !pin.url) ? '' : pin.url;
  return _awardsArtSrc[key] || null;
}

/* One artwork slot. Known pictures are painted straight into the markup, so the
   re-render that follows every crown or removal doesn't flash initials; the rest
   queue for _awardsViewLoadArt. `opts.hd` asks for the CDN's largest size once
   the normal one has loaded (for the big slots); `opts.bd` is the id of a
   backdrop that should take the same picture (the spotlight's blur).

   The slot is a .thumb-wrap with the app's ✎ .img-src-btn beside the image, so
   the shared picker handlers pick it up: the badge on hover, press-and-hold on
   touch. Its click is caught in the capture phase, so it never crowns the
   nominee underneath. */
function _awardsArtSlot(item, type, imgId, queue, cls, opts) {
  opts = opts || {};
  const label = item.title || item.album || item.artist || '';
  const img   = _cerImgItem(item, type, imgId);
  const known = _awardsArtKnown(item, type);
  if (known === null) queue.push({ imgId, item, type, ck: img.prefKey, hd: !!opts.hd, bd: opts.bd || '' });
  const inner = known
    ? `<img class="thumb" alt="" src="${esc(known)}" onerror="_awardsArtBroken(this)" data-ck="${esc(img.prefKey)}">`
    : `<div class="thumb-initials">${esc(initials(label))}</div>`;
  return `<div class="aw-art thumb-wrap ${cls || ''}"><div id="${imgId}">${inner}</div><button type="button" class="img-src-btn" id="srcbtn-${imgId}" data-imgid="${imgId}" data-type="${type}" data-prefkey="${esc(img.prefKey)}" data-name="${esc(img.name)}" data-artist="${esc(img.artist || '')}" data-album="${esc(img.album || '')}" title="${esc(t('img_picker_change'))}" aria-label="${esc(t('img_picker_change_for', { name: label }))}"></button></div>`;
}

// A picture picked (or reset) in the ✎ picker. refreshImgInstances() has already
// redrawn every slot showing it; what's left is the session cache, which would
// otherwise hand the old picture to the next render, and the spotlight's blurred
// backdrop, which isn't a slot of its own.
function _awardsOnImgChoice(prefkey) {
  delete _awardsArtSrc[prefkey];
  delete _awardsThumbSrc[prefkey];   // the Pick nominees window's own cache
  const pin = imgChoicePrefs[prefkey];
  const url = pin && pin.source !== 'off' ? pin.url : '';
  document.querySelectorAll('.aw-spot-bd[data-prefkey]').forEach(bd => {
    if (bd.dataset.prefkey !== prefkey) return;
    bd.style.backgroundImage = url ? `url("${String(url).replace(/"/g, '%22')}")` : '';
  });
}

// A remembered picture that has since gone dead: forget it and show initials;
// the next render looks it up again.
function _awardsArtBroken(img) {
  delete _awardsArtSrc[img.dataset.ck];
  const box = img.parentElement;
  if (box) box.innerHTML = `<div class="thumb-initials">?</div>`;
}

async function _awardsViewLoadArt(queue, seq) {
  const bdUrl = u => `url("${String(u).replace(/"/g, '%22')}")`;
  for (const job of queue) {
    if (seq !== _awardsViewSeq) return;
    const el = document.getElementById(job.imgId);
    if (!el) continue;
    try { await fetchAndInjectImage(el, _cerImgItem(job.item, job.type, job.imgId), job.type); } catch (e) {}
    const img = el.querySelector('img');
    if (!img) continue;
    // Remember it once it has actually loaded, after any source fallback, not
    // just once a URL was found.
    const done = () => {
      const src = img.currentSrc || img.src;
      if (!src) return;
      _awardsArtSrc[job.ck] = src;
      if (job.bd) { const bd = document.getElementById(job.bd); if (bd) bd.style.backgroundImage = bdUrl(src); }
      if (job.hd) {
        const hi = shHiResArt(src);
        if (hi && hi !== src) {
          const pre = new Image();
          pre.onload = () => { if (img.isConnected) img.src = hi; };   // fires done() again with the large one
          pre.src = hi;
        }
      }
    };
    img.addEventListener('load', done);
    if (img.complete && img.naturalWidth) done();
  }
}

// The field as the art views see it. Auto categories: their single entry is the
// award, and in a tie the rest of the tied field follows, one click from taking it.
function _awardsCatField(cat, catData) {
  const nominees = catData.nominees || [];
  if (cat.auto) {
    const w = nominees[0];
    if (!w) return { winner: null, entries: [] };
    const wk = _awardItemKey(w);
    const ties = (catData.ties || []).length > 1 ? catData.ties : [];
    return {
      winner: w,
      entries: [{ item: w, isW: true, mark: '🏆' },
        ...ties.map((item, i) => ({ item, tie: i, mark: '=' })).filter(e => _awardItemKey(e.item) !== wk)],
    };
  }
  const wk = catData.winner ? _awardItemKey(catData.winner) : null;
  return {
    winner: wk ? catData.winner : null,
    entries: nominees.map((item, i) => {
      const isW = _awardItemKey(item) === wk;
      return { item, i, n: nominees.length, isW, removable: true, mark: isW ? '🏆' : String(i + 1).padStart(2, '0') };
    }),
  };
}

function _awardsEntryText(item, cat, year) {
  const plays = Number(item.plays);
  // Most Growth reads its delta off the plays every time, so a nominee added by
  // hand shows it as well as a suggested one
  const growth = _awardsGrowthFor(cat, year, item);
  return {
    lbl:   item.title || item.album || item.artist || '',
    sub:   (item.title ? item.artist : (item.album ? item.artist : item.song)) || '',
    // Blank when the user has hidden plays; every view already skips an empty score
    score: _awScoreText(_awardsHidePlays ? '' : growth ? _awardsGrowthLabel(growth) : (item.playLabel || (plays ? `${plays.toLocaleString()} plays` : ''))),
  };
}

// Splits a score like "173 plays · with a DJ/producer" into the count ("173
// plays") and the note after it ("with a DJ/producer"), so Spotlight can keep
// the count beside the name and put the note on its own line under the artist.
// Whichever part mentions plays is the count; the rest is the note.
function _awardsScoreParts(score) {
  const parts = String(score || '').split(' · ');
  if (parts.length < 2) return { count: parts[0] || '', note: '' };
  let i = parts.findIndex(p => /plays?/.test(p));
  if (i < 0) i = 0;
  return { count: parts[i], note: parts.filter((_, k) => k !== i).join(' · ') };
}

// Click (and Enter / Space, via the list's keydown handler) crowns the entry,
// or hands a tied auto award over. The auto winner itself does nothing.
function _awardsEntryAttrs(year, cat, e) {
  if (cat.auto) {
    return e.tie == null ? ''
      : ` data-pick role="button" tabindex="0" title="${esc(t('awx_make_winner'))}" onclick="awardsPickTieWinner(${year},'${esc(cat.id)}',${e.tie})"`;
  }
  // Every nominee can be dragged to a new place; in reorder mode that is all a
  // click does, so crowning is off until Done
  const drag = ` data-nom-i="${e.i}" draggable="true"`;
  if (_awardsReordering.has(cat.id)) return drag;
  return `${drag} data-pick role="button" tabindex="0" onclick="awardsPickWinner(${year},'${esc(cat.id)}',${esc(JSON.stringify(e.item))})"`;
}

/* ─── Reordering nominees on the cards ─────────────────────────────────────────
   The order on a card is the order of the category's nominees array, which is
   also the ceremony's order, so it is worth being able to fix without opening
   the picker. Two ways, in every view:
   • drag a nominee onto another one's place (mouse; native drag and drop)
   • ⇅ Reorder in the card's actions, which gives each nominee ◀ ▶ (or ▲ ▼ in
     the list views) buttons, for touch screens and the keyboard
   A move redraws only that card, so the rest of the grid doesn't replay its
   entrance animation, and focus stays on the arrow that was pressed. */
const _awardsReordering = new Set();   // category ids with reorder mode on
let _awardsDrag = null;                // { card, from } while a nominee is dragged
let _awardsCardSeq = 0;                // keeps image ids unique across single-card redraws

function _awardsMoveCtl(year, cat, e, axis) {
  if (cat.auto || !_awardsReordering.has(cat.id)) return '';
  const [back, fwd] = axis === 'x' ? ['◀', '▶'] : ['▲', '▼'];
  const btn = (dir, to, glyph, label, off) =>
    `<button type="button" data-dir="${dir}" onclick="event.stopPropagation();awardsMoveNominee(${year},'${esc(cat.id)}',${e.i},${to},'${dir}')" aria-label="${label}" title="${label}"${off ? ' disabled' : ''}>${glyph}</button>`;
  return `<span class="aw-move aw-move-${axis}">${btn('back', e.i - 1, back, 'Move earlier', e.i === 0)}${btn('fwd', e.i + 1, fwd, 'Move later', e.i === e.n - 1)}</span>`;
}

function awardsToggleReorder(year, catId) {
  if (_awardsReordering.has(catId)) _awardsReordering.delete(catId);
  else _awardsReordering.add(catId);
  const card = _awardsRerenderCard(year, catId);
  card?.querySelector('.awards-cat-reorder-btn')?.focus();
}

async function awardsMoveNominee(year, catId, from, to, focusDir) {
  const data = _awardsYearData[year];
  const noms = data?.categories?.[catId]?.nominees;
  if (!noms || from === to || from < 0 || to < 0 || from >= noms.length || to >= noms.length) return;
  const [moved] = noms.splice(from, 1);
  noms.splice(to, 0, moved);
  const card = _awardsRerenderCard(year, catId);
  if (focusDir && card) {
    // Follow the nominee to its new place; at either end the arrow that still works
    const ctl = card.querySelector(`[data-nom-i="${to}"] .aw-move`);
    const btn = ctl?.querySelector(`[data-dir="${focusDir}"]:not(:disabled)`) || ctl?.querySelector('button:not(:disabled)');
    btn?.focus();
  }
  await _awardsSave(year);
}

// Redraws one category card in place, in the current view. Returns the new card.
function _awardsRerenderCard(year, catId) {
  const data = _awardsYearData[year];
  const old  = document.getElementById('awardsCat_' + catId);
  if (!data || !old) return null;
  const active = AWARD_CATEGORIES.filter(c => data.categories[c.id]?.enabled ?? c.defaultOn);
  const i   = active.findIndex(c => c.id === catId);
  const cat = active[i];
  if (!cat) return null;
  const cd = data.categories[catId] || { enabled: true, nominees: [], winner: null };
  const queue = [];
  const html = _awardsView === 'ballot'
    ? _awardsRenderCatCard(cat, cd, year, i)
    : _awardsRenderArtCard(cat, cd, year, i, _awardsView, `awv${_awardsViewSeq}_${i}m${++_awardsCardSeq}`, queue);
  const tmp = document.createElement('div');
  tmp.innerHTML = html;
  const card = tmp.firstElementChild;
  card.classList.add('no-anim');
  const scrollX = old.querySelector('.aw-reel-track')?.scrollLeft || 0;
  old.replaceWith(card);
  if (scrollX) { const tr = card.querySelector('.aw-reel-track'); if (tr) tr.scrollLeft = scrollX; }
  if (queue.length) _awardsViewLoadArt(queue, _awardsViewSeq);
  return card;
}

// Native drag and drop, delegated from the list so it survives every re-render.
// A nominee only ever lands inside its own card.
function _awardsBindDrag(el) {
  const clear = () => el.querySelectorAll('.is-drop, .is-dragging').forEach(n => n.classList.remove('is-drop', 'is-dragging'));
  el.addEventListener('dragstart', e => {
    const it = e.target.closest?.('[data-nom-i]');
    if (!it) return;
    const card = it.closest('.awards-cat-card');
    _awardsDrag = { card, from: +it.dataset.nomI };
    e.dataTransfer.effectAllowed = 'move';
    try { e.dataTransfer.setData('text/plain', it.dataset.nomI); } catch (_) {}
    it.classList.add('is-dragging');
    card.classList.add('is-sorting');
  });
  el.addEventListener('dragover', e => {
    const it = e.target.closest?.('[data-nom-i]');
    if (!_awardsDrag || !it || it.closest('.awards-cat-card') !== _awardsDrag.card) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (!it.classList.contains('is-drop')) {
      _awardsDrag.card.querySelectorAll('.is-drop').forEach(n => n.classList.remove('is-drop'));
      if (+it.dataset.nomI !== _awardsDrag.from) it.classList.add('is-drop');
    }
  });
  el.addEventListener('drop', e => {
    const it = e.target.closest?.('[data-nom-i]');
    const d = _awardsDrag;
    if (!d || !it || it.closest('.awards-cat-card') !== d.card) return;
    e.preventDefault();
    _awardsDrag = null;
    clear();
    d.card.classList.remove('is-sorting');
    const catId = d.card.id.replace(/^awardsCat_/, '');
    awardsMoveNominee(+d.card.dataset.year, catId, d.from, +it.dataset.nomI);
  });
  el.addEventListener('dragend', () => {
    if (_awardsDrag) _awardsDrag.card.classList.remove('is-sorting');
    _awardsDrag = null;
    clear();
  });
}

function _awardsEntryRemove(year, cat, e) {
  return e.removable
    ? `<button class="aw-x" onclick="awardsRemoveNominee(event,${year},'${esc(cat.id)}',${esc(JSON.stringify(e.item))})" title="${esc(t('awx_remove'))}" aria-label="${esc(t('awx_remove'))}">✕</button>`
    : '';
}

function _awardsSpotlightBody(cat, f, year, idp, queue) {
  const w = f.winner;
  let hero;
  if (w) {
    const x = _awardsEntryText(w, cat, year);
    const heroId = `${idp}_hero`;
    const known = _awardsArtKnown(w, cat.type);
    hero = `<div class="aw-spot-hero is-crowned">
      <div class="aw-spot-bd" id="${heroId}_bd" data-prefkey="${esc(_cerImgItem(w, cat.type, '').prefKey)}"${known ? ` style="background-image:url(&quot;${esc(known)}&quot;)"` : ''}></div>
      ${_awardsArtSlot(w, cat.type, heroId, queue, 'aw-spot-art', { hd: true, bd: heroId + '_bd' })}
      ${_awardsClipBtn(cat, w)}
      <div class="aw-spot-meta">
        <span class="aw-spot-label">${esc(t('awards_winner'))}</span>
        <span class="aw-spot-name" title="${esc(x.lbl)}">${esc(x.lbl)}</span>
        ${x.sub ? `<span class="aw-spot-sub" title="${esc(x.sub)}">${esc(x.sub)}</span>` : ''}
        ${x.score ? `<span class="aw-spot-score">${esc(x.score)}</span>` : ''}
        ${_awardsRatingChip(w)}
      </div>
    </div>`;
  } else {
    hero = `<div class="aw-spot-hero is-open">
      <div class="aw-spot-bd"></div>
      <div class="aw-spot-sealed" aria-hidden="true">?</div>
      <div class="aw-spot-meta">
        <span class="aw-spot-label">${esc(t('awards_view_uncrowned'))}</span>
        <span class="aw-spot-name">${esc(_awPl('awx_nominees', f.entries.length))}</span>
      </div>
    </div>`;
  }
  // An auto award's winner is the hero already; below it go only the tied rest
  const rows = (cat.auto ? f.entries.filter(e => !e.isW) : f.entries).map((e, k) => {
    const x = _awardsEntryText(e.item, cat, year);
    const sp = _awardsScoreParts(x.score);
    return `<div class="aw-spot-row${e.isW ? ' is-winner' : ''}" style="--i:${k}"${_awardsEntryAttrs(year, cat, e)}>
      <span class="aw-spot-rank">${e.mark}</span>
      ${_awardsArtSlot(e.item, cat.type, `${idp}_r${k}`, queue, 'aw-spot-thumb')}
      ${_awardsClipBtn(cat, e.item)}
      <span class="aw-spot-text">
        <span class="aw-spot-rname" title="${esc(x.lbl)}">${esc(x.lbl)}</span>
        ${x.sub ? `<span class="aw-spot-rsub" title="${esc(x.sub)}">${esc(x.sub)}</span>` : ''}
        ${sp.note ? `<span class="aw-spot-rnote" title="${esc(sp.note)}">${esc(sp.note)}</span>` : ''}
      </span>
      ${_awardsRatingChip(e.item)}
      ${sp.count ? `<span class="aw-spot-rscore">${esc(sp.count)}</span>` : ''}
      ${_awardsMoveCtl(year, cat, e, 'y')}
      ${_awardsEntryRemove(year, cat, e)}
    </div>`;
  }).join('');
  return hero + (rows ? `<div class="aw-spot-list">${rows}</div>` : '');
}

function _awardsTilesBody(cat, f, year, idp, queue) {
  return `<div class="aw-tiles">${f.entries.map((e, k) => {
    const x = _awardsEntryText(e.item, cat, year);
    return `<div class="aw-tile${e.isW ? ' is-winner' : ''}" style="--i:${k}"${_awardsEntryAttrs(year, cat, e)}>
      <div class="aw-tile-frame">
        ${_awardsArtSlot(e.item, cat.type, `${idp}_t${k}`, queue, 'aw-tile-art')}
        <span class="aw-rank">${e.mark}</span>
        ${_awardsClipBtn(cat, e.item)}
        ${_awardsEntryRemove(year, cat, e)}
        ${_awardsMoveCtl(year, cat, e, 'x')}
      </div>
      <span class="aw-tile-name" title="${esc(x.lbl)}">${esc(x.lbl)}</span>
      ${x.sub ? `<span class="aw-tile-sub" title="${esc(x.sub)}">${esc(x.sub)}</span>` : ''}
      ${_awardsRatingChip(e.item)}
      ${_awardsGrowthChip(cat, year, e.item)}
    </div>`;
  }).join('')}</div>`;
}

/* Four columns, the winner leading at 2×2. The last cell stretches over any
   columns left empty in its row, so the mosaic always closes as a rectangle. */
function _awardsCollageBody(cat, f, year, idp, queue) {
  const ordered = f.winner ? [...f.entries.filter(e => e.isW), ...f.entries.filter(e => !e.isW)] : f.entries;
  const cells = ordered.length + (f.winner ? 3 : 0);
  const gap = cells % 4 ? 4 - cells % 4 : 0;
  return `<div class="aw-collage"><div class="aw-collage-grid">${ordered.map((e, k) => {
    const x = _awardsEntryText(e.item, cat, year);
    // A lone entry (an untied auto award) would fill only half the width, so it
    // becomes a full-width banner instead
    const span = ordered.length === 1 ? ';grid-column:1 / -1'
      : (k === ordered.length - 1 && gap && !e.isW) ? `;grid-column:span ${gap + 1}` : '';
    return `<div class="aw-col-cell${e.isW ? ' is-winner' : ''}" style="--i:${k}${span}"${_awardsEntryAttrs(year, cat, e)}>
      ${_awardsArtSlot(e.item, cat.type, `${idp}_c${k}`, queue, 'aw-col-art', { hd: e.isW })}
      <span class="aw-rank">${e.mark}</span>
      ${_awardsClipBtn(cat, e.item)}
      ${_awardsEntryRemove(year, cat, e)}
      ${_awardsMoveCtl(year, cat, e, 'x')}
      <div class="aw-col-cap">
        ${e.isW ? `<span class="aw-col-win">${esc(t('awards_winner'))}</span>` : ''}
        <span class="aw-col-name" title="${esc(x.lbl)}">${esc(x.lbl)}</span>
        ${x.sub ? `<span class="aw-col-sub">${esc(x.sub)}</span>` : ''}
        ${_awardsRatingChip(e.item)}
        ${_awardsGrowthChip(cat, year, e.item)}
      </div>
    </div>`;
  }).join('')}</div></div>`;
}

function _awardsReelBody(cat, f, year, idp, queue) {
  return `<div class="aw-reel-track">${f.entries.map((e, k) => {
    const x = _awardsEntryText(e.item, cat, year);
    return `<div class="aw-poster${e.isW ? ' is-winner' : ''}" style="--i:${k}"${_awardsEntryAttrs(year, cat, e)}>
      <div class="aw-poster-frame">
        ${_awardsArtSlot(e.item, cat.type, `${idp}_p${k}`, queue, 'aw-poster-art', { hd: true })}
        <span class="aw-rank">${e.mark}</span>
        ${_awardsClipBtn(cat, e.item)}
        ${_awardsEntryRemove(year, cat, e)}
        ${_awardsMoveCtl(year, cat, e, 'x')}
        ${e.isW ? `<span class="aw-poster-ribbon">${esc(t('awards_winner'))}</span>` : ''}
      </div>
      <span class="aw-poster-name" title="${esc(x.lbl)}">${esc(x.lbl)}</span>
      ${x.sub ? `<span class="aw-poster-sub" title="${esc(x.sub)}">${esc(x.sub)}</span>` : ''}
      ${x.score ? `<span class="aw-poster-score">${esc(x.score)}</span>` : ''}
      ${_awardsRatingChip(e.item)}
    </div>`;
  }).join('')}</div>`;
}

function awardsReelScroll(btn, dir) {
  const track = btn.closest('.awards-cat-card')?.querySelector('.aw-reel-track');
  if (track) track.scrollBy({ left: dir * track.clientWidth * 0.8, behavior: 'smooth' });
}

function _awardsRenderArtCard(cat, catData, year, idx, view, idp, queue) {
  const f = _awardsCatField(cat, catData);
  const count = (catData.nominees || []).length;
  const bodyFn = { spotlight: _awardsSpotlightBody, tiles: _awardsTilesBody, collage: _awardsCollageBody, reel: _awardsReelBody }[view];
  let body = f.entries.length
    ? bodyFn(cat, f, year, idp, queue)
    : `<div class="awards-no-nominees">${t('awards_no_nominees')}</div>`;
  if (cat.auto && f.entries.length > 1) {
    const w = f.winner;
    body = `<div class="awards-tie-hint">${esc(t('awards_tie_hint', { score: w.playLabel || `${w.plays} plays` }))}</div>` + body;
  }
  // "Click a nominee to crown the winner" is said once, in the toolbar
  body += _awardsReorderHint(cat);

  const actions = _awardsCatActionsHtml(cat, year, count);
  const chev = d => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`;
  const head = view === 'reel'
    ? _awardsCatHeadHtml(cat, count, `<div class="aw-reel-actions">${actions}${f.entries.length > 1
        ? `<button class="dc-btn dc-btn-normal dc-btn-sm dc-btn-icon aw-reel-nav" onclick="awardsReelScroll(this,-1)" aria-label="Scroll back">${chev('M15 18l-6-6 6-6')}</button><button class="dc-btn dc-btn-normal dc-btn-sm dc-btn-icon aw-reel-nav" onclick="awardsReelScroll(this,1)" aria-label="Scroll forward">${chev('M9 18l6-6-6-6')}</button>`
        : ''}</div>`)
    : _awardsCatHeadHtml(cat, count);
  const foot = (view === 'reel' || !actions) ? '' : `<div class="awards-cat-footer">${actions}</div>`;

  return `<div class="awards-cat-card aw-v-${view}${catData.winner ? ' has-winner' : ''}${_awardsReordering.has(cat.id) ? ' is-reordering' : ''}${_awardsCollapsed.has(cat.id) ? ' is-collapsed' : ''}" id="awardsCat_${cat.id}" data-year="${year}" data-awtype="${esc(cat.type || '')}" style="--i:${idx || 0}">
    ${head}
    <div class="awards-cat-body">${body}</div>
    ${foot}
  </div>`;
}

/* ─── Nominee playlist ─────────────────────────────────────────────────────────
   One button per category card: every nominee into a playlist, so the whole
   field can be heard before a winner is picked. It goes through the app's usual
   playlist picker (add to an existing playlist or start a new one).

   What each nominee contributes:
   • a song — itself
   • an album — every song from it you played in the year's eligibility
     window, most played first
   • an artist — their AWARDS_PL_ARTIST_SONGS most played songs in the window
   An album or artist with no plays in the window falls back to the same
   songs the rest of the app's playlist buttons use (dcPlTracksFor). Plays come
   from allPlays, so it works the same for Last.fm, Sheets and CSV libraries. */
const AWARDS_PL_ARTIST_SONGS = 5;

function _awardsPlTopSongs(plays, limit) {
  const m = {};
  for (const p of plays) {
    const k = _sk(p);
    (m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }).plays++;
  }
  return Object.values(m).sort((a, b) => b.plays - a.plays).slice(0, limit || Infinity)
    .map(x => ({ title: x.title, artist: x.artist, album: x.album }));
}

function awardsCatPlaylist(year, catId) {
  const data = _awardsYearData[year];
  const cat  = AWARD_CATEGORIES.find(c => c.id === catId);
  const nominees = data?.categories?.[catId]?.nominees || [];
  if (!cat || !nominees.length) return;
  const start = new Date((data.eligStart || `${year}-01-01`) + 'T00:00:00');
  const end   = new Date((data.eligEnd   || `${year}-12-31`) + 'T23:59:59');
  const inWin = allPlays.filter(p => p.date >= start && p.date <= end);

  const tracks = [];
  for (const n of nominees) {
    if (cat.type === 'song') { tracks.push({ title: n.title, artist: n.artist, album: n.album || '' }); continue; }
    const artistLc = (n.artist || '').toLowerCase();
    let songs;
    if (cat.type === 'album') {
      const albumLc = (n.album || '').toLowerCase();
      // Same album identity as the nominee picker: album title + lead artist
      songs = _awardsPlTopSongs(inWin.filter(p => (p.album || '').toLowerCase() === albumLc && _pk(p) === artistLc));
      if (!songs.length) songs = dcPlTracksFor('album', '', n.artist, n.album);
    } else {
      songs = _awardsPlTopSongs(inWin.filter(p => _pk(p) === artistLc), AWARDS_PL_ARTIST_SONGS);
      if (!songs.length) songs = dcPlTracksFor('artist', '', n.artist, '');
    }
    tracks.push(...songs);
  }

  const name = t('awards_cat_' + cat.id);
  dcOpenPlaylistPicker(tracks, `${name} ${year}`, `${year} My Grammys · ${name} nominees`);
}

function awardsToggleConfig() {
  const panel = document.getElementById('awardsConfigPanel');
  const open = panel.style.display !== 'none';
  panel.style.display = open ? 'none' : '';
  document.getElementById('awardsConfigToggleBtn').classList.toggle('active', !open);
  if (!open) {
    const keyEl = document.getElementById('awardsGeminiKey');
    if (keyEl) keyEl.value = localStorage.getItem('dc_gemini_api_key') || '';
    // Read on open, so a value synced from another device shows correctly
    const featEl = document.getElementById('awardsCreditFeatures');
    if (featEl) featEl.checked = _awardsCreditFeatures;
    const hideEl = document.getElementById('awardsHidePlays');
    if (hideEl) hideEl.checked = _awardsHidePlays;
    const rateEl = document.getElementById('awardsShowRating');
    if (rateEl) rateEl.checked = _awardsShowRating;
    const clipEl = document.getElementById('awardsSamples');
    if (clipEl) clipEl.checked = _awardsSamples;
  }
}

function awardsUpdateElig() {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  data.eligStart = document.getElementById('awardsEligStart').value;
  data.eligEnd   = document.getElementById('awardsEligEnd').value;
  _awardsSave(_awardsYear);
}

function awardsToggleCat(catId, enabled) {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  if (!data.categories[catId]) data.categories[catId] = { enabled, nominees: [], winner: null };
  data.categories[catId].enabled = enabled;
  _awardsSave(_awardsYear);
  _awardsRenderCatList(data);
  // The card's own look and the counts; the list itself stays as it is
  document.querySelector(`#awardsCatToggles .awc-card[data-cat="${catId}"]`)?.classList.toggle('is-on', enabled);
  _awcUpdateCounts(data);
}

// Enable All / Disable All: every category showing under the current search
// and filters (all of them when nothing narrows the list)
function awardsToggleAllCats(enabled) {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  _awardsSetCats(data, AWARD_CATEGORIES.filter(c => _awcMatches(c, data)), enabled);
}

async function awardsGenerateCandidates() {
  if (!allPlays.length) return;
  const btn = document.getElementById('awardsGenerateBtn');
  const statusEl = document.getElementById('awardsStatus');
  const log = msg => { if (statusEl) statusEl.textContent = msg; };

  // The button holds an SVG icon plus a label span, so stash/restore innerHTML —
  // writing t('awards_generate') into textContent would drop the icon.
  const btnLabel = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.textContent = t('awards_generating'); }

  let data;
  try {
    log(t('awx_loading_year'));
    data = await _awardsLoad(_awardsYear);
    const active = AWARD_CATEGORIES.filter(c => data.categories[c.id]?.enabled ?? c.defaultOn);

    for (const cat of active) {
      log(t('awx_calculating', { c: t('awards_cat_' + cat.id) }));
      const cands = await _awardsGetCandidates(cat, data.eligStart, data.eligEnd, log);
      const cd = data.categories[cat.id];
      if (cat.auto) {
        // A tie keeps the user's earlier tie-break if that item is still in it
        const prevKey = cd.winner ? _awardItemKey(cd.winner) : null;
        const w = (cands.length > 1 && cands.find(c => _awardItemKey(c) === prevKey)) || cands[0] || null;
        cd.nominees = w ? [w] : [];
        cd.winner   = w;
        if (cands.length > 1) cd.ties = cands; else delete cd.ties;
      } else if (!cd.nominees.length && cands.length) {
        cd.nominees = cands.slice(0, 8);
      }
    }
    log(t('awx_saving'));
    await _awardsSave(_awardsYear);
  } finally {
    // Always give the button back, even if a category blew up mid-run
    if (btn) { btn.disabled = false; btn.innerHTML = btnLabel; }
    if (statusEl) statusEl.textContent = '';
  }
  if (data) _awardsRenderCatList(data);
}

async function awardsGenerateCatCandidates(year, catId) {
  const data = _awardsYearData[year] || await _awardsLoad(year);
  if (!data) return;
  const catDef = AWARD_CATEGORIES.find(c => c.id === catId);
  if (!catDef) return;
  const btn = document.querySelector(`[data-catid="${catId}"]`);
  // Restore whatever label the card had (Change / Pick nominees) instead of hard-coding one
  const btnLabel = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.textContent = t('awards_loading'); }
  let cands = [];
  try {
    cands = await _awardsGetCandidates(catDef, data.eligStart, data.eligEnd);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = btnLabel; }
  }
  _awardsShowPicker(year, catId, cands);
}

/* ─── Nominee picker ─────────────────────────────────────────────────────────
   The picker builds ONE play-count index for the eligibility window when it
   opens, then every search / sort / page runs off that cached array instead of
   re-walking allPlays on each keystroke.                                     */

// Does a play fit the category's own rule? Answered on the raw play, which still has the
// structured `artists` array the indexed item drops. `null` = the category is about listening
// history (new artist, comeback, growth…) rather than the item itself, so it can't rank a
// browse list; genre is answered later, from the tag cache, since those load asynchronously.
function _awardsPickerPlayFits(p, f = _awardsPickerCatFilter) {
  // A combined filter is its base's rule; the genre half waits for the tags
  if (f.includes('+genre:')) return _awardsPickerPlayFits(p, f.split('+')[0]);
  if (f === 'collab')     return _isCollab(p);
  if (f === 'duo')        return _isDuo(p);
  if (f === 'remix')      return _isRemix(p);
  if (f === 'nonenglish') return _hasNonLatinScript(p.title) || _hasNonLatinScript(p.artist);
  // The album guard comes first so the fake play _awardsPickerHasFit() probes with
  // answers false instead of reaching releaseTypeOf() with nothing to look up.
  if (f === 'soundtrack') return !!p.album && releaseTypeOfPlay(p) === 'soundtrack';
  if (f === 'deluxe')     return !!p.album && _isDeluxeAlbum(p.album);
  if (_AWARDS_PLAY_TESTS[f]) return _AWARDS_PLAY_TESTS[f](p);
  // Half the answer — the pop half is genre, so it waits for _awardsPickerItemFits().
  if (f === 'pop_solo')   return !_isCollab(p);
  if (f === 'pop_duo')    return _isCollab(p);
  return null;
}

// Same question for an indexed item: the flag stored at build time, or a live genre lookup.
// Deliberately a soft signal, never a hard filter — a "collab" the artist field can't reveal
// (one credited artist, two people actually singing) is still one the user can pick by hand.
function _awardsPickerItemFits(item) {
  const f = _awardsPickerCatFilter;
  if (f === 'summer') return (item.summerPlays || 0) > 0;
  if (f === 'holiday') return (item.holidayPlays || 0) > 0;
  if (f === 'night' || f === 'morning') return (item.hourPlays || 0) > 0;
  // Billing was settled at index time; the genre half is answered here, from the cache.
  if (f === 'pop_solo' || f === 'pop_duo') {
    const tags = _awardsPickerItemTags(item);
    return !!item.fit && tags !== undefined && _genreMatch(tags, 'genre:pop');
  }
  // Combined filters: the base's rule (when it has one) and the genre both have to fit
  if (f.includes('+genre:') && item.fit === false) return false;
  if (f.startsWith('genre:') || f === 'rock_group' || f.includes('+genre:')) {
    const g = f === 'rock_group' ? 'genre:rock' : f.includes('+genre:') ? f.split('+')[1] : f;
    if (_awardsPickerCatType === 'album') {
      const fits = _awardsAlbumSheetFits(item, g);
      if (fits !== null) return fits;
    }
    const tags = _awardsPickerItemTags(item);
    return tags === undefined ? false : _genreMatch(tags, g);
  }
  return item.fit;
}

/* How well a candidate fits the category, 0 – 100, or null when the category
   has nothing to measure. Only categories with a real degree get one: genres
   (how strongly its tags point there) and the summer / night / morning songs
   (the share of its plays that landed then). Yes-or-no rules like Collab or
   Cover have no in-between, so they keep the plain matches grouping instead.
   A candidate whose genre hasn't been looked up yet gets null too, since its
   genre chip already shows "?". */
function _awardsPickerFitPct(item) {
  const f = _awardsPickerCatFilter;
  if (!item.plays) return null;
  if (f === 'summer') return Math.round((item.summerPlays || 0) / item.plays * 100);
  if (f === 'holiday') return Math.round((item.holidayPlays || 0) / item.plays * 100);
  if (f === 'night' || f === 'morning') return Math.round((item.hourPlays || 0) / item.plays * 100);
  let g;
  if (f === 'pop_solo' || f === 'pop_duo') {
    if (!item.fit) return null;             // wrong billing: no amount of pop makes it fit
    g = 'genre:pop';
  } else if (f.includes('+genre:')) {
    if (item.fit === false) return null;
    g = f.split('+')[1];
  } else if (f === 'rock_group') g = 'genre:rock';
  else if (f.startsWith('genre:')) g = f;
  else return null;
  // An album the sheet has genres for: the average fit of its tracks
  if (_awardsPickerCatType === 'album') {
    const tracks = _awardsSheetGenres().albums.get(_ak(item));
    if (tracks && tracks.length) return Math.round(tracks.reduce((n, tags) => n + _genreFitScore(tags, g), 0) / tracks.length);
  }
  const tags = _awardsPickerItemTags(item);
  return tags === undefined ? null : _genreFitScore(tags, g);
}

// The fit tag on a picker row ("92% fit"). Nothing for a 0, which would only
// repeat what the grouping already says.
function _awardsPickerFitChip(item) {
  const pct = _awardsPickerFitPct(item);
  if (!pct) return '';
  const f = _awardsPickerCatFilter;
  const tier = pct >= 75 ? 'hi' : pct >= 45 ? 'mid' : 'lo';
  const tip = f === 'summer' ? t('awx_fit_summer', { n: pct })
    : f === 'holiday' ? (pct === 100 ? t('awx_fit_holiday_all') : t('awx_fit_holiday', { n: pct }))
    : (f === 'night' || f === 'morning') ? t('awx_fit_' + f, { n: pct })
    : t('awx_fit_genre', { n: pct });
  return `<span class="awards-picker-fit is-${tier}" title="${esc(tip)}">${esc(t('awx_pk_fit', { n: pct }))}</span>`;
}

// Genre tags for a picker row: the sheet's for that song / album, else the artist's
function _awardsPickerItemTags(item) {
  if (_awardsPickerCatType === 'song')  return _awardsSongTags(item);
  if (_awardsPickerCatType === 'album') return _awardsAlbumSheetTags(item) || _awardsGenreCache[(item.artist || '').toLowerCase()];
  return _awardsArtistTags(item);
}

// Whether this category can rank the browse list at all
function _awardsPickerHasFit() {
  const f = _awardsPickerCatFilter;
  return f === 'summer' || f === 'holiday' || f === 'night' || f === 'morning' || f === 'rock_group' || f.startsWith('genre:') || f.includes('+genre:') || _awardsPickerPlayFits({}) !== null;
}

// Plural noun for the category's matches, used in the group headers
function _awardsPickerFitLabel() {
  const f = _awardsPickerCatFilter;
  const kind = _awardsPickerCatType === 'album' ? 'albums' : _awardsPickerCatType === 'artist' ? 'artists' : 'songs';
  if (f === 'collab')     return 'Collaborations';
  if (f === 'duo')        return 'Duos';
  if (f === 'remix')      return 'Remixes, edits & versions';
  if (f === 'nonenglish') return 'Non-English ' + kind;
  if (f === 'summer')     return 'Summer songs';
  if (f === 'holiday')    return 'Holiday ' + kind;
  if (f === 'soundtrack') return 'Soundtrack ' + kind;
  if (f === 'deluxe')     return 'Deluxe editions';
  if (f === 'rt:ep')      return 'EPs';
  if (f === 'rt:live')    return 'Live albums';
  if (f === 'reissue')    return 'Reissues & remasters';
  if (f === 'compilation') return 'Compilations & greatest hits';
  if (f === 'cover')      return 'Covers';
  if (f === 'acoustic')   return 'Acoustic & stripped versions';
  if (f === 'deep_cut')   return 'Album tracks that were never singles';
  if (f === 'night')      return 'Songs played at night';
  if (f === 'morning')    return 'Songs played in the morning';
  if (f === 'pop_solo')   return 'Solo pop songs';
  if (f === 'pop_duo')    return 'Pop duos & groups';
  if (f === 'feat')       return 'Songs with two or more artists';
  if (f === 'feat+genre:christian') return 'Christian & gospel collaborations';
  if (f === 'instr_ver')  return 'Instrumental versions';
  if (f === 'genre:ccm')  return 'Contemporary Christian ' + kind;
  if (f === 'genre:christian') return 'Christian & gospel ' + kind;
  if (f === 'genre:christian-hip-hop') return 'Christian hip-hop ' + kind;
  if (f === 'genre:lo-fi') return 'Lo-fi & chill beats';
  if (f === 'genre:piano') return 'Piano ' + kind;
  if (f === 'genre:video-game') return 'Video game music';
  if (f === 'new+genre:pop')   return 'New pop artists';
  if (f === 'debut+genre:pop') return 'Pop albums';
  if (f === 'rt:ep+genre:pop') return 'Pop EPs';
  if (f === 'remix+genre:pop') return 'Pop remixes & versions';
  if (f === 'genre:synth-pop') return 'Synth-pop & electropop ' + kind;
  if (f === 'genre:latin-pop') return 'Latin pop ' + kind;
  if (f === 'genre:alt-pop')   return 'Alt-pop & bedroom pop ' + kind;
  if (f === 'genre:art-pop')   return 'Art pop ' + kind;
  if (f === 'genre:folk') return 'Folk & acoustic ' + kind;
  if (f === 'genre:singer-songwriter') return 'Singer-songwriter ' + kind;
  if (f === 'genre:indie-pop') return 'Indie pop ' + kind;
  if (f === 'genre:metal')     return 'Metal ' + kind;
  if (f === 'rock_group')      return 'Rock songs';
  if (f === 'genre:pop-rock')  return 'Pop/rock ' + kind;
  if (f === 'genre:pop-punk')  return 'Pop-punk ' + kind;
  if (f === 'genre:indie-rock') return 'Indie rock ' + kind;
  if (f === 'genre:classic-rock') return 'Classic rock ' + kind;
  if (f === 'genre:hard-rock') return 'Hard rock ' + kind;
  if (f === 'genre:post-punk') return 'Post-punk & new wave ' + kind;
  if (f === 'genre:grunge')    return 'Grunge & 90s alternative ' + kind;
  if (f === 'genre:prog')      return 'Prog & psychedelic ' + kind;
  if (f === 'genre:shoegaze')  return 'Shoegaze & dream pop ' + kind;
  if (f === 'genre:goth')      return 'Goth rock ' + kind;
  if (f === 'genre:punk')      return 'Punk & emo ' + kind;
  if (f === 'genre:j-pop')     return 'J-pop & anime ' + kind;
  if (f === 'genre:classical') return 'Classical & instrumental ' + kind;
  if (f.startsWith('genre:')) return f.replace('genre:', '').replace('rnb', 'R&B').replace(/^./, c => c.toUpperCase()) + ' ' + kind;
  return '';
}

// One pass over allPlays → every song/album/artist in the window, with play count + last play
function _awardsPickerBuildIndex() {
  const start = new Date(_awardsPickerEligWin.start + 'T00:00:00');
  const end   = new Date(_awardsPickerEligWin.end   + 'T23:59:59');
  const map   = {};
  const stats = _awardsPickerHasStats();
  let total = 0;
  for (const p of allPlays) {
    if (p.date < start || p.date > end) continue;
    let k;
    if (_awardsPickerCatType === 'song') {
      k = _sk(p);
      if (!map[k]) map[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0, last: 0 };
    } else if (_awardsPickerCatType === 'album') {
      if (!p.album) continue;
      k = _ak(p);
      if (!map[k]) map[k] = { album: p.album, artist: _pa(p), plays: 0, last: 0 };
    } else {
      k = _pk(p);
      if (!map[k]) map[k] = { artist: _pa(p), plays: 0, last: 0 };
    }
    const item = map[k];
    if (item.fit === undefined) item.fit = _awardsPickerPlayFits(p);   // computed once, off the raw play
    item.plays++;
    const ts = +p.date;
    if (ts > item.last) item.last = ts;
    if (stats) { total++; _awardsStatAddPlay(item, p, ts); }
    if (_awardsPickerCatFilter === 'summer') {
      const mo = tzDateOf(p).getMonth();
      if (mo >= 5 && mo <= 7) item.summerPlays = (item.summerPlays || 0) + 1;
    }
    if (_awardsPickerCatFilter === 'holiday' && _awardsHolidayPlay(p)) item.holidayPlays = (item.holidayPlays || 0) + 1;
    if ((_awardsPickerCatFilter === 'night' || _awardsPickerCatFilter === 'morning')
        && _awardsHourFits(_awardsPickerCatFilter, tzDateOf(p).getHours())) {
      item.hourPlays = (item.hourPlays || 0) + 1;
    }
  }
  // Song of the Summer ranks on summer plays, so label the rows with that number
  if (_awardsPickerCatFilter === 'summer') {
    for (const item of Object.values(map)) item.playLabel = (item.summerPlays || 0) + ' summer plays';
  }
  // Same for the holiday song, on its holiday plays
  if (_awardsPickerCatFilter === 'holiday') {
    for (const item of Object.values(map)) item.playLabel = (item.holidayPlays || 0) + ' holiday plays';
  }
  // Same for the night and morning songs
  if (_awardsPickerCatFilter === 'night' || _awardsPickerCatFilter === 'morning') {
    for (const item of Object.values(map)) item.playLabel = (item.hourPlays || 0) + ' ' + _awardsPickerCatFilter + ' plays';
  }
  // Most Growth: every artist row shows its change on the year before
  if (_awardsPickerCatFilter === 'growth') {
    const { start: es, end: ee } = _awardsPickerEligWin;
    for (const item of Object.values(map)) item.playLabel = _awardsGrowthLabel(_awardsGrowthDelta(item.artist, es, ee));
  }

  // Carry the suggestion metadata (custom play labels, release years) onto the indexed
  // items so the generated candidates and the browse list stay one and the same object.
  _awardsPickerSuggKeys = new Set();
  for (const cand of _awardsPickerAutoCands) {
    const ck = _awardItemKey(cand);
    _awardsPickerSuggKeys.add(ck);
    const hit = map[_awardsPickerCatType === 'song' ? _sk(cand)
              : _awardsPickerCatType === 'album' ? _ak(cand)
              : _pk(cand)];
    if (hit) {
      hit.sugg = true;
      if (cand.playLabel) hit.playLabel = cand.playLabel;
      if (cand.releaseYear !== undefined) hit.releaseYear = cand.releaseYear;
    } else {
      // Candidate the raw index can't reproduce (growth deltas, streaks…) — keep it as-is
      map[ck] = Object.assign({ plays: 0, last: 0 }, cand, { sugg: true });
    }
  }

  _awardsPickerAllItems = Object.values(map).sort((a, b) => b.plays - a.plays);
  if (stats) _awardsStatFinish(_awardsPickerAllItems, total);
}

/* ─── Year stats in the picker ────────────────────────────────────────────────
   Song, Album and Artist of the Year are the big three, so their picker shows
   how each candidate actually lived through the eligibility window, not just
   its play count: streaks, days / weeks / months played, its biggest day, week
   and month, and where it got to on the weekly and monthly charts. Everything
   is limited to the window the year is configured with.

   Collected in the index pass (_awardsStatAddPlay), reduced to numbers once it
   ends (_awardsStatFinish), and the per-day maps dropped, so the only extra
   cost of opening the picker is one Map update per play. */
const AWARDS_STAT_CATS = new Set(['song_of_year', 'album_of_year', 'artist_of_year']);

function _awardsPickerHasStats() {
  return AWARDS_STAT_CATS.has(_awardsPickerCtx?.catId);
}

// Extra sort orders for those categories. Each returns "bigger is better";
// chart peak is negated so #1 sorts first and never-charted sorts last.
const AWARDS_STAT_SORTS = {
  streak:   s => s.streak.len,
  days:     s => s.days,
  bestday:  s => s.peakDay.n,
  weeks1:   s => (s.wChart ? s.wChart.at1 : 0) * 1000 + (s.wChart ? s.wChart.top10 : 0),
  peak:     s => s.wChart ? -s.wChart.peak : -Infinity,
};
const AWARDS_STAT_SORT_LABELS = {
  streak: 'Longest streak', days: 'Most days played', bestday: 'Biggest day',
  weeks1: 'Most weeks at #1', peak: 'Best chart peak',
};

function _awardsStatAddPlay(item, p, ts) {
  if (!item._d) {
    item._d = new Map(); item._w = new Map(); item._m = new Map();
    item.first = ts;
    // The key the chart runs file this item under, which is not always the
    // picker's own (albums there are keyed on the raw album + album artist)
    item.crKey = _awardsPickerCatType === 'song' ? songKey(p)
      : _awardsPickerCatType === 'album' ? albumKeyOf(p) : _pa(p);
    if (_awardsPickerCatType === 'artist') { item._songs = new Set(); item._albums = new Set(); }
    if (_awardsPickerCatType === 'album')  item._songs = new Set();
  }
  if (ts < item.first) item.first = ts;
  const ds = dayStrOf(p), wk = playWeekKeyOf(p), mk = monthKeyOf(p);
  item._d.set(ds, (item._d.get(ds) || 0) + 1);
  item._w.set(wk, (item._w.get(wk) || 0) + 1);
  item._m.set(mk, (item._m.get(mk) || 0) + 1);
  if (item._songs) item._songs.add(songKey(p));
  if (item._albums && p.album) item._albums.add(albumKeyOf(p));
}

// "YYYY-MM-DD" → whole days since the epoch, so consecutive dates differ by 1
function _awardsStatDayNo(ds) {
  return Date.UTC(+ds.slice(0, 4), +ds.slice(5, 7) - 1, +ds.slice(8, 10)) / 864e5;
}

// Longest run of keys `step` days apart: { len, from, to }
function _awardsStatRun(keys, step) {
  const sorted = [...keys].sort();
  let best = { len: 0, from: '', to: '' }, len = 0, from = '', prev = null;
  for (const k of sorted) {
    const n = _awardsStatDayNo(k);
    if (prev !== null && n - prev === step) len++;
    else { len = 1; from = k; }
    if (len > best.len) best = { len, from, to: k };
    prev = n;
  }
  return best;
}

// Largest entry of a key → count map: { n, key }
function _awardsStatMax(m) {
  let n = 0, key = '';
  for (const [k, v] of m) if (v > n || (v === n && k < key)) { n = v; key = k; }
  return { n, key };
}

// Every month of the eligibility window, as "YYYY-MM"
function _awardsStatWindowMonths() {
  const out = [];
  let y = +_awardsPickerEligWin.start.slice(0, 4), m = +_awardsPickerEligWin.start.slice(5, 7);
  const endY = +_awardsPickerEligWin.end.slice(0, 4), endM = +_awardsPickerEligWin.end.slice(5, 7);
  while ((y < endY || (y === endY && m <= endM)) && out.length < 36) {
    out.push(`${y}-${String(m).padStart(2, '0')}`);
    if (++m > 12) { m = 1; y++; }
  }
  return out;
}

/* Weekly and monthly chart records inside the window, read from the cached
   full-history chart runs (the same ones the chart-run panel and Records use),
   so a "#1" here is the #1 the Charts tab showed that week. A week counts when
   any of its days falls in the window. */
function _awardsStatChartRuns() {
  const type = _awardsPickerCatType === 'song' ? 'songs' : _awardsPickerCatType === 'album' ? 'albums' : 'artists';
  const s = new Date(_awardsPickerEligWin.start + 'T00:00:00');
  s.setDate(s.getDate() - 6);
  const win = {
    week:  { lo: localDateStr(s), hi: _awardsPickerEligWin.end },
    month: { lo: _awardsPickerEligWin.start.slice(0, 7), hi: _awardsPickerEligWin.end.slice(0, 7) },
  };
  const out = {};
  for (const period of ['week', 'month']) {
    try { out[period] = { res: _crFull(period).result[type] || {}, ...win[period] }; }
    catch (e) { out[period] = null; }
  }
  return out;
}

function _awardsStatChart(run, key) {
  const d = run && key ? run.res[key] : null;
  if (!d) return null;
  let peak = Infinity, at1 = 0, top10 = 0, on = 0, peakKey = '';
  for (const e of d.entries) {
    if (e.periodKey < run.lo || e.periodKey > run.hi) continue;
    on++;
    if (e.rank === 1) at1++;
    if (e.rank <= 10) top10++;
    if (e.rank < peak) { peak = e.rank; peakKey = e.periodKey; }
  }
  return on ? { peak, peakKey, at1, top10, on } : null;
}

function _awardsStatFinish(items, total) {
  const months = _awardsStatWindowMonths();
  const runs = _awardsStatChartRuns();
  let rank = 0, prevPlays = -1;
  items.forEach((item, i) => {
    // Competition ranking on plays: level items share a place
    if (item.plays !== prevPlays) { rank = i + 1; prevPlays = item.plays; }
    if (!item._d) return;   // a suggestion the index could not reproduce
    item.st = {
      rank, of: items.length,
      share: total ? item.plays / total : 0,
      days: item._d.size, weeks: item._w.size, months: item._m.size,
      streak:  _awardsStatRun(item._d.keys(), 1),
      wstreak: _awardsStatRun(item._w.keys(), 7),
      peakDay: _awardsStatMax(item._d), peakWeek: _awardsStatMax(item._w), peakMonth: _awardsStatMax(item._m),
      first: item.first, last: item.last,
      songs: item._songs ? item._songs.size : 0,
      albums: item._albums ? item._albums.size : 0,
      monthly: months.map(mk => [mk, item._m.get(mk) || 0]),
      wChart: _awardsStatChart(runs.week, item.crKey),
      mChart: _awardsStatChart(runs.month, item.crKey),
    };
    delete item._d; delete item._w; delete item._m; delete item._songs; delete item._albums;
  });
}

// Short date labels for the stats: "3 Mar 2024", "March 2024"
function _awardsStatDate(ds)  { return fmtDate(new Date(ds + 'T00:00:00')); }
function _awardsStatMonth(mk) { return `${t(_CR_MON_LONG[+mk.slice(5, 7) - 1])} ${mk.slice(0, 4)}`; }

// The one-line summary under each row
function _awardsPickerStatLine(item, idx) {
  const s = item.st;
  if (!s) return '';
  // A few labelled pills, number first; weeks/months live in the full card
  const pl = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const pill = (title, html, cls) => `<span class="aw-pst-pill${cls ? ' ' + cls : ''}" title="${title}">${html}</span>`;
  const bits = [];
  if (s.wChart && s.wChart.at1) {
    bits.push(pill('Weeks at #1 on your weekly chart', `👑 #1 for <b>${pl(s.wChart.at1, 'week', 'weeks')}</b>`, 'is-gold'));
  } else if (s.wChart) {
    bits.push(pill('Best position on your weekly chart', `Peaked at <b>#${s.wChart.peak}</b>`));
  }
  if (s.streak.len > 1) bits.push(pill('Longest run of days in a row with a play', `🔥 <b>${s.streak.len} days</b> in a row`, 'is-hot'));
  bits.push(pill(`Days with at least one play (${pl(s.weeks, 'week', 'weeks')}, ${pl(s.months, 'month', 'months')})`, `Played on <b>${pl(s.days, 'day', 'days')}</b>`));
  if (s.peakDay.n > 1) bits.push(pill('Most plays in a single day', `<b>${s.peakDay.n} plays</b> in one day`));
  return `<span class="awards-picker-statline">${bits.join('')}<button type="button" class="dc-btn dc-btn-normal dc-btn-sm awards-picker-stats-btn" onclick="event.stopPropagation();awardsPickerToggleStats(${idx},this)" title="All stats for ${esc(String(_awardsPickerCtx.year))}" aria-expanded="false">📊 Stats</button></span>`;
}

// The full card, opened under a row by its 📊 button
function _awardsPickerStatsHtml(item) {
  const s = item.st;
  if (!s) return '';
  const type = _awardsPickerCatType;
  const noun = type === 'song' ? 'songs' : type === 'album' ? 'albums' : 'artists';
  const one = type === 'song' ? 'song' : type === 'album' ? 'album' : 'artist';
  const year = esc(String(_awardsPickerCtx.year));
  const pl = (n, a, b) => `${n.toLocaleString()} ${n === 1 ? a : b}`;
  const short = ds => _awardsStatDate(ds).replace(/\s\d{4}$/, '');   // "11 Jan", the year is a given
  const tile = (label, value, note, cls) => `<div class="dc-card-inset aw-pst-tile${cls ? ' ' + cls : ''}">
      <span class="aw-pst-label">${label}</span>
      <span class="aw-pst-value">${value}</span>
      ${note ? `<span class="aw-pst-note">${note}</span>` : ''}
    </div>`;
  const section = (title, body) => `<div class="aw-pst-sec"><div class="aw-pst-sec-title">${title}</div>${body}</div>`;

  // Headline: how many plays, and where that puts it
  const pct = `${(s.share * 100).toFixed(s.share < 0.01 ? 2 : 1)}%`;
  const hero = `<div class="aw-pst-hero${s.rank === 1 ? ' is-gold' : ''}">
      <div class="aw-pst-hero-rank">#${s.rank}</div>
      <div class="aw-pst-hero-text">
        <div class="aw-pst-hero-main">${s.rank === 1 ? `Your most played ${one} of ${year}` : `Your #${s.rank} ${one} of ${year}`}</div>
        <div class="aw-pst-hero-sub"><b>${pl(item.plays, 'play', 'plays')}</b> out of ${s.of.toLocaleString()} ${noun} you played · ${pct} of all your listening</div>
      </div>
    </div>`;

  // Habits: how often and how hard
  const range = r => r.len > 1 ? `${short(r.from)} – ${short(r.to)}` : '';
  const tiles = [
    tile('Days you played it', pl(s.days, 'day', 'days'), `across ${pl(s.months, 'month', 'months')}`),
    tile('Longest streak', `${pl(s.streak.len, 'day', 'days')} in a row`, range(s.streak), s.streak.len >= 7 ? 'is-hot' : ''),
    tile('Weeks in a row', pl(s.wstreak.len, 'week', 'weeks'), s.wstreak.len > 1 ? `from the week of ${short(s.wstreak.from)}` : ''),
    tile('Best day', pl(s.peakDay.n, 'play', 'plays'), `on ${short(s.peakDay.key)}`),
    tile('Best week', pl(s.peakWeek.n, 'play', 'plays'), `week of ${short(s.peakWeek.key)}`),
    tile('Best month', pl(s.peakMonth.n, 'play', 'plays'), `in ${esc(_awardsStatMonth(s.peakMonth.key).split(' ')[0])}`),
  ];
  if (type === 'artist') tiles.push(tile('Songs played', pl(s.songs, 'song', 'songs'), `from ${pl(s.albums, 'album', 'albums')}`));
  if (type === 'album')  tiles.push(tile('Tracks played', pl(s.songs, 'track', 'tracks'), 'different songs from it'));

  // Charts: one plain sentence per chart, the #1 run first
  const chartRow = (label, c, unit) => {
    if (!c) return `<div class="aw-pst-chart"><span class="aw-pst-chart-name">${label}</span><span class="aw-pst-none">Never made the chart</span></div>`;
    const chips = [c.at1
      ? `<span class="dc-chip aw-pst-chip is-gold">👑 #1 for ${pl(c.at1, unit, unit + 's')}</span>`
      : `<span class="dc-chip aw-pst-chip is-strong">Peaked at #${c.peak}</span>`];
    if (c.top10) chips.push(`<span class="dc-chip aw-pst-chip">${pl(c.top10, unit, unit + 's')} in the top 10</span>`);
    chips.push(`<span class="dc-chip aw-pst-chip">${pl(c.on, unit, unit + 's')} on the chart</span>`);
    return `<div class="aw-pst-chart"><span class="aw-pst-chart-name">${label}</span>${chips.join('')}</div>`;
  };

  // Plays per month, each bar labelled with its count
  const top = Math.max(1, ...s.monthly.map(([, n]) => n));
  const bars = s.monthly.map(([mk, n]) => {
    const h = n ? Math.max(6, Math.round(n / top * 100)) : 0;
    const peak = n && mk === s.peakMonth.key;
    return `<div class="aw-pst-bar${peak ? ' is-peak' : ''}${n ? '' : ' is-empty'}" title="${esc(_awardsStatMonth(mk))}: ${pl(n, 'play', 'plays')}">
        <span class="aw-pst-bar-n">${n || ''}</span>
        <span class="aw-pst-bar-fill" style="height:${h}%"></span>
        <span class="aw-pst-bar-lbl">${esc(t(_CR_MON_SHORT[+mk.slice(5, 7) - 1]))}</span>
      </div>`;
  }).join('');
  const first = short(localDateStr(tzDate(new Date(s.first))));
  const last  = short(localDateStr(tzDate(new Date(s.last))));

  const ax = type === 'artist' ? _awardsArtistExtras(item) : null;

  return hero
    + (ax ? ax.highlights : '')
    + section('Through the year', `<div class="aw-pst-months" style="--n:${s.monthly.length}" aria-label="Plays per month">${bars}</div>
        <div class="aw-pst-span"><span>First play <b>${first}</b></span><span>Last play <b>${last}</b></span></div>`)
    + section('How you listened', `<div class="aw-pst-grid">${tiles.join('')}</div>`)
    + section('On your charts', `<div class="aw-pst-charts">${chartRow('Weekly', s.wChart, 'week')}${chartRow('Monthly', s.mChart, 'month')}</div>`)
    + (ax ? ax.rest : '')
    + `<div class="aw-pst-foot">Counting ${esc(_awardsStatDate(_awardsPickerEligWin.start))} – ${esc(_awardsStatDate(_awardsPickerEligWin.end))}, this year's eligibility window</div>`;
}

// Opens the card straight under its row, without re-rendering the list
/* ── Artist of the Year extras ───────────────────────────────────────────────
   Unlockable highlights, career growth year by year, the plaques earned in the
   window and every record the artist holds. Built when a card opens, not with
   the picker index, since only artists get them and most cards stay shut. */

// Plays per calendar year for every artist (primary artist, as the picker
// counts them), cached until the plays change
let _awardsArtistYearIdx = null, _awardsArtistYearIdxKey = '';
function _awardsArtistYears() {
  const key = allPlays.length + '|' + (allPlays.length ? +allPlays[0].date : 0);
  if (_awardsArtistYearIdx && _awardsArtistYearIdxKey === key) return _awardsArtistYearIdx;
  const years = new Map();   // "2016" → Map(artistKey → plays)
  for (const p of allPlays) {
    const y = dayStrOf(p).slice(0, 4);
    let m = years.get(y);
    if (!m) years.set(y, m = new Map());
    const k = _pk(p);
    m.set(k, (m.get(k) || 0) + 1);
  }
  _awardsArtistYearIdxKey = key;
  return (_awardsArtistYearIdx = years);
}

// Does a credit string name this artist (collabs count for each artist named)
function _awardsCreditMatches(credit, lower) {
  if (!credit) return false;
  if (credit.toLowerCase() === lower) return true;
  return splitArtists(credit).some(a => a.trim().toLowerCase() === lower);
}

function _awardsArtistExtras(item) {
  const s = item.st;
  const name = item.artist, lower = name.toLowerCase(), key = lower;
  const year = String(_awardsPickerCtx.year);
  const pl = (n, a, b) => `${n.toLocaleString()} ${n === 1 ? a : b}`;
  const short = ds => _awardsStatDate(ds).replace(/\s\d{4}$/, '');
  const section = (title, body, cls) => `<div class="aw-pst-sec${cls ? ' ' + cls : ''}"><div class="aw-pst-sec-title">${title}</div>${body}</div>`;
  const start = new Date(_awardsPickerEligWin.start + 'T00:00:00');
  const end   = new Date(_awardsPickerEligWin.end + 'T23:59:59');

  // Their songs in the window, and the first play ever
  const songs = new Map();
  let firstEver = null;
  for (const p of allPlays) {
    if (_pk(p) !== key) continue;
    if (!firstEver || p.date < firstEver) firstEver = p.date;
    if (p.date < start || p.date > end) continue;
    const sk = songKey(p);
    const e = songs.get(sk) || songs.set(sk, { title: p.title, n: 0 }).get(sk);
    e.n++;
  }
  const topSongs = [...songs.values()].sort((a, b) => b.n - a.n).slice(0, 3);

  // Their songs and albums on the weekly charts inside the window
  const hits = { song1: [], songTop10: 0, songOn: 0, album1: [], albumTop10: 0 };
  try {
    const wk = new Date(start); wk.setDate(wk.getDate() - 6);
    const lo = localDateStr(wk), hi = _awardsPickerEligWin.end;
    const full = _crFull('week').result;
    const scan = (res, nameOf, ones, top10Key, onKey) => {
      for (const d of Object.values(res || {})) {
        if (!_awardsCreditMatches(d._artist, lower)) continue;
        let best = Infinity, at1 = 0;
        for (const e of d.entries) {
          if (e.periodKey < lo || e.periodKey > hi) continue;
          if (e.rank < best) best = e.rank;
          if (e.rank === 1) at1++;
        }
        if (best === Infinity) continue;
        if (onKey) hits[onKey]++;
        if (best <= 10) hits[top10Key]++;
        if (best === 1) ones.push({ name: nameOf(d), at1 });
      }
    };
    scan(full.songs,  d => d._title, hits.song1,  'songTop10', 'songOn');
    scan(full.albums, d => d._album, hits.album1, 'albumTop10', null);
    hits.song1.sort((a, b) => b.at1 - a.at1);
  } catch (e) {}

  // Plaques earned in the window, and how many they hold in all
  let certs = [], certsAll = 0;
  try {
    certs = certsInRange(start, end).filter(c => _awardsCreditMatches(c.artist, lower));
    certsAll = _certTimeline.filter(c => _awardsCreditMatches(c.artist, lower)).length;
  } catch (e) {}

  // Year by year
  const yIdx = _awardsArtistYears();
  const allYears = [...yIdx.keys()].sort();
  const career = allYears.map(y => {
    const m = yIdx.get(y), n = m.get(key) || 0;
    let rank = 0;
    if (n) { rank = 1; for (const v of m.values()) if (v > n) rank++; }
    return { y, n, rank };
  });
  // Trim the empty years before they arrived
  while (career.length > 1 && !career[0].n) career.shift();
  const cur = career.find(c => c.y === year);
  const prev = career[career.indexOf(cur) - 1];
  const bestYear = career.reduce((a, c) => (c.n > a.n ? c : a), { n: 0 });
  const bestRank = career.filter(c => c.rank).reduce((a, c) => (!a || c.rank < a.rank ? c : a), null);
  const firstDay = firstEver ? localDateStr(tzDate(firstEver)) : '';
  const firstYear = firstDay.slice(0, 4);

  // ── Highlights: the badges they unlocked ──
  const badges = [];
  const badge = (icon, title, sub, cls) => badges.push(`<div class="aw-pst-badge${cls ? ' ' + cls : ''}" style="--i:${badges.length}">
      <span class="aw-pst-badge-icon" aria-hidden="true">${icon}</span>
      <span class="aw-pst-badge-text"><b>${title}</b>${sub ? `<small>${sub}</small>` : ''}</span>
    </div>`);
  if (firstYear === year) badge('🆕', 'Breakout year', `You first played them on ${short(firstDay)}`, 'is-new');
  if (cur && bestYear.y === year && career.length > 1) badge('📈', 'Biggest year ever', `${pl(cur.n, 'play', 'plays')}, more than any other year`, 'is-gold');
  if (hits.song1.length) badge('👑', `${pl(hits.song1.length, '#1 hit', '#1 hits')}`, esc(hits.song1.slice(0, 2).map(h => h.name).join(', ')) + (hits.song1.length > 2 ? ` +${hits.song1.length - 2}` : ''), 'is-gold');
  if (hits.album1.length) badge('💽', `${pl(hits.album1.length, '#1 album', '#1 albums')}`, esc(hits.album1.map(h => h.name).slice(0, 2).join(', ')), 'is-gold');
  if (hits.songTop10) badge('🔟', `${pl(hits.songTop10, 'top 10 hit', 'top 10 hits')}`, `of ${pl(hits.songOn, 'song', 'songs')} that made your weekly chart`);
  if (certs.length) badge('💿', `${pl(certs.length, 'new plaque', 'new plaques')}`, 'certified this year', 'is-plat');
  if (s.streak.len >= 7) badge('🔥', `${s.streak.len}-day streak`, 'played every single day', 'is-hot');
  if (s.peakDay.n >= 10) badge('🎧', `${s.peakDay.n} plays in one day`, `on ${short(s.peakDay.key)}`, 'is-hot');
  if (topSongs[0]) badge('🎤', esc(topSongs[0].title), `their biggest song, ${pl(topSongs[0].n, 'play', 'plays')}`);
  const highlights = badges.length ? section('Highlights', `<div class="aw-pst-badges">${badges.join('')}</div>`) : '';

  // ── Career: one bar per year ──
  let careerHtml = '';
  if (career.length > 1 && cur) {
    const top = Math.max(1, ...career.map(c => c.n));
    const delta = prev && prev.n ? Math.round((cur.n - prev.n) / prev.n * 100) : null;
    const trend = !prev || !prev.n
      ? `<span class="aw-pst-trend is-new">New in ${esc(year)}</span>`
      : delta >= 0
        ? `<span class="aw-pst-trend is-up">▲ ${delta}% vs ${esc(prev.y)}</span>`
        : `<span class="aw-pst-trend is-down">▼ ${Math.abs(delta)}% vs ${esc(prev.y)}</span>`;
    const bars = career.map(c => `<div class="aw-pst-yr${c.y === year ? ' is-cur' : ''}${c.n ? '' : ' is-empty'}" title="${esc(c.y)}: ${pl(c.n, 'play', 'plays')}${c.rank ? `, #${c.rank} artist` : ''}">
        <span class="aw-pst-yr-n">${c.n || ''}</span>
        <span class="aw-pst-yr-fill" style="height:${c.n ? Math.max(6, Math.round(c.n / top * 100)) : 0}%"></span>
        <span class="aw-pst-yr-lbl">${esc(career.length <= 8 ? c.y : "'" + c.y.slice(2))}</span>
        <span class="aw-pst-yr-rank">${c.rank ? '#' + c.rank : '–'}</span>
      </div>`).join('');
    careerHtml = section(`Year by year ${trend}`,
      `<div class="aw-pst-years" style="--n:${career.length}">${bars}</div>
       <div class="aw-pst-span"><span>Bars are plays, <b>#</b> is their artist rank that year</span>${bestRank ? `<span>Best rank <b>#${bestRank.rank}</b> in ${esc(bestRank.y)}</span>` : ''}</div>`);
  }

  // ── Plaques earned in the window ──
  const tierIcon = { gold: '📀', platinum: '💿', diamond: '💎' };
  const tierName = c => c.tier === 'diamond' ? tDiamondLabel(c.mult) : tTierLabel(c.tier);
  const certHtml = section(`Certifications <span class="aw-pst-sec-count">${pl(certsAll, 'plaque', 'plaques')} all time</span>`,
    certs.length
      ? `<div class="aw-pst-plaques">${certs.slice().sort((a, b) => a.date - b.date).map(c => `
          <div class="aw-pst-plaque is-${c.tier}">
            <span class="aw-pst-plaque-icon" aria-hidden="true">${tierIcon[c.tier] || '📀'}</span>
            <span class="aw-pst-plaque-text"><b>${esc(c.title)}</b><small>${esc(tierName(c))} ${c.type === 'album' ? 'album' : 'song'} · ${pl(c.n, 'play', 'plays')} · ${esc(short(localDateStr(c.tz)))}</small></span>
          </div>`).join('')}</div>`
      : `<div class="aw-pst-none">No new plaques in ${esc(year)}</div>`);

  // ── Records: filled in after the card opens, the tally may need building ──
  const recHtml = section('Records they hold', '<div class="aw-pst-recs"><div class="aw-pst-none">Counting records…</div></div>', 'aw-pst-rec-sec');

  return { highlights, rest: careerHtml + certHtml + recHtml };
}

// Every all-time record the artist holds, from the Records tab's tally
function _awardsArtistFillRecords(card, artist) {
  const paint = () => {
    const box = card.querySelector('.aw-pst-recs');
    if (!box || !card.isConnected) return;
    const recs = (recArtistRecordsFor(artist) || []).filter(r => !r.isCert);
    if (!recs.length) { box.innerHTML = `<div class="aw-pst-none">No all-time records yet</div>`; return; }
    // Records they top first, then by their place in the table
    const rk = r => parseInt(String(r.rank).replace(/\D/g, ''), 10) || 999;
    recs.sort((a, b) => rk(a) - rk(b));
    const top1 = recs.filter(r => rk(r) === 1).length;
    const row = r => {
      const d = r.details || [];
      const hi = d.length ? d[pickHeadlineDetail(d)] : null;
      const n = rk(r);
      return `<div class="aw-pst-rec${n === 1 ? ' is-gold' : n <= 3 ? ' is-podium' : ''}">
          <span class="aw-pst-rec-rank">${n === 1 ? '🥇' : n === 2 ? '🥈' : n === 3 ? '🥉' : n < 999 ? '#' + n : '•'}</span>
          <span class="aw-pst-rec-text"><b>${esc(r.label)}${r.qualifier ? ` <i>${esc(r.qualifier)}</i>` : ''}</b><small>${esc(r.name)}</small></span>
          ${hi ? `<span class="aw-pst-rec-fig">${esc(hi.value)}</span>` : ''}
        </div>`;
    };
    const SHOW = 6;
    box.innerHTML = `<div class="aw-pst-rec-sum"><b>${recs.length}</b> ${recs.length === 1 ? 'record' : 'records'} on your Records tab${top1 ? ` · <b>${top1}</b> at #1` : ''}</div>
      <div class="aw-pst-rec-list">${recs.slice(0, SHOW).map(row).join('')}</div>
      ${recs.length > SHOW ? `<div class="aw-pst-rec-list aw-pst-rec-more" hidden>${recs.slice(SHOW).map(row).join('')}</div>
        <button type="button" class="aw-pst-rec-toggle" onclick="event.stopPropagation();const m=this.previousElementSibling;m.hidden=!m.hidden;this.textContent=m.hidden?'Show all ${recs.length}':'Show fewer'">Show all ${recs.length}</button>` : ''}`;
  };
  if (_recArtistTally) { paint(); return; }
  // Records not built this session: build once, after the card has painted
  setTimeout(() => { try { if (!_recArtistTally) buildRecords(); } catch (e) {} paint(); }, 80);
}

function awardsPickerToggleStats(idx, btn) {
  const row = btn.closest('.awards-picker-result-row');
  if (!row) return;
  const open = row.nextElementSibling?.classList.contains('awards-picker-stats') ? row.nextElementSibling : null;
  if (open) {
    open.remove();
    btn.setAttribute('aria-expanded', 'false');
    row.classList.remove('has-stats-open');
    return;
  }
  const item = _awardsPickerRows[idx];
  if (!item?.st) return;
  const card = document.createElement('div');
  card.className = 'awards-picker-stats';
  card.innerHTML = _awardsPickerStatsHtml(item);
  row.after(card);
  if (_awardsPickerCatType === 'artist') _awardsArtistFillRecords(card, item.artist);
  btn.setAttribute('aria-expanded', 'true');
  row.classList.add('has-stats-open');
  card.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

// The list the body should show right now: search filter + genre filter + sort
function _awardsPickerVisible() {
  const q = (document.getElementById('awardsPickerSearch')?.value || '').toLowerCase().trim();
  const hasFit = _awardsPickerHasFit();
  const isSummer = _awardsPickerCatFilter === 'summer';
  const isHoliday = _awardsPickerCatFilter === 'holiday';

  const list = _awardsPickerAllItems.filter(item =>
    !q || [item.title, item.album, item.artist].filter(Boolean).join(' ').toLowerCase().includes(q));

  // group: 0 = suggested, 1 = matches the category's rule, 2 = everything else.
  // Nothing is ever dropped — the rule only decides the order.
  for (const item of list) item.grp = item.sugg ? 0 : (hasFit && _awardsPickerItemFits(item) ? 1 : 2);

  if (_awardsPickerSort === 'az') {
    list.sort((a, b) => (a.title || a.album || a.artist || '').localeCompare(b.title || b.album || b.artist || ''));
  } else if (_awardsPickerSort === 'recent') {
    list.sort((a, b) => b.last - a.last);
  } else if (AWARDS_STAT_SORTS[_awardsPickerSort]) {
    // Stat sorts: items without stats (suggestions the index could not
    // reproduce) go last, and play count breaks every tie
    const val = AWARDS_STAT_SORTS[_awardsPickerSort];
    list.sort((a, b) => {
      const va = a.st ? val(a.st) : -Infinity, vb = b.st ? val(b.st) : -Infinity;
      return vb - va || b.plays - a.plays;
    });
  } else if (_awardsPickerSort === 'rated') {
    // Unrated candidates sort last rather than as a zero — never rated is not
    // the same judgement as rated badly, and burying them under the 0.x scores
    // would say it was.
    list.sort((a, b) => {
      const sa = _awardsPickerItemScore(a), sb = _awardsPickerItemScore(b);
      if (sa == null && sb == null) return b.plays - a.plays;
      if (sa == null) return 1;
      if (sb == null) return -1;
      return sb - sa || b.plays - a.plays;
    });
  } else {
    list.sort((a, b) => a.grp - b.grp
      || (isSummer ? (b.summerPlays || 0) - (a.summerPlays || 0) : 0)
      || (isHoliday ? (b.holidayPlays || 0) - (a.holidayPlays || 0) : 0)
      || b.plays - a.plays);
  }
  return list;
}

// A candidate's own rating, shown on its nominee row so nominations can be made
// on the user's actual verdict instead of play count alone. Songs are keyed by
// title+artist and albums by album+artist, matching songKey()/albumKeyOf();
// artist candidates use their album average, which is what the artist modal
// treats as an artist's headline number.
function _awardsPickerItemScore(item) {
  if (typeof ratingSongScore !== 'function') return null;
  if (item.title)  return ratingSongScore((item.title + '|||' + item.artist).toLowerCase());
  if (item.album)  { const r = ratingAlbumScore(item.album + '|||' + item.artist); return r ? r.score : null; }
  if (item.artist) return ratingArtistSummary(item.artist).albumAvg;
  return null;
}

function _awardsPickerScoreChip(item) {
  const s = _awardsPickerItemScore(item);
  // Not a number (an artist with no rated albums averages to NaN) shows nothing,
  // not a lone "—" chip
  return Number.isFinite(s) ? ratingChip(s, 'rt-chip--row') : '';
}

/* ─── Year and genres on every picker row ───────────────────────────────────
   Every song and album row shows its release year, and every row shows its
   genres, not just the suggested ones. Both come from slow web lookups, so a
   row is only looked up once it scrolls into view (the same observer as the
   thumbnails), a few at a time, and answers are saved for next time (see
   _awardsSaveLookupCaches). Sheet genres need no lookup and show straight away. */

// The album key the release-year lookups use; '' for artists and songs with no album
function _awardsPickerYearKey(item) {
  if (_awardsPickerCatType === 'artist' || !item.album || item.album === '—') return '';
  return item.album.toLowerCase() + '|||' + (item.artist || '').toLowerCase();
}

// undefined = not looked up yet, null = looked up and not found
function _awardsPickerItemYear(item) {
  if (item.releaseYear !== undefined) return item.releaseYear;   // a suggestion that came with its year
  const k = _awardsPickerYearKey(item);
  if (!k) return null;
  return k in _awardsAlbumYearCache ? _awardsAlbumYearCache[k] : undefined;
}

function _awardsPickerYearText(item) {
  const y = _awardsPickerItemYear(item);
  if (y) return ' · ' + y;
  // Only the categories that rank on release year say so when it's missing;
  // anywhere else a blank is quieter than "year unknown" on half the list
  return y === null && item.releaseYear === null ? ' · year unknown' : '';
}

// Genre chips for a row. Genre categories show five and flag the unknowns,
// since the genre is the point there; elsewhere three, and a blank when none.
function _awardsPickerGenreInner(item) {
  const isGenreCat = _awardsPickerCatFilter.startsWith('genre:') || _awardsPickerCatFilter === 'rock_group' || _awardsPickerCatFilter.includes('+genre:');
  // The sheet marks a blank genre cell with "-"; that is not a genre to show
  const raw = _awardsPickerItemTags(item);
  const tags = Array.isArray(raw) ? raw.filter(g => g && !/^[-–—\s]+$/.test(g)) : raw;
  if (tags && tags.length) {
    // One line: the first few, then "+N" holding the rest in its tooltip, so a
    // row never grows into a stack of chips (phase 9 part 5 step 6)
    const max = isGenreCat ? 3 : 2;
    const rest = tags.slice(max, isGenreCat ? 5 : 3);
    return tags.slice(0, max).map(t => `<span class="dc-chip awards-picker-genre-tag">${esc(t)}</span>`).join('')
      + (rest.length ? `<span class="dc-chip awards-picker-genre-tag awards-picker-genre-more" title="${esc(rest.join(', '))}">+${rest.length}</span>` : '');
  }
  if (!isGenreCat) return '';
  return `<span class="dc-chip awards-picker-genre-tag awards-picker-genre-unk">${tags === undefined ? '…' : 'no genre'}</span>`;
}

// The artist whose tags stand in for a row with no sheet genres (as _awardsSongTags reads them)
function _awardsPickerGenreArtist(item) {
  return _awardsPickerCatType === 'song' ? _pa(item) : (item.artist || '');
}

// One release-year lookup per album at a time, however many rows ask for it
const _awardsAlbumYearQueue = {};
function _awardsAlbumYearOnce(album, artist) {
  const k = album.toLowerCase() + '|||' + artist.toLowerCase();
  if (k in _awardsAlbumYearCache) return Promise.resolve(_awardsAlbumYearCache[k]);
  if (!_awardsAlbumYearQueue[k]) {
    _awardsAlbumYearQueue[k] = _awardsGetAlbumYear(album, artist).finally(() => { delete _awardsAlbumYearQueue[k]; });
  }
  return _awardsAlbumYearQueue[k];
}

let _awardsMetaPending = [];   // [{ idx, item }] rows seen but not looked up yet
let _awardsMetaPumping = false;
const AWARDS_META_PARALLEL = 6;   // gentle on Last.fm, iTunes and MusicBrainz

// Whether a row still has anything to look up
function _awardsPickerNeedsMeta(item) {
  return _awardsPickerItemYear(item) === undefined || _awardsPickerItemTags(item) === undefined;
}

async function _awardsPickerFetchMeta(item) {
  const jobs = [];
  if (_awardsPickerItemYear(item) === undefined) jobs.push(_awardsAlbumYearOnce(item.album, item.artist || ''));
  if (_awardsPickerItemTags(item) === undefined) {
    const a = _awardsPickerGenreArtist(item);
    if (a) jobs.push(_awardsGetArtistGenre(a));
  }
  try { await Promise.all(jobs); } catch (e) {}
}

// Repaint one row's year and genres in place, if it's still the same row
function _awardsPickerPaintMeta(idx, item) {
  if (_awardsPickerRows[idx] !== item) return;
  const row = document.querySelector(`#awardsPickerBody .awards-picker-result-row[data-idx="${idx}"]`);
  if (!row) return;
  const y = row.querySelector('.awards-picker-year');
  if (y) y.textContent = _awardsPickerYearText(item);
  const g = row.querySelector('.awards-picker-genre-tags');
  if (g) { g.innerHTML = _awardsPickerGenreInner(item); _awardsPickerMarkClipped(row); }
}

async function _awardsPickerPumpMeta() {
  if (_awardsMetaPumping) return;   // the running pump will get to the new jobs
  _awardsMetaPumping = true;
  const seq = _awardsThumbSeq;      // a rebuild bumps this, same as for the thumbnails
  // A pool of workers, not batches: one slow album (MusicBrainz can take
  // seconds) shouldn't hold up the rows behind it
  const worker = async () => {
    while (seq === _awardsThumbSeq && _awardsMetaPending.length) {
      const { idx, item } = _awardsMetaPending.shift();
      await _awardsPickerFetchMeta(item);
      if (seq === _awardsThumbSeq) _awardsPickerPaintMeta(idx, item);
    }
  };
  try {
    await Promise.all(Array.from({ length: AWARDS_META_PARALLEL }, worker));
  } finally { _awardsMetaPumping = false; }
  if (_awardsMetaPending.length) _awardsPickerPumpMeta();
}

function _awardsPickerResultRow(item, idx) {

  const picked = _awardsPickerSelKeys.has(_awardItemKey(item));
  const lbl = item.title || item.album || item.artist || '';
  const sub = item.title ? item.artist : (item.album ? item.artist : '');
  // Year and genres sit in their own spans so the lazy lookup can fill them in place
  const rel = `<span class="awards-picker-year">${esc(_awardsPickerYearText(item))}</span>`;
  const genreHtml = `<span class="awards-picker-genre-tags">${_awardsPickerGenreInner(item)}</span>`;
  const statLine = _awardsPickerStatLine(item, idx);
  const cls = 'awards-picker-result-row'
    + (picked ? ' is-picked' : '')
    + (idx === _awardsPickerActive ? ' is-active' : '')
    + (statLine ? ' has-stats' : '');
  return `<div class="${cls}" data-idx="${idx}" onclick="awardsPickerToggleRow(${idx})" title="${esc(t(picked ? 'awx_pk_drop' : 'awx_pk_add'))}">
    <span class="awards-picker-add-icon">${picked ? '✓' : '+'}</span>
    ${_awardsPickerThumbHtml(item, 'awPkThumb' + idx)}
    <span class="awards-picker-main">
      <span class="awards-picker-lbl" title="${esc(lbl)}">${esc(lbl)}</span>
      ${sub ? `<span class="awards-picker-sub" title="${esc(sub)}">${esc(sub)}${rel}</span>` : ''}
    </span>
    ${genreHtml}
    ${_awardsPickerFitChip(item)}
    ${_awardsPickerScoreChip(item)}
    <span class="awards-picker-plays">${esc(_awScoreText(item.playLabel || item.plays + ' plays'))}</span>
    ${_awardsPickerPrevBtn(item, `awardsPickerPreviewRow(${idx})`)}
    ${_awardsPickerListenBtns(item, `awardsPickerPlayRow(${idx})`)}
    ${statLine}
  </div>`;
}

function _awardsPickerSelHtml() {
  if (!_awardsPickerSel.length) return '<div class="awards-picker-nom-empty">No nominees yet — click any row below to add one</div>';
  return _awardsPickerSel.map((item, i) => {
    const lbl = item.title || item.album || item.artist || '';
    const sub = item.title ? item.artist : (item.album ? item.artist : '');
    const tip = sub ? `${lbl} — ${sub}` : lbl;
    // Draggable cards: the order here is the order the nominees appear on the award card
    return `<div class="awards-picker-nom-row" draggable="true" data-i="${i}" title="${esc(tip)} · ${esc(t('awx_pk_drag_tip'))}"
        ondragstart="awardsPickerDragStart(event,${i})"
        ondragover="awardsPickerDragOver(event)"
        ondragleave="awardsPickerDragLeave(event)"
        ondrop="awardsPickerDrop(event,${i})"
        ondragend="awardsPickerDragEnd(event)">
      <span class="awards-picker-nom-num">${i + 1}</span>
      ${_awardsPickerThumbHtml(item, 'awPkNomThumb' + i)}
      <span class="awards-picker-nom-text">
        <span class="awards-picker-nom-lbl">${esc(lbl)}</span>
        ${sub ? `<span class="awards-picker-nom-sub">${esc(sub)}</span>` : ''}
      </span>
      <span class="awards-picker-nom-actions">
        ${_awardsPickerPrevBtn(item, `awardsPickerPreviewNom(${i})`)}
        ${_awardsPickerListenBtns(item, `awardsPickerPlayNom(${i})`)}
      </span>
      <button class="awards-picker-nom-x" data-i="${i}" onclick="event.stopPropagation();awardsPickerRemoveNom(this)" title="${esc(t('awx_remove'))}" aria-label="${esc(t('awx_remove'))} ${esc(lbl)}">✕</button>
    </div>`;
  }).join('');
}

function _awardsPickerBodyHtml() {
  const list = _awardsPickerVisible();
  const q = (document.getElementById('awardsPickerSearch')?.value || '').trim();
  if (!list.length) {
    return `<div class="awards-empty">${q ? `No results for "${esc(q)}"` : t('awards_no_candidates')}</div>`;
  }
  _awardsPickerRows = list.slice(0, _awardsPickerShown);

  const showHeaders = _awardsPickerSort === 'plays';
  const fitLabel = _awardsPickerFitLabel();
  const year = _awardsPickerCtx.year;
  const headers = [
    t('awx_pk_suggested'),
    fitLabel ? t('awx_pk_fit_from', { f: fitLabel, y: year }) : t('awx_pk_rest', { y: year }),
    // For a filtered category the tail is still fair game: the artist field can't spot every
    // collab, so say so rather than hiding those rows.
    fitLabel ? t('awx_pk_rest_fit', { y: year })
             : t('awx_pk_rest', { y: year }),
  ];
  let html = '', lastGrp = -1;
  _awardsPickerRows.forEach((item, i) => {
    if (showHeaders && item.grp !== lastGrp) {
      lastGrp = item.grp;
      html += `<div class="awards-picker-group">${headers[item.grp]}</div>`;
    }
    html += _awardsPickerResultRow(item, i);
  });

  const left = list.length - _awardsPickerRows.length;
  if (left > 0) html += `<button class="dc-btn dc-btn-normal dc-btn-sm awards-picker-more" onclick="awardsPickerShowMore()">${esc(t('awx_pk_more', { n: Math.min(left, AWARDS_PICKER_PAGE), left: left.toLocaleString(currentLang) }))}</button>`;
  return html;
}

// Repaint just the nominee chips and the count. The browse list underneath is
// not touched, so nothing gets re-filtered, re-sorted or re-rendered.
function _awardsPickerSyncSel() {
  const selEl   = document.getElementById('awardsPickerSelected');
  const countEl = document.getElementById('awardsPickerCount');
  const tallyEl = document.getElementById('awardsPickerTally');
  if (selEl)   { selEl.innerHTML = _awardsPickerSelHtml(); _awardsPickerLoadNomThumbs(); }
  if (countEl) countEl.textContent = t('awards_picker_selected', { count: _awardsPickerSel.length });
  if (tallyEl) tallyEl.textContent = _awardsPickerSel.length;
}

/* Flip the picked state of the rows already on screen, in place. Rebuilding the
   body instead — which is what adding or removing a nominee used to do — re-runs
   _awardsPickerVisible() over the whole year's index and regenerates 60 rows of
   HTML, each with a rating chip behind it, all to change one tick mark. On a
   phone with a large library that was seconds of jank per tap.
   Pass a key to touch only that item's row; pass nothing to resync them all. */
function _awardsPickerSyncRows(onlyKey) {
  const bodyEl = document.getElementById('awardsPickerBody');
  if (!bodyEl) return;
  _awardsPickerRows.forEach((item, i) => {
    const k = _awardItemKey(item);
    if (onlyKey && k !== onlyKey) return;
    const row = bodyEl.querySelector(`.awards-picker-result-row[data-idx="${i}"]`);
    if (!row) return;
    const picked = _awardsPickerSelKeys.has(k);
    row.classList.toggle('is-picked', picked);
    row.title = t(picked ? 'awx_pk_drop' : 'awx_pk_add');
    const icon = row.querySelector('.awards-picker-add-icon');
    if (icon) icon.textContent = picked ? '✓' : '+';
  });
}

// Full rebuild — only for the things that genuinely reorder the list (sort,
// search, paging). Selection changes go through the two helpers above.
function _awardsPickerRefresh(resetPaging) {
  if (resetPaging) { _awardsPickerShown = AWARDS_PICKER_PAGE; _awardsPickerActive = -1; }
  _awardsPickerSyncSel();
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) { bodyEl.innerHTML = _awardsPickerBodyHtml(); _awardsPickerLoadThumbs(); }
}

function _awardsShowPicker(year, catId, candidates) {
  const data = _awardsYearData[year];
  if (!data) return;
  const catDef = AWARD_CATEGORIES.find(c => c.id === catId);
  if (!catDef) return;

  const existingNominees = data.categories[catId]?.nominees || [];
  _awardsPickerSel       = existingNominees.slice();
  _awardsPickerSelKeys   = new Set(_awardsPickerSel.map(_awardItemKey));
  _awardsPickerCatType   = catDef.type;
  _awardsPickerCatFilter = catDef.filter || '';
  _awardsPickerEligWin   = { start: data.eligStart, end: data.eligEnd };
  _awardsPickerAutoCands = candidates || [];
  _awardsPickerSort      = 'plays';
  _awardsPickerShown     = AWARDS_PICKER_PAGE;
  _awardsPickerActive    = -1;
  _awardsPickerRows      = [];
  _awardsPrevKey         = null;   // no preview open yet

  const typeLabel = t(catDef.type === 'song' ? 'awx_pk_songs' : catDef.type === 'album' ? 'awx_pk_albums' : 'awx_pk_artists');
  _awardsPickerCtx = { year, catId, typeLabel };
  _awardsPickerBuildIndex();

  const html = `<div class="awards-picker-overlay" id="awardsPickerOverlay" onclick="awardsPickerBgClick(event)">
    <div class="dc-modal awards-picker-modal">
      <div class="awards-picker-head">
        <span class="awards-picker-eyebrow">${year} · ${typeLabel}</span>
        <span class="awards-picker-title">${esc(t('awards_cat_' + catDef.id))}</span>
        ${_awardsFavBtn(catDef.id, 'awards-picker-fav')}
        <button class="dc-btn dc-btn-plain dc-btn-icon dc-modal-close awards-picker-close" onclick="awardsPickerClose()" aria-label="Close" data-i18n-aria="set_close">✕</button>
      </div>
      <div class="awards-picker-ballot">
        <div class="awards-picker-ballot-head">
          <span class="awards-picker-ballot-title">${esc(t('awx_pk_nominees'))} <span class="awards-picker-tally" id="awardsPickerTally">${_awardsPickerSel.length}</span></span>
          <span class="awards-picker-ballot-hint">${esc(t('awx_pk_drag'))}</span>
          <div class="awards-picker-quick">
            <button onclick="awardsPickerFillTop(8)" title="${esc(t('awx_pk_fill_tip', { n: 8 }))}">${esc(t('awx_pk_fill', { n: 8 }))}</button>
            <button onclick="awardsPickerFillTop(5)" title="${esc(t('awx_pk_fill_tip', { n: 5 }))}">${esc(t('awx_pk_top', { n: 5 }))}</button>
            <button class="awards-picker-quick-clear" onclick="awardsPickerClearSel()">${esc(t('awx_pk_clear'))}</button>
          </div>
        </div>
        <div class="awards-picker-selected" id="awardsPickerSelected">${_awardsPickerSelHtml()}</div>
      </div>
      ${_awardsPickerPreviewKind() ? '<div class="awards-picker-preview" id="awardsPickerPreview" hidden></div>' : ''}
      <div class="awards-picker-tools">
        <div class="awards-picker-search-wrap">
          <input type="text" id="awardsPickerSearch" placeholder="${esc(t('awx_pk_search', { what: typeLabel, y: year }))}" oninput="awardsPickerDoSearch()" autocomplete="off" spellcheck="false">
          <!-- × clears the search; only shown while there is text (see awardsPickerDoSearch) -->
          <button type="button" class="awards-picker-search-clear" id="awardsPickerSearchClear" onclick="awardsPickerClearSearch()" title="${esc(t('awx_pk_clear_search'))}" aria-label="${esc(t('awx_pk_clear_search'))}" hidden>×</button>
        </div>
        <select class="awards-picker-sort" id="awardsPickerSort" onchange="awardsPickerSetSort(this.value)" title="${esc(t('awx_pk_sort_tip'))}">
          <option value="plays">${esc(t('awx_pk_sort_plays'))}</option>
          <option value="az">A–Z</option>
          <option value="recent">${esc(t('awx_pk_sort_recent'))}</option>
          <option value="rated">${esc(t('awx_pk_sort_rated'))}</option>
          ${_awardsPickerHasStats() ? Object.entries(AWARDS_STAT_SORT_LABELS).map(([v, l]) => `<option value="${v}">${l}</option>`).join('') : ''}
        </select>
      </div>
      <div class="awards-picker-body" id="awardsPickerBody">${_awardsPickerBodyHtml()}</div>
      <div class="awards-picker-foot">
        <span class="awards-picker-count" id="awardsPickerCount" title="${esc(t('awx_pk_keys_tip'))}">${t('awards_picker_selected', { count: _awardsPickerSel.length })}</span>
        <button class="dc-btn dc-btn-main" onclick="awardsPickerSave(${year},'${catId}')">${t('awards_save_nominees')}</button>
      </div>
    </div>
  </div>`;

  const wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstElementChild);
  _awardsPickerLoadThumbs();   // row and nominee-chip artwork
  _awardsPickerLoadNomThumbs();
  requestAnimationFrame(() => document.getElementById('awardsPickerSearch')?.focus());

  // Keyboard: ↑↓ walk the list, Enter adds/removes, Ctrl/⌘+Enter saves, Esc closes
  _awardsPickerKeyHandler = e => {
    if (!document.getElementById('awardsPickerOverlay')) return;
    // While the "remove all?" warning is open it owns the keyboard: Escape
    // closes only the warning, and Enter/Space press whichever button has focus
    // instead of toggling a row in the list behind it
    if (document.getElementById('awardsPickerConfirm')) {
      if (e.key === 'Escape') { e.preventDefault(); awardsPickerClearCancel(); }
      else if (e.key === 'Tab') _awardsPickerConfirmTrapTab(e);
      else if (e.key !== 'Enter' && e.key !== ' ') e.preventDefault();
      return;
    }
    if (e.key === 'Escape') { e.preventDefault(); awardsPickerClose(); return; }
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); awardsPickerSave(year, catId); return; }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      if (!_awardsPickerRows.length) return;
      e.preventDefault();
      const next = _awardsPickerActive + (e.key === 'ArrowDown' ? 1 : -1);
      _awardsPickerActive = Math.max(0, Math.min(_awardsPickerRows.length - 1, next));
      _awardsPickerPaintActive();
      return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      awardsPickerToggleRow(_awardsPickerActive >= 0 ? _awardsPickerActive : 0);
    }
  };
  document.addEventListener('keydown', _awardsPickerKeyHandler);
}

// Move the keyboard highlight without re-rendering the whole list
function _awardsPickerPaintActive() {
  const bodyEl = document.getElementById('awardsPickerBody');
  if (!bodyEl) return;
  bodyEl.querySelectorAll('.awards-picker-result-row.is-active').forEach(el => el.classList.remove('is-active'));
  const row = bodyEl.querySelector(`.awards-picker-result-row[data-idx="${_awardsPickerActive}"]`);
  if (row) { row.classList.add('is-active'); row.scrollIntoView({ block: 'nearest' }); }
}

// Clicking a row toggles it: add if new, remove if it is already nominated
function awardsPickerToggleRow(idx) {
  const item = _awardsPickerRows[idx];
  if (!item) return;
  const k = _awardItemKey(item);
  if (_awardsPickerSelKeys.has(k)) {
    _awardsPickerSel = _awardsPickerSel.filter(n => _awardItemKey(n) !== k);
    _awardsPickerSelKeys.delete(k);
  } else {
    _awardsPickerSel.push(item);
    _awardsPickerSelKeys.add(k);
  }
  _awardsPickerActive = idx;
  _awardsPickerSyncSel();
  _awardsPickerSyncRows(k);
  _awardsPickerPaintActive();
}

function awardsPickerRemoveNom(btn) {
  const i = +btn.dataset.i;
  const item = _awardsPickerSel[i];
  if (!item) return;
  const k = _awardItemKey(item);
  _awardsPickerSelKeys.delete(k);
  _awardsPickerSel.splice(i, 1);
  _awardsPickerSyncSel();
  _awardsPickerSyncRows(k);   // the same item may be on screen in the browse list
}

/* Clear asks first — one stray click would otherwise wipe a hand-built ballot.
   The warning is the site's own window, opened over the picker, rather than the
   browser's confirm() box. It lives inside the picker overlay, so closing the
   picker takes it along. Cancel has focus, so a reflex Enter is the safe answer. */
function awardsPickerClearSel() {
  const n = _awardsPickerSel.length;
  const overlay = document.getElementById('awardsPickerOverlay');
  if (!n || !overlay || document.getElementById('awardsPickerConfirm')) return;
  const catName = _awardsPickerCtx ? t('awards_cat_' + _awardsPickerCtx.catId) : '';
  const wrap = document.createElement('div');
  wrap.innerHTML = `<div class="awards-picker-confirm" id="awardsPickerConfirm" onclick="if(event.target===this)awardsPickerClearCancel()">
    <div class="dc-modal awards-picker-confirm-box" role="alertdialog" aria-modal="true" aria-labelledby="awardsPickerConfirmTitle" aria-describedby="awardsPickerConfirmText">
      <div class="awards-picker-confirm-icon" aria-hidden="true">
        <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
      </div>
      <div class="awards-picker-confirm-title" id="awardsPickerConfirmTitle">Remove all nominees?</div>
      <div class="awards-picker-confirm-text" id="awardsPickerConfirmText">This takes all <strong>${n}</strong> nominee${n === 1 ? '' : 's'} off ${catName ? `<strong>${esc(catName)}</strong>` : 'this category'}. Nothing is saved until you press Save Nominees, so closing the picker without saving keeps your current ballot.</div>
      <div class="awards-picker-confirm-actions">
        <button type="button" class="dc-btn dc-btn-normal awards-picker-confirm-cancel" onclick="awardsPickerClearCancel()">Cancel</button>
        <button type="button" class="dc-btn dc-btn-plain dc-btn-danger awards-picker-confirm-ok" onclick="awardsPickerClearConfirm()">Remove all</button>
      </div>
    </div>
  </div>`;
  overlay.appendChild(wrap.firstElementChild);
  document.querySelector('#awardsPickerConfirm .awards-picker-confirm-cancel')?.focus();
}

// Keep Tab cycling between the warning's two buttons
function _awardsPickerConfirmTrapTab(e) {
  const btns = [...document.querySelectorAll('#awardsPickerConfirm button')];
  if (!btns.length) return;
  e.preventDefault();
  const i = btns.indexOf(document.activeElement);
  btns[(i + (e.shiftKey ? -1 : 1) + btns.length) % btns.length].focus();
}

function _awardsPickerConfirmClose() {
  document.getElementById('awardsPickerConfirm')?.remove();
  document.getElementById('awardsPickerSearch')?.focus();   // back to where typing goes
}

function awardsPickerClearCancel() { _awardsPickerConfirmClose(); }

function awardsPickerClearConfirm() {
  _awardsPickerConfirmClose();
  _awardsPickerSel = [];
  _awardsPickerSelKeys = new Set();
  _awardsPickerSyncSel();
  _awardsPickerSyncRows();
}

// One-click ballot: take the top N of whatever list is currently on screen
function awardsPickerFillTop(n) {
  for (const item of _awardsPickerVisible()) {
    if (_awardsPickerSel.length >= n) break;
    const k = _awardItemKey(item);
    if (_awardsPickerSelKeys.has(k)) continue;
    _awardsPickerSel.push(item);
    _awardsPickerSelKeys.add(k);
  }
  _awardsPickerSyncSel();
  _awardsPickerSyncRows();
}

function awardsPickerShowMore() {
  _awardsPickerShown += AWARDS_PICKER_PAGE;
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) { bodyEl.innerHTML = _awardsPickerBodyHtml(); _awardsPickerLoadThumbs(); }
}

function awardsPickerSetSort(v) {
  _awardsPickerSort = v;
  _awardsPickerRefresh(true);
}

function awardsPickerDoSearch() {
  _awardsPickerShown  = AWARDS_PICKER_PAGE;
  _awardsPickerActive = -1;
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) { bodyEl.innerHTML = _awardsPickerBodyHtml(); _awardsPickerLoadThumbs(); }
  // Show the × only while there is something to clear
  const clearBtn = document.getElementById('awardsPickerSearchClear');
  if (clearBtn) clearBtn.hidden = !document.getElementById('awardsPickerSearch')?.value;
}

// The × in the search box: empty it, show the full list again, keep typing focus
function awardsPickerClearSearch() {
  const searchEl = document.getElementById('awardsPickerSearch');
  if (!searchEl) return;
  searchEl.value = '';
  awardsPickerDoSearch();
  searchEl.focus();
}

/* --- Drag to reorder the selected nominees --- */
function awardsPickerDragStart(e, i) {
  _awardsPickerDragFrom = i;
  e.dataTransfer.effectAllowed = 'move';
  try { e.dataTransfer.setData('text/plain', String(i)); } catch (_) {}
  e.currentTarget.classList.add('is-dragging');
}
function awardsPickerDragOver(e) {
  if (_awardsPickerDragFrom < 0) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  e.currentTarget.classList.add('is-dropzone');
}
function awardsPickerDragLeave(e) { e.currentTarget.classList.remove('is-dropzone'); }
function awardsPickerDragEnd(e)   { _awardsPickerDragFrom = -1; e.currentTarget.classList.remove('is-dragging'); }
function awardsPickerDrop(e, to) {
  e.preventDefault();
  const from = _awardsPickerDragFrom;
  _awardsPickerDragFrom = -1;
  // Reordering only changes the chips — the browse list is unaffected either way.
  if (from < 0 || from === to) { _awardsPickerSyncSel(); return; }
  const [moved] = _awardsPickerSel.splice(from, 1);
  _awardsPickerSel.splice(to, 0, moved);
  _awardsPickerSyncSel();
}

/* --- Previews inside the picker, so you can judge a nominee before picking it ---
   Video of the Year: every song row (and nominee chip) gets a ▶ button that
   finds the song's music video through the same YouTube lookup the mini player
   uses and plays it in a small panel at the top of the picker.
   Best Album Concept: every album gets an "i" button that shows the cover,
   Last.fm's write-up of the album (which usually says what it is about), and
   its tracklist with what you played that year.
   Best Album Cover: the cover is the whole point, so every row carries a small
   thumbnail, and the ⤢ button shows the cover as large as the picker allows.
   Clicking the button on the one already showing closes the panel. The panel
   lives inside the picker, so closing the picker closes it (and stops a video). */
const _awardsVidCache = {};       // item key → YouTube video id ('' when none was found)
const _awardsAlbumInfoCache = {}; // item key → { summary, url, tracks[] } from Last.fm
let _awardsPrevKey = null;        // key of the item in the preview panel, null when closed
let _awardsPrevSeq = 0;           // guards the async lookups against a quick second click

// Categories that get a preview button, and which kind
const _AWARDS_PREVIEW_KIND = {
  video_of_year:      'video',
  best_album_concept: 'album',
  best_album_cover:   'cover',
  best_deluxe_cover:  'cover',
};
const _AWARDS_PREVIEW_UI = {
  video: { icon: '▶', onIcon: '■', title: 'Watch a bit of the video', onTitle: 'Close the video' },
  album: { icon: 'i', onIcon: '✕', title: 'About this album',         onTitle: 'Close the album info' },
  cover: { icon: '⤢', onIcon: '✕', title: 'See the cover large',      onTitle: 'Close the cover' },
};

function _awardsPickerPreviewKind() {
  return _AWARDS_PREVIEW_KIND[_awardsPickerCtx?.catId] || null;
}

/* Artwork on every row and nominee chip, so a list of names reads at a glance:
   the song's art, the album cover or the artist's picture, whichever the
   category is about. Loaded after every rebuild of the list (open, search,
   sort, "show more"), one at a time through the same image cascade as the
   charts; a newer rebuild stops an older queue. The chips are rebuilt on every
   add, remove and drag, so a picture that has already arrived is remembered
   and put straight back instead of flashing back to initials. */
let _awardsThumbSeq = 0;
let _awardsNomThumbSeq = 0;
const _awardsThumbSrc = {};   // prefKey → image URL already shown once

function _awardsPickerThumbType() {
  return _awardsPickerCatType === 'artist' ? 'artist' : _awardsPickerCatType === 'album' ? 'album' : 'song';
}
// Keyed like the ✎ picker's choices, so a new pick can drop the stale entry
function _awardsThumbCacheKey(item) { return _cerImgItem(item, _awardsPickerThumbType(), '').prefKey; }

/* Each thumb carries the app's ✎ .img-src-btn (badge on hover, press-and-hold
   on touch), so a wrong picture can be swapped without leaving the picker. Its
   click is caught in the capture phase, so it never toggles the row. A picked
   picture is drawn from the pin; fetchAndInjectImage would find it anyway, but
   the cache below would otherwise put the old one back first. */
function _awardsPickerThumbHtml(item, imgId) {
  const type  = _awardsPickerThumbType();
  const cls   = 'awards-picker-thumb' + (type === 'artist' ? ' is-artist' : '');
  const label = item.title || item.album || item.artist || '';
  const img   = _cerImgItem(item, type, imgId);
  const pin   = imgChoicePrefs[img.prefKey];
  const src   = pin ? (pin.source !== 'off' && pin.url) || '' : _awardsThumbSrc[img.prefKey];
  const inner = src ? `<img class="thumb" alt="" src="${esc(src)}">` : `<div class="thumb-initials">${esc(initials(label))}</div>`;
  return `<div class="cer-art thumb-wrap ${cls}"><div id="${imgId}">${inner}</div><button type="button" class="img-src-btn" id="srcbtn-${imgId}" data-imgid="${imgId}" data-type="${type}" data-prefkey="${esc(img.prefKey)}" data-name="${esc(img.name)}" data-artist="${esc(img.artist || '')}" data-album="${esc(img.album || '')}" title="${esc(t('img_picker_change'))}" aria-label="${esc(t('img_picker_change_for', { name: label }))}"></button></div>`;
}

async function _awardsPickerThumbQueue(jobs, isLive) {
  const type = _awardsPickerThumbType();
  for (const { imgId, item } of jobs) {
    if (!isLive()) return;
    const el = document.getElementById(imgId);
    if (!el || el.querySelector('img')) continue;   // gone, or already filled from the cache
    const ck = _awardsThumbCacheKey(item);
    if (_awardsThumbSrc[ck] && !imgChoicePrefs[ck]) { el.innerHTML = `<img class="thumb" alt="" src="${esc(_awardsThumbSrc[ck])}">`; continue; }
    try { await fetchAndInjectImage(el, _cerImgItem(item, type, imgId), type); } catch (e) {}
    const src = document.getElementById(imgId)?.querySelector('img')?.getAttribute('src');
    if (src) _awardsThumbSrc[ck] = src;
  }
}
/* List rows load lazily: a row joins the queue only once it scrolls within
   200px of the visible part of the list, and the queue is drained in list
   order, one lookup at a time. A rebuild (search, sort, "show more") drops the
   old observer and anything still waiting. The nominee chips are few and all
   on screen, so they skip this and just load. */
let _awardsThumbObs = null;
let _awardsThumbPending = [];   // [{ idx, imgId, item }] seen but not loaded yet
let _awardsThumbPumping = false;

// Marks the genre boxes that didn't fit their row, so CSS fades the last chip
// out instead of cutting it hard. Runs after every list render and lookup.
function _awardsPickerMarkClipped(root) {
  (root || document.getElementById('awardsPickerBody'))?.querySelectorAll('.awards-picker-genre-tags').forEach(g =>
    g.classList.toggle('is-clipped', g.scrollWidth > g.clientWidth + 1));
}

function _awardsPickerLoadThumbs() {
  _awardsPickerMarkClipped();
  const seq = ++_awardsThumbSeq;
  if (_awardsThumbObs) { _awardsThumbObs.disconnect(); _awardsThumbObs = null; }
  _awardsThumbPending = [];
  _awardsMetaPending = [];
  const bodyEl = document.getElementById('awardsPickerBody');
  if (!bodyEl) return;
  if (!('IntersectionObserver' in window)) {
    _awardsPickerThumbQueue(_awardsPickerRows.map((item, i) => ({ imgId: 'awPkThumb' + i, item })), () => seq === _awardsThumbSeq);
    _awardsPickerRows.forEach((item, idx) => { if (_awardsPickerNeedsMeta(item)) _awardsMetaPending.push({ idx, item }); });
    _awardsPickerPumpMeta();
    return;
  }
  const obs = _awardsThumbObs = new IntersectionObserver(entries => {
    if (seq !== _awardsThumbSeq) return;
    for (const e of entries) {
      if (!e.isIntersecting) continue;
      obs.unobserve(e.target);
      const idx = +e.target.dataset.idx;
      const item = _awardsPickerRows[idx];
      if (!item) continue;
      if (!e.target.querySelector('.awards-picker-thumb img')) _awardsThumbPending.push({ idx, imgId: 'awPkThumb' + idx, item });
      // A row can be answered by another row's lookup (same album, same artist)
      // after it was drawn, so one with nothing left to fetch still gets repainted
      if (_awardsPickerNeedsMeta(item)) _awardsMetaPending.push({ idx, item });
      else _awardsPickerPaintMeta(idx, item);
    }
    _awardsThumbPending.sort((a, b) => a.idx - b.idx);
    _awardsMetaPending.sort((a, b) => a.idx - b.idx);
    _awardsPickerPumpThumbs();
    _awardsPickerPumpMeta();
  }, { root: bodyEl, rootMargin: '200px 0px' });
  // Rows with a cached picture and a known year and genre have nothing to fetch
  bodyEl.querySelectorAll('.awards-picker-result-row').forEach(row => {
    const item = _awardsPickerRows[+row.dataset.idx];
    if (!row.querySelector('.awards-picker-thumb img') || (item && _awardsPickerNeedsMeta(item))) obs.observe(row);
  });
}

async function _awardsPickerPumpThumbs() {
  if (_awardsThumbPumping) return;   // the running pump will get to the new jobs
  _awardsThumbPumping = true;
  const seq = _awardsThumbSeq;
  try {
    while (seq === _awardsThumbSeq && _awardsThumbPending.length) {
      const job = _awardsThumbPending.shift();
      await _awardsPickerThumbQueue([job], () => seq === _awardsThumbSeq);
    }
  } finally { _awardsThumbPumping = false; }
  // A rebuild while the last lookup was in flight leaves its jobs for a fresh pump
  if (_awardsThumbPending.length) _awardsPickerPumpThumbs();
}
function _awardsPickerLoadNomThumbs() {
  const seq = ++_awardsNomThumbSeq;
  _awardsPickerThumbQueue(_awardsPickerSel.map((item, i) => ({ imgId: 'awPkNomThumb' + i, item })), () => seq === _awardsNomThumbSeq);
}

/* Listening: every category but Video of the Year (which has its own video
   button) gets a ♪ that plays a 30-second store preview of the nominee, found
   the same way the ceremony finds them, and a link to a YouTube search for it.
   For an artist the sample is whichever of their songs the stores rank first.
   One sample at a time, through the ceremony's audio slot. */
let _awardsClipKey = null;           // key of the nominee whose sample is loading/playing
let _awardsClipLoading = false;
const _awardsClipMiss = new Set();   // keys neither store had a preview for

function _awardsPickerHasListen() { return _awardsPickerPreviewKind() !== 'video'; }

function _awardsPickerYtQuery(item) {
  const a = item.artist || '';
  if (_awardsPickerCatType === 'artist') return a;
  if (_awardsPickerCatType === 'album')  return `${a} ${item.album || ''} album`.trim();
  return `${a} ${item.title || ''}`.trim();
}

function _awardsPickerClipUi(item) {
  const k = _awardItemKey(item);
  if (_awardsClipKey === k) return _awardsClipLoading
    ? { icon: '◌', cls: ' is-on is-loading', title: t('awx_clip_finding') }
    : { icon: '❚❚', cls: ' is-on', title: t('awx_clip_stop') };
  if (_awardsClipMiss.has(k)) return { icon: '♪', cls: ' is-miss', title: t('awx_clip_none_yt') };
  return { icon: '♪', cls: '', title: t('awx_clip_play') };
}

function _awardsPickerListenBtns(item, onclick) {
  if (!_awardsPickerHasListen()) return '';
  const ui = _awardsPickerClipUi(item);
  const yt = 'https://www.youtube.com/results?search_query=' + encodeURIComponent(_awardsPickerYtQuery(item));
  // stopPropagation: the row itself toggles the nomination on click
  return `<button class="awards-picker-clip-btn${ui.cls}" onclick="event.stopPropagation();${onclick}" title="${ui.title}">${ui.icon}</button>`
    + `<a class="awards-picker-yt-btn" href="${esc(yt)}" target="_blank" rel="noopener" draggable="false" onclick="event.stopPropagation()" title="${esc(t('awx_yt'))}">`
    + `<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path fill="currentColor" d="M23 7.2a3 3 0 0 0-2.1-2.1C19 4.6 12 4.6 12 4.6s-7 0-8.9.5A3 3 0 0 0 1 7.2 31 31 0 0 0 .5 12a31 31 0 0 0 .5 4.8 3 3 0 0 0 2.1 2.1c1.9.5 8.9.5 8.9.5s7 0 8.9-.5a3 3 0 0 0 2.1-2.1 31 31 0 0 0 .5-4.8 31 31 0 0 0-.5-4.8zM9.7 15.1V8.9l5.8 3.1-5.8 3.1z"/></svg></a>`;
}

// Only the ♪ buttons change, so the list and chips aren't rebuilt
function _awardsPickerPaintClipBtns() {
  const paint = (sel, items, attr) => document.querySelectorAll(sel).forEach(row => {
    const item = items[+row.dataset[attr]];
    const btn = row.querySelector('.awards-picker-clip-btn');
    if (!item || !btn) return;
    const ui = _awardsPickerClipUi(item);
    btn.className = 'awards-picker-clip-btn' + ui.cls;
    btn.textContent = ui.icon;
    btn.title = ui.title;
  });
  paint('#awardsPickerBody .awards-picker-result-row', _awardsPickerRows, 'idx');
  paint('#awardsPickerSelected .awards-picker-nom-row', _awardsPickerSel, 'i');
}

function _awardsPickerStopClip() {
  if (!_awardsClipKey) return;
  _ceremonyStopAudio();
  _awardsClipKey = null;
  _awardsClipLoading = false;
  _awardsPickerPaintClipBtns();
}

function awardsPickerPlayRow(idx) { const it = _awardsPickerRows[idx]; if (it) _awardsPickerPlayClip(it); }
function awardsPickerPlayNom(i)   { const it = _awardsPickerSel[i];    if (it) _awardsPickerPlayClip(it); }

async function _awardsPickerPlayClip(item) {
  const k = _awardItemKey(item);
  if (_awardsClipKey === k) { _awardsPickerStopClip(); return; }   // second click stops it
  _ceremonyStopAudio();
  try { if (_ytPlayer && _ytPlayer.getPlayerState() === YT.PlayerState.PLAYING) _ytPlayer.pauseVideo(); } catch (e) {}
  _awardsClipKey = k;
  _awardsClipLoading = true;
  _awardsClipMiss.delete(k);
  _awardsPickerPaintClipBtns();
  const token = _ceremonyAudioToken;   // any later stop or play bumps it

  let takes = [];
  try { takes = await _ceremonyPreviewTakes(item, _awardsPickerCatType); } catch (e) {}
  if (token !== _ceremonyAudioToken || _awardsClipKey !== k) return;
  if (!takes.length) {
    _awardsClipMiss.add(k);
    _awardsClipKey = null;
    _awardsClipLoading = false;
    _awardsPickerPaintClipBtns();
    return;
  }
  const audio = _ceremonyAudio = new Audio(takes[0].url);
  audio.volume = 0.8;
  audio.addEventListener('ended', () => {
    if (_ceremonyAudio !== audio) return;
    _ceremonyAudio = null;
    _awardsClipKey = null;
    _awardsPickerPaintClipBtns();
  });
  try {
    await audio.play();
    if (token !== _ceremonyAudioToken) { audio.pause(); return; }
    _awardsClipLoading = false;
  } catch (e) {
    if (_ceremonyAudio === audio) _ceremonyAudio = null;
    _awardsClipKey = null;
    _awardsClipLoading = false;
  }
  _awardsPickerPaintClipBtns();
}

function _awardsPickerPrevBtn(item, onclick) {
  const kind = _awardsPickerPreviewKind();
  if (!kind || !(kind === 'video' ? item.title : item.album)) return '';
  const ui = _AWARDS_PREVIEW_UI[kind];
  const on = _awardsPrevKey === _awardItemKey(item);
  // stopPropagation: the row itself toggles the nomination on click
  return `<button class="awards-picker-prev-btn awards-picker-prev-btn--${kind}${on ? ' is-on' : ''}" onclick="event.stopPropagation();${onclick}" title="${on ? ui.onTitle : ui.title}">${on ? ui.onIcon : ui.icon}</button>`;
}

function awardsPickerPreviewRow(idx) { const it = _awardsPickerRows[idx]; if (it) _awardsPickerPreview(it); }
function awardsPickerPreviewNom(i)   { const it = _awardsPickerSel[i];    if (it) _awardsPickerPreview(it); }

// Only the preview buttons change, so the list and chips aren't rebuilt
function _awardsPickerPaintPrevBtns() {
  const ui = _AWARDS_PREVIEW_UI[_awardsPickerPreviewKind()];
  if (!ui) return;
  const paint = (sel, items, attr) => document.querySelectorAll(sel).forEach(row => {
    const item = items[+row.dataset[attr]];
    const btn = row.querySelector('.awards-picker-prev-btn');
    if (!item || !btn) return;
    const on = _awardsPrevKey === _awardItemKey(item);
    btn.classList.toggle('is-on', on);
    btn.textContent = on ? ui.onIcon : ui.icon;
    btn.title = on ? ui.onTitle : ui.title;
  });
  paint('#awardsPickerBody .awards-picker-result-row', _awardsPickerRows, 'idx');
  paint('#awardsPickerSelected .awards-picker-nom-row', _awardsPickerSel, 'i');
}

function awardsPickerClosePreview() {
  _awardsPrevKey = null;
  _awardsPrevSeq++;
  const panel = document.getElementById('awardsPickerPreview');
  if (panel) { panel.innerHTML = ''; panel.hidden = true; }   // emptying it stops the video
  _awardsPickerPaintPrevBtns();
}

async function _awardsPickerPreview(item) {
  const panel = document.getElementById('awardsPickerPreview');
  const kind = _awardsPickerPreviewKind();
  if (!panel || !kind) return;
  const k = _awardItemKey(item);
  if (_awardsPrevKey === k) { awardsPickerClosePreview(); return; }
  _awardsPrevKey = k;
  const seq = ++_awardsPrevSeq;
  _awardsPickerPaintPrevBtns();

  const ui = _AWARDS_PREVIEW_UI[kind];
  const name = kind === 'video' ? item.title : item.album;
  const head = `<div class="awards-picker-preview-head">
      <span class="awards-picker-preview-lbl">${esc(name)} <span>· ${esc(item.artist || '')}</span></span>
      <button class="awards-picker-nom-x" onclick="awardsPickerClosePreview()" title="${ui.onTitle}">✕</button>
    </div>`;
  panel.hidden = false;
  if (kind === 'album') return _awardsPickerAlbumPreview(item, k, seq, panel, head);
  if (kind === 'cover') {
    const imgId = 'awardsPrevCover';
    panel.innerHTML = head + `<div class="awards-picker-preview-bigcover">${_cerArtHtml(item, 'album', imgId, 'awards-picker-preview-cover')}</div>`;
    _awardsLoadArtQueue([{ imgId, item, type: 'album' }], () => seq === _awardsPrevSeq);
    return;
  }

  // Two sounds at once is never wanted: pause the mini player if it's going
  _awardsPickerStopClip();
  try { if (_ytPlayer && _ytPlayer.getPlayerState() === YT.PlayerState.PLAYING) _ytPlayer.pauseVideo(); } catch (e) {}

  const query = `${item.artist || ''} ${item.title} official music video`.trim();
  const ytSearch = 'https://www.youtube.com/results?search_query=' + encodeURIComponent(query);
  const status = msg => { if (seq === _awardsPrevSeq) panel.innerHTML = head + `<div class="awards-picker-preview-msg">${msg}</div>`; };
  status('Finding the video…');

  let vid = _awardsVidCache[k];
  // Where the video came from, for the "Wrong video?" line under it
  let from = 'an earlier search';
  // The site-wide search memory, shared with the mini player (see _ytMemGet)
  if (vid === undefined) {
    const remembered = await _ytMemGet(query);
    if (seq !== _awardsPrevSeq) return;
    if (remembered) vid = _awardsVidCache[k] = remembered;
  }
  // Then the free music databases (see _ytFreeLookup) — no quota, so this
  // works for signed-out visitors too
  if (vid === undefined) {
    const free = await _ytFreeLookup(item.artist || '', item.title);
    if (seq !== _awardsPrevSeq) return;
    if (free) { vid = _awardsVidCache[k] = free; from = 'Wikidata or MusicBrainz'; _ytMemPut(query, free); }
    else if (_ytNeedsSignIn()) { status(_ytSignInHTML()); return; }
  }
  if (vid === undefined) {
    // The server sleeps when idle and can take ~30s to wake, like in _ytSearch
    for (let attempt = 0; attempt <= 5 && vid === undefined; attempt++) {
      try {
        const res = await fetch(`${BACKEND_API}/api/youtube/search?q=${encodeURIComponent(query)}`);
        if (res.status === 502 || res.status === 503) throw new TypeError('asleep');
        const data = await res.json();
        vid = data.videoId || '';
        if (vid) { _ytMemPut(query, vid); from = 'YouTube search'; }
      } catch (e) {
        if (e.name !== 'TypeError' || attempt === 5) { vid = null; break; }
        status('Waking up the server…');
        await new Promise(r => setTimeout(r, 6000));
      }
      if (seq !== _awardsPrevSeq) return;
    }
    if (vid !== null) _awardsVidCache[k] = vid;   // don't remember a network failure
  }
  if (seq !== _awardsPrevSeq) return;

  if (!vid) {
    status(`No video found — <a href="${esc(ytSearch)}" target="_blank" rel="noopener">search YouTube ↗</a>`);
    return;
  }
  panel.innerHTML = head + `<div class="awards-picker-preview-frame">
      <iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(vid)}?autoplay=1&rel=0&playsinline=1"
        allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen
        title="${esc(item.title)} video"></iframe>
    </div>
    <a class="awards-picker-preview-yt" href="https://www.youtube.com/watch?v=${encodeURIComponent(vid)}" target="_blank" rel="noopener">Wrong video? It came from ${from}: open on YouTube ↗</a>`;
}

// "Song (Remastered)" / "Song - Live" / "Song [feat. X]" all count as "song"
function _awardsTrackNorm(s) {
  return (s || '').toLowerCase().replace(/\s*[(\[][^)\]]*[)\]]/g, '').replace(/\s+-\s+.*$/, '').trim();
}

// Last.fm album.getInfo, trimmed to what the panel shows. Works for every data
// source: it only needs the album and artist names, not a Last.fm account.
async function _awardsFetchAlbumInfo(item, k) {
  if (_awardsAlbumInfoCache[k]) return _awardsAlbumInfoCache[k];
  const r = await fetch(lfmUrl('album.getInfo', { album: item.album, artist: _primaryArtist(item.artist || ''), autocorrect: 1 }));
  const d = await r.json();
  const a = d && d.album;
  let summary = '';
  if (a?.wiki?.summary) {
    // The summary is HTML ending in a "Read more on Last.fm" link. DOMParser turns
    // it into plain text without running anything in it (unlike innerHTML).
    summary = new DOMParser().parseFromString(a.wiki.summary, 'text/html').body.textContent || '';
    summary = summary.replace(/\s*Read more on Last\.fm\.?\s*$/i, '').trim();
  }
  let tracks = a?.tracks?.track || [];
  if (!Array.isArray(tracks)) tracks = [tracks];   // a one-track album comes back as an object
  const info = { summary, url: a?.url || '', tracks: tracks.map(t => t.name).filter(Boolean) };
  _awardsAlbumInfoCache[k] = info;   // only reached on a good response, so failures are retried
  return info;
}

async function _awardsPickerAlbumPreview(item, k, seq, panel, head) {
  // What you played from this album in the category's eligibility window
  const start = new Date(_awardsPickerEligWin.start + 'T00:00:00');
  const end   = new Date(_awardsPickerEligWin.end   + 'T23:59:59');
  const ak = _ak(item);
  const played = new Map();   // normalised title → { title, plays }
  for (const p of allPlays) {
    if (!p.album || p.date < start || p.date > end || _ak(p) !== ak) continue;
    const n = _awardsTrackNorm(p.title);
    const e = played.get(n) || { title: p.title, plays: 0 };
    e.plays++;
    played.set(n, e);
  }

  const imgId = 'awardsPrevCover';
  const year = _awardsPickerCtx.year;
  // info: undefined while Last.fm is being asked, null when it couldn't be reached
  const render = (info, note) => {
    if (seq !== _awardsPrevSeq) return;
    // Tracklist: Last.fm's order when it has one, with your plays matched in;
    // anything you played that it doesn't list (bonus tracks) goes at the end.
    const listed = info?.tracks || [];
    const rows = [], used = new Set();
    listed.forEach((name, i) => {
      const n = _awardsTrackNorm(name);
      const hit = played.get(n);
      if (hit) used.add(n);
      rows.push({ title: name, plays: hit ? hit.plays : 0, num: i + 1 });
    });
    const extra = [...played.entries()].filter(([n]) => !used.has(n)).map(([, e]) => e).sort((a, b) => b.plays - a.plays);
    for (const e of extra) rows.push({ title: e.title, plays: e.plays, num: listed.length ? '+' : rows.length + 1 });
    // Count the album's own tracks against its length; bonus/deluxe ones separately,
    // or "18 of 13 tracks" happens
    const nListed = used.size;
    const tally = listed.length
      ? `You played ${nListed} of ${listed.length} tracks in ${year}` + (extra.length ? ` · plus ${extra.length} more` : '')
      : `${extra.length} track${extra.length === 1 ? '' : 's'} you played in ${year}`;

    const about = info === undefined ? `<p class="awards-picker-preview-about is-muted">Looking up the album…</p>`
      : info?.summary ? `<p class="awards-picker-preview-about">${esc(info.summary)}</p>`
      : `<p class="awards-picker-preview-about is-muted">${esc(note || 'Last.fm has no write-up for this album.')}</p>`;
    const more = info?.url ? `<a class="awards-picker-preview-yt" href="${esc(info.url)}/+wiki" target="_blank" rel="noopener">Read more on Last.fm ↗</a>` : '';
    const tracksHtml = rows.length ? `<div class="awards-picker-preview-tally">${tally}</div>
      <ol class="awards-picker-preview-tracks">${rows.map(r => `<li class="${r.plays ? 'is-played' : ''}">
        <span class="awards-picker-preview-tnum">${r.num}</span>
        <span class="awards-picker-preview-tname">${esc(r.title)}</span>
        <span class="awards-picker-preview-tplays">${r.plays ? r.plays + (r.plays === 1 ? ' play' : ' plays') : '–'}</span>
      </li>`).join('')}</ol>` : '';

    panel.innerHTML = head + `<div class="awards-picker-preview-album">
        ${_cerArtHtml(item, 'album', imgId, 'awards-picker-preview-cover')}
        <div class="awards-picker-preview-info">${about}${more}</div>
      </div>${tracksHtml}`;
    _awardsLoadArtQueue([{ imgId, item, type: 'album' }], () => seq === _awardsPrevSeq);
  };

  render(undefined);   // your own plays and the cover straight away, the write-up when it lands
  let info = null, note = '';
  try { info = await _awardsFetchAlbumInfo(item, k); }
  catch (e) { note = 'Couldn’t reach Last.fm for the write-up.'; }
  render(info, note);
}

function awardsPickerBgClick(e) { if (e.target.id === 'awardsPickerOverlay') awardsPickerClose(); }

function awardsPickerClose() {
  const el = document.getElementById('awardsPickerOverlay');
  if (el) el.remove();
  if (_awardsPickerKeyHandler) { document.removeEventListener('keydown', _awardsPickerKeyHandler); _awardsPickerKeyHandler = null; }
  _awardsPickerSel      = [];
  _awardsPickerSelKeys  = new Set();
  _awardsPickerAllItems = [];   // drop the index so a big library isn't held in memory
  _awardsPickerRows     = [];
  _awardsPickerSuggKeys = new Set();
  _awardsPrevKey         = null;   // the preview went away with the overlay
  _awardsPrevSeq++;
  _awardsThumbSeq++;               // stop loading row thumbnails
  _awardsNomThumbSeq++;
  if (_awardsThumbObs) { _awardsThumbObs.disconnect(); _awardsThumbObs = null; }
  _awardsThumbPending = [];
  _awardsPickerStopClip();         // a sample shouldn't outlive the picker
  _awardsClipMiss.clear();
}

// Indexed items carry picker-only fields (fit, grp, last, summerPlays…) — keep them out of
// the saved/synced document, which only ever held the identity plus the play count.
function _awardsCleanNominee(item) {
  const out = {};
  for (const f of ['title', 'album', 'artist', 'plays', 'playLabel', 'releaseYear']) {
    if (item[f] !== undefined) out[f] = item[f];
  }
  return out;
}

async function awardsPickerSave(year, catId) {
  const nominees = _awardsPickerSel.map(_awardsCleanNominee);
  awardsPickerClose();
  const data = _awardsYearData[year];
  if (!data) return;
  if (!data.categories[catId]) data.categories[catId] = { enabled: true, nominees: [], winner: null };
  data.categories[catId].nominees = nominees;
  const wk = data.categories[catId].winner ? _awardItemKey(data.categories[catId].winner) : null;
  if (wk && !nominees.some(n => _awardItemKey(n) === wk)) data.categories[catId].winner = null;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

async function awardsPickWinner(year, catId, item) {
  const data = _awardsYearData[year];
  if (!data?.categories?.[catId]) return;
  const curWk = data.categories[catId].winner ? _awardItemKey(data.categories[catId].winner) : null;
  data.categories[catId].winner = (_awardItemKey(item) === curWk) ? null : item;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

// Break a tie in an auto category: the chosen item becomes its one nominee and
// winner, which is all the ceremony and a shared copy read. The tie stays on
// record so the choice can be changed again.
async function awardsPickTieWinner(year, catId, i) {
  const cd = _awardsYearData[year]?.categories?.[catId];
  const item = cd?.ties?.[i];
  if (!item) return;
  cd.nominees = [item];
  cd.winner   = item;
  await _awardsSave(year);
  _awardsRenderCatList(_awardsYearData[year]);
}

async function awardsRemoveNominee(e, year, catId, item) {
  e.stopPropagation();
  const data = _awardsYearData[year];
  if (!data?.categories?.[catId]) return;
  const ik = _awardItemKey(item);
  data.categories[catId].nominees = data.categories[catId].nominees.filter(n => _awardItemKey(n) !== ik);
  if (data.categories[catId].winner && _awardItemKey(data.categories[catId].winner) === ik) data.categories[catId].winner = null;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

// ── Real-Life Awards ──────────────────────────────────────────────────────────

// The year in this tab is the *ceremony* year, the way grammy.com labels it: the
// 68th Grammys were held in February 2026 and honour music released in 2025. So
// the artists we match against are the ones the user played during the
// eligibility year (the year before), because that's the music being judged.
const GRAMMY_FIRST_CEREMONY_YEAR = 1959;   // the 1st Annual Grammy Awards
const REAL_LIFE_ARTIST_COUNT     = 50;     // how deep into the year's artists to look
const REAL_LIFE_CONCURRENCY      = 8;      // lookups in flight at once

function _grammyCeremonyNo(year) { return year - GRAMMY_FIRST_CEREMONY_YEAR + 1; }

function _ordinal(n) {
  const rem100 = n % 100, rem10 = n % 10;
  if (rem100 >= 11 && rem100 <= 13) return n + 'th';
  return n + (({ 1: 'st', 2: 'nd', 3: 'rd' })[rem10] || 'th');
}

// One entry per artist name, holding the promise so that flipping between years
// (or back to a year already seen) never refetches the same artist.
const _grammyArtistCache = {};
// Bumped on every load so a slow year that the user has already navigated away
// from can't paint over the year they're looking at now.
let _realLifeLoadToken = 0;

// Ask our own /grammy-proxy Function for an artist's complete Grammy record —
// every nomination and win, with the ceremony year on each. See
// functions/grammy-proxy.js for why grammy.com can't be read from the browser.
function _grammyFetchArtist(artist) {
  const key = (artist || '').toLowerCase();
  if (_grammyArtistCache[key]) return _grammyArtistCache[key];

  const isLocal = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  const base = isLocal ? 'https://dankcharts.fm/grammy-proxy' : '/grammy-proxy';

  _grammyArtistCache[key] = fetch(base + '?artist=' + encodeURIComponent(artist))
    .then(r => r.ok ? r.json() : { found: false })
    .catch(() => ({ found: false }));
  return _grammyArtistCache[key];
}

// Walk a list with a handful of requests in flight at once — fifty artists one
// at a time would be a long wait, fifty at once is rude to the proxy.
async function _grammyMapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      out[i] = await fn(items[i], i);
    }
  }));
  return out;
}

// Which show the Real-Life Awards tab is on: the Grammys, or one of the shows
// read from Wikipedia (RL_WIKI_SHOWS: the MTV VMAs, the AMAs, the iHeartRadio
// Music Awards, the World Music Awards, the Billboard Music Awards, the ARIA
// Music Awards, the Juno Awards, the BRIT Awards). They all share
// one year stepper and one content area; this just picks the loader.
const RL_SHOW_IDS = ['grammys', 'vmas', 'amas', 'iheart', 'wma', 'billboard', 'aria', 'juno', 'brit'];
let _realLifeShow = (() => {
  try { const v = localStorage.getItem('dc_awards_reallife_show'); return RL_SHOW_IDS.includes(v) ? v : 'grammys'; }
  catch (e) { return 'grammys'; }
})();

// Light up the tab of the show that's showing
function _realLifeSyncShowUI() {
  document.querySelectorAll('.awards-show-opt').forEach(b =>
    b.setAttribute('aria-checked', b.dataset.show === _realLifeShow ? 'true' : 'false'));
}

// Clicking a show's tab. Going through _awardsSetYear pulls the year inside the
// new show's range (the VMAs only go back to 1984, the AMAs to 1974, iHeartRadio
// to 2014) and loads it.
function realLifeSetShow(show) {
  if (!RL_SHOW_IDS.includes(show)) return;
  _awardsCloseYearPicker();
  _realLifeShow = show;
  try { localStorage.setItem('dc_awards_reallife_show', show); } catch (e) {}
  _awardsSetYear('reallife', _realLifeYear);
}

// Entry point for the Real-Life tab, whichever show is picked
function loadRealLifeAwards(year) {
  _realLifeSyncShowUI();
  // A year remembered from the Grammys can be older than the show's first ceremony
  const { min, max } = _awardsYearBounds('reallife');
  if (year < min || year > max || _realLifeSnapYear(year) !== year) {
    year = _realLifeSnapYear(Math.max(min, Math.min(max, year)));
    _realLifeYear = year;
    _awardsSyncYearUI('reallife');
  }
  return RL_WIKI_SHOWS[_realLifeShow] ? _loadRealLifeWiki(_realLifeShow, year) : _loadRealLifeGrammys(year);
}

async function _loadRealLifeGrammys(year) {
  const contentEl = document.getElementById('realLifeContent');
  const statusEl  = document.getElementById('realLifeStatus');
  const token = ++_realLifeLoadToken;
  contentEl.innerHTML = '';

  if (!allPlays.length) {
    statusEl.textContent = 'Load your music data first.';
    return;
  }

  // Top artists of the eligibility year — the music this ceremony is judging.
  // Users whose data doesn't reach back that far fall back to everything they
  // have, so the tab still says something useful.
  const eligYear = year - 1;
  const start = new Date(`${eligYear}-01-01`);
  const end   = new Date(`${eligYear}-12-31T23:59:59`);
  const inYear = allPlays.filter(p => p.date >= start && p.date <= end);
  const pool = inYear.length ? inYear : allPlays;
  const { artists } = _awardsCountMaps(pool);
  // 50 rather than a handful: past the top ten or so is exactly where the
  // surprises are, the artist you played twice who turns out to have been
  // nominated. Each one is a single cached proxy call, so the depth is cheap.
  const topArtists  = _awardsTopN(artists, REAL_LIFE_ARTIST_COUNT, 1);

  const ceremony = t('awx_rl_ceremony', { o: _ordinal(_grammyCeremonyNo(year)), n: _grammyCeremonyNo(year) });
  let done = 0;
  const tick = () => {
    if (token !== _realLifeLoadToken) return;
    statusEl.textContent = t('awx_rl_checking', { n: topArtists.length, y: eligYear, c: ceremony, d: done });
  };
  tick();

  const looked = await _grammyMapLimit(topArtists, REAL_LIFE_CONCURRENCY, async a => {
    const data = await _grammyFetchArtist(a.artist);
    done++; tick();
    return { played: a, data };
  });
  if (token !== _realLifeLoadToken) return;   // the user moved on

  // Keep the user's own listening order: their #1 artist of the year leads.
  const results = looked
    .filter(r => r.data?.found)
    .map(r => ({ ...r, entries: (r.data.entries || []).filter(e => e.year === year) }))
    .filter(r => r.entries.length);

  statusEl.textContent = '';

  const headline = `<div class="awards-reallife-head">
      <div class="awards-reallife-ceremony">${esc(ceremony)}</div>
      <div class="awards-reallife-sub">${esc(t('awx_rl_held', { y: year, e: eligYear }))}${inYear.length ? '' : esc(t('awx_rl_alltime_match'))}</div>
    </div>`;
  const credit = `<div class="awards-reallife-credit">${t('awx_rl_credit', { link: '<a href="https://www.grammy.com/awards/" target="_blank" rel="noopener">grammy.com</a>' })}</div>`;

  if (!results.length) {
    contentEl.innerHTML = headline +
      `<div class="awards-empty">${esc(t('awx_rl_none_top', { n: topArtists.length, y: eligYear, c: ceremony }))}</div>` +
      credit;
    return;
  }

  const wins = results.reduce((n, r) => n + r.entries.filter(e => e.won).length, 0);
  const noms = results.reduce((n, r) => n + r.entries.length, 0);
  const tally = _rlTallyHtml(noms, wins);

  // Artwork is loaded after the list paints, through the app's normal image
  // cascade, so a picture pinned on the charts shows up here too.
  const artQueue = [];

  contentEl.innerHTML = headline + tally + results.map((r, ri) => {
    // Wins first within an artist, so the good news is at the top of the card.
    const rows = r.entries.slice().sort((a, b) => (b.won ? 1 : 0) - (a.won ? 1 : 0));
    const artistId = `rl-art-${ri}`;
    artQueue.push({ imgId: artistId, type: 'artist', item: {
      name: r.played.artist, artist: r.played.artist,
      prefKey: 'artist:' + r.played.artist.toLowerCase(),
    } });

    // The artist's portrait runs down the whole card, with their name and every
    // nomination beside it.
    return `<div class="dc-card-inset awards-reallife-card${_rlCardCls(rows.length)}">
      ${_rlArtHtml(artistId, r.played.artist, 'awards-reallife-portrait')}
      <div class="awards-reallife-body">
        <div class="awards-reallife-artist">
          <a href="${esc(r.data.url)}" target="_blank" rel="noopener">${esc(r.data.artist)}</a>
          <span class="awards-reallife-alltime">${esc(t('awx_rl_alltime', { w: _awPl('awx_wins', r.data.wins), n: r.data.nominations }))}</span>
        </div>
        ${rows.map((e, ei) => {
          const workId = `rl-work-${ri}-${ei}`;
          const art = _rlWorkArt(e, r);
          if (art) artQueue.push({ imgId: workId, type: art.type, item: art.item });
          return `<div class="awards-reallife-row">
            ${art ? _rlArtHtml(workId, e.title, 'awards-reallife-thumb') : '<div class="awards-reallife-thumb is-blank"></div>'}
            <span class="awards-reallife-badge ${e.won ? 'won' : 'nom'}">${e.won ? '🏆 ' + esc(t('awx_rl_won')) : '🎗 ' + esc(t('awx_rl_nominated'))}</span>
            <span class="awards-reallife-rowtext">
              <span class="awards-reallife-cat">${esc(_rlCatCase(e.category))}</span>
              ${e.title ? `<span class="awards-reallife-work">${esc(e.title)}</span>` : ''}
            </span>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('') + credit;

  _realLifeLoadArt(artQueue, token);
}

// "Your artists picked up 28 nominations and won 2." in the language on screen
function _rlTallyHtml(noms, wins) {
  const n = `<strong>${noms}</strong> ${esc(t(noms === 1 ? 'awx_w_nom_one' : 'awx_w_nom_other'))}`;
  return `<div class="awards-reallife-tally">${wins ? t('awx_rl_tally_won', { n, w: `<strong>${wins}</strong>` }) : t('awx_rl_tally', { n })}</div>`;
}

// A card with one or two nominations gets a small square portrait instead of
// a tall one that leaves the card mostly empty (phase 9 part 5 step 9)
function _rlCardCls(n) { return n <= 2 ? ' is-short' : ''; }

// grammy.com writes categories in Title Case ("Song Of The Year"); put the
// small words back in lower case ("Song of the Year"), never the first word
const _RL_SMALL_WORDS = new Set(['of', 'the', 'a', 'an', 'and', 'or', 'for', 'in', 'on', 'with', 'by', 'to', 'at', 'from']);
function _rlCatCase(s) {
  return String(s || '').split(' ').map((w, i) => (i > 0 && _RL_SMALL_WORDS.has(w.toLowerCase()) && /^[A-Z][a-z]*$/.test(w)) ? w.toLowerCase() : w).join(' ');
}

// An empty thumb slot with the initials showing, for fetchAndInjectImage to fill
// in place — the same shape the ceremony slides use.
function _rlArtHtml(imgId, label, cls) {
  return `<div class="${cls}"><div id="${imgId}"><div class="thumb-initials">${esc(initials(label || ''))}</div></div></div>`;
}

// What picture belongs next to one nomination, in the shape fetchAndInjectImage
// wants. Album categories get the album's cover, everything else the single's —
// and a category with no work at all (Best New Artist, Producer Of The Year)
// gets nothing rather than a repeat of the artist photo above it.
function _rlWorkArt(entry, result) {
  if (!entry.title) return null;

  // Look the artwork up under the user's own spelling of the artist, not
  // grammy.com's, so it shares a prefKey with their charts — a picture they
  // pinned on "Beyoncé" is found here, where grammy.com would say "Beyoncé
  // Knowles". On a row the artist only wrote or featured on, the credited name
  // is the one that will actually find the cover.
  const credited = entry.artists || [];
  const isTheirs = !credited.length ||
    credited.some(a => a.toLowerCase() === (result.data.artist || '').toLowerCase());
  const artist = isTheirs ? result.played.artist : credited[0];

  const type = /\balbum\b|soundtrack|compendium|recording package/i.test(entry.category) ? 'album' : 'song';
  const key = artist.toLowerCase() + '|||' + entry.title.toLowerCase();
  return type === 'album'
    ? { type, item: { name: entry.title, album: entry.title, artist, prefKey: 'album:' + key } }
    : { type, item: { name: entry.title, title: entry.title, artist, prefKey: 'song:' + key } };
}

// One at a time: fetchAndInjectImage already paces the Deezer proxy, and it drops
// any job whose container has left the DOM, so a year the user has navigated
// away from stops loading by itself.
async function _realLifeLoadArt(queue, token) {
  for (const job of queue) {
    if (token !== _realLifeLoadToken) return;
    const el = document.getElementById(job.imgId);
    if (!el) continue;
    try {
      await fetchAndInjectImage(el, { imgId: job.imgId, prefKey: 'artist:' + (job.item.artist || '').toLowerCase(), ...job.item }, job.type);
    } catch (e) {}
  }
}

// ── Real-Life Awards: shows read from Wikipedia (VMAs, AMAs, iHeartRadio) ─────

// The VMAs, AMAs and iHeartRadio awards have no artist database like grammy.com's, but Wikipedia
// keeps one page per ceremony ("2025 MTV Video Music Awards", "American Music
// Awards of 2025") with every category's winner and nominees in a table. Its
// API sends CORS headers when asked (origin=*), so the browser reads it directly
// and DOMParser does the parsing — no proxy needed. One fetch gets the whole
// ceremony, so we can match every artist the user played, not just their top 50
// like the Grammys tab.
//
// Each show says which page(s) hold a year, what to call the ceremony, and which
// stretch of the user's listening it judges:
//   pages(year)        → Wikipedia titles; more than one when a year had two shows
//   window(year, date) → { start, end, label } of the plays to match; `date` is
//                        the ceremony date from the page's infobox, or null

// The twelve months leading up to the night itself — for shows that move
// around the calendar and cover about the year before them. Without a date
// from the page, assume the end of January.
function _rlWikiYearBefore(y, date) {
  const end = date || new Date(`${y}-01-31T23:59:59`);
  const start = new Date(end); start.setFullYear(start.getFullYear() - 1);
  const fmt = d => d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  return { start, end, label: `${fmt(start)} to ${fmt(end)}` };
}

// For shows whose awards went to a calendar year's chart or sales leaders: the
// twelve months before the night when the page gives its date, otherwise the
// calendar year itself (they were mostly held late in that year)
function _rlWikiDateOrCalendarYear(y, date) {
  return date ? _rlWikiYearBefore(y, date) : {
    start: new Date(`${y}-01-01`),
    end:   new Date(`${y}-12-31T23:59:59`),
    label: String(y),
  };
}

const RL_WIKI_SHOWS = {
  vmas: {
    first: 1984,   // the 1st MTV Video Music Awards
    short: 'VMAs',
    pages: y => [{ title: `${y}_MTV_Video_Music_Awards` }],
    ceremony: y => `${y} MTV Video Music Awards`,
    // The VMAs judge videos from roughly mid-June of the year before to
    // mid-June of the ceremony year, so: July to June.
    window: y => ({
      start: new Date(`${y - 1}-07-01`),
      end:   new Date(`${y}-06-30T23:59:59`),
      label: `July ${y - 1} to June ${y}`,
    }),
  },
  amas: {
    first: 1974,   // the 1st American Music Awards
    short: 'AMAs',
    // 2003 had two shows, one in January and one in November, and Wikipedia
    // splits them into two pages under a disambiguation title.
    pages: y => y === 2003
      ? [{ title: 'American_Music_Awards_of_2003_(January)', group: 'January' },
         { title: 'American_Music_Awards_of_2003_(November)', group: 'November' }]
      : [{ title: `American_Music_Awards_of_${y}` }],
    ceremony: y => `American Music Awards of ${y}`,
    // The AMAs have moved around — January for decades, then November, now May —
    // and each show covers about the year before it. So match the twelve months
    // leading up to the night itself, read off the page.
    window: _rlWikiYearBefore,
  },
  iheart: {
    first: 2014,   // the 1st iHeartRadio Music Awards
    short: 'iHeartRadio Music Awards',
    pages: y => [{ title: `${y}_iHeartRadio_Music_Awards` }],
    ceremony: y => `${y} iHeartRadio Music Awards`,
    // Held in spring (March to May), honouring the radio year before it
    window: _rlWikiYearBefore,
  },
  wma: {
    first: 1999,
    short: 'World Music Awards',
    // Held 1989–2014, on and off, and wound up after that. Wikipedia only has a
    // page for these years (1989–1998, 2000, 2002 and 2011–2013 have none, and
    // 2009's title points at the general article), so the year arrows step
    // between just these.
    years: [1999, 2001, 2003, 2004, 2005, 2006, 2007, 2008, 2010, 2014],
    pages: y => [{ title: `${y}_World_Music_Awards` }],
    ceremony: y => `${y} World Music Awards`,
    // No tables on these pages: the winners are bullet lists under headings
    lists: true,
    // A list with nobody in bold is an honours list (Legend Award), so
    // everyone on it won
    honours: true,
    // The awards went to the year's best sellers
    window: _rlWikiDateOrCalendarYear,
  },
  billboard: {
    first: 1990,
    short: 'Billboard Music Awards',
    // Held 1990–2007, then from 2011 on. Wikipedia has pages for these years
    // up to 2024; every year since is offered too, so a new show turns up on
    // its own once its page exists.
    years: [1990, 1991, 1999, 2001, 2002, 2003, 2004, 2005, 2006,
      ...Array.from({ length: Math.max(0, new Date().getFullYear() - 2010) }, (_, i) => 2011 + i)],
    pages: y => [{ title: `${y}_Billboard_Music_Awards` }],
    ceremony: y => `${y} Billboard Music Awards`,
    // Most years are tables; 2001 is bullet lists under headings
    lists: true,
    // The awards go to the year's Billboard chart leaders: December shows for
    // that year, May shows for the year before — the date on the page sorts it
    window: _rlWikiDateOrCalendarYear,
  },
  aria: {
    first: 1987,   // the 1st ARIA Music Awards
    short: 'ARIA Music Awards',
    pages: y => [{ title: `${y}_ARIA_Music_Awards` }],
    ceremony: y => `${y} ARIA Music Awards`,
    // 2011 on are tables; before that, nested bullet lists (1987–2008) and
    // results tables (2009–2010)
    lists: true,
    // Held in November for releases from about the year to mid-year, and
    // their pages give no date, so match the calendar year of the show
    window: _rlWikiDateOrCalendarYear,
  },
  juno: {
    first: 1971,   // the 1st Juno Awards (1970's were still the Gold Leaf Awards)
    short: 'Juno Awards',
    pages: y => [{ title: `Juno_Awards_of_${y}` }],
    ceremony: y => `Juno Awards of ${y}`,
    // 2013 on are tables; before that, `Winner:` paragraphs and bullet lists
    lists: true,
    // Held in spring for the year before; the date is on the page when it's
    // known, and the end of January stands in when it isn't
    window: _rlWikiYearBefore,
  },
  brit: {
    first: 1977,   // the first BRIT Awards, for the Queen's Silver Jubilee
    short: 'BRIT Awards',
    // A one-off in 1977, then every year from 1982
    years: [1977, ...Array.from({ length: Math.max(0, new Date().getFullYear() - 1981) }, (_, i) => 1982 + i)],
    pages: y => [{ title: `Brit_Awards_${y}` }],
    ceremony: y => `BRIT Awards ${y}`,
    lists: true,
    // Held in February or March for the year before
    window: _rlWikiYearBefore,
  },
};
// Bump the version whenever the parsing changes, so years saved under the old
// rules are read again
const RL_WIKI_CACHE_LS = 'dc_rl_wiki_cache_v6';  // parsed ceremonies, so a past year is fetched once, ever
const RL_WIKI_FRESH_MS = 86400000;                // this year's page can still change (winners land late), so refetch daily
try { ['dc_vma_cache_v1', 'dc_rl_wiki_cache_v1', 'dc_rl_wiki_cache_v2', 'dc_rl_wiki_cache_v3', 'dc_rl_wiki_cache_v4', 'dc_rl_wiki_cache_v5'].forEach(k => localStorage.removeItem(k)); } catch (e) {}   // caches this replaced

const _rlWikiCache = {};   // "show:year" → promise of the parsed ceremony, for this session

function _rlWikiStored() {
  try { const v = JSON.parse(localStorage.getItem(RL_WIKI_CACHE_LS) || '{}'); return v && typeof v === 'object' ? v : {}; }
  catch (e) { return {}; }
}
function _rlWikiStore(key, data) {
  const all = _rlWikiStored();
  all[key] = { at: Date.now(), data };
  try { localStorage.setItem(RL_WIKI_CACHE_LS, JSON.stringify(all)); } catch (e) { /* full or blocked: memory cache still works */ }
}

// The parsed ceremony for one show and year:
//   { found, year, url, date, categories: [{ name, nominees: [{ who, title, rest, won }] }] }
// `found: false` means Wikipedia has no page for it (not held, or not written
// up yet); `error: true` means we couldn't reach it, which isn't cached so the
// next visit tries again.
function _rlWikiFetchYear(showId, year) {
  const key = showId + ':' + year;
  if (_rlWikiCache[key]) return _rlWikiCache[key];

  const stored = _rlWikiStored()[key];
  if (stored && (year < tzNow().getFullYear() || Date.now() - stored.at < RL_WIKI_FRESH_MS)) {
    return (_rlWikiCache[key] = Promise.resolve(stored.data));
  }

  const pages = RL_WIKI_SHOWS[showId].pages(year);
  const p = Promise.all(pages.map(pg => _rlWikiFetchPage(pg.title, year, RL_WIKI_SHOWS[showId])))
    .then(parsed => {
      const got = parsed.map((r, i) => ({ ...r, group: pages[i].group })).filter(r => r.categories.length);
      // With two shows in one year, each category says which night it was
      const categories = got.flatMap(r => r.group
        ? r.categories.map(c => ({ ...c, name: `${c.name} (${r.group})` }))
        : r.categories);
      const data = {
        found: categories.length > 0, year, categories,
        hasPage: parsed.some(r => r.hasPage),   // a page, even one with no winners listed
        url: 'https://en.wikipedia.org/wiki/' + (got[0]?.title || pages[0].title),
        date: got[got.length - 1]?.date || null,   // the later show sets the listening window
      };
      if (data.found) _rlWikiStore(key, data);
      return data;
    })
    .catch(() => {
      delete _rlWikiCache[key];
      return { found: false, year, error: true };
    });
  _rlWikiCache[key] = p;
  return p;
}

// One Wikipedia page → { title, date, categories }. A missing page, or one that
// redirects somewhere without the year in its name (2024's AMAs weren't held,
// so that title just points at the general AMAs article), counts as no ceremony.
async function _rlWikiFetchPage(title, year, show) {
  const api = 'https://en.wikipedia.org/w/api.php?' + new URLSearchParams({
    action: 'parse', page: title, prop: 'text', format: 'json', formatversion: '2', redirects: '1', origin: '*',
  });
  // Wikipedia turns away a burst of requests (429) now and then; one short wait
  // and a second try gets through, and only then is it reported as a failure
  let r = await fetch(api);
  if (r.status === 429 || r.status >= 500) {
    await new Promise(res => setTimeout(res, 1500));
    r = await fetch(api);
  }
  if (!r.ok) throw new Error('wikipedia ' + r.status);
  const j = await r.json();
  if (!j || j.error || !j.parse || !String(j.parse.title || '').includes(String(year))) {
    return { title, date: null, categories: [], hasPage: false };
  }
  const doc = new DOMParser().parseFromString(j.parse.text || '', 'text/html');
  // The winners tables first; for shows whose older pages are laid out other
  // ways, results tables, then bullet lists
  let categories = _rlWikiParse(doc);
  if (!categories.length && show?.lists) categories = _rlWikiParseResultTables(doc);
  if (!categories.length && show?.lists) categories = _rlWikiParseLists(doc, show);
  if (!categories.length && show?.lists) categories = _rlWikiParse(doc, true);
  categories = _rlWikiTidy(categories);
  return { title: j.parse.title.replace(/ /g, '_'), date: _rlWikiDate(doc), categories, hasPage: true };
}

// Final touches on any page's results, whichever reader produced them:
//   who presented the award is dropped — `British Single of the Year
//     (presented by Simon Mayo)` is just British Single of the Year
//   a special award written `Global Success Award: Adele` names Adele as the
//     winner and the award as what she won
function _rlWikiTidy(categories) {
  const presenter = /\s*\((?:co-)?presented by [^)]*\)/gi;
  return categories.map(c => ({
    name: c.name.replace(presenter, '').trim(),
    nominees: c.nominees.map(n => {
      const who = n.who.replace(presenter, '').trim();
      const honour = !n.title && who.match(/^([^:]{3,60}(?:award|of the year|contribution[^:]*|producer[^:]*)):\s+(.+)$/i);
      return honour ? { ...n, who: honour[2].trim(), title: honour[1].trim() } : { ...n, who };
    }).filter(n => n.who),
  })).filter(c => c.name && c.nominees.length);
}

// The ceremony date from the page's infobox ("May 26, 2025"), as an ISO date
// string so it survives the localStorage round trip, or null
function _rlWikiDate(doc) {
  const row = [...doc.querySelectorAll('.infobox tr')].find(tr => /^\s*Date/i.test(tr.querySelector('th')?.textContent || ''));
  const cell = row?.querySelector('td');
  if (!cell) return null;
  const m = _rlWikiText(cell).match(/[A-Z][a-z]+ \d{1,2}, \d{4}/);
  const d = m ? new Date(m[0]) : null;
  if (!d || isNaN(d)) return null;
  // Built from the local date parts, not toISOString(), which can slip a day
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

// Plain text of a node with footnote markers ([1], [a]) left out
function _rlWikiText(node) {
  const c = node.cloneNode(true);
  c.querySelectorAll('sup, .reference, style').forEach(e => e.remove());
  return c.textContent.replace(/\s+/g, ' ').trim();
}

// Read every category out of the "Winners and nominees" section. Wikipedia lays
// the categories out three ways over the years, and all are handled:
//   list cells, newer: each <td> starts with its own <div> header, then a list
//   list cells, older: a <th> row of headers, then a <td> row of lists, by column
//     — in both, the winner is the bold top-level <li> and the other nominees
//     are a <ul> nested under it
//   one row per category (older AMAs): category | winner | nominees, with the
//     names in each cell split by <br>
function _rlWikiParse(doc, anywhere = false) {
  const head = doc.getElementById('Winners_and_nominees') || doc.querySelector('h2[id^="Winners"], h2[id^="Nominations"], h2[id^="Nominees"]');
  // With no such heading, `anywhere` (a last resort, for pages that file the
  // tables under "People", "Albums"… like the 2004 Junos) reads every table
  if (!head && !anywhere) return [];

  // Only tables between that heading and the next section count — later
  // sections (performances, presenters) use the same table class.
  const FOLLOWS = Node.DOCUMENT_POSITION_FOLLOWING;
  const nextH2 = head && [...doc.querySelectorAll('h2')].find(h => h !== head && (head.compareDocumentPosition(h) & FOLLOWS));
  const tables = [...doc.querySelectorAll('table.wikitable')].filter(t => !head ||
    ((head.compareDocumentPosition(t) & FOLLOWS) && (!nextH2 || (t.compareDocumentPosition(nextH2) & FOLLOWS))));

  const categories = [];
  for (const table of tables) {
    let headers = [];
    for (const tr of table.rows) {
      const cells = [...tr.children];
      const tds = cells.filter(c => c.tagName === 'TD');
      if (!tds.length) {   // a header row for the older list layout
        headers = cells.filter(c => c.tagName === 'TH').map(_rlWikiText);
        continue;
      }

      // One row per category: name, winner(s), nominees. A table whose first
      // column isn't the category (1987's "Other awards": Winner | Award |
      // Work) is a one-off honour in a different shape, so it's left out.
      if (tds.length >= 3 && !tds.some(td => td.querySelector(':scope > ul'))) {
        if (headers.length && !/categor|award|^$/i.test(headers[0])) continue;
        const name = _rlWikiText(tds[0]);
        const nominees = [
          ..._rlWikiSplitCell(tds[1]).map(el => _rlWikiEntry(el, true)),
          ..._rlWikiSplitCell(tds[2]).map(el => _rlWikiEntry(el, false)),
        ].filter(n => n.who);
        if (name && nominees.length) categories.push({ name, nominees });
        continue;
      }

      tds.forEach((td, col) => {
        const list = td.querySelector(':scope > ul');
        if (!list) return;
        const own = td.querySelector(':scope > div');
        const name = own ? _rlWikiText(own) : (headers[col] || '');
        if (!name) return;

        const nominees = [];
        for (const li of list.querySelectorAll(':scope > li')) {
          const top = li.cloneNode(true);
          top.querySelectorAll(':scope > ul').forEach(e => e.remove());
          nominees.push(_rlWikiEntry(top, !!top.querySelector('b')));
          for (const sub of li.querySelectorAll(':scope > ul > li')) nominees.push(_rlWikiEntry(sub, false));
        }
        const kept = nominees.filter(n => n.who);
        if (kept.length) categories.push({ name, nominees: kept });
      });
    }
  }
  return categories;
}

// Pages with no winners tables (the World Music Awards, older ARIAs) list the
// awards as bullets under headings instead, written a few ways over the years:
//   `Category: Winner`, maybe with `Nominees: a, b` or `Runners-up: a, b and c`
//     nested under it (WMA 1999, 2003, 2006)
//   a heading per category, then its nominees with the winner in bold (WMA
//     2008, 2010) — the "heading" can also be a small <dt> label (ARIA 2007)
//   the bold winner with the other nominees nested under it (ARIA 2007)
//   a bullet per category with the winner and nominees nested under it
//     (ARIA 1987–2006: `Album of the Year` → **Tina Arena – Don't Ask** → …)
//   a heading with a plain list of names and nobody in bold — for a show that
//     says so (`honours`) or an honour by its name (Hall of Fame, Legend
//     Award), a list of honourees, so everyone on it won; otherwise it just
//     means the page never marked the winner
//   a heading per category, a `Winner: Luba` paragraph, then an "Other
//     nominees" list (Junos 1971–2012). Pages written this way also carry
//     `Category: Name` bullets in their intro about late changes to the
//     nominees, which aren't results, so those are dropped when this shape is
//     found.
// Sections about the show rather than the awards (performers, references, the
// "multiple winners" tallies, the broadcast and events schedule…) are skipped.
const RL_WIKI_SKIP_SECTIONS = /^(performers?|performances|presenters|hosts|references|notes|external links|see also|international telecasts?|broadcast|delays|records|charity|official sponsor|top award winners|(primary |main )?ceremon|background|multiple (winners|nominations|wins)|most (wins|nominations)|judging|presentations|events|bidding|(saturday |sunday )?gala|sunday|saturday)/i;
const RL_WIKI_HONOURS = /hall of fame|legend|lifetime achievement|icon award/i;

function _rlWikiParseLists(doc, show) {
  const categories = [];
  let h2 = '', h3 = '', label = '';
  let pending = null;   // the category a `Winner:` paragraph just opened, waiting for its nominees list
  const nodes = [...doc.querySelectorAll('h2, h3, h4, dt, p, ul')];
  // An entry plus everything nested under it, as nominees
  const withNested = (li, won) => {
    const top = li.cloneNode(true);
    top.querySelectorAll(':scope > ul').forEach(e => e.remove());
    return [
      _rlWikiListEntry(top, _rlWikiText(top), won),
      ...[...li.querySelectorAll(':scope > ul > li')].map(sub => _rlWikiEntry(sub, false)),
    ];
  };
  for (const node of nodes) {
    if (node.tagName === 'H2') { h2 = _rlWikiText(node); h3 = ''; label = ''; pending = null; continue; }
    if (node.tagName === 'H3') { h3 = _rlWikiText(node); label = ''; pending = null; continue; }
    if (node.tagName === 'H4' || node.tagName === 'DT') {
      if (!node.closest('table, .navbox, .infobox')) { label = _rlWikiText(node); pending = null; }
      continue;
    }
    // A top-level list only: nested ones are read with their parent, and
    // lists in tables, infoboxes and navboxes aren't award lists
    if (!h2 || node.closest('li, table, .navbox, .reflist, .infobox')) continue;
    if (RL_WIKI_SKIP_SECTIONS.test(h2) || RL_WIKI_SKIP_SECTIONS.test(h3)) continue;

    // `Winner: Luba` (Junos): opens the heading's category with its winner. A
    // tie is `Winner (tie):` with nothing after it, and the winners in the
    // next list instead.
    if (node.tagName === 'P') {
      const text = _rlWikiText(node);
      const m = text.match(/^winners?(\s*\([^)]*\))?\s*[:：]\s*(.*)$/i);
      if (!m) continue;
      const name = label || h3 || h2;
      if (!m[2].trim()) {
        pending = { name, nominees: [], winnerPara: true, listWins: true };
        categories.push(pending);
        continue;
      }
      const el = node.cloneNode(true);
      // Drop the bold "Winner:" label, so only the winner's own markup is left
      const tag = [...el.querySelectorAll('b')].find(b => /^winners?(\s*\([^)]*\))?\s*[:：]?$/i.test(_rlWikiText(b)));
      if (tag) tag.remove();
      const winner = _rlWikiListEntry(el, m[2].trim(), true);
      if (!winner.who) continue;
      pending = { name, nominees: [winner], winnerPara: true };
      categories.push(pending);
      continue;
    }
    // …and the list after it fills that category in: the tied winners, or
    // the "Other nominees"
    if (pending) {
      for (const li of node.querySelectorAll(':scope > li')) {
        const top = li.cloneNode(true);
        top.querySelectorAll(':scope > ul').forEach(e => e.remove());
        const entry = _rlWikiListEntry(top, _rlWikiText(top), !!pending.listWins);
        if (entry.who && entry.who.length <= 90) pending.nominees.push(entry);
      }
      // After a tie's winners, the next list is still this category's nominees
      if (pending.listWins) pending.listWins = false;
      else pending = null;
      continue;
    }

    const bare = [];   // names with no "Category:" in front, for the heading's category
    for (const li of node.querySelectorAll(':scope > li')) {
      const top = li.cloneNode(true);
      top.querySelectorAll(':scope > ul').forEach(e => e.remove());
      const text = _rlWikiText(top);
      const subs = [...li.querySelectorAll(':scope > ul > li')];
      const bold = !!top.querySelector('b');

      // A bullet that's only a category name (which can have its own dash:
      // `Breakthrough Artist – Album`), with the bold winner nested under it
      // (ARIA 1987–2006)
      if (!bold && subs.length && !/[:：]/.test(text) &&
          subs.some(sub => sub.querySelector(':scope > b'))) {
        const nominees = subs.flatMap(sub => withNested(sub, !!sub.querySelector(':scope > b')));
        const kept = nominees.filter(n => n.who && n.who.length <= 90);
        if (kept.length) categories.push({ name: text, nominees: kept });
        continue;
      }

      // Full-width colons turn up too (`Chinese Artist ：Nicholas Tse`). A colon
      // after a dash belongs to the title (`Hilltop Hoods – The Hard Road:
      // Restrung`), not a category label.
      const labelled = /^[^:：]*\s[–—−-]\s/.test(text) ? null : text.match(/^(.{3,120}?)\s*[:：]\s*(.+)$/);
      if (!labelled) {
        // A bold winner can carry the other nominees nested under it (ARIA 2007)
        if (bold && subs.length) bare.push(...withNested(li, true));
        else bare.push(_rlWikiListEntry(top, text, bold));
        continue;
      }
      // `Natalie Imbruglia: recognises her international chart success…` — a
      // special award written up as a sentence: the name before the colon is
      // who won it, and the heading above names the award
      if (labelled[2].length > 90) {
        bare.push({ who: labelled[1].trim(), title: '', rest: '', won: true });
        continue;
      }

      const winnerEl = doc.createElement('span');
      winnerEl.textContent = labelled[2];
      const nominees = [_rlWikiListEntry(winnerEl, labelled[2], true)];
      // "Nominees: Puff Daddy, Usher" / "Runners-up: Daddy Yankee, RBD, Mana and Juanes".
      // Only lines labelled like that: other nested lines are commentary
      // (2007 quotes the presenters' speeches under the Legend Awards).
      for (const sub of li.querySelectorAll(':scope > ul > li')) {
        const line = _rlWikiText(sub);
        const label = line.match(/^(other\s+)?(nominees|runners?[- ]up)\s*:\s*/i);
        if (!label) continue;
        for (const name of line.slice(label[0].length).split(/,\s*|\s+and\s+/)) {
          if (name.trim()) nominees.push({ who: name.trim(), title: '', rest: '', won: false });
        }
      }
      categories.push({ name: labelled[1].trim(), nominees: nominees.filter(n => n.who), labelled: true });
    }

    // A plain list straight under "Winners" or "Nominees" is a roll call of
    // everyone who won something (2003), repeating the real categories below it
    const heading = label || h3 || h2;
    label = '';   // a <dt> label names just the one list after it
    // A whole sentence isn't a name: some special awards are written up as a
    // line of prose ("recognises her international chart success…")
    const kept = bare.filter(n => n.who && n.who.length <= 90);
    if (kept.length && !/^(winners|nominees|nominees (and|&) winners)$/i.test(heading)) {
      if ((show?.honours || RL_WIKI_HONOURS.test(heading)) && !kept.some(n => n.won)) {
        kept.forEach(n => { n.won = true; });   // an honours list
      }
      categories.push({ name: heading, nominees: kept });
    }
  }
  // On a page laid out as `Winner:` paragraphs, the `Category: Name` bullets
  // are the intro's notes on late changes to the nominees, not results
  const byPara = categories.some(c => c.winnerPara);
  return categories
    .filter(c => !(byPara && c.labelled))
    .map(({ name, nominees }) => ({ name, nominees }));
}

// Results tables (ARIA 2009–2010): a header row per category, then a row per
// nominee — artist, work, and a Result cell reading "Won" or "Nominated":
//   ┌ Album of the Year ─────────────────────────┐
//   │ Artist        │ Album              │ Result │
//   │ Empire of the Sun │ Walking on a Dream │ Won │
function _rlWikiParseResultTables(doc) {
  const categories = [];
  for (const table of doc.querySelectorAll('table.wikitable')) {
    if (![...table.querySelectorAll('th')].some(th => /^result/i.test(_rlWikiText(th)))) continue;
    let name = '', cur = null;
    for (const tr of table.rows) {
      const cells = [...tr.children];
      const tds = cells.filter(c => c.tagName === 'TD');
      if (!tds.length) {
        // One header cell across the row is a category; a row of several
        // (Artist | Album | Result) is the column headings
        const ths = cells.filter(c => c.tagName === 'TH');
        if (ths.length === 1) { const t = _rlWikiText(ths[0]); if (t) { name = t; cur = null; } }
        continue;
      }
      if (tds.length < 2 || !name) continue;
      const result = _rlWikiText(tds[tds.length - 1]);
      if (!/^(won|winner|nominated|nominee)/i.test(result)) continue;
      const workCell = tds.length > 2 ? tds[1] : null;
      const i = workCell?.querySelector('i');
      const title = workCell ? (i ? _rlWikiText(i) : _rlWikiText(workCell).replace(/^["“]|["”]$/g, '').trim()) : '';
      if (!cur) { cur = { name, nominees: [] }; categories.push(cur); }
      cur.nominees.push({ who: _rlWikiText(tds[0]), title, rest: '', won: /^(won|winner)/i.test(result) });
    }
  }
  return categories.filter(c => c.nominees.some(n => n.who));
}

// One name in a bullet list. Like a table entry, plus the "by" form these
// pages use for songs and albums: `"Sexy Chick" by David Guetta feat. Akon`,
// `The Fame by Lady Gaga` (the title in quotes or italics, so a band called
// "Stand by Me" isn't split).
function _rlWikiListEntry(el, text, won) {
  const by = text.match(/^(.+?)\s+by\s+(.+)$/);
  if (by) {
    const i = el.querySelector('i');
    const quoted = by[1].match(/^["“](.+)["”]$/);
    if (quoted || (i && _rlWikiText(i) === by[1])) {
      return { who: by[2].trim(), title: (quoted ? quoted[1] : by[1]).trim(), rest: '', won };
    }
  }
  return _rlWikiEntry(el, won);
}

// A table cell holding several names split by <br> → one element per name
function _rlWikiSplitCell(td) {
  return td.innerHTML.split(/<br\s*\/?>/i).map(html => {
    const el = td.ownerDocument.createElement('span');
    el.innerHTML = html;
    return el;
  }).filter(el => el.textContent.trim());
}

// One nominee line. Usually the credited artists come first and the work after
// a dash — `Lady Gaga and Bruno Mars – "Die with a Smile"` — but the older AMA
// tables put the work first — `Hangin' Tough – New Kids on the Block` — so a
// first half that's all quotes or italics is read as the title. Anything left
// over (a director, "starring …") is kept so its artists can still be matched.
function _rlWikiEntry(el, won) {
  const text = _rlWikiText(el);
  // Dashes come as en, em, hyphen, or now and then a minus sign (2016's AMAs),
  // and once in a while straight after a closing quote or bracket with no space
  // (`"God's Plan"– Drake`, `"Call Me Maybe"- Carly Rae Jepsen`,
  // `Megan Thee Stallion (featuring Beyoncé)– "Savage"`) or straight before an
  // opening quote (`Tony Christie –"(Is This the Way to) Amarillo"`)
  const parts = text.split(/\s[–—−-]\s|(?<=["”)])[–—−-]\s|\s[–—−](?=["“])/);
  const i = el.querySelector('i');
  const italic = i ? _rlWikiText(i) : '';
  const quotes = s => (s.match(/["“”]/g) || []).length;
  // Strip the outer quotes — but only a closing quote that's actually unpaired,
  // so a nickname at the end (`Luis Angel "El Flaco"`) keeps its own
  const unquote = s => {
    s = s.trim().replace(/^["“]\s*/, '');
    return (quotes(s) % 2 ? s.replace(/\s*["”]$/, '') : s).trim();
  };
  // Title first when the first half is all quotes or italics, or opens a quote
  // that only closes at the very end (`"Work – Rihanna featuring Drake"`) —
  // but not a nickname like `"Weird Al" Yankovic`, whose quote closes early.
  // The iHeartRadio pages add two twists: a song followed by a note in
  // brackets (`"Savage" (Remix)`, a cover's `"Black Dog" (Led Zeppelin)`),
  // which stays part of the title so the original artist isn't credited, and a
  // label in front (`Pop: 25 – Adele` in Album of the Year per genre).
  if (parts.length > 1) {
    // The whole first half is tried before the label is peeled off, so a title
    // with its own colon (`Selena Gomez: My Mind & Me – Selena Gomez`) stays whole
    const lead = parts[0].match(/^([^:"“]{1,30}):\s+(.+)$/);
    const tries = [{ head: parts[0], label: '' }];
    if (lead) tries.push({ head: lead[2], label: ` (${lead[1]})` });
    const who = unquote(parts.slice(1).join(' – '));
    for (const { head, label } of tries) {
      const bracketed = head.match(/^["“]([^"”]+)["”]\s*(\(.*\))$/);
      if (bracketed) return { who, title: `${bracketed[1].trim()} ${bracketed[2]}${label}`, rest: '', won };
      if (/^["“].*["”]$/.test(head) || /^["“][^"”]*$/.test(head) || (italic && italic === head)) {
        return { who, title: unquote(head) + label, rest: '', won };
      }
    }
  }
  // The 1970s AMA tables use a comma instead of a dash, before an album in
  // italics or a song in quotes: `Charlie Rich, Behind Closed Doors`,
  // `Merle Haggard, "If We Make It Through December"`. The title has to come
  // off, or its words ("Make") get matched as artists.
  if (parts.length === 1) {
    // The Junos go the other way, title first: `Anne Murray Duets: Friends &
    // Legends, Anne Murray` (album in italics), `"Hello", Martha Wainwright`
    const tq = text.match(/^["“]([^"”]+)["”]\s*,\s*(.+)$/);
    if (tq) return { who: tq[2].trim(), title: tq[1].trim(), rest: '', won };
    if (italic && text.startsWith(italic) && /^\s*,\s*\S/.test(text.slice(italic.length))) {
      return { who: text.slice(italic.length).replace(/^\s*,\s*/, '').trim(), title: italic, rest: '', won };
    }
    const sq = text.match(/^(.+?),\s*["“]([^"”]+)["”]\s*$/);
    if (sq) return { who: sq[1].trim(), title: sq[2].trim(), rest: '', won };
    // Billboard puts the song after the credit with no dash: in brackets —
    // `Camila Cabello featuring Young Thug ("Havana")` — or straight after a
    // bracketed feature — `Ellie Goulding x Diplo (featuring Swae Lee) "Close to Me"`.
    // Only those two shapes, so a nickname at the end (`Luis Angel "El Flaco"`)
    // isn't mistaken for a song.
    const bq = text.match(/^(.+?)\s*\(["“]([^"”]+)["”]\)\s*$/) || text.match(/^(.+\))\s*["“]([^"”]+)["”]\s*$/);
    if (bq) return { who: bq[1].trim(), title: bq[2].trim(), rest: '', won };
    if (italic && text !== italic && text.endsWith(italic)) {
      return { who: text.slice(0, -italic.length).replace(/[\s,]+$/, ''), title: italic, rest: '', won };
    }
  }

  const who = parts.shift().trim();
  const after = parts.join(' – ').trim();
  // Songs are in quotes, albums and films in italics
  let title = '';
  const q = after.match(/"([^"]+)"/) || after.match(/“([^”]+)”/);
  if (q) title = q[1].trim();
  else if (after) title = italic || after.replace(/\s*\(.*$/, '').trim();
  const rest = title ? after.replace(q ? q[0] : title, '').trim() : after;
  return { who, title, rest, won };
}

// Same folding as the Grammy proxy: accents and punctuation away, so
// "Beyoncé", "BEYONCE" and "Beyonce" all compare equal.
function _rlWikiNorm(s) {
  return (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// Which of the user's artists a nominee line credits. The credit is split into
// the separate artists it names — at "and", "featuring", "&", commas, brackets,
// "for" and the like — and each one has to match one of the user's artists by
// its whole name. So "Rosé and Bruno Mars" finds both Rosé and Bruno Mars, but
// an artist called just "Selena" or "Max" doesn't pick up Selena Gomez's or
// Max Martin's nominations. The whole credit is tried too, so a name with its
// own "and" or comma (Earth, Wind & Fire; Tyler, the Creator) still matches,
// and " x " collaborations are split as a second step so Lil Nas X stays whole.
// Quote marks split too, so `Taylor Swift's "Question...?"` (iHeartRadio's
// sample award) finds Taylor Swift. A leading "The" is ignored on both sides.
// The work's own title is left out:
// a song called "Taylor Swift" isn't a nomination for her.
const RL_WIKI_CREDIT_SPLIT = /\s*(?:,|;|&|\+|\/|:|\(|\)|\[|\]|["“”]|\band\b|\bfeaturing\b|\bfeat\b\.?|\bft\b\.?|\bwith\b|\bvs\b\.?|\bversus\b|\bstarring\b|\bpresents\b|\bfor\b|\bdirectors?\b)\s*/i;

// The lookup key for an artist name: folded, with any leading "The" dropped
function _rlWikiKey(s) {
  return _rlWikiNorm(s).replace(/^the /, '');
}

function _rlWikiMatch(nominee, byKey) {
  const hits = new Set();
  for (const part of [nominee.who, nominee.rest]) {
    if (!part) continue;
    const clean = part.replace(/['’]s\b/g, '');   // "Taylor Swift's" → "Taylor Swift"
    for (const piece of [clean, ...clean.split(RL_WIKI_CREDIT_SPLIT)]) {
      for (const name of [piece, ...piece.split(/\s+x\s+/i)]) {
        const a = byKey.get(_rlWikiKey(name));
        if (a) hits.add(a);
      }
    }
  }
  return [...hits];
}

async function _loadRealLifeWiki(showId, year) {
  const show = RL_WIKI_SHOWS[showId];
  const contentEl = document.getElementById('realLifeContent');
  const statusEl  = document.getElementById('realLifeStatus');
  const token = ++_realLifeLoadToken;
  contentEl.innerHTML = '';

  if (!allPlays.length) {
    statusEl.textContent = 'Load your music data first.';
    return;
  }

  const ceremony = show.ceremony(year);
  statusEl.textContent = `Loading the ${ceremony}…`;
  const data = await _rlWikiFetchYear(showId, year);
  if (token !== _realLifeLoadToken) return;   // the user moved on
  statusEl.textContent = '';

  const credit = `<div class="awards-reallife-credit">Winners and nominees from <a href="${esc(data.url || 'https://en.wikipedia.org/')}" target="_blank" rel="noopener">Wikipedia</a></div>`;

  if (!data.found) {
    const msg = data.error
      ? `Couldn't reach Wikipedia for the ${esc(ceremony)}. Try again in a moment.`
      : year >= tzNow().getFullYear()
        ? `The ${year} ${show.short} haven't happened yet, or aren't written up yet. Check back after the ceremony.`
        : data.hasPage
          ? `Wikipedia's page on the ${esc(ceremony)} doesn't list the winners.`
          : `Wikipedia has no page for the ${esc(ceremony)}, so it may not have been held.`;
    contentEl.innerHTML = `<div class="awards-empty">${msg}</div>` + credit;
    return;
  }

  // Match against the stretch of listening this ceremony judges. Like the
  // Grammys tab, data that doesn't reach back that far falls back to the
  // whole library.
  const win = show.window(year, data.date ? new Date(data.date + 'T23:59:59') : null);
  const inWindow = allPlays.filter(p => p.date >= win.start && p.date <= win.end);
  const pool = inWindow.length ? inWindow : allPlays;
  const { artists } = _awardsCountMaps(pool);
  const byKey = new Map();   // _rlWikiKey(name) → the user's most-played artist by that name
  for (const a of Object.values(artists)) {
    const k = _rlWikiKey(a.artist);
    if (k.length < 2) continue;
    const had = byKey.get(k);
    if (!had || had.plays < a.plays) byKey.set(k, a);
  }

  // Group the user's artists' nominations by artist, in listening order
  const mine = new Map();   // played artist → { played, rows: [{ category, nominee }] }
  const yours = new Set();  // "catIdx:nomIdx" of every line that credits one of them
  data.categories.forEach((cat, ci) => cat.nominees.forEach((nom, ni) => {
    for (const a of _rlWikiMatch(nom, byKey)) {
      yours.add(ci + ':' + ni);
      if (!mine.has(a)) mine.set(a, { played: a, rows: [] });
      mine.get(a).rows.push({ category: cat.name, nominee: nom });
    }
  }));
  const results = [...mine.values()].sort((a, b) => b.played.plays - a.played.plays);

  // Before the show, the page lists nominees with nobody in bold yet
  const decided = data.categories.some(c => c.nominees.some(n => n.won));
  const windowLabel = inWindow.length ? `matched against your plays from ${win.label}` : 'matched against your whole library';
  const headline = `<div class="awards-reallife-head">
      <div class="awards-reallife-ceremony">${esc(ceremony)}</div>
      <div class="awards-reallife-sub">${data.categories.length} categories · ${windowLabel}${decided ? '' : ' · winners not announced yet'}</div>
    </div>`;

  let tally, cards = '';
  const artQueue = [];
  if (!results.length) {
    tally = `<div class="awards-empty">${esc(t('awx_rl_none_played', { c: ceremony }))}</div>`;
  } else {
    const wins = results.reduce((n, r) => n + r.rows.filter(x => x.nominee.won).length, 0);
    const noms = results.reduce((n, r) => n + r.rows.length, 0);
    tally = _rlTallyHtml(noms, wins);

    // Same card as the Grammys tab: portrait down the side, one row per nomination
    cards = results.map((r, ri) => {
      const rows = r.rows.slice().sort((a, b) => (b.nominee.won ? 1 : 0) - (a.nominee.won ? 1 : 0));
      const artistId = `rlw-art-${ri}`;
      artQueue.push({ imgId: artistId, type: 'artist', item: {
        name: r.played.artist, artist: r.played.artist,
        prefKey: 'artist:' + r.played.artist.toLowerCase(),
      } });
      const plays = r.played.plays;
      return `<div class="dc-card-inset awards-reallife-card${_rlCardCls(rows.length)}">
        ${_rlArtHtml(artistId, r.played.artist, 'awards-reallife-portrait')}
        <div class="awards-reallife-body">
          <div class="awards-reallife-artist">
            <span>${esc(r.played.artist)}</span>
            <span class="awards-reallife-alltime">${esc(tCount('plays', plays))}${inWindow.length ? esc(t('awx_rl_that_season')) : ''}</span>
          </div>
          ${rows.map((x, xi) => {
            const workId = `rlw-work-${ri}-${xi}`;
            const art = _rlWikiWorkArt(x.category, x.nominee, r.played);
            if (art) artQueue.push({ imgId: workId, type: art.type, item: art.item });
            const work = x.nominee.title || '';
            // On a shared credit ("Lady Gaga and Bruno Mars") say who it was with
            const withWho = _rlWikiNorm(x.nominee.who) !== _rlWikiNorm(r.played.artist) ? x.nominee.who : '';
            return `<div class="awards-reallife-row">
              ${art ? _rlArtHtml(workId, work, 'awards-reallife-thumb') : '<div class="awards-reallife-thumb is-blank"></div>'}
              <span class="awards-reallife-badge ${x.nominee.won ? 'won' : 'nom'}">${x.nominee.won ? '🏆 ' + esc(t('awx_rl_won')) : '🎗 ' + esc(t('awx_rl_nominated'))}</span>
              <span class="awards-reallife-rowtext">
                <span class="awards-reallife-cat">${esc(_rlCatCase(x.category))}</span>
                ${work || withWho ? `<span class="awards-reallife-work">${esc(work)}${withWho ? `${work ? ' · ' : ''}${esc(withWho)}` : ''}</span>` : ''}
              </span>
            </div>`;
          }).join('')}
        </div>
      </div>`;
    }).join('');
  }

  // Then the whole ceremony, every category, with the user's artists marked
  const all = `<div class="rlw-all">
      <div class="rlw-all-head">${esc(t('awx_rl_every_cat'))}</div>
      <div class="rlw-cat-grid">${data.categories.map((cat, ci) => `
        <div class="rlw-cat">
          <div class="rlw-cat-name">${esc(cat.name)}</div>
          <ul class="rlw-cat-list">${cat.nominees.map((n, ni) => `
            <li class="${n.won ? 'is-won' : ''}${yours.has(ci + ':' + ni) ? ' is-yours' : ''}">
              <span class="rlw-cat-mark" aria-hidden="true">${n.won ? '🏆' : ''}</span>
              <span class="rlw-cat-text"><span class="rlw-cat-who">${esc(n.who)}</span>${n.title ? ` <span class="rlw-cat-title">${esc(n.title)}</span>` : ''}</span>
            </li>`).join('')}
          </ul>
        </div>`).join('')}
      </div>
      <div class="rlw-all-key"><span class="rlw-key-dot" aria-hidden="true"></span> An artist you played</div>
    </div>`;

  contentEl.innerHTML = headline + tally + cards + all + credit;
  _realLifeLoadArt(artQueue, token);
}

// A nomination's thumbnail: the album cover for album categories, the song's
// cover for everything else. Looked up under the user's own spelling of the
// artist when the credit is theirs, so a picture they pinned on their charts
// shows up here too.
function _rlWikiWorkArt(category, nominee, played) {
  if (!nominee.title) return null;
  const mainCredit = nominee.who.split(/\s+(?:and|&|featuring|feat\.|ft\.|with|x)\s+|,\s*/i)[0].trim();
  const artist = _rlWikiNorm(nominee.who).startsWith(_rlWikiNorm(played.artist)) ? played.artist : (mainCredit || played.artist);
  const key = artist.toLowerCase() + '|||' + nominee.title.toLowerCase();
  return /\balbum\b|soundtrack/i.test(category)
    ? { type: 'album', item: { name: nominee.title, album: nominee.title, artist, prefKey: 'album:' + key } }
    : { type: 'song',  item: { name: nominee.title, title: nominee.title, artist, prefKey: 'song:' + key } };
}

// ── Ceremony ──────────────────────────────────────────────────────────────────
// One category per slide: the nominees with their artwork, a sealed envelope, and
// — only once the envelope is opened — the winner, with a 30-second preview of the
// track playing underneath. The last slide is a roll call of every winner.

let _ceremonyYear = null;
let _ceremonyData = null;            // the ballot on stage: the user's own year, or a shared copy
let _ceremonyShared = null;          // { id, name } while watching someone else's shared link
let _ceremonyCats = [];
let _ceremonyIdx  = 0;               // -1 = the stats & records intro, cats.length = the roll call
let _ceremonySummary = null;         // _awardsSummary() for the opening slide, or null for none
let _ceremonySummaryFinal = null;    // the same with tonight's results in, for the roll call
let _ceremonyRevealed = new Set();   // category ids already opened this session
let _ceremonyRenderSeq = 0;          // bumped per render so stale image loads can't land
let _ceremonyAudio = null;           // one <audio>, reused by every slide
let _ceremonyAudioToken = 0;         // guards async preview lookups against fast nav
let _ceremonyFadeTimer = null;
let _ceremonySound = localStorage.getItem('dc_ceremony_sound') !== 'off';
let _ceremonyKeyHandler = null;
const _ceremonyPreviewCache = {};    // "type:artist|||name" → ranked [{url,label}]
let _cerTakeIdx = 0;                 // which take the winner panel is on
let _cerTakeCtx = null;              // { item, type } behind that panel, for "wrong track?"

// Nominee showcase: walks the nominees one at a time with a clip of each, before
// anyone touches the envelope.
let _cerShowIdx   = -1;              // nominee being showcased, -1 = not running
let _cerShowTimer = null;
let _cerShowToken = 0;               // cancels a step whose async work outlived it
const CER_SHOW_MS        = 15000;    // seconds per nominee, with sound
const CER_SHOW_SILENT_MS = 6000;     // …and without

// The categories that make it on stage: switched on, and with something to show.
function _ceremonyCatsFor(data) {
  return AWARD_CATEGORIES.filter(c => {
    const cd = data.categories[c.id];
    return cd?.enabled && (cd.nominees?.length > 0 || cd.winner);
  });
}

async function startAwardsCeremony() {
  const year = _awardsYear;
  const data = _awardsYearData[year];
  if (!data) return;
  _ceremonyShared = null;
  // The opening slide's all-time records need every year's ballot. The tab has
  // usually loaded them already for its own summary, so this is normally instant.
  await _awardsEnsureAllYearsLoaded();
  _ceremonyOpen(data, year, _ceremonyCatsFor(data),
    _awardsSummary(year, { spoilerFree: true }), _awardsSummary(year));
}

// Everything below reads the ballot from _ceremonyData, so the same stage plays
// the user's own year and a shared copy loaded from a link.
function _ceremonyOpen(data, year, cats, summary, finalSummary) {
  _ceremonyData = data;
  _ceremonyYear = year;
  _ceremonyCats = cats;
  _ceremonySummary      = _awardsSummaryOk(summary) ? summary : null;
  _ceremonySummaryFinal = _awardsSummaryOk(finalSummary) ? finalSummary : null;
  if (!_ceremonyCats.length) return;
  _ceremonyIdx = _ceremonyFirstIdx();
  _ceremonyRevealed = new Set();
  document.getElementById('awardsCeremonyOverlay').style.display = 'flex';
  document.body.style.overflow = 'hidden';
  ceremonyToggleDrawer(false);
  _ceremonyPaintSoundBtn();
  _ceremonyDrawSidebar(data);
  _ceremonyRender();

  // ← → walk the ceremony, space/enter opens the envelope, esc leaves
  _ceremonyKeyHandler = e => {
    if (document.getElementById('awardsCeremonyOverlay')?.style.display === 'none') return;
    const showing = _cerShowIdx >= 0;
    const drawer = document.getElementById('awardsCeremonyModal')?.classList.contains('is-drawer-open');
    if (e.key === 'Escape')     { e.preventDefault(); drawer ? ceremonyToggleDrawer(false) : showing ? cerShowStop() : closeCeremony(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); showing ? cerShowNext() : ceremonyNav(1); }
    else if (e.key === 'ArrowLeft')  { e.preventDefault(); showing ? cerShowPrev() : ceremonyNav(-1); }
    else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); ceremonyReveal(); }
  };
  document.addEventListener('keydown', _ceremonyKeyHandler);
}

function closeCeremony() {
  // A shared link has no app of its own behind it — leaving the ceremony takes
  // the guest to the front page, which is also the invitation to make their own.
  if (_ceremonyShared) { location.href = location.pathname; return; }
  document.getElementById('awardsCeremonyOverlay').style.display = 'none';
  document.body.style.overflow = '';
  cerShowStop(true);
  _ceremonyStopAudio();
  if (_ceremonyKeyHandler) { document.removeEventListener('keydown', _ceremonyKeyHandler); _ceremonyKeyHandler = null; }
}

// ☰ Categories: the category list slides in over the stage (full-screen
// ceremony, phase 9 part 5 step 7). force = true / false sets it.
function ceremonyToggleDrawer(force) {
  const modal = document.getElementById('awardsCeremonyModal');
  if (!modal) return;
  const open = typeof force === 'boolean' ? force : !modal.classList.contains('is-drawer-open');
  modal.classList.toggle('is-drawer-open', open);
  document.getElementById('ceremonyCatsBtn')?.setAttribute('aria-expanded', String(open));
}

function ceremonyOverlayClick(e) {
  // The ceremony fills the screen, so there is no backdrop left to click; a
  // click on the stage outside the open drawer just closes the drawer.
  const modal = document.getElementById('awardsCeremonyModal');
  if (modal?.classList.contains('is-drawer-open') && !e.target.closest('#ceremonySidebar, #ceremonyCatsBtn')) ceremonyToggleDrawer(false);
}

function _ceremonyIsFinale() { return _ceremonyIdx >= _ceremonyCats.length; }
function _ceremonyIsIntro()  { return _ceremonyIdx < 0; }
// The stats slide opens the show when there is one; otherwise it starts on the first category
function _ceremonyFirstIdx() { return _ceremonySummary ? -1 : 0; }

// "2025 My Grammys" for your own; a shared copy is someone else's, so it carries
// their name when they set one.
function _ceremonyTitle() {
  if (!_ceremonyShared) return t('awx_cer_title', { y: _ceremonyYear });
  return _ceremonyShared.name ? t('awx_cer_title_named', { name: _ceremonyShared.name, y: _ceremonyYear }) : t('awx_cer_title_shared', { y: _ceremonyYear });
}

// A shared copy may come from a newer build with a category this one does not
// know yet, so the label saved alongside it is the fallback.
function _ceremonyCatName(cat) {
  const key = 'awards_cat_' + cat.id;
  const name = t(key);
  return name === key ? (cat.label || cat.id) : name;
}

function _ceremonyDrawSidebar(data) {
  document.getElementById('ceremonySidebar').innerHTML =
    `<div class="ceremony-sidebar-title">${esc(_ceremonyTitle())}</div>` +
    (_ceremonySummary
      ? `<div class="ceremony-sidebar-row ceremony-sidebar-intro${_ceremonyIsIntro() ? ' active' : ''}" data-idx="-1" onclick="ceremonyGoTo(-1)">
          <span class="ceremony-sidebar-dot">📊</span> ${esc(t('awx_title'))}
        </div>`
      : '') +
    _ceremonyCats.map((cat, i) => {
      const hasWinner = !!data.categories[cat.id]?.winner;
      // The trophy only appears once the envelope has actually been opened —
      // the sidebar shouldn't spoil a category the user hasn't reached yet.
      const opened = hasWinner && _ceremonyRevealed.has(cat.id);
      return `<div class="ceremony-sidebar-row${i === _ceremonyIdx ? ' active' : ''}${opened ? ' done' : ''}" data-idx="${i}" onclick="ceremonyGoTo(${i})">
        <span class="ceremony-sidebar-dot">${opened ? '🏆' : (hasWinner ? '✉' : '○')}</span> ${esc(_ceremonyCatName(cat))}
      </div>`;
    }).join('') +
    `<div class="ceremony-sidebar-row ceremony-sidebar-finale${_ceremonyIsFinale() ? ' active' : ''}" data-idx="${_ceremonyCats.length}" onclick="ceremonyGoTo(${_ceremonyCats.length})">
      <span class="ceremony-sidebar-dot">🎬</span> ${esc(t('awx_cer_all_winners'))}
    </div>`;
  _ceremonyPaintDots();
}

// Progress dots in the top bar: one per category, the current one long, the
// opened ones gold. Nothing lit on the opening and closing slides.
function _ceremonyPaintDots() {
  const el = document.getElementById('ceremonyDots');
  if (!el) return;
  el.innerHTML = _ceremonyCats.map((cat, i) =>
    `<i class="${i === _ceremonyIdx ? 'is-on' : ''}${_ceremonyRevealed.has(cat.id) ? ' is-done' : ''}"></i>`).join('');
}

/* ── Artwork ──────────────────────────────────────────────────────────────── */

// Describe an award item the way fetchAndInjectImage() wants it, reusing the same
// prefKey convention as the charts so a picture pinned there shows up here too.
function _cerImgItem(item, type, imgId) {
  const artist = item.artist || '';
  if (type === 'artist') {
    return { imgId, name: artist, artist, prefKey: 'artist:' + artist.toLowerCase() };
  }
  if (type === 'album') {
    const album = item.album || '';
    return { imgId, name: album, album, artist, prefKey: 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase() };
  }
  const title = item.title || '';
  return { imgId, name: title, title, artist, album: item.album || '', prefKey: 'song:' + artist.toLowerCase() + '|||' + title.toLowerCase() };
}

function _cerArtHtml(item, type, imgId, cls) {
  const label = item.title || item.album || item.artist || '';
  return `<div class="cer-art ${cls}"><div id="${imgId}"><div class="thumb-initials">${esc(initials(label))}</div></div></div>`;
}

// Load the queued artwork one at a time — fetchAndInjectImage already paces the
// Deezer proxy, and it drops anything whose container left the DOM, so switching
// slides mid-load resolves itself.
async function _ceremonyLoadArt(queue, seq) {
  return _awardsLoadArtQueue(queue, () => seq === _ceremonyRenderSeq);
}

// isLive() is asked before each job, so a render that has been replaced stops
// fetching. Shared by the ceremony and the stats summary on the awards tab.
async function _awardsLoadArtQueue(queue, isLive) {
  for (const job of queue) {
    if (!isLive()) return;
    const el = document.getElementById(job.imgId);
    if (!el) continue;
    // A shared copy carries the owner's artwork, so the guest sees the same
    // pictures they did. If one has gone dead, look it up the normal way.
    if (job.item.img) {
      const lbl = job.item.title || job.item.album || job.item.artist || '';
      el.innerHTML = `<img class="thumb" alt="" src="${esc(job.item.img)}">`;
      el.querySelector('img').onerror = () => {
        el.innerHTML = `<div class="thumb-initials">${esc(initials(lbl))}</div>`;
        fetchAndInjectImage(el, _cerImgItem(job.item, job.type, job.imgId), job.type).catch(() => {});
      };
      continue;
    }
    try { await fetchAndInjectImage(el, _cerImgItem(job.item, job.type, job.imgId), job.type); } catch (e) {}
  }
}

/* ── Slides ───────────────────────────────────────────────────────────────── */

function _ceremonyRender() {
  const data = _ceremonyData;
  if (!data) return;
  cerShowStop(true);
  _ceremonyStopAudio();
  const seq = ++_ceremonyRenderSeq;
  const slide = document.getElementById('ceremonySlide');
  const badge = document.getElementById('ceremonyYearBadge');
  const name  = document.getElementById('ceremonyCatName');
  const prog  = document.getElementById('ceremonyProgress');
  const nextBtn = document.getElementById('ceremonyNextBtn');
  const prevBtn = document.getElementById('ceremonyPrevBtn');
  badge.textContent = _ceremonyTitle();

  const queue = [];
  if (_ceremonyIsIntro()) {
    // Opening slide: where the records stand before tonight's first envelope
    name.textContent = t('awx_title');
    prog.textContent = '📊 ' + t('awx_cer_before');
    slide.className = 'ceremony-slide is-intro';
    slide.innerHTML = _awardsSummaryHtml(_ceremonySummary, queue, `cerSum_${seq}`);
  } else if (_ceremonyIsFinale()) {
    name.textContent = t('awx_cer_winners');
    prog.textContent = '🎬 ' + t('awx_cer_rollcall');
    slide.className = 'ceremony-slide is-finale';
    slide.innerHTML = _ceremonyFinaleHtml(data, queue);
  } else {
    const cat     = _ceremonyCats[_ceremonyIdx];
    const catData = data.categories[cat.id] || { nominees: [], winner: null };
    name.textContent = _ceremonyCatName(cat);
    prog.textContent = `${_ceremonyIdx + 1} / ${_ceremonyCats.length}`;
    const opened = _ceremonyRevealed.has(cat.id) && catData.winner;
    slide.className = 'ceremony-slide' + (opened ? ' is-revealed' : '');
    slide.innerHTML = _ceremonyCatSlideHtml(cat, catData, queue);
    if (opened) _ceremonyMarkWinnerCard(catData.winner);
  }

  prevBtn.disabled = _ceremonyIdx === _ceremonyFirstIdx();
  nextBtn.textContent = _ceremonyIsIntro() ? '🎬 ' + t('awx_cer_start')
    : (_ceremonyIdx === _ceremonyCats.length - 1 ? '🏆 ' + t('awx_cer_all_winners') : t('awards_ceremony_next'));
  nextBtn.style.visibility = _ceremonyIsFinale() ? 'hidden' : '';
  // Rows carry their own index, since the optional intro row shifts the positions
  document.querySelectorAll('.ceremony-sidebar-row').forEach(el => el.classList.toggle('active', +el.dataset.idx === _ceremonyIdx));
  _ceremonyPaintDots();
  document.getElementById('ceremonyStage').scrollTop = 0;
  _ceremonyLoadArt(queue, seq);
}

function _ceremonyCatSlideHtml(cat, catData, queue) {
  const nominees = catData.nominees || [];
  const winner   = catData.winner   || null;
  const type     = cat.type;
  const seq      = _ceremonyRenderSeq;

  if (!nominees.length && !winner) return `<div class="ceremony-no-nom">${t('awards_ceremony_no_nom')}</div>`;

  // An auto category's "nominees" list holds exactly one entry and that entry IS
  // the winner — printing it above the envelope showed the answer before anyone
  // opened anything. Those categories get a sealed placeholder instead, and the
  // name only appears in the winner panel after the reveal.
  const cards = (cat.auto ? [] : nominees).map((n, i) => {
    const imgId = `cerArt_${seq}_${i}`;
    queue.push({ imgId, item: n, type });
    const lbl = n.title || n.album || n.artist || '';
    const sub = (n.title || n.album) ? (n.artist || '') : '';
    return `<div class="cer-nom-card" data-nk="${esc(_awardItemKey(n))}">
      ${_cerArtHtml(n, type, imgId, 'cer-art-sm')}
      <div class="cer-nom-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-nom-sub">${esc(sub)}</div>` : ''}
      <span class="cer-nom-trophy">🏆</span>
    </div>`;
  }).join('');

  // Standing in for the field an auto category does not have: a blank sleeve, so
  // the slide is not just an envelope floating in empty space.
  const sealedHtml = (cat.auto && winner)
    ? `<div class="cer-sealed">
         <div class="cer-sealed-card"><span class="cer-sealed-mark">?</span></div>
         <div class="cer-sealed-note">${esc(t('awards_ceremony_auto_sealed'))}</div>
       </div>`
    : '';

  // Winner artwork is queued first so the reveal never lands on an empty square
  let winnerHtml = '';
  if (winner) {
    const wImgId = `cerWin_${seq}`;
    queue.unshift({ imgId: wImgId, item: winner, type });
    const lbl = winner.title || winner.album || winner.artist || '';
    const sub = (winner.title || winner.album) ? (winner.artist || '') : '';
    winnerHtml = `<div class="cer-winner">
      <div class="cer-winner-art-wrap">
        ${_cerArtHtml(winner, type, wImgId, 'cer-art-lg')}
        <span class="cer-winner-badge">🏆</span>
      </div>
      <div class="cer-winner-label">${t('awards_winner')}</div>
      <div class="cer-winner-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-winner-sub">${esc(sub)}</div>` : ''}
      <div class="cer-player" id="ceremonyPlayer">
        <button class="cer-play-btn" id="ceremonyPlayBtn" onclick="ceremonyTogglePlay()" title="${esc(t('awx_cer_preview_30'))}">▶</button>
        <div class="cer-player-bar"><div class="cer-player-fill" id="ceremonyPlayFill"></div></div>
        <span class="cer-player-note" id="ceremonyPlayNote">${esc(t('awx_cer_preview'))}</span>
        <button class="cer-take-btn" id="ceremonyTakeBtn" onclick="ceremonyNextTake()" style="display:none" title="${esc(t('awards_preview_wrong'))}">⤿</button>
      </div>
    </div>`;
  }

  // Auto categories hold a single nominee that *is* the winner, so showcasing it
  // would give the game away — only offer the walk-through for a real field.
  const showcaseBtn = (!cat.auto && nominees.length > 1)
    ? `<button class="ceremony-nominees-btn" onclick="cerShowStart()">▶ ${esc(t('awx_cer_meet'))}</button>`
    : '';

  const envelope = winner
    ? `<div class="cer-envelope-wrap">
         <div class="cer-envelope" onclick="ceremonyReveal()" role="button" tabindex="0" title="${esc(t('awx_cer_open_env'))}">
           <div class="cer-env-back"></div>
           <div class="cer-env-card"><span class="cer-env-card-star">🏆</span></div>
           <div class="cer-env-front"></div>
           <div class="cer-env-flap"></div>
           <div class="cer-env-seal">★</div>
         </div>
         <div class="cer-cta-row">
           ${showcaseBtn}
           <button class="ceremony-reveal-btn" onclick="ceremonyReveal()">✉ ${t('awards_open_envelope')}</button>
         </div>
       </div>`
    : `<div class="cer-no-winner">${_ceremonyShared
        ? esc(t('awx_cer_no_winner_shared'))
        : esc(t('awx_cer_no_winner'))}</div>`;

  return `${cards ? `<div class="cer-nominees">${cards}</div>` : sealedHtml}${envelope}${winnerHtml}`;
}

function _ceremonyFinaleHtml(data, queue) {
  const seq = _ceremonyRenderSeq;
  const rows = _ceremonyCats.map((cat, i) => {
    const w = data.categories[cat.id]?.winner;
    if (!w) return '';
    const imgId = `cerFin_${seq}_${i}`;
    queue.push({ imgId, item: w, type: cat.type });
    const lbl = w.title || w.album || w.artist || '';
    const sub = (w.title || w.album) ? (w.artist || '') : '';
    return `<div class="cer-fin-card" onclick="ceremonyGoTo(${i})" title="${esc(_ceremonyCatName(cat))}">
      ${_cerArtHtml(w, cat.type, imgId, 'cer-art-md')}
      <div class="cer-fin-cat">${esc(_ceremonyCatName(cat))}</div>
      <div class="cer-fin-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-fin-sub">${esc(sub)}</div>` : ''}
    </div>`;
  }).join('');
  // A guest reaching the end is the moment to tell them where this came from.
  const cta = _ceremonyShared
    ? `<div class="cer-shared-cta"><a href="${esc(location.pathname)}" class="cer-shared-cta-btn">🏆 ${esc(t('awx_cer_make_own'))}</a></div>`
    : '';
  // After the roll call, the records again with tonight's results counted in,
  // marked where a holder changed since the opening slide
  const stats = _ceremonySummaryFinal
    ? `<div class="cer-finale-stats">${_awardsSummaryHtml(_ceremonySummaryFinal, queue, `cerFinSum_${seq}`, {
        kicker: t('awx_after', { y: _ceremonyYear }),
        title: t('awx_final_title'),
        before: _ceremonySummary,
        winsView: true,
      })}</div>`
    : '';
  if (!rows) return `<div class="ceremony-no-nom">${esc(t('awx_no_winners'))}</div>${stats}${cta}`;
  return `<div class="cer-finale-grid">${rows}</div>${stats}${cta}`;
}

/* ── The reveal ───────────────────────────────────────────────────────────── */

function ceremonyReveal() {
  if (_ceremonyIsFinale()) return;
  const cat  = _ceremonyCats[_ceremonyIdx];
  const data = _ceremonyData;
  const winner = data?.categories?.[cat?.id]?.winner;
  if (!cat || !winner || _ceremonyRevealed.has(cat.id)) return;
  const slide = document.getElementById('ceremonySlide');
  if (!slide || slide.classList.contains('is-opening')) return;

  cerShowStop(true);                           // opening the envelope ends the walk-through
  _ceremonyRevealed.add(cat.id);
  slide.classList.add('is-opening');           // flap lifts, the card rides up out of it
  setTimeout(() => {
    slide.classList.remove('is-opening');
    slide.classList.add('is-revealed');
    _ceremonyMarkWinnerCard(winner);
    // The winner leads the revealed slide (the field shrinks to a strip under
    // it), so ride back to the top where it is.
    const stage = document.getElementById('ceremonyStage');
    if (stage) stage.scrollTo({ top: 0, behavior: _cerReducedMotion() ? 'auto' : 'smooth' });
    _triggerConfetti();
    _ceremonyDrawSidebar(data);
    _ceremonyStartPreview(winner, cat.type);   // still inside the click's activation, so autoplay is allowed
  }, 1150);
}

// Ring the winning nominee in gold and fade the rest of the field
function _ceremonyMarkWinnerCard(winner) {
  const wk = _awardItemKey(winner);
  document.querySelectorAll('.cer-nom-card').forEach(card => {
    card.classList.toggle('is-winner', card.dataset.nk === wk);
    card.classList.toggle('is-dimmed', card.dataset.nk !== wk);
  });
}

function ceremonyNav(delta) {
  const data = _ceremonyData;
  if (!data) return;
  const idx = Math.max(_ceremonyFirstIdx(), Math.min(_ceremonyCats.length, _ceremonyIdx + delta));
  if (idx === _ceremonyIdx) return;
  _ceremonyIdx = idx;
  _ceremonyDrawSidebar(data);
  _ceremonyRender();
}

function ceremonyGoTo(idx) {
  const data = _ceremonyData;
  if (!data) return;
  ceremonyToggleDrawer(false);   // picked from the drawer: close it to show the slide
  _ceremonyIdx = Math.max(_ceremonyFirstIdx(), Math.min(_ceremonyCats.length, idx));
  _ceremonyDrawSidebar(data);
  _ceremonyRender();
}

/* ── Song previews ────────────────────────────────────────────────────────── */

// 30-second clip for the winner: iTunes first (no proxy, wide catalogue), Deezer second.
/* ── Preview matching ─────────────────────────────────────────────────────────
   iTunes search is a fuzzy free-text match and its first hit is very often the
   wrong recording. Searching "Taylor Swift The Fate of Ophelia" returns the
   Chainsmokers remix first and a spoken "Track by Track" commentary second,
   with the actual song only third; covers by the Vitamin String Quartet or the
   Piano Tribute Players rank high whenever the real track is thin on metadata.
   Taking the first result that happened to carry a previewUrl therefore played
   the wrong thing often enough to spoil the reveal.

   Every candidate is now scored against the nominee and anything that does not
   clearly match is thrown away — at the moment the envelope opens, silence is
   better than somebody else's song. What survives is kept as a ranked list so
   the player can offer the next-best take if the top one is still off. */

// Accents, curly quotes and punctuation all differ between our data and the
// stores', so comparisons run on a flattened form of the string.
function _cerNorm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[‘’ʼ`]/g, "'")
    // Stylised letters, before punctuation is stripped. Deezer files JOYRIDE.
    // under "Ke$ha" while we hold "Kesha"; dropping the $ left "ke ha", which
    // matched nothing and threw away a perfect hit. Same for P!nk and A$AP.
    .replace(/\$/g, 's')
    .replace(/!/g, 'i')
    .replace(/[ø∅]/g, 'o')
    .replace(/@/g, 'a')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9' ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// "The Fate of Ophelia (Loud Luxury Remix)" and "Song - Live at Wembley" both
// reduce to their plain title, so a nominee still matches its own recording.
function _cerPlainTitle(s) {
  return String(s || '')
    .replace(/\s*[\(\[][^)\]]*[\)\]]/g, ' ')
    .replace(/\s+-\s+.*$/, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function _cerCoreTitle(s) { return _cerNorm(_cerPlainTitle(s)); }

// Versions we only want when the nominee itself asks for them.
const _CER_QUALS = ['remix', 'live', 'acoustic', 'instrumental', 'demo', 'remaster',
                    'radio edit', 'extended', 'sped up', 'slowed', 'reprise', 'edit'];
function _cerQuals(s) {
  const n = _cerNorm(s);
  return new Set(_CER_QUALS.filter(q => n.includes(q)));
}

// Never the recording anyone meant, whatever the search engine thinks.
// Technically the right recording, but nobody wants the instrumental playing
// under a winner's name — allowed only as a last resort, never ahead of a real
// take, so these are penalised rather than rejected.
// Words that only join names together, never identify an artist.
const _CER_JOINERS = new Set(['and', 'the', 'feat', 'ft', 'featuring', 'with', 'x', 'vs', 'versus', 'a', 'of']);

const _CER_WEAK = ['instrumental', 'acapella', 'a cappella', 'sped up', 'slowed', 'demo', 'karaoke'];

const _CER_JUNK = /\b(karaoke|tribute|made famous|made popular|originally performed|in the style of|cover version|track by track|commentary|interview|8 bit|lullaby|music box|string quartet|piano version|as made)\b/;

/* Scores one search result against the nominee. Returns -Infinity for anything
   that should not be played at all, so callers can simply drop those. */
function _cerMatchScore(wantArtist, wantTitle, candArtist, candTitle) {
  const wa = _cerNorm(wantArtist), ca = _cerNorm(candArtist);
  if (!wa || !ca) return -Infinity;

  // The nominee's artist has to be recognisable in the candidate's credit. A
  // collaboration ("Lady Gaga & Bruno Mars") still counts for either half.
  // Credits are compared as sets of names, ignoring the words that only join
  // them — "Lady Gaga, Bruno Mars", "Lady Gaga & Bruno Mars" and "Lady Gaga
  // feat. Bruno Mars" are one credit written three ways, and a plain substring
  // test scores the shortest, least complete version highest.
  const wt = wa.split(' ').filter(x => !_CER_JOINERS.has(x));
  const ct = ca.split(' ').filter(x => !_CER_JOINERS.has(x));
  const ctSet = new Set(ct), wtSet = new Set(wt);
  if (!wt.length || !ct.length) return -Infinity;
  const fwd = wt.filter(x => ctSet.has(x)).length / wt.length;   // they list everyone we asked for
  const rev = ct.filter(x => wtSet.has(x)).length / ct.length;   // they list nobody we did not

  let aScore;
  if (fwd === 1 || rev === 1) aScore = 3;                        // one credit contains the other
  else if (Math.max(fwd, rev) >= 0.5) aScore = 1;
  else aScore = 0;
  if (!aScore) return -Infinity;
  // Among equals, prefer the pressing that names the whole line-up.
  const creditBonus = fwd === 1 ? 1 : 0;

  const wFull = _cerNorm(wantTitle), cFull = _cerNorm(candTitle);
  const wCore = _cerCoreTitle(wantTitle), cCore = _cerCoreTitle(candTitle);

  // Junk is only junk when the nominee did not ask for it — somebody really can
  // have a song called "Karaoke".
  if (_CER_JUNK.test(cFull + ' ' + ca) && !_CER_JUNK.test(wFull + ' ' + wa)) return -Infinity;

  let tScore;
  if (!wFull) tScore = 0;                                   // artist award: any track by them
  else if (wFull === cFull) tScore = 6;
  else if (wCore && wCore === cCore) tScore = 4;
  else if (wCore && cCore.includes(wCore)) tScore = 2;
  else if (wCore && wCore.includes(cCore) && cCore.length > 4) tScore = 1;
  else return -Infinity;

  // A remix or a live take when the nominee is the studio cut is the single most
  // common way this went wrong, so disagreement is punished hard.
  let q = 0;
  if (wFull) {
    const wq = _cerQuals(wantTitle), cq = _cerQuals(candTitle);
    // A remaster is the same recording, so it is no worse than the plain title.
    // Deezer now only carries some studio cuts as "(2025 Remaster)", and the old
    // penalty tied them with "Live In Denver", which then won on search order.
    for (const k of cq) if (k !== 'remaster') q += wq.has(k) ? 2 : -4;
    for (const k of wq) if (!cq.has(k) && k !== 'remaster') q -= 3;
  }
  for (const w of _CER_WEAK) if (cFull.includes(w) && !wFull.includes(w)) q -= 8;
  return aScore * 2 + tScore + q + creditBonus;
}

/* Runs one search term past both stores and returns whatever survives scoring. */
async function _cerSearchTakes(term, artist, name, type, wantAlbum) {
  const takes = [];
  // Song awards also read the record a take comes from: Apple files a live take
  // as plain "I Write Sins Not Tragedies" on "Live Session (iTunes Exclusive)",
  // and from the title alone that looked like the studio cut and won.
  const add = (url, title, candArtist, candAlbum, order) => {
    // An album award wants any track off that record, so it is the album name
    // that has to match, not the track name.
    const candTitle = type === 'album' ? candAlbum : title;
    let score = _cerMatchScore(artist, name, candArtist, candTitle);
    if (score === -Infinity) return;
    const pen = type === 'album' ? 0 : _cerAlbumPenalty(candAlbum, name, wantAlbum);
    score += pen;
    takes.push({ url, label: `${title} — ${candArtist}`, title, score, order,
                 clean: !pen && _cerCleanTake(type === 'album' ? '' : name, title) });
  };

  // A wide net, because the right recording is regularly several rows down.
  try {
    const r = await fetch(`https://itunes.apple.com/search?term=${encodeURIComponent(term)}&entity=song&limit=25`);
    const d = await r.json();
    (d?.results || []).forEach((x, i) => {
      if (x.previewUrl) add(x.previewUrl, x.trackName || '', x.artistName || '', x.collectionName || '', i);
    });
  } catch (e) {}

  // Deezer as the second opinion, and often the better one: it carries remixes
  // and edits Apple never lists. This branch never ran before — deezerFetch
  // resolves to a Response and the old code read .data straight off it.
  try {
    const r = await deezerFetch(`search/track?q=${encodeURIComponent(term)}&limit=25`);
    if (r.ok) {
      const d = await r.json();
      (d?.data || []).forEach((x, i) => {
        if (x.preview) add(x.preview, x.title || '', x.artist?.name || '', x.album?.title || '', i + 0.5);
      });
    }
  } catch (e) {}

  // Best score first; within a score keep the store's own relevance order.
  takes.sort((a, b) => (b.score - a.score) || (a.order - b.order));
  const seen = new Set();
  return takes.filter(x => !seen.has(x.url) && seen.add(x.url));
}

/* Ranked list of playable takes for a nominee: [{ url, label }], best first.

   Widens the search in steps rather than giving up on the first miss. Both
   stores narrow on every word in the term, so a version name they have never
   heard of sinks the whole query: "Kesha JOYRIDE. - Revved Up Remix" returns
   nothing at all from iTunes, while "Kesha JOYRIDE" finds the record. Dropping
   the qualifier, then the featured credits, gets the base recording of the right
   song, which the scorer ranks below an exact take but well above silence. */
async function _ceremonyPreviewTakes(item, type) {
  const artist = item.artist || '';
  const name   = type === 'album' ? (item.album || '') : type === 'artist' ? '' : (item.title || '');
  const albumName = type === 'artist' ? '' : (item.album || '');
  const key    = `${type}:${artist.toLowerCase()}|||${name.toLowerCase()}|||${albumName.toLowerCase()}`;
  if (key in _ceremonyPreviewCache) return _ceremonyPreviewCache[key];

  const plain = _cerPlainTitle(name);
  // Lead artist only — a store often files "Tate McRae, Wreckno" under just the
  // first name, and the scorer still checks the full credit afterwards.
  const lead  = artist.split(/,|;|&|\bfeat\.?\b|\bft\.?\b|\bwith\b/i)[0].trim();

  const terms = [];
  for (const term of [`${artist} ${name}`.trim(), `${artist} ${plain}`.trim(), `${lead} ${plain}`.trim(), plain]) {
    if (term && !terms.includes(term)) terms.push(term);
  }

  let out = [];
  for (const term of terms) {
    out = await _cerSearchTakes(term, artist, name, type, albumName);
    if (out.length) break;
  }

  // Track search alone misses two things: an album whose songs are also filed on
  // a compilation (Jon Schmidt's "To the Summit" comes back only as a track on
  // "Solo Sessions Vol. 2", so the album name never matches), and a studio cut
  // that search ranks below every live and acoustic take (Panic!'s "I Write Sins
  // Not Tragedies"). Looking the record up as an album and reading its tracklist
  // catches both. Songs only pay for it when nothing clean was found.
  if (albumName && (type === 'album' || !out.some(t => t.clean))) {
    const more = await _cerAlbumTakes(artist, albumName, name, type);
    if (more.length) {
      const seen = new Set(out.map(t => t.url));
      out = out.concat(more.filter(t => !seen.has(t.url)))
               .sort((a, b) => (b.score - a.score) || (a.order - b.order));
    }
  }
  _ceremonyPreviewCache[key] = out;
  return out;
}

// True when a take is the version the nominee names: no live/acoustic/remix
// tag it didn't ask for, and none it asked for missing. A remaster counts as clean.
function _cerCleanTake(wantTitle, candTitle) {
  const wq = _cerQuals(wantTitle), cq = _cerQuals(candTitle);
  wq.delete('remaster'); cq.delete('remaster');
  if (wq.size !== cq.size || [...wq].some(k => !cq.has(k))) return false;
  const c = _cerNorm(candTitle), w = _cerNorm(wantTitle);
  return !_CER_WEAK.some(x => c.includes(x) && !w.includes(x));
}

// Whole words only: album names say "Deluxe Edition", which a plain substring
// test reads as "edit".
const _CER_ALBUM_QUALS = [/\blive\b/, /\bacoustic\b/, /\bunplugged\b/, /\bremix(es)?\b/, /\bdemos?\b/, /\binstrumentals?\b/];

// Marks down a take whose record is a live, acoustic or remix release the
// nominee didn't come from. The nominee's own album saying "Live" (Hole's "Live
// Through This") means it's wanted, so those words are let through.
function _cerAlbumPenalty(candAlbum, wantTitle, wantAlbum) {
  const c = _cerNorm(candAlbum), w = _cerNorm(`${wantTitle} ${wantAlbum || ''}`);
  let pen = 0;
  for (const re of _CER_ALBUM_QUALS) if (re.test(c) && !re.test(w)) pen -= 4;
  return pen;
}

/* Finds the nominee's album on iTunes and Deezer and returns playable takes from
   its tracklist. For an album award every track counts, title track first; for
   a song award only the tracks whose name matches. */
async function _cerAlbumTakes(artist, albumName, songName, type) {
  const lead = artist.split(/,|;|&|\bfeat\.?\b|\bft\.?\b|\bwith\b/i)[0].trim();
  const q = encodeURIComponent(`${lead} ${_cerPlainTitle(albumName)}`);
  const albumCore = _cerCoreTitle(albumName);
  const takes = [];

  // Best two matching albums per store: the plain release and, when it's gone,
  // the deluxe reissue (Deezer only has Panic!'s debut as a 20th anniversary set)
  const bestTwo = list => list
    .map((x, i) => ({ ...x, score: _cerMatchScore(artist, albumName, x.artist, x.title), i }))
    .filter(x => x.score !== -Infinity)
    .sort((a, b) => (b.score - a.score) || (a.i - b.i))
    .slice(0, 2);

  const addTrack = (al, url, title, candArtist, order) => {
    if (!url) return;
    let score;
    if (type === 'album') {
      // Any track is the album; the title track (if there is one) leads, and
      // tracks the scorer would mark down (demos, live bonus cuts) are skipped.
      if (!_cerCleanTake('', title)) return;
      score = al.score + (_cerCoreTitle(title) === albumCore ? 1 : 0);
    } else {
      score = _cerMatchScore(artist, songName, candArtist, title);
      if (score === -Infinity) return;
    }
    takes.push({ url, label: `${title} — ${candArtist}`, title, score, order,
                 clean: _cerCleanTake(type === 'album' ? '' : songName, title) });
  };

  try {
    const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=album&limit=10`);
    const d = await r.json();
    const albums = bestTwo((d?.results || []).map(x => ({ id: x.collectionId, artist: x.artistName || '', title: x.collectionName || '' })));
    for (const al of albums) {
      const tr = await fetch(`https://itunes.apple.com/lookup?id=${al.id}&entity=song&limit=200`);
      const td = await tr.json();
      (td?.results || []).filter(x => x.wrapperType === 'track')
        .forEach((x, i) => addTrack(al, x.previewUrl, x.trackName || '', x.artistName || '', 100 + i));
    }
  } catch (e) {}

  try {
    const r = await deezerFetch(`search/album?q=${q}&limit=10`);
    if (r.ok) {
      const d = await r.json();
      const albums = bestTwo((d?.data || []).map(x => ({ id: x.id, artist: x.artist?.name || '', title: x.title || '' })));
      for (const al of albums) {
        const tr = await deezerFetch(`album/${al.id}/tracks?limit=100`);
        if (!tr.ok) continue;
        const td = await tr.json();
        (td?.data || []).forEach((x, i) => addTrack(al, x.preview, x.title || '', x.artist?.name || '', 100.5 + i));
      }
    }
  } catch (e) {}
  return takes;
}

function _ceremonyPaintPlayer(state, note) {
  const btn  = document.getElementById('ceremonyPlayBtn');
  const noteEl = document.getElementById('ceremonyPlayNote');
  if (btn)  btn.textContent = state;
  if (noteEl && note !== undefined) noteEl.textContent = note;
}

// Shared clip player. `paint(state, note)` lets the winner panel and the nominee
// showcase report progress in their own UI. Resolves with the playing audio, or
// null when there was nothing to play.
async function _ceremonyPlayClip(item, type, opts) {
  opts = opts || {};
  const paint = opts.paint || (() => {});
  _ceremonyStopAudio();
  if (!_ceremonySound) { paint('▶', 'previews muted'); return null; }
  const token = ++_ceremonyAudioToken;
  paint('◌', 'finding preview…');

  const takes = await _ceremonyPreviewTakes(item, type);
  if (token !== _ceremonyAudioToken) return null;
  if (!takes.length) { paint('▶', 'no preview found'); return null; }
  // Wrap, so stepping past the last take comes back round to the best one.
  const take = takes[((opts.takeIdx || 0) % takes.length + takes.length) % takes.length];

  const audio = _ceremonyAudio = new Audio(take.url);
  audio.volume = 0;
  if (opts.fillId) {
    audio.addEventListener('timeupdate', () => {
      const fill = document.getElementById(opts.fillId);
      if (fill && audio.duration) fill.style.width = (audio.currentTime / audio.duration * 100) + '%';
    });
  }
  audio.addEventListener('ended', () => paint('▶', opts.endNote || 'replay preview'));
  try {
    await audio.play();
    if (token !== _ceremonyAudioToken) { audio.pause(); return null; }
    paint('❚❚', opts.label ? opts.label(take, takes.length) : (opts.playingNote || t('awx_cer_preview_30')));
    _ceremonyFadeIn(audio);
    return audio;
  } catch (e) {
    // Autoplay refused (no user gesture credited) — leave it under the play button
    paint('▶', 'tap to hear it');
    audio.volume = 0.7;
    return null;
  }
}

function _ceremonyStartPreview(item, type, takeIdx) {
  _cerTakeCtx = { item, type };
  _cerTakeIdx = takeIdx || 0;
  return _ceremonyPlayClip(item, type, {
    paint: _ceremonyPaintPlayer,
    fillId: 'ceremonyPlayFill',
    takeIdx: _cerTakeIdx,
    // Naming the recording makes a bad match obvious instead of merely puzzling,
    // and the button beside it steps to the next-best take. The name is shown
    // whenever the take is not literally the nominee's own title, so a stand-in
    // version is never substituted quietly.
    label: (take, total) => {
      _ceremonyPaintTakeBtn(total);
      const want = type === 'album' ? (item.album || '') : type === 'artist' ? '' : (item.title || '');
      const exact = want && _cerNorm(take.title) === _cerNorm(want);
      return (!exact || total > 1) ? take.label : t('awx_cer_preview_30');
    },
  });
}

/* Show the "wrong track?" button only when there is another take to offer. */
function _ceremonyPaintTakeBtn(total) {
  const btn = document.getElementById('ceremonyTakeBtn');
  if (btn) btn.style.display = total > 1 ? '' : 'none';
}

/* Step to the next-best match for the winner that is currently on screen. */
function ceremonyNextTake() {
  if (!_cerTakeCtx) return;
  _ceremonyStartPreview(_cerTakeCtx.item, _cerTakeCtx.type, _cerTakeIdx + 1);
}

/* ── Nominee showcase ─────────────────────────────────────────────────────── */

function _ceremonyNominees() {
  const cat = _ceremonyCats[_ceremonyIdx];
  if (!cat) return [];
  return _ceremonyData?.categories?.[cat.id]?.nominees || [];
}

function cerShowStart() {
  if (_ceremonyIsFinale() || _cerShowIdx >= 0) return;
  const noms = _ceremonyNominees();
  const slide = document.getElementById('ceremonySlide');
  if (!noms.length || !slide || slide.classList.contains('is-revealed')) return;

  slide.classList.add('is-showcasing');
  const panel = document.createElement('div');
  panel.className = 'cer-showcase';
  panel.id = 'cerShowcase';
  panel.innerHTML = `
    <div class="cer-show-step" id="cerShowStep"></div>
    <div class="cer-art cer-art-lg" id="cerShowArt"></div>
    <div class="cer-show-name" id="cerShowName"></div>
    <div class="cer-show-sub" id="cerShowSub"></div>
    <div class="cer-show-bar"><div class="cer-show-fill" id="cerShowFill"></div></div>
    <div class="cer-show-note" id="cerShowNote"></div>
    <div class="cer-show-controls">
      <button onclick="cerShowPrev()" title="${esc(t('awx_cer_prev_nom'))}" aria-label="${esc(t('awx_cer_prev_nom'))}">◄</button>
      <button onclick="cerShowNext()" title="${esc(t('awx_cer_next_nom'))}">${esc(t('awx_cer_skip'))} ►</button>
      <button onclick="cerShowStop()" title="${esc(t('awx_cer_back_env'))}">■ ${esc(t('awx_cer_stop'))}</button>
    </div>`;
  slide.insertBefore(panel, slide.querySelector('.cer-envelope-wrap') || null);
  // Ride to the bottom so the showcase controls clear the sticky nav row
  const stage = document.getElementById('ceremonyStage');
  if (stage) requestAnimationFrame(() => stage.scrollTo({ top: stage.scrollHeight, behavior: 'smooth' }));
  _cerShowStep(0);
}

async function _cerShowStep(i) {
  clearTimeout(_cerShowTimer);
  const token = ++_cerShowToken;
  const noms  = _ceremonyNominees();
  const cat   = _ceremonyCats[_ceremonyIdx];
  if (!cat || !document.getElementById('cerShowcase')) return;
  if (i >= noms.length) { cerShowStop(); return; }     // the field is done — back to the envelope

  _cerShowIdx = i;
  const nom = noms[i];
  _cerShowPaint(i, nom, noms.length);

  const audio = await _ceremonyPlayClip(nom, cat.type, {
    paint: (state, note) => { const el = document.getElementById('cerShowNote'); if (el && note) el.textContent = note; },
    playingNote: 'now playing',
  });
  if (token !== _cerShowToken) return;

  const ms = audio ? CER_SHOW_MS : CER_SHOW_SILENT_MS;
  _cerShowRunBar(ms);
  _cerShowTimer = setTimeout(() => _cerShowStep(i + 1), ms);
}

function _cerShowPaint(i, nom, total) {
  const lbl = nom.title || nom.album || nom.artist || '';
  const sub = (nom.title || nom.album) ? (nom.artist || '') : '';
  const step = document.getElementById('cerShowStep');
  if (step) step.textContent = `Nominee ${i + 1} of ${total}`;
  const nameEl = document.getElementById('cerShowName');
  if (nameEl) nameEl.textContent = lbl;
  const subEl = document.getElementById('cerShowSub');
  if (subEl) subEl.textContent = sub;

  // Borrow the artwork the nominee strip already loaded rather than fetching it twice
  const art = document.getElementById('cerShowArt');
  if (art) {
    const src = document.querySelectorAll('.cer-nom-card')[i]?.querySelector('img.thumb')?.src;
    art.innerHTML = src
      ? `<img class="thumb" alt="" src="${esc(src)}">`
      : `<div class="thumb-initials">${esc(initials(lbl))}</div>`;
  }
  _cerShowSpotlight(i);
}

// Light up the nominee being played, fade the rest of the field
function _cerShowSpotlight(i) {
  document.querySelectorAll('.cer-nom-card').forEach((card, n) => {
    card.classList.toggle('is-spotlight', n === i);
    card.classList.toggle('is-dimmed', n !== i);
  });
}

// The bar is driven by the clock, not the audio, so it still counts down in silence
function _cerShowRunBar(ms) {
  const fill = document.getElementById('cerShowFill');
  if (!fill) return;
  fill.style.transition = 'none';
  fill.style.width = '0%';
  void fill.offsetWidth;
  fill.style.transition = `width ${ms}ms linear`;
  fill.style.width = '100%';
}

function cerShowNext() { if (_cerShowIdx >= 0) _cerShowStep(_cerShowIdx + 1); }
function cerShowPrev() { if (_cerShowIdx > 0)  _cerShowStep(_cerShowIdx - 1); }

function cerShowStop(quiet) {
  clearTimeout(_cerShowTimer);
  _cerShowTimer = null;
  _cerShowToken++;
  const wasRunning = _cerShowIdx >= 0;
  _cerShowIdx = -1;
  if (wasRunning) _ceremonyStopAudio();
  document.getElementById('cerShowcase')?.remove();
  const slide = document.getElementById('ceremonySlide');
  if (slide) slide.classList.remove('is-showcasing');
  document.querySelectorAll('.cer-nom-card').forEach(c => c.classList.remove('is-spotlight', 'is-dimmed'));
  if (wasRunning && !quiet) {
    // Hand the moment back to the envelope
    const env = document.querySelector('.cer-envelope');
    if (env) {
      env.classList.add('is-ready');
      env.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }
}

function _ceremonyFadeIn(audio) {
  clearInterval(_ceremonyFadeTimer);
  let v = 0;
  _ceremonyFadeTimer = setInterval(() => {
    v = Math.min(0.7, v + 0.07);
    if (audio === _ceremonyAudio) audio.volume = v;
    if (v >= 0.7) clearInterval(_ceremonyFadeTimer);
  }, 60);
}

function _ceremonyStopAudio() {
  _ceremonyAudioToken++;
  clearInterval(_ceremonyFadeTimer);
  if (_ceremonyAudio) { try { _ceremonyAudio.pause(); } catch (e) {} _ceremonyAudio = null; }
  const fill = document.getElementById('ceremonyPlayFill');
  if (fill) fill.style.width = '0%';
}

function ceremonyTogglePlay() {
  if (_ceremonyAudio) {
    if (_ceremonyAudio.paused) { _ceremonyAudio.play().then(() => _ceremonyPaintPlayer('❚❚', t('awx_cer_preview_30'))).catch(() => {}); }
    else { _ceremonyAudio.pause(); _ceremonyPaintPlayer('▶', 'paused'); }
    return;
  }
  // No clip loaded yet (muted, autoplay refused, or a fresh visit) — fetch it now
  if (_ceremonyIsFinale()) return;
  const cat = _ceremonyCats[_ceremonyIdx];
  if (!cat) return;   // the stats intro has no category and no clip
  const winner = _ceremonyData?.categories?.[cat.id]?.winner;
  if (!winner) return;
  if (!_ceremonySound) { _ceremonySound = true; localStorage.setItem('dc_ceremony_sound', 'on'); _ceremonyPaintSoundBtn(); }
  _ceremonyStartPreview(winner, cat.type);
}

function ceremonyToggleSound() {
  _ceremonySound = !_ceremonySound;
  localStorage.setItem('dc_ceremony_sound', _ceremonySound ? 'on' : 'off');
  _ceremonyPaintSoundBtn();
  if (!_ceremonySound) { _ceremonyStopAudio(); _ceremonyPaintPlayer('▶', 'preview muted'); }
}

function _ceremonyPaintSoundBtn() {
  const btn = document.getElementById('ceremonySoundBtn');
  if (!btn) return;
  btn.textContent = _ceremonySound ? '🔊' : '🔇';
  btn.title = t(_ceremonySound ? 'awx_cer_sound_on' : 'awx_cer_sound_off');
  btn.setAttribute('aria-label', btn.title);
}

/* ── Sharing ──────────────────────────────────────────────────────────────────
   "Share ceremony" freezes the year's ballot into a public copy (see
   dcShareCeremony in firebase.js) and hands back a link. Whoever opens the link
   gets this same stage — nominees, envelopes, previews, the roll call — without
   an account or any music data of their own. It works the same for every data
   source, because what is copied is the finished ballot, not the plays behind it.

   The copy is a snapshot: changing a winner afterwards does not touch it until
   the owner presses "Update link", which rewrites the same document so the link
   they already sent keeps working.                                            */

const CER_SHARE_PARAM = 'ceremony';

function _cerShareUrl(id) {
  return `${location.origin}${location.pathname}?${CER_SHARE_PARAM}=${encodeURIComponent(id)}`;
}

// Only the fields the stage reads. Play counts and anything else hanging off a
// nominee stay on the owner's device. Firestore refuses undefined values, so
// absent fields are left out rather than written empty.
function _cerShareItem(item, img) {
  const out = { artist: item.artist || '' };
  if (item.title) out.title = item.title;
  if (item.album) out.album = item.album;
  if (img) out.img = img;
  return out;
}

/* The picture the owner sees for an item, as a plain URL, so the guest gets the
   same artwork instead of whatever their own lookup lands on. Mirrors the order
   fetchAndInjectImage uses — a pinned choice first, then the remembered source,
   then the rest — without touching the page. The getters cache, so anything the
   owner has already looked at costs nothing. */
async function _cerResolveImg(item, type) {
  const it = _cerImgItem(item, type, '');
  const choice = it.prefKey && imgChoicePrefs[it.prefKey];
  if (choice) {
    if (choice.source === 'off') return null;
    // Only real web addresses travel: an uploaded picture held as a data: or
    // blob: URL is either far too big for the document or means nothing on
    // another device.
    if (/^https?:\/\//.test(choice.url || '')) return choice.url;
  }
  const SOURCES = AUTO_IMG_SOURCES;
  const pref = (it.prefKey && itemSourcePrefs[it.prefKey]) || 'deezer';
  if (pref === 'off') return null;
  for (const source of [pref, ...SOURCES.filter(x => x !== pref)]) {
    try {
      let url = null;
      if (type === 'artist')     url = await getArtistImage(it.name, source);
      else if (type === 'album') url = await getAlbumImage(it.album, it.artist, source);
      else                       url = await getTrackImage(it.title, it.artist, source);
      if (url && /^https?:\/\//.test(url)) return url;
    } catch (e) {}
  }
  return null;
}

// The public copy of one year. onProgress(done, total) reports the artwork
// lookups, which are the only slow part.
async function _cerBuildShare(year, data, onProgress) {
  const cats = _ceremonyCatsFor(data);
  // The guest has no other years to count from, so the opening stats slide is
  // worked out here and travels with the copy, spoiler-free like the owner's.
  await _awardsEnsureAllYearsLoaded();
  const summary = _awardsSummary(year, { spoilerFree: true });
  const summaryFinal = _awardsSummary(year);   // the roll call's version, with the results in
  // The opening slide shows the nominations ranking; the roll call shows the
  // wins list instead, with a picture for every award as well as every artist
  const jobsFor = sum => !sum.yearNoms ? [] : [
    ...sum.records.flatMap(r => r.items.slice(0, 1).map(item => ({ item, type: r.type }))),
    ...(sum.spoilerFree
      ? sum.ranking.map(item => ({ item, type: 'artist' }))
      : sum.winners.flatMap(w => [{ item: w, type: 'artist' }, ...w.items.map(item => ({ item, type: item.type }))])),
  ];
  const sumJobs = [...jobsFor(summary), ...jobsFor(summaryFinal)];
  const total = sumJobs.length + cats.reduce((n, c) => {
    const cd = data.categories[c.id];
    return n + (cd.nominees?.length || 0) + (cd.winner ? 1 : 0);
  }, 0);
  let done = 0;
  const seen = new Map();   // the same record nominated twice is only looked up once
  const art = async (item, type) => {
    const k = type + '|' + _awardItemKey(item);
    if (!seen.has(k)) seen.set(k, await _cerResolveImg(item, type));
    onProgress && onProgress(++done, total);
    return seen.get(k);
  };

  const out = [];
  for (const cat of cats) {
    const cd = data.categories[cat.id];
    const nominees = [];
    for (const n of (cd.nominees || [])) nominees.push(_cerShareItem(n, await art(n, cat.type)));
    const winner = cd.winner ? _cerShareItem(cd.winner, await art(cd.winner, cat.type)) : null;
    out.push({ id: cat.id, label: cat.label, type: cat.type, auto: !!cat.auto, nominees, winner });
  }
  // Only the leaders' pictures are shown on the slide, so only they get one.
  // The items are summary-only objects, so the URL is written onto them directly.
  for (const job of sumJobs) {
    const img = await art(job.item, job.type);
    if (img) job.item.img = img;
  }
  const payload = {
    year,
    name: (localStorage.getItem('dc_display_name') || '').trim().slice(0, 60),
    cats: out,
  };
  if (summary.yearNoms) payload.summary = summary;
  if (summaryFinal.yearNoms) payload.summaryFinal = summaryFinal;
  return payload;
}

/* ── The share dialog ─────────────────────────────────────────────────────── */

let _cerShareBusy = false;

function openCeremonyShare() {
  const data = _awardsYearData[_awardsYear];
  if (!data || !_ceremonyCatsFor(data).length) { dcPlToast('Add some nominees before sharing the ceremony.'); return; }
  document.getElementById('cerShareSub').textContent = t('cer_share_sub', { year: _awardsYear });
  document.getElementById('cerShareModal').classList.add('open');
  _cerShareRender();
}

function closeCeremonyShare() {
  if (_cerShareBusy) return;   // let a write in flight finish before the dialog goes
  document.getElementById('cerShareModal').classList.remove('open');
}

// Draws whichever step the dialog is on: signed out, not shared yet, or live.
function _cerShareRender(note) {
  const body = document.getElementById('cerShareBody');
  const foot = document.getElementById('cerShareFoot');
  if (!body) return;
  const data = _awardsYearData[_awardsYear];
  const signedIn = typeof dcIsSignedIn === 'function' && dcIsSignedIn();
  const noteHtml = note ? `<div class="dc-frame-callout">${dcIco('alert')}<span>${esc(note)}</span></div>` : '';
  const setFoot = html => { if (foot) { foot.innerHTML = html; foot.style.display = html ? '' : 'none'; } };

  // Writing the public copy needs an account, so the link can be updated or
  // taken down later by the person who made it — and only by them.
  if (!signedIn) {
    body.innerHTML = `<p class="dc-frame-lead">${esc(t('cer_share_signin_text'))}</p>${noteHtml}`;
    setFoot(`<button class="dc-btn dc-btn-main" onclick="_cerShareSignIn()">${esc(t('cer_share_signin'))}</button>`);
    return;
  }

  if (!data?.shareId) {
    body.innerHTML = `<p class="dc-frame-lead">${esc(t('cer_share_create_text'))}</p>${noteHtml}`;
    setFoot(`<button class="dc-btn dc-btn-main" onclick="_cerSharePublish()">${dcIco('link')}${esc(t('cer_share_create'))}</button>`);
    return;
  }

  const url = _cerShareUrl(data.shareId);
  const canNative = typeof navigator.share === 'function';
  body.innerHTML = `
    <div class="dc-field-row cer-share-link-row">
      <input class="dc-input cer-share-link" id="cerShareLink" type="text" readonly value="${esc(url)}" onfocus="this.select()">
      <button class="dc-btn dc-btn-main" onclick="_cerShareCopy()">${dcIco('copy')}${esc(t('cer_share_copy'))}</button>
    </div>
    <p class="dc-frame-note">${esc(t('cer_share_live_text'))}</p>
    ${noteHtml}`;
  setFoot(`
    <div class="dc-frame-foot-start">
      <button class="dc-btn dc-btn-plain dc-btn-danger cer-share-stop" onclick="_cerShareStop()">${esc(t('cer_share_stop'))}</button>
    </div>
    <button class="dc-btn dc-btn-normal" onclick="_cerSharePublish()">${dcIco('refresh')}${esc(t('cer_share_update'))}</button>
    ${canNative ? `<button class="dc-btn dc-btn-normal" onclick="_cerShareNative()">${dcIco('share')}${esc(t('cer_share_native'))}</button>` : ''}`);
}

async function _cerShareSignIn() {
  if (typeof dcSignIn !== 'function') return;
  await dcSignIn();
  _cerShareRender();
}

// Create the link, or refresh the one that already exists.
async function _cerSharePublish() {
  if (_cerShareBusy) return;
  const year = _awardsYear;
  const data = _awardsYearData[year];
  if (!data) return;
  _cerShareBusy = true;
  const body = document.getElementById('cerShareBody');
  body.innerHTML = `<div class="dc-empty"><span class="dc-spinner"></span><span id="cerShareProgress">${esc(t('cer_share_gathering'))}</span></div>`;
  const foot = document.getElementById('cerShareFoot');
  if (foot) foot.style.display = 'none';
  try {
    const payload = await _cerBuildShare(year, data, (done, total) => {
      const el = document.getElementById('cerShareProgress');
      if (el) el.textContent = t('cer_share_gathering_n', { done, total });
    });
    const el = document.getElementById('cerShareProgress');
    if (el) el.textContent = t('cer_share_saving');
    const id = await dcShareCeremony(data.shareId || null, payload);
    if (!id) { _cerShareBusy = false; _cerShareRender(t('cer_share_err_save')); return; }
    const isNew = data.shareId !== id;
    data.shareId = id;
    if (isNew) _awardsSave(year);   // remember the link, on every device, so Update reuses it
    _cerShareBusy = false;
    _cerShareRender(isNew ? t('cer_share_created') : t('cer_share_updated'));
  } catch (e) {
    console.warn('[dankcharts] Ceremony share failed:', e);
    _cerShareBusy = false;
    _cerShareRender(t('cer_share_err_create'));
  }
}

async function _cerShareCopy() {
  const input = document.getElementById('cerShareLink');
  if (!input) return;
  try { await navigator.clipboard.writeText(input.value); }
  catch (e) { input.select(); document.execCommand('copy'); }
  dcPlToast(t('cer_share_copied'));
}

function _cerShareNative() {
  const data = _awardsYearData[_awardsYear];
  if (!data?.shareId) return;
  navigator.share({ title: t('cer_share_native_title', { year: _awardsYear }), text: t('cer_share_native_text', { year: _awardsYear }), url: _cerShareUrl(data.shareId) }).catch(() => {});
}

// Taking a link down deletes the public copy, so everyone who has it loses it.
async function _cerShareStop() {
  const year = _awardsYear;
  const data = _awardsYearData[year];
  if (!data?.shareId || _cerShareBusy) return;
  // The site's own warning window, never the browser's confirm()
  if (typeof window.dcConfirmBox === 'function') {
    window.dcConfirmBox(t('cer_share_stop_title'), t('cer_share_stop_text'), t('cer_share_stop'), _cerShareDoStop);
  } else _cerShareDoStop();
}
async function _cerShareDoStop() {
  const year = _awardsYear;
  const data = _awardsYearData[year];
  if (!data?.shareId || _cerShareBusy) return;
  _cerShareBusy = true;
  const ok = await dcUnshareCeremony(data.shareId);
  _cerShareBusy = false;
  if (!ok) { _cerShareRender(t('cer_share_err_stop')); return; }
  delete data.shareId;
  _awardsSave(year);
  _cerShareRender(t('cer_share_removed'));
}

/* ── Watching a shared link ───────────────────────────────────────────────── */

// Runs instead of the normal boot when the page is opened with ?ceremony=<id>.
// The guest's own charts never load; the overlay is the whole page.
async function openSharedCeremony(id) {
  window.dcCeremonyViewer = true;   // firebase.js skips its background sync for this visit
  _ceremonyShared = { id, name: '' };

  // The overlay sits inside the hidden main app in the markup. Lift it out so
  // it shows on its own.
  const overlay = document.getElementById('awardsCeremonyOverlay');
  document.body.appendChild(overlay);
  overlay.classList.add('is-shared');
  overlay.style.display = 'flex';
  document.body.style.overflow = 'hidden';
  _ceremonyPaintSoundBtn();

  const slide = document.getElementById('ceremonySlide');
  const say = (html) => {
    document.getElementById('ceremonySidebar').innerHTML = '';
    document.getElementById('ceremonyYearBadge').textContent = 'dankcharts.fm';
    document.getElementById('ceremonyCatName').textContent = '';
    document.getElementById('ceremonyProgress').textContent = '';
    document.getElementById('ceremonyPrevBtn').style.visibility = 'hidden';
    document.getElementById('ceremonyNextBtn').style.visibility = 'hidden';
    slide.className = 'ceremony-slide';
    slide.innerHTML = html;
  };
  say(`<div class="ceremony-no-nom">Loading the ceremony…</div>`);

  const snap = /^[A-Za-z0-9]{6,40}$/.test(id) && typeof dcLoadSharedCeremony === 'function'
    ? await dcLoadSharedCeremony(id) : null;
  if (!snap || !Array.isArray(snap.cats) || !snap.cats.length) {
    say(`<div class="ceremony-no-nom">This ceremony isn't available. The link may be wrong, or it was taken down.</div>
         <div class="cer-shared-cta"><a href="${esc(location.pathname)}" class="cer-shared-cta-btn">Go to dankcharts.fm</a></div>`);
    return;
  }

  // Rebuild the shape the stage expects. Category details come from this
  // build where it knows the id, so types and auto flags stay authoritative.
  const known = Object.fromEntries(AWARD_CATEGORIES.map(c => [c.id, c]));
  const data = { year: snap.year, categories: {} };
  const cats = snap.cats.map(c => {
    data.categories[c.id] = { enabled: true, nominees: c.nominees || [], winner: c.winner || null };
    return { ...(known[c.id] || {}), id: c.id, label: c.label, type: c.type || known[c.id]?.type || 'song', auto: !!c.auto };
  });
  _ceremonyShared = { id, name: snap.name || '' };
  document.getElementById('ceremonyPrevBtn').style.visibility = '';
  // Links made before the stats slide existed have no summary; they just start on the first category
  _ceremonyOpen(data, snap.year, cats, snap.summary || null, snap.summaryFinal || null);
  document.title = `${_ceremonyTitle()} · dankcharts.fm`;
}

// People who turn motion off get the reveal without confetti or glides
function _cerReducedMotion() {
  return !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
}

function _triggerConfetti() {
  const el = document.getElementById('ceremonyConfetti');
  if (!el || _cerReducedMotion()) return;
  el.innerHTML = '';
  const colors = ['#FFD700','#FFC04D','#FF69B4','#00CED1','#FF6347','#7B68EE','#32CD32','#FF8C00'];
  for (let i = 0; i < 90; i++) {
    const p = document.createElement('div');
    p.className = 'confetti-piece';
    p.style.cssText = `left:${Math.random()*100}%;background:${colors[i%colors.length]};animation-delay:${(Math.random()*0.9).toFixed(2)}s;animation-duration:${(1.6+Math.random()*1.4).toFixed(2)}s;width:${6+Math.random()*6|0}px;height:${6+Math.random()*6|0}px;border-radius:${Math.random()>.5?'50%':'3px'};`;
    el.appendChild(p);
  }
  setTimeout(() => { if (el) el.innerHTML = ''; }, 3600);
}

// ═══════════════════════════════════════════════════════════════
// ─── YOUR SOUNDTRACK ───────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════

let stPeriodType = 'year';
let stYear = tzNow().getFullYear();
let stMonth = tzNow().getMonth() + 1;
let _stCurrentPlays = [];
let _stReplayTimer = null;
let _stReplaySnapshots = [];
let _stReplayIdx = 0;
let _stReplayMax = 0;
let _stReplayPaused = false;
let _stReplaySpeedMs = 1200;
let _stBubbleTimer = null;
let _stBubbleSeeds = [];
let _stBubbleQueue = [];
let _stBubbleUid = 0;
let stReelMode = 'plays';    // which stat card is driving the reel below the stats strip
let _stPeakDayDate = null;   // Date of the busiest day in the current period (set by stRenderStats)
let _stReelLoaderId = 0;     // guards async reel image batches against stale renders
let _stReelEntries = [];     // what the reel is currently showing, for the ＋ Playlist button

function stGetPeriodPlays() {
  if (stPeriodType === 'alltime') return allPlays.slice();
  return allPlays.filter(p => {
    const d = tzDateOf(p);
    if (stPeriodType === 'year') return d.getFullYear() === stYear;
    return d.getFullYear() === stYear && (d.getMonth() + 1) === stMonth;
  });
}

// ── Reel data builders — one per stat-card mode, all chronological ───
// Caps every reel at ST_REEL_MAX evenly-spaced entries so an All-Time period
// with tens of thousands of plays can't blow up the ticker's DOM/image cost.
const ST_REEL_MAX = 400;

function stDecimate(arr, max) {
  if (arr.length <= max) return arr;
  const out = [];
  const step = arr.length / max;
  for (let i = 0; i < max; i++) out.push(arr[Math.floor(i * step)]);
  return out;
}

function stBuildReelPlays(plays) {
  const sorted = [...plays].sort((a, b) => a.date - b.date);
  return stDecimate(sorted, ST_REEL_MAX).map(p => ({
    type: 'song', title: p.title, artist: p.artist, album: p.album || '—', date: p.date
  }));
}

// Every artist in first-play-of-period order — each artist appears once, so
// the ticker loop cycles the full set before any artist can repeat.
function stBuildReelArtists(plays) {
  const sorted = [...plays].sort((a, b) => a.date - b.date);
  const seen = new Set();
  const out = [];
  for (const p of sorted) {
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    for (const ar of list) {
      if (seen.has(ar)) continue;
      seen.add(ar);
      out.push({ type: 'artist', artist: ar, date: p.date });
    }
  }
  return stDecimate(out, ST_REEL_MAX);
}

// Same first-seen logic as stRenderDiscoveries(), shaped for cards instead of bubbles.
function stBuildReelDiscoveries(plays) {
  const fsMap = stGetFirstSeenArtists();
  const seen = new Set();
  const out = [];
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      if (seen.has(artist)) continue;
      seen.add(artist);
      const fd = fsMap[artist];
      if (!fd) continue;
      const ftz = tzDate(fd);
      const inPeriod = stPeriodType === 'alltime' ? true :
        stPeriodType === 'year' ? ftz.getFullYear() === stYear :
        ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
      if (inPeriod) out.push({ type: 'artist', artist, date: fd });
    }
  }
  out.sort((a, b) => a.date - b.date);
  return stDecimate(out, ST_REEL_MAX);
}

// One card per active day, carrying that day's play count and top track.
function stBuildReelDays(plays) {
  const days = {};
  for (const p of plays) {
    const d = tzDateOf(p);
    const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    let day = days[dk];
    if (!day) day = days[dk] = { date: d, count: 0, songCounts: {} };
    day.count++;
    const sk = songKey(p);
    let s = day.songCounts[sk];
    if (!s) s = day.songCounts[sk] = { title: p.title, artist: p.artist, album: p.album || '—', count: 0 };
    s.count++;
  }
  const out = Object.values(days).map(day => {
    const top = Object.values(day.songCounts).sort((a, b) => b.count - a.count)[0];
    return { type: 'day', date: day.date, count: day.count, topTitle: top.title, topArtist: top.artist, topAlbum: top.album };
  });
  out.sort((a, b) => a.date - b.date);
  return stDecimate(out, ST_REEL_MAX);
}

// Every song played on the single busiest day (see _stPeakDayDate, set by stRenderStats).
function stBuildReelPeakDay(plays) {
  if (!_stPeakDayDate) return [];
  const pd = _stPeakDayDate;
  const dayPlays = plays.filter(p => {
    const d = tzDateOf(p);
    return d.getFullYear() === pd.getFullYear() && d.getMonth() === pd.getMonth() && d.getDate() === pd.getDate();
  }).sort((a, b) => a.date - b.date);
  return stDecimate(dayPlays.map(p => ({
    type: 'song', title: p.title, artist: p.artist, album: p.album || '—', date: p.date
  })), ST_REEL_MAX);
}

const ST_MONTH_KEYS = ['month_jan','month_feb','month_mar','month_apr','month_may_short','month_jun','month_jul','month_aug','month_sep','month_oct','month_nov','month_dec'];

function stGetPeriodLabel() {
  if (stPeriodType === 'alltime') return t('st_period_alltime');
  if (stPeriodType === 'year') return String(stYear);
  return t(ST_MONTH_KEYS[stMonth - 1]) + ' ' + stYear;
}

function stSetPeriod(type) {
  // an open period picker belongs to the old view, so close it
  if (document.getElementById('awardsYearPicker')?.dataset.kind === 'soundtrack') _awardsCloseYearPicker();
  stPeriodType = type;
  document.querySelectorAll('.st-period-btn').forEach(b => b.classList.toggle('active', b.dataset.stPeriod === type));
  const navBar = document.getElementById('stNavBar');
  if (navBar) navBar.style.display = type === 'alltime' ? 'none' : '';
  // Chart History Replay is a Year-only section, so its toolbar button is too
  const replayBtn = document.getElementById('stTopReplayBtn');
  if (replayBtn) replayBtn.style.display = type === 'year' ? '' : 'none';
  if (type === 'year') { stYear = tzNow().getFullYear(); }
  if (type === 'month') { stYear = tzNow().getFullYear(); stMonth = tzNow().getMonth() + 1; }
  renderSoundtrack();
}

// The toolbar's Chart History Replay: bring the replay into view and start it
function stJumpToReplay() {
  const sec = document.getElementById('stReplaySection');
  if (!sec || sec.style.display === 'none') return;
  sec.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
  // start it unless it is already going (then its Play button is hidden)
  if (document.getElementById('stReplayBtn')?.style.display !== 'none') stStartReplay();
}

function stNavigate(dir) {
  if (stPeriodType === 'year') {
    const newYear = stYear + dir;
    if (newYear > tzNow().getFullYear()) return;
    stYear = newYear;
  } else if (stPeriodType === 'month') {
    let m = stMonth + dir, y = stYear;
    if (m < 1) { m = 12; y--; }
    if (m > 12) { m = 1; y++; }
    const now = tzNow();
    if (y > now.getFullYear() || (y === now.getFullYear() && m > now.getMonth() + 1)) return;
    stYear = y; stMonth = m;
  }
  renderSoundtrack();
}

/* Period picker: click the year (or month) between the arrows to jump straight
   to one. Year view = a grid of every year you have plays in, newest first.
   Month view = the 12 months of a year, with ‹ › in the header to change year.
   Reuses the Awards year picker's popover, chips and close handlers. */
function stOpenPeriodPicker() {
  const label = document.getElementById('stNavLabel');
  const existing = document.getElementById('awardsYearPicker');
  if (existing) {
    const wasSame = existing.dataset.kind === 'soundtrack';
    _awardsCloseYearPicker();
    if (wasSame) return;   // a second click on the label closes it
  }
  if (!allPlays.length || stPeriodType === 'alltime') return;
  const now = tzNow();
  const maxYear = now.getFullYear();
  let minTs = Infinity;
  for (const p of allPlays) if (p.date < minTs) minTs = p.date;
  const minYear = Math.min(tzDate(minTs).getFullYear(), stYear);

  const pop = document.createElement('div');
  pop.id = 'awardsYearPicker';
  pop.className = 'awards-year-picker';
  pop.dataset.kind = 'soundtrack';
  pop.setAttribute('role', 'dialog');
  pop.setAttribute('aria-label', stPeriodType === 'month' ? t('st_pick_month') : t('awx_pick_year'));

  // Month view: which year's months are on show (starts on the selected one)
  let pickYear = stYear;
  const draw = () => {
    if (stPeriodType === 'year') {
      let chips = '';
      for (let y = maxYear; y >= minYear; y--) {
        chips += `<button type="button" class="awards-year-chip${y === stYear ? ' is-current' : ''}" data-year="${y}">${y}</button>`;
      }
      pop.innerHTML = `<div class="awards-year-picker-grid">${chips}</div>`;
      return;
    }
    let chips = '';
    for (let m = 1; m <= 12; m++) {
      const future = pickYear === maxYear && m > now.getMonth() + 1;
      const cur = pickYear === stYear && m === stMonth;
      chips += `<button type="button" class="awards-year-chip${cur ? ' is-current' : ''}" data-month="${m}"${future ? ' disabled' : ''}>${esc(t(ST_MONTH_KEYS[m - 1]))}</button>`;
    }
    pop.innerHTML =
      `<div class="st-pick-head">` +
        `<button type="button" class="dc-btn dc-btn-plain dc-btn-icon awards-year-nav-btn" data-step="-1" aria-label="${esc(t('st_nav_prev'))}"${pickYear <= minYear ? ' disabled' : ''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg></button>` +
        `<span class="st-pick-year">${pickYear}</span>` +
        `<button type="button" class="dc-btn dc-btn-plain dc-btn-icon awards-year-nav-btn" data-step="1" aria-label="${esc(t('st_nav_next'))}"${pickYear >= maxYear ? ' disabled' : ''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg></button>` +
      `</div>` +
      `<div class="awards-year-picker-grid">${chips}</div>`;
  };
  draw();
  document.body.appendChild(pop);

  // Under the stepper pill, left edges aligned, kept inside the viewport
  const r = label.parentElement.getBoundingClientRect();
  pop.style.top  = `${r.bottom + 8}px`;
  pop.style.left = `${Math.max(8, Math.min(r.left, window.innerWidth - pop.offsetWidth - 8))}px`;
  label.classList.add('is-open');
  label.setAttribute('aria-expanded', 'true');

  pop.addEventListener('click', e => {
    const step = e.target.closest('[data-step]');
    if (step) {
      pickYear = Math.max(minYear, Math.min(maxYear, pickYear + +step.dataset.step));
      draw();
      pop.querySelector(`[data-step="${step.dataset.step}"]:not(:disabled)`)?.focus();
      return;
    }
    const chip = e.target.closest('.awards-year-chip');
    if (!chip || chip.disabled) return;
    _awardsCloseYearPicker();
    if (chip.dataset.year) stYear = +chip.dataset.year;
    else { stYear = pickYear; stMonth = +chip.dataset.month; }
    renderSoundtrack();
    label.focus();
  });
  const cur = pop.querySelector('.is-current');
  if (cur) { cur.scrollIntoView({ block: 'nearest' }); cur.focus({ preventScroll: true }); }

  // Same outside click / Escape / scroll / resize closing as the Awards picker
  setTimeout(() => {
    document.addEventListener('pointerdown', _awardsYearPickerOutside, true);
    document.addEventListener('keydown', _awardsYearPickerKey, true);
    window.addEventListener('scroll', _awardsCloseYearPicker, { passive: true });
    window.addEventListener('resize', _awardsCloseYearPicker);
  }, 0);
}

// ── The Reel — ticker below the stats strip, driven by the active stat card ──
const ST_REEL_ACCENTS = { plays: 'var(--accent)', days: 'var(--teal)', artists: 'var(--green)', new: 'var(--gold1)', peak: 'var(--amber)' };
const ST_REEL_SUB_KEYS = { plays: 'st_reel_sub_plays', days: 'st_reel_sub_days', artists: 'st_reel_sub_artists', new: 'st_reel_sub_new', peak: 'st_reel_sub_peak' };

function stSetReelMode(mode) {
  stReelMode = mode;
  document.querySelectorAll('#stStatsStrip .st-stat').forEach(el => {
    el.classList.toggle('active', el.dataset.reelMode === mode);
  });
  stRenderReel(_stCurrentPlays);
}

// Mirrors buildCard() in renderTimeMachine() — same card anatomy/classes, one
// entry type at a time instead of a combined songs+artists+albums toggle.
function stBuildReelCard(entry, i, suffix, songItems, artistItems) {
  const imgId = 'stReelImg-' + suffix + '-' + i;
  // Copy B of the deck — hidden when the reel is short enough not to loop.
  const dupe = suffix === 'b' ? ' dcreel-dupe' : '';
  const dateStr = d => `${t(ST_MONTH_KEYS[d.getMonth()]).substring(0, 3)} ${d.getDate()}`;

  if (entry.type === 'artist') {
    const prefKey = 'artist:' + entry.artist.toLowerCase();
    artistItems.push({ imgId, name: entry.artist, artist: entry.artist, album: '', title: '', prefKey });
    return '<div class="dc-card-inset tm-card tm-card-search' + dupe + '" data-type="artist" onclick="_tmShowArtistMenu(event,' + esc(JSON.stringify(entry.artist)) + ')">' +
      '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.artist)) + '</div></div>' +
      '<div class="tm-card-info">' +
      '<div class="tm-card-title">' + esc(entry.artist) + '</div>' +
      '<div class="tm-card-year">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
      '</div></div>';
  }

  if (entry.type === 'day') {
    const prefKey = 'song:' + entry.topArtist.toLowerCase() + '|||' + entry.topTitle.toLowerCase();
    songItems.push({ imgId, title: entry.topTitle, artist: entry.topArtist, album: entry.topAlbum, name: entry.topTitle, prefKey });
    return '<div class="dc-card-inset tm-card tm-card-song' + dupe + '" data-type="day" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.topTitle)) + ',' + esc(JSON.stringify(entry.topArtist)) + ',' + esc(JSON.stringify(entry.topAlbum)) + ')">' +
      '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.topTitle)) + '</div></div>' +
      '<div class="tm-card-info">' +
      '<div class="tm-card-title">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
      '<div class="tm-card-sub">' + esc(entry.topTitle + ' · ' + entry.topArtist) + '</div>' +
      '<div class="tm-card-year">' + entry.count.toLocaleString() + ' ' + esc(tUnit('plays', entry.count)) + '</div>' +
      '</div></div>';
  }

  // 'song' — Plays and Peak Day reels
  const sub = entry.artist + (entry.album && entry.album !== '—' ? ' · ' + entry.album : '');
  const prefKey = 'song:' + entry.artist.toLowerCase() + '|||' + entry.title.toLowerCase();
  songItems.push({ imgId, title: entry.title, artist: entry.artist, album: entry.album, name: entry.title, prefKey });
  return '<div class="dc-card-inset tm-card tm-card-song' + dupe + '" data-type="song" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.title)) + ',' + esc(JSON.stringify(entry.artist)) + ',' + esc(JSON.stringify(entry.album)) + ')">' +
    '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.title)) + '</div></div>' +
    '<div class="tm-card-info">' +
    '<div class="tm-card-title">' + esc(entry.title) + '</div>' +
    '<div class="tm-card-sub">' + esc(sub) + '</div>' +
    '<div class="tm-card-year">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
    '</div></div>';
}

// Mirrors loadTmBatch() in renderTimeMachine() — batches image fetches against
// the shared imgCache, mirroring the 'a' copy into the 'b' copy to halve calls.
async function stReelLoadBatch(pairs, type, loaderId) {
  const BATCH = 4;
  for (let i = 0; i < pairs.length; i += BATCH) {
    if (_stReelLoaderId !== loaderId) return;
    await Promise.all(pairs.slice(i, i + BATCH).map(async ([aItem, bItem]) => {
      if (_stReelLoaderId !== loaderId) return;
      const aEl = document.getElementById(aItem.imgId);
      if (!aEl) return;
      // Behind whatever the page is showing — see queueImg().
      await queueImg(() => aEl.isConnected && fetchAndInjectImage(aEl, aItem, type), true);
      const bEl = bItem && document.getElementById(bItem.imgId);
      if (bEl) bEl.innerHTML = aEl.innerHTML;
    }));
  }
}

// The whole active reel into the picker. Each mode carries a different card
// shape: Plays and Peak Day are already songs, Days cards stand for that day's
// top track, and Artists/Discoveries cards resolve to one recent play each.
function stReelAddToPlaylist() {
  const tracks = [];
  for (const e of (_stReelEntries || [])) {
    if (e.type === 'song')      tracks.push({ title: e.title, artist: e.artist, album: e.album });
    else if (e.type === 'day')  tracks.push({ title: e.topTitle, artist: e.topArtist, album: e.topAlbum });
    else if (e.type === 'artist') { const s = _tmArtistLastSongs(e.artist, 1)[0]; if (s) tracks.push(s); }
  }
  const label = t(ST_REEL_SUB_KEYS[stReelMode]);
  dcOpenPlaylistPicker(tracks, label, `${stGetPeriodLabel()} · ${label}`);
}

function stRenderReel(plays) {
  const section = document.getElementById('stReelSection');
  const track = document.getElementById('stReelTickerTrack');
  const outer = document.getElementById('stReelTickerOuter');
  if (!section || !track) return;

  const sub = document.getElementById('stReelSub');
  if (sub) sub.textContent = t(ST_REEL_SUB_KEYS[stReelMode]) + ' · ' + t('tm_hint');
  section.style.setProperty('--sc', ST_REEL_ACCENTS[stReelMode]);

  let entries;
  switch (stReelMode) {
    case 'days':    entries = stBuildReelDays(plays); break;
    case 'artists': entries = stBuildReelArtists(plays); break;
    case 'new':     entries = stBuildReelDiscoveries(plays); break;
    case 'peak':    entries = stBuildReelPeakDay(plays); break;
    default:        entries = stBuildReelPlays(plays); break;
  }

  // Held for the header's "＋ Playlist" button — see stReelAddToPlaylist().
  _stReelEntries = entries;
  const plBtn = document.getElementById('stReelPlBtn');
  if (plBtn) plBtn.style.display = entries.length ? '' : 'none';

  if (!entries.length) {
    if (outer) outer.style.display = 'none';
    track.innerHTML = `<div class="tm-empty">${t('st_no_data')}</div>`;
    return;
  }
  if (outer) outer.style.display = '';

  const aSongItems = [], aArtistItems = [], bSongItems = [], bArtistItems = [];
  const firstCopy = entries.map((e, i) => stBuildReelCard(e, i, 'a', aSongItems, aArtistItems)).join('');
  const secondCopy = entries.map((e, i) => stBuildReelCard(e, i, 'b', bSongItems, bArtistItems)).join('');
  track.innerHTML = firstCopy + secondCopy;
  // Same reel engine as the Time Machine, so this one drags too. See dcMountReel().
  dcMountReel(outer, track, Math.max(20, entries.length * 4));

  const ldr = ++_stReelLoaderId;
  const songPairs = aSongItems.map((a, i) => [a, bSongItems[i]]);
  const artistPairs = aArtistItems.map((a, i) => [a, bArtistItems[i]]);
  stReelLoadBatch(songPairs, 'song', ldr).then(() => stReelLoadBatch(artistPairs, 'artist', ldr));
}

function renderSoundtrack() {
  if (!allPlays.length) {
    document.getElementById('stStatsStrip').innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    return;
  }
  const plays = stGetPeriodPlays();
  _stCurrentPlays = plays;
  _stFacts = {};

  const navLabel = document.getElementById('stNavLabel');
  if (navLabel) {
    navLabel.textContent = stGetPeriodLabel();
    navLabel.title = stPeriodType === 'month' ? t('st_pick_month') : t('awx_pick_year');
  }

  const heroPeriod = document.getElementById('stHeroPeriod');
  if (heroPeriod) {
    const label = stGetPeriodLabel();
    heroPeriod.textContent = label;
    heroPeriod.setAttribute('data-text', label); // mirrored by the ::before stencil-echo effect
    heroPeriod.classList.toggle('st-hero-period--long', label.length > 7);
  }
  const heroEyebrow = document.getElementById('stHeroEyebrow');
  if (heroEyebrow) heroEyebrow.textContent = t('nav_soundtrack');
  const heroSubtitle = document.getElementById('stHeroSubtitle');
  if (heroSubtitle) {
    heroSubtitle.textContent = stPeriodType === 'alltime' ? t('st_subtitle_alltime') :
      stPeriodType === 'month' ? t('st_subtitle_month') : t('st_subtitle_year');
  }

  stRenderStats(plays);
  stRenderReel(plays);
  stRenderTopCharts(plays);
  stRenderActivity(plays);
  stRenderLoyalty(plays);
  stRenderDiscoveries(plays);
  stRenderMilestones(plays);
  stRenderStreaks(plays);
  stRenderGrammys(plays);
  stRenderGem(plays);

  // Reset replay
  const replayCanvas = document.getElementById('stReplayCanvas');
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  if (replayCanvas) replayCanvas.style.display = 'none';
  if (replayBtn) replayBtn.style.display = '';
  if (replayStop) replayStop.style.display = 'none';
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }

  // Close card preview
  const cardPreview = document.getElementById('stCardPreview');
  if (cardPreview) cardPreview.style.display = 'none';

  // Section visibility
  const isYear = stPeriodType === 'year';
  const isAlltime = stPeriodType === 'alltime';
  const loyaltySection = document.getElementById('stLoyaltySection');
  const activitySection = document.getElementById('stActivitySection');
  const replaySection = document.getElementById('stReplaySection');
  if (loyaltySection) loyaltySection.style.display = isYear ? '' : 'none';
  if (activitySection) activitySection.style.display = (isYear || isAlltime) ? '' : 'none';
  if (replaySection) replaySection.style.display = isYear ? '' : 'none';

  stRenderChapters();
  const storyLbl = document.getElementById('stStoryBtnLabel');
  if (storyLbl) storyLbl.textContent = stPeriodType === 'alltime' ? t('st_story_play_all') : t('st_story_play', { period: stGetPeriodLabel() });
  requestAnimationFrame(stSetupReveal);
}

// ── Chapters ──────────────────────────────────────────────────
// Each section is a chapter: a headline band (one big sentence over a dim
// picture) and the section's full detail under it. The section renderers
// leave the facts a band needs in _stFacts; stRenderChapters() writes the
// bands from them and numbers the chapters that are showing. The same
// bands are the screens of "Play your year".
let _stFacts = {};
let _stHeadToken = 0; // guards the band pictures against a newer render

// The headline sentence: translated text with ##N## standing in for the
// number, which is drawn larger in the chapter's colour.
function stHeadTitle(key, num, params) {
  const s = esc(t(key, Object.assign({ n: '##N##' }, params || {})));
  return s.replace('##N##', `<span class="st-chap-num">${esc(String(num))}</span>`);
}

function stFillHead(ch, o) {
  const head = document.getElementById('stHead_' + ch);
  if (!head) return;
  head.classList.toggle('st-chap-head--wide', !!o.right);
  head.innerHTML = `<div class="st-chap-bg"></div>
    <div class="st-chap-l">
      <div class="st-chap-label"><span class="st-chap-n"></span>${esc(o.label)}</div>
      <div class="st-chap-title">${o.title}</div>
      ${o.sub ? `<div class="st-chap-sub">${o.sub}</div>` : ''}
    </div>
    ${o.right ? `<div class="st-chap-r">${o.right}</div>` : ''}`;
  if (o.bg) stHeadBg(head, o.bg);
  if (o.thumbs) stHeadThumbs(head, o.thumbs);
}

// The dim picture behind a band: [type, name, artist] for getArtAuto()
function stHeadBg(head, args) {
  const bg = head.querySelector('.st-chap-bg');
  if (!bg || !args || !args[1]) return;
  const tok = _stHeadToken;
  queueImg(() => getArtAuto(...args).then(url => {
    if (url && tok === _stHeadToken && bg.isConnected) {
      bg.style.backgroundImage = `url("${sizedArtUrl(url, 600)}")`;
      bg.classList.add('is-loaded');
    }
  }), true);
}

// A collage of song covers behind a band, in place of the one picture:
// [{ title, artist }], most-played first. The list repeats to fill the band,
// shifted by a few each row so the same cover doesn't stack straight down.
// Same lookups as everywhere else, so covers already seen come from cache.
function stHeadCollage(head, songs) {
  const bg = head && head.querySelector('.st-chap-bg');
  if (!bg) return;
  bg.classList.add('st-chap-collage');
  const COLS = 12, ROWS = 4; // more than a band shows; the extra is cropped
  let html = '';
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) html += `<div class="st-collage-tile" data-s="${(c + r * 5) % songs.length}"></div>`;
  }
  bg.innerHTML = html;
  const tok = _stHeadToken;
  songs.forEach((s, si) => {
    if (!bg.querySelector(`[data-s="${si}"]`)) return;
    queueImg(() => getArtAuto('song', s.title, s.artist).then(url => {
      if (!url || tok !== _stHeadToken || !bg.isConnected) return;
      bg.querySelectorAll(`[data-s="${si}"]`).forEach(el => { el.style.backgroundImage = `url("${sizedArtUrl(url, 120)}")`; el.classList.add('is-loaded'); });
      bg.classList.add('is-loaded');
    }), true);
  });
}

// Small covers / portraits on the band's right: [{ type, name, artist }]
function stHeadThumbHtml(items, round) {
  return `<div class="st-chap-thumbs${round ? ' is-round' : ''}">${items.map((it, i) =>
    `<div class="st-chap-thumb" data-i="${i}" title="${esc(it.name)}"><div class="thumb-initials">${esc(initials(it.name))}</div></div>`).join('')}</div>`;
}
function stHeadThumbs(head, items) {
  const tok = _stHeadToken;
  items.forEach((it, i) => {
    queueImg(() => getArtAuto(it.type, it.name, it.artist).then(url => {
      const el = head.querySelector(`.st-chap-thumb[data-i="${i}"]`);
      if (url && tok === _stHeadToken && el) el.innerHTML = thumbHtml(url, it.name, false);
    }), true);
  });
}

// Chapter 9's band — on its own so stRefreshGrammys() can redraw it when a
// ballot finishes loading after the rest of the page.
function stFillGrammysHead() {
  const g = _stFacts.grammys;
  if (g && g.n) {
    stFillHead('grammys', {
      label: t('st_aw_title'),
      title: stHeadTitle('st_ch_aw_title', g.n),
      sub: esc(g.top),
      bg: ['artist', g.top],
    });
  } else {
    stFillHead('grammys', { label: t('st_aw_title'), title: esc(t('st_ch_gram_none')) });
  }
}

function stRenderChapters() {
  _stHeadToken++;
  const f = _stFacts;
  const periodLabel = stGetPeriodLabel();

  // The year: a grid of the period's albums that comes apart toward the text
  stRenderYearMosaic();

  // Top songs and artists
  if (f.topSongs && f.topSongs.length) {
    const s = f.topSongs[0];
    stFillHead('top', {
      label: t('st_ch_top_name'),
      title: esc(t('st_ch_top_title', { song: s.title })),
      sub: f.topArtist ? esc(t('st_ch_top_sub', { artist: f.topArtist })) : '',
      bg: ['song', s.title, s.artist],
      right: stHeadThumbHtml(f.topSongs.slice(0, 5).map(x => ({ name: x.title }))),
      thumbs: f.topSongs.slice(0, 5).map(x => ({ type: 'song', name: x.title, artist: x.artist })),
    });
  } else {
    stFillHead('top', { label: t('st_ch_top_name'), title: esc(t('st_no_data')) });
  }

  // Monthly Activity
  const a = f.activity;
  if (a) {
    stFillHead('activity', {
      label: t('st_activity_title'),
      title: esc(t('st_ch_act_title', { month: a.peak })),
      sub: esc(a.artist ? t('st_ch_act_sub', { plays: tCount('plays', a.plays), artist: a.artist }) : tCount('plays', a.plays)),
      // a few songs: a collage of their covers; too few to fill it: the artist's photo
      bg: a.artist && !(a.songs && a.songs.length >= 4) ? ['artist', a.artist] : null,
    });
    if (a.songs && a.songs.length >= 4) stHeadCollage(document.getElementById('stHead_activity'), a.songs);
  } else {
    stFillHead('activity', { label: t('st_activity_title'), title: esc(t('st_no_data')) });
  }

  // Loyalty
  const l = f.loyalty;
  if (l) {
    stFillHead('loyalty', {
      label: t('st_loyalty_title'),
      title: stHeadTitle('st_ch_loyal_title', l.score + '%'),
      sub: esc(l.verdict + ' · ' + l.sub),
      bg: l.artist ? ['artist', l.artist] : null,
    });
  } else {
    stFillHead('loyalty', { label: t('st_loyalty_title'), title: esc(t('st_ch_loyal_none')), sub: esc(t('st_loyalty_no_prev', { year: stYear - 1 })) });
  }

  // New Discoveries
  const d = f.discoveries;
  if (d && d.n) {
    stFillHead('new', {
      label: t('st_discoveries_title'),
      title: stHeadTitle('st_ch_new_title', d.n.toLocaleString()),
      sub: d.top[0] ? esc(t('st_ch_new_sub', { artist: d.top[0] })) : '',
      bg: d.top[0] ? ['artist', d.top[0]] : null,
      right: stHeadThumbHtml(d.top.slice(0, 5).map(x => ({ name: x })), true),
      thumbs: d.top.slice(0, 5).map(x => ({ type: 'artist', name: x })),
    });
  } else {
    stFillHead('new', { label: t('st_discoveries_title'), title: esc(t('st_discoveries_none')) });
  }

  // Milestones: the latest of your own totals, or failing that the artist ones
  const m = f.milestones || {};
  if (m.overall) {
    stFillHead('milestones', {
      label: t('st_ch_ms_name'),
      title: stHeadTitle('st_ch_ms_title', m.overall.nTarget.toLocaleString()),
      sub: esc(t('st_ch_ms_sub', { title: m.overall.rawTitle, date: fmtDate(tzDate(m.overall.date)) })),
      bg: ['song', m.overall.rawTitle, m.overall.rawArtist],
    });
  } else if (m.artistCount) {
    stFillHead('milestones', {
      label: t('st_ch_ms_name'),
      title: stHeadTitle('st_ch_ms_title_artist', m.artistCount.toLocaleString()),
      sub: m.artist ? esc(t('st_ch_ms_sub_artist', { n: m.artist.nTarget.toLocaleString(), artist: m.artist.rawArtist })) : '',
      bg: m.artist ? ['artist', m.artist.rawArtist] : null,
    });
  } else {
    stFillHead('milestones', { label: t('st_ch_ms_name'), title: esc(t('st_milestones_none')) });
  }

  // Streaks
  const s = f.streak;
  if (s && s.n) {
    stFillHead('streaks', {
      label: t('st_streaks_title'),
      title: stHeadTitle('st_ch_streak_title', s.n.toLocaleString()),
      sub: s.start ? esc(t('st_ch_streak_sub', { from: s.start, to: s.end })) : '',
      bg: s.artist ? ['artist', s.artist] : null,
    });
  } else {
    stFillHead('streaks', { label: t('st_streaks_title'), title: esc(t('st_no_data')) });
  }

  // Grammy winners (your own My Grammys picks)
  stFillGrammysHead();

  // Underrated Gem: written when its Last.fm lookup comes back (stRenderGem)
  stFillHead('gem', { label: t('st_gem_title'), title: esc(t('st_gem_loading')) });

  // Replay (Year view only) and Share carry their button in the band
  stFillHead('replay', {
    label: t('st_replay_title'),
    title: esc(t('st_ch_replay_title', { period: periodLabel })),
    sub: esc(t('st_ch_replay_sub')),
    bg: f.topArtist ? ['artist', f.topArtist] : null,
    right: `<button class="dc-btn dc-btn-main st-act-btn" id="stReplayBtn" onclick="stStartReplay()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13l10.5-6.5z"/></svg><span>${esc(t('st_replay_btn'))}</span></button>`,
  });
  stFillHead('share', {
    label: t('st_card_title'),
    title: esc(stPeriodType === 'alltime' ? t('st_ch_share_title_all') : t('st_ch_share_title', { period: periodLabel })),
    sub: esc(t('st_card_hint')),
    right: `<button class="dc-btn dc-btn-main st-act-btn" onclick="stOpenCard()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V4M7.5 8.5 12 4l4.5 4.5"/><path d="M5 13v5.5A1.5 1.5 0 0 0 6.5 20h11a1.5 1.5 0 0 0 1.5-1.5V13"/></svg><span>${esc(t('st_card_open'))}</span></button>`,
  });

  stNumberChapters();
}

// ── Play your year (phase 9 part 6, choice 1C) ─────────────────
// The chapters full screen, one headline per screen, like the Awards
// ceremony. Each screen is read from a chapter's band on the page, so the
// story and the scroll page always say the same thing. Tap / click the right
// side or press → / Space for the next screen, the left side or ← to go
// back, Esc or ✕ to leave.
let _stStory = null; // { screens, idx, lastFocus }

function stStoryScreens() {
  const screens = [];
  document.querySelectorAll('#soundtrackView .st-chap').forEach(ch => {
    if (ch.style.display === 'none' || ch.classList.contains('st-chap--quiet')) return;
    const kind = ch.dataset.ch;
    const head = ch.querySelector('.st-chap-head');
    if (!head) return;
    const bg = head.querySelector('.st-chap-bg');
    const pic = bg && bg.style.backgroundImage ? bg.style.backgroundImage.replace(/^url\(["']?|["']?\)$/g, '') : '';
    const labelEl = head.querySelector('.st-chap-label');
    const label = labelEl ? labelEl.textContent.replace(/\s+/g, ' ').trim() : '';
    const s = { kind, label, pic };
    if (kind === 'year') {
      s.title = esc(document.getElementById('stHeroPeriod')?.textContent || '');
      s.sub = esc(document.getElementById('stHeroSubtitle')?.textContent || '');
      // the five numbers under the year
      s.extra = `<div class="st-story-tiles">${[...document.querySelectorAll('#stStatsStrip .st-stat')].map(tile =>
        `<div><b>${esc(tile.querySelector('.st-stat-val')?.textContent || '')}</b><span>${esc(tile.querySelector('.st-stat-label')?.textContent || '')}</span></div>`).join('')}</div>`;
    } else {
      s.title = head.querySelector('.st-chap-title')?.innerHTML || '';
      s.sub = head.querySelector('.st-chap-sub')?.innerHTML || '';
      // covers / portraits from the band's right side
      const thumbs = head.querySelector('.st-chap-thumbs');
      if (thumbs) s.extra = thumbs.outerHTML;
      if (kind === 'artist') {
        const big = document.querySelector('#stFeaturedStats .st-fa-big');
        if (big) s.extra = `<div class="st-story-fact"><b>${esc(big.querySelector('.st-fa-big-num')?.textContent || '')}</b><span>${esc(big.querySelector('.st-fa-big-label')?.textContent || '')}</span></div>`;
      }
      if (kind === 'replay') s.action = { label: t('st_replay_btn'), run: 'stStoryClose();stJumpToReplay()' };
      if (kind === 'share') s.action = { label: t('st_card_open'), run: 'stStoryClose();stOpenCard()' };
    }
    s.color = getComputedStyle(ch).getPropertyValue('--sc').trim();
    screens.push(s);
  });
  return screens;
}

function stStoryOpen() {
  const screens = stStoryScreens();
  if (!screens.length) return;
  let ov = document.getElementById('stStory');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'stStory';
    ov.className = 'st-story';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    document.body.appendChild(ov);
    ov.addEventListener('click', e => {
      if (e.target.closest('button, a')) return;
      // a tap on the left third goes back, anywhere else goes on
      const r = ov.getBoundingClientRect();
      stStoryGo(e.clientX < r.left + r.width / 3 ? -1 : 1);
    });
  }
  _stStory = { screens, idx: 0, lastFocus: document.activeElement };
  ov.setAttribute('aria-label', t('st_story_play', { period: stGetPeriodLabel() }));
  document.body.classList.add('st-story-open');
  document.addEventListener('keydown', stStoryKey);
  ov.hidden = false;
  stStoryRender();
  ov.querySelector('.st-story-close')?.focus();
}

function stStoryClose() {
  const ov = document.getElementById('stStory');
  if (ov) { ov.hidden = true; ov.innerHTML = ''; }
  document.body.classList.remove('st-story-open');
  document.removeEventListener('keydown', stStoryKey);
  const back = _stStory && _stStory.lastFocus;
  _stStory = null;
  if (back && back.focus) back.focus();
}

function stStoryKey(e) {
  if (!_stStory) return;
  if (e.key === 'Escape') { e.preventDefault(); stStoryClose(); }
  else if (e.key === 'ArrowRight' || e.key === 'PageDown' || (e.key === ' ' && !e.target.closest('button'))) { e.preventDefault(); stStoryGo(1); }
  else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); stStoryGo(-1); }
  else if (e.key === 'Tab') {
    // keep the keyboard inside the story while it is open
    const f = [...document.querySelectorAll('#stStory button')];
    if (!f.length) return;
    const i = f.indexOf(document.activeElement);
    if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); }
    else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); }
  }
}

function stStoryGo(dir) {
  if (!_stStory) return;
  const n = _stStory.idx + dir;
  if (n < 0) return;
  if (n >= _stStory.screens.length) { stStoryClose(); return; } // past the last screen: done
  _stStory.idx = n;
  stStoryRender();
}

function stStoryRender() {
  const ov = document.getElementById('stStory');
  if (!ov || !_stStory) return;
  const { screens, idx } = _stStory;
  const s = screens[idx];
  const focusedNav = document.activeElement && document.activeElement.closest && document.activeElement.closest('#stStory') ? document.activeElement.dataset.nav : null;
  ov.style.setProperty('--sc', s.color || 'var(--accent)');
  ov.innerHTML = `
    <div class="st-story-bg"${s.pic ? ` style="background-image:url('${esc(s.pic)}')"` : ''}></div>
    <div class="st-story-top">
      <div class="st-story-bars" aria-hidden="true">${screens.map((_, i) => `<i class="${i < idx ? 'is-done' : i === idx ? 'is-on' : ''}"></i>`).join('')}</div>
      <div class="st-story-meta">
        <span>${esc(stGetPeriodLabel())} · ${esc(t('st_story_count', { n: idx + 1, total: screens.length }))}</span>
        <button type="button" class="dc-btn dc-btn-plain dc-btn-icon st-story-close" data-nav="close" onclick="stStoryClose()" aria-label="${esc(t('set_close'))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button>
      </div>
    </div>
    <div class="st-story-stage${s.kind === 'year' ? ' is-year' : ''}" aria-live="polite">
      ${s.pic && s.kind !== 'year' ? `<div class="st-story-art${s.kind === 'artist' || s.kind === 'new' || s.kind === 'activity' || s.kind === 'loyalty' || s.kind === 'streaks' || s.kind === 'replay' ? ' is-round' : ''}" style="background-image:url('${esc(s.pic)}')"></div>` : ''}
      <div class="st-story-text">
        <div class="st-story-label">${esc(s.label)}</div>
        <div class="st-story-title">${s.title}</div>
        ${s.sub ? `<div class="st-story-sub">${s.sub}</div>` : ''}
        ${s.extra || ''}
        ${s.action ? `<button type="button" class="dc-btn dc-btn-main st-story-action" onclick="${s.action.run}">${esc(s.action.label)}</button>` : ''}
      </div>
    </div>
    <div class="st-story-nav">
      <button type="button" class="dc-btn dc-btn-normal st-story-prev" data-nav="prev" onclick="stStoryGo(-1)"${idx === 0 ? ' disabled' : ''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg><span>${esc(t('st_nav_prev'))}</span></button>
      <button type="button" class="dc-btn dc-btn-main st-story-next" data-nav="next" onclick="stStoryGo(1)"><span>${esc(idx === screens.length - 1 ? t('st_story_done') : t('st_nav_next'))}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg></button>
    </div>`;
  // keep keyboard focus on the button that was used
  if (focusedNav) ov.querySelector(`[data-nav="${focusedNav}"]:not([disabled])`)?.focus();
  // the thumbs carry ids-free markup; nothing else to load
}

// A language change while Your Soundtrack is open: draw it again (the
// chapter headlines are written in JS) and keep an open story on its screen
function stOnLanguageChange() {
  if (typeof currentPeriod === 'undefined' || currentPeriod !== 'soundtrack' || !allPlays.length) return;
  const idx = _stStory ? _stStory.idx : null;
  renderSoundtrack();
  if (idx !== null && _stStory) {
    _stStory.screens = stStoryScreens();
    _stStory.idx = Math.min(idx, _stStory.screens.length - 1);
    stStoryRender();
  }
}

// ── Chapter 1's band: the period's albums as a grid that disintegrates ──
// The most-played albums fill the band's right side as a tight grid of
// covers; toward the left (where the big year sits) the tiles thin out,
// shrink, drift and fade, as if the grid were coming apart. The pattern is
// seeded from the period, so a re-render draws the same picture.
const ST_MOSAIC_MAX = 96; // enough distinct covers that the denser grid rarely repeats one
function stRenderYearMosaic() {
  const head = document.getElementById('stHeroCard');
  const box = document.getElementById('stYearMosaic');
  if (!head || !box) return;
  box.innerHTML = '';

  // albums by plays in this period ("—" means no album: skipped)
  const counts = new Map();
  for (const p of _stCurrentPlays) {
    if (!p.album || p.album === '—') continue;
    const ar = albumArtist(p);
    const k = ar.toLowerCase() + '|||' + p.album.toLowerCase();
    const rec = counts.get(k) || { album: p.album, artist: ar, n: 0 };
    rec.n++; counts.set(k, rec);
  }
  const albums = [...counts.values()].sort((a, b) => b.n - a.n).slice(0, ST_MOSAIC_MAX);
  if (!albums.length) return;

  const W = head.clientWidth || 900, H = head.clientHeight || 200;
  const size = W < 640 ? 36 : 46; // smaller tiles = more albums on the band
  const cols = Math.ceil(W / size), rows = Math.ceil(H / size);
  // small seeded random, so the same period always comes apart the same way
  let seed = 0;
  for (const ch of stGetPeriodLabel()) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };

  const cells = [];
  for (let c = cols - 1; c >= 0; c--) {
    for (let r = 0; r < rows; r++) {
      const x = (c + 0.5) / cols;                       // 0 = left edge, 1 = right edge
      const solid = Math.min(1, Math.max(0, (x - 0.2) / 0.5)); // 0 left of 20%, 1 right of 70%
      if (rnd() > solid * 0.9 + 0.08) continue;           // gaps grow toward the left
      const loose = 1 - solid;                            // how far this tile has come apart
      cells.push({
        left: c * size, top: r * size,
        scale: 1 - loose * (0.25 + rnd() * 0.45),
        dx: (rnd() - 0.7) * loose * size * 1.6,
        dy: (rnd() - 0.5) * loose * size * 1.2,
        rot: (rnd() - 0.5) * loose * 40,
        op: 0.95 - loose * 0.6,
        delay: Math.round((1 - x) * 700 + rnd() * 200),
      });
    }
  }
  const tok = _stHeadToken;
  box.innerHTML = cells.map((t, i) => {
    const a = albums[i % albums.length];
    return `<div class="st-mosaic-tile" data-a="${i % albums.length}" style="left:${t.left}px;top:${t.top}px;width:${size}px;height:${size}px;--tx:${t.dx.toFixed(1)}px;--ty:${t.dy.toFixed(1)}px;--rot:${t.rot.toFixed(1)}deg;--sc2:${t.scale.toFixed(2)};--op:${t.op.toFixed(2)};--d:${t.delay}ms" title="${esc(a.album)}"></div>`;
  }).join('');
  // one lookup per album, shared by every tile that shows it
  albums.forEach((a, ai) => {
    if (!box.querySelector(`[data-a="${ai}"]`)) return;
    queueImg(() => getArtAuto('album', a.album, a.artist, a.album).then(url => {
      if (!url || tok !== _stHeadToken) return;
      box.querySelectorAll(`[data-a="${ai}"]`).forEach(el => { el.style.backgroundImage = `url("${sizedArtUrl(url, 120)}")`; el.classList.add('is-loaded'); });
    }), true);
  });
}

// "Chapter 1 · …", counting only the chapters that are showing
function stNumberChapters() {
  let n = 0;
  document.querySelectorAll('#soundtrackView .st-chap').forEach(ch => {
    const on = ch.style.display !== 'none' && !ch.classList.contains('st-chap--quiet');
    if (on) n++;
    const el = ch.querySelector('.st-chap-n');
    if (el) el.textContent = on ? t('st_ch_label', { n }) + ' · ' : '';
  });
}

function stSetupReveal() {
  if (!('IntersectionObserver' in window)) {
    document.querySelectorAll('#soundtrackView .st-reveal').forEach(el => el.classList.add('st-in'));
    return;
  }
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('st-in'); obs.unobserve(e.target); } });
  }, { threshold: 0.07, rootMargin: '0px 0px -20px 0px' });
  document.querySelectorAll('#soundtrackView .st-reveal').forEach(el => {
    el.classList.remove('st-in');
    obs.observe(el);
  });
}

// ── Animated count-up ─────────────────────────────────────────
function stCountUp(id, target) {
  const el = document.getElementById(id);
  if (!el) return;
  if (target === 0) { el.textContent = '0'; return; }
  const dur = 900;
  const start = Date.now();
  const tick = () => {
    const p = Math.min((Date.now() - start) / dur, 1);
    const ease = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(ease * target).toLocaleString();
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

// ── Stats strip ───────────────────────────────────────────────
function stRenderStats(plays) {
  const ids = ['stStatPlaysVal','stStatDaysVal','stStatArtistsVal','stStatNewVal'];
  if (!plays.length) {
    ids.forEach(id => { const el = document.getElementById(id); if (el) el.textContent = '0'; });
    const peakEl = document.getElementById('stStatPeakVal'); if (peakEl) peakEl.textContent = '—';
    const peakNoteEl = document.getElementById('stStatPeakNote'); if (peakNoteEl) peakNoteEl.textContent = '';
    _stPeakDayDate = null;
    return;
  }

  const dayCounts = {};
  for (const p of plays) {
    const d = tzDateOf(p);
    const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    (dayCounts[dk] || (dayCounts[dk] = { count: 0, date: d })).count++;
  }
  const daySet = new Set(Object.keys(dayCounts));
  const artistSet = new Set(plays.map(p => p.artist.toLowerCase()));

  // New discoveries: each comma-split artist whose first-ever play falls in
  // this period, counted individually — same splitting rules (incl. hardwired
  // exceptions like "Tyler, The Creator") as the main charts use.
  const fsMap = stGetFirstSeenArtists();
  const splitArtistSet = new Set(plays.flatMap(p => p.artists || splitArtists(p.artist)));
  let newCount = 0;
  for (const a of splitArtistSet) {
    const fd = fsMap[a];
    if (!fd) continue;
    const ftz = tzDate(fd);
    const inPeriod = stPeriodType === 'alltime' ? true :
      stPeriodType === 'year' ? ftz.getFullYear() === stYear :
      ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
    if (inPeriod) newCount++;
  }

  // Peak day: the single busiest day within the period
  let peakDay = null;
  for (const dk of daySet) {
    if (!peakDay || dayCounts[dk].count > dayCounts[peakDay].count) peakDay = dk;
  }
  _stPeakDayDate = peakDay ? dayCounts[peakDay].date : null; // consumed by stBuildReelPeakDay

  stCountUp('stStatPlaysVal', plays.length);
  stCountUp('stStatDaysVal', daySet.size);
  stCountUp('stStatArtistsVal', artistSet.size);
  stCountUp('stStatNewVal', newCount);

  const peakEl = document.getElementById('stStatPeakVal');
  const peakNoteEl = document.getElementById('stStatPeakNote');
  if (peakEl && peakDay) {
    const pd = dayCounts[peakDay].date;
    peakEl.textContent = `${t(ST_MONTH_KEYS[pd.getMonth()]).substring(0, 3)} ${pd.getDate()}`;
    if (peakNoteEl) peakNoteEl.textContent = `${dayCounts[peakDay].count.toLocaleString()} ${tUnit('plays', dayCounts[peakDay].count)}`;
  }

  const noteEl = document.getElementById('stStatPlaysNote');
  if (noteEl) noteEl.textContent = daySet.size > 0 ? t('st_per_day', { n: Math.round(plays.length / daySet.size).toLocaleString() }) : '';
}

// Reuses the app's canonical first-seen map (built from each play's already
// comma-split .artists list, same as the New Entries/"NEW" badges on the
// main charts) so a discovery counts per individual artist, not per raw
// "Artist A, Artist B" credit string — with the same hardwired exceptions
// (e.g. "Tyler, The Creator") that splitArtists() respects everywhere else.
function stGetFirstSeenArtists() {
  if (!firstSeenMaps || !firstSeenMaps.artistFirst) firstSeenMaps = buildFirstSeenMaps();
  return firstSeenMaps.artistFirst;
}

// ── Top 50 Artists + Songs — iPod-style coverflow carousels ───
function stRenderTopCharts(plays) {
  // Each comma-split artist counts on its own (honoring the hardwired
  // exceptions in splitArtists, e.g. "Tyler, The Creator") — same rule
  // New Discoveries and the artist-modal rank use, so a "Artist A, Artist B"
  // credit doesn't get counted as one combined act.
  const artistCounts = {};
  for (const p of plays) {
    for (const a of (p.artists || splitArtists(p.artist))) artistCounts[a] = (artistCounts[a] || 0) + 1;
  }
  const topArtists = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, 50);

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 50);

  // Albums, the way the albums chart counts them: roll-up credit when singles
  // count toward their album on the charts, and singles / EPs that are
  // separated in Settings → Releases in lists of their own (not in Top Albums)
  const roll = rollupAffectsCharts();
  const albumMap = {};
  for (const p of plays) tallyAlbumPlay(albumMap, p, roll, k => {
    const [album, artist] = k.split('|||');
    return { key: k, album, artist, count: 0 };
  });
  const buckets = { album: [] };
  for (const typ of separatedTypes()) buckets[typ] = [];
  for (const e of Object.values(albumMap)) (buckets[albumBucketOf(e.album, e.artist)] || buckets.album).push(e);
  for (const b in buckets) buckets[b] = buckets[b].sort((a, b2) => b2.count - a.count).slice(0, 50);
  const albumItems = list => list.map(a => ({
    title: a.album, sub: a.artist, count: a.count, imgType: 'album', imgArgs: [a.album, a.artist],
    onCenterTap: () => openAlbumModal(a.key)
  }));

  const taEl = document.getElementById('stTopArtists');
  const tsEl = document.getElementById('stTopSongs');
  const tabEl = document.getElementById('stTopAlbums');
  if (tabEl) {
    if (buckets.album.length) stInitCoverflow(tabEl, albumItems(buckets.album), t('st_top_albums'));
    else tabEl.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
  }
  const typesEl = document.getElementById('stTopReleaseTypes');
  if (typesEl) {
    const TYPE_TITLE = { single: 'st_top_singles', ep: 'st_top_eps' };
    const types = separatedTypes().filter(typ => buckets[typ] && buckets[typ].length);
    typesEl.innerHTML = types.map(typ => `<div class="st-sub st-cf-section">
        <div class="st-sub-title">${esc(t(TYPE_TITLE[typ]))}</div>
        <div id="stTopType_${typ}"></div>
      </div>`).join('');
    types.forEach(typ => stInitCoverflow(document.getElementById('stTopType_' + typ), albumItems(buckets[typ]), t(TYPE_TITLE[typ])));
  }
  _stFacts.topSongs = topSongs.slice(0, 5);
  _stFacts.topArtist = topArtists[0] ? topArtists[0][0] : null;

  if (taEl) {
    if (topArtists.length) {
      stInitCoverflow(taEl, topArtists.map(([name, count]) => ({
        title: name, sub: '', count, imgType: 'artist', imgArgs: [name],
        onCenterTap: () => stOpenArtistModal(name)
      })), t('st_top_artists'));
    } else {
      taEl.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    }
  }

  if (tsEl) {
    if (topSongs.length) {
      stInitCoverflow(tsEl, topSongs.map(s => ({
        title: s.title, sub: s.artist, count: s.count, imgType: 'track', imgArgs: [s.title, s.artist]
      })), t('st_top_songs'));
    } else {
      tsEl.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    }
  }

  const featuredEl = document.getElementById('stFeaturedArtist');
  if (featuredEl) {
    if (topArtists.length) {
      featuredEl.style.display = '';
      stRenderFeaturedArtist(plays, topArtists[0][0], topArtists[0][1]);
    } else {
      featuredEl.style.display = 'none';
    }
  }
}

// ── Coverflow carousel engine ──────────────────────────────────
// Renders `items` (up to 50) as absolutely-positioned 3D cards inside
// `viewportEl` and wires up drag (mouse+touch via Pointer Events), wheel,
// and keyboard navigation. Images load lazily around whichever card is
// centered so a 50-entry list never fires 50 simultaneous image fetches.
function stInitCoverflow(viewportEl, items, label) {
  const n = items.length;
  const uid = viewportEl.id || 'cf' + Math.random().toString(36).slice(2);

  // Same prefKey convention as the chart tables, so a source cycled here (or there)
  // is remembered everywhere and shares the same image cache.
  items.forEach((it, i) => {
    it.imgId = `art-${uid}-${i}`;
    if (it.imgType === 'artist') {
      it.name = it.imgArgs[0];
      it.prefKey = 'artist:' + it.imgArgs[0].toLowerCase();
    } else if (it.imgType === 'album') {
      it.album = it.name = it.imgArgs[0];
      it.artist = it.imgArgs[1];
      it.prefKey = 'album:' + it.imgArgs[1].toLowerCase() + '|||' + it.imgArgs[0].toLowerCase();
    } else {
      it.artist = it.imgArgs[1];
      it.prefKey = 'song:' + it.imgArgs[1].toLowerCase() + '|||' + it.imgArgs[0].toLowerCase();
    }
  });

  viewportEl.innerHTML = `
    <div class="st-cf-viewport" tabindex="0" role="listbox" aria-label="${esc(label || '')}">
      <button type="button" class="st-cf-nav st-cf-nav-prev" aria-label="${esc(t('st_nav_prev'))}">&lsaquo;</button>
      <div class="st-cf-track">
        ${items.map((it, i) => `
          <div class="st-cf-card" id="idx-${uid}-${i}" data-idx="${i}" role="option">
            <div class="st-cf-art" id="${it.imgId}" title="Click to try the next image source"><div class="thumb-initials">${esc(initials(it.title))}</div></div>
            <span class="st-cf-rank${i < 3 ? ' st-cf-medal st-cf-medal-' + (i + 1) : ''}">${i + 1}</span>
          </div>`).join('')}
      </div>
      <button type="button" class="st-cf-nav st-cf-nav-next" aria-label="${esc(t('st_nav_next'))}">&rsaquo;</button>
    </div>
    <div class="st-cf-meta">
      <div class="st-cf-name"></div>
      <div class="st-cf-sub"></div>
      <div class="st-cf-count"></div>
    </div>
    <div class="st-cf-progress"><div class="st-cf-progress-fill"></div></div>`;

  const viewport = viewportEl.querySelector('.st-cf-viewport');
  const track = viewportEl.querySelector('.st-cf-track');
  const cards = Array.from(viewportEl.querySelectorAll('.st-cf-card'));
  const nameEl = viewportEl.querySelector('.st-cf-name');
  const subEl = viewportEl.querySelector('.st-cf-sub');
  const countEl = viewportEl.querySelector('.st-cf-count');
  const progressFill = viewportEl.querySelector('.st-cf-progress-fill');
  const prevBtn = viewportEl.querySelector('.st-cf-nav-prev');
  const nextBtn = viewportEl.querySelector('.st-cf-nav-next');

  const state = { pos: 0, stepPx: 96, dragging: false, startX: 0, startPos: 0, lastX: 0, lastT: 0, velocity: 0 };
  const loaded = new Set();
  const RADIUS = 3;

  function computeStep() {
    const w = viewport.clientWidth || 320;
    state.stepPx = Math.max(84, Math.min(174, w / 3.6));
  }
  computeStep();

  function ensureImages(centerIdx) {
    for (let off = -RADIUS; off <= RADIUS; off++) {
      const idx = centerIdx + off;
      if (idx < 0 || idx >= n || loaded.has(idx)) continue;
      loaded.add(idx);
      const it = items[idx];
      const artEl = cards[idx]?.querySelector('.st-cf-art');
      // Shares the same deezer→itunes→lastfm→youtube fallback chain (and per-item
      // source preference) as the chart tables. Routed through the same global
      // queue (queueImg) so requests are throttled like the tables — firing
      // all ~7 lookups at once floods the Deezer proxy, triggers rate-limiting,
      // and silently downgrades to lower-res itunes/lastfm art.
      if (artEl) queueImg(() => fetchAndInjectImage(artEl, it, it.imgType));
    }
  }

  function updateMeta() {
    const idx = Math.max(0, Math.min(n - 1, Math.round(state.pos)));
    const it = items[idx];
    if (!it) return;
    nameEl.textContent = it.title;
    subEl.textContent = it.sub || '';
    subEl.style.display = it.sub ? '' : 'none';
    countEl.textContent = `#${idx + 1} · ${it.count.toLocaleString()} ${tUnit('plays', it.count)}`;
    progressFill.style.width = n > 1 ? `${(idx / (n - 1)) * 100}%` : '100%';
    viewport.setAttribute('aria-activedescendant', `idx-${uid}-${idx}`);
  }

  function render() {
    const centerRounded = Math.round(state.pos);
    cards.forEach((card, i) => {
      const offset = i - state.pos;
      const abs = Math.abs(offset);
      if (abs > 9) {
        if (card.style.visibility !== 'hidden') card.style.visibility = 'hidden';
        return;
      }
      if (card.style.visibility === 'hidden') card.style.visibility = '';
      const angle = Math.max(-68, Math.min(68, -offset * 68));
      const scale = Math.max(0.5, 1 - Math.min(abs, 5) * 0.11);
      const tx = offset * state.stepPx;
      const tz = -Math.min(abs, 6) * 44;
      const op = Math.max(0, 1 - Math.min(abs, 6) * 0.17);
      card.style.transform = `translate(-50%,-50%) translateX(${tx}px) translateZ(${tz}px) rotateY(${angle}deg) scale(${scale})`;
      card.style.opacity = op;
      card.style.zIndex = String(1000 - Math.round(abs * 10));
      card.classList.toggle('is-center', i === centerRounded);
    });
    updateMeta();
  }

  function clampPos(p, elastic) {
    if (p < 0) return elastic ? p * 0.3 : 0;
    if (p > n - 1) return elastic ? (n - 1) + (p - (n - 1)) * 0.3 : n - 1;
    return p;
  }

  function goTo(idx, animate) {
    idx = Math.max(0, Math.min(n - 1, idx));
    track.classList.toggle('st-cf-animate', animate !== false);
    state.pos = idx;
    render();
    ensureImages(idx);
  }

  // ── Pointer drag (mouse + touch + pen, unified) ──────────────
  viewport.addEventListener('pointerdown', e => {
    if (e.target.closest('.st-cf-nav')) return;
    state.dragging = true;
    state.startX = e.clientX;
    state.startPos = state.pos;
    state.lastX = e.clientX;
    state.lastT = performance.now();
    state.velocity = 0;
    track.classList.remove('st-cf-animate');
    viewport.classList.add('is-dragging');
    viewport.setPointerCapture(e.pointerId);
  });

  viewport.addEventListener('pointermove', e => {
    if (!state.dragging) return;
    const deltaX = e.clientX - state.startX;
    const rawPos = state.startPos - deltaX / state.stepPx;
    state.pos = clampPos(rawPos, true);
    const now = performance.now();
    const dt = now - state.lastT;
    if (dt > 0) state.velocity = (e.clientX - state.lastX) / dt;
    state.lastX = e.clientX;
    state.lastT = now;
    render();
  });

  function endDrag(e) {
    if (!state.dragging) return;
    state.dragging = false;
    viewport.classList.remove('is-dragging');
    try { viewport.releasePointerCapture(e.pointerId); } catch (err) {}
    const moved = Math.abs(e.clientX - state.startX);
    if (moved < 4) {
      // treat as a click/tap rather than a drag
      // Pointer capture (set on pointerdown, above) retargets e.target to `viewport`
      // for pointerup, so a real hit-test at the pointer's coordinates is needed here.
      const hit = document.elementFromPoint(e.clientX, e.clientY);
      const card = hit && hit.closest('.st-cf-card');
      if (card) {
        const idx = Number(card.dataset.idx);
        const isCentered = idx === Math.round(state.pos);
        // Tapping the artwork of the already-centered card opens the image picker
        // instead of selecting it — the art is only hit-testable when centered (see CSS).
        if (isCentered && hit.closest('.st-cf-art')) {
          const it = items[idx];
          openImgPicker({
            imgid: it.imgId, type: it.imgType, prefkey: it.prefKey,
            name: it.imgType === 'artist' ? it.name : (it.title || it.name),
            artist: it.artist || '', album: it.album || ''
          });
          return;
        }
        if (isCentered && items[idx].onCenterTap) items[idx].onCenterTap();
        else goTo(idx, true);
        return;
      }
    }
    const flingSteps = -state.velocity * 140 / state.stepPx;
    goTo(Math.round(state.pos + flingSteps), true);
  }
  viewport.addEventListener('pointerup', endDrag);
  viewport.addEventListener('pointercancel', endDrag);

  // ── Wheel (mouse wheel + trackpad) — live scrub, settles on pause ──
  // Each event's contribution is capped to one card so a single physical
  // wheel notch (~100-120px in Chrome) can never overshoot past the next
  // entry — only sustained/continuous scrolling (trackpad) covers more ground.
  let wheelSettleTimer = null;
  viewport.addEventListener('wheel', e => {
    e.preventDefault();
    let delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (e.deltaMode === 1) delta *= 16;              // "line" mode (Firefox) → approx px
    else if (e.deltaMode === 2) delta *= viewport.clientHeight; // "page" mode
    track.classList.remove('st-cf-animate');
    const step = Math.sign(delta) * Math.min(Math.abs(delta) / 220, 1);
    state.pos = clampPos(state.pos + step, true);
    render();
    clearTimeout(wheelSettleTimer);
    wheelSettleTimer = setTimeout(() => goTo(Math.round(state.pos), true), 130);
  }, { passive: false });

  // ── Keyboard ───────────────────────────────────────────────
  viewport.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); goTo(Math.round(state.pos) + 1, true); }
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); goTo(Math.round(state.pos) - 1, true); }
    else if (e.key === 'PageDown') { e.preventDefault(); goTo(Math.round(state.pos) + 5, true); }
    else if (e.key === 'PageUp') { e.preventDefault(); goTo(Math.round(state.pos) - 5, true); }
    else if (e.key === 'Home') { e.preventDefault(); goTo(0, true); }
    else if (e.key === 'End') { e.preventDefault(); goTo(n - 1, true); }
  });

  prevBtn.addEventListener('click', () => goTo(Math.round(state.pos) - 1, true));
  nextBtn.addEventListener('click', () => goTo(Math.round(state.pos) + 1, true));

  window.addEventListener('resize', () => { computeStep(); render(); }, { passive: true });

  goTo(0, false);
}

// ── Featured #1 Artist — banner + accomplishment collage ──────
// Pulls a banner photo (same artist-image lookup used everywhere else, so it
// works regardless of data source) and computes a set of "wrapped"-style
// stats scoped to just this artist's plays within the active period.
function stRenderFeaturedArtist(periodPlays, artistName, totalCount) {
  const nameEl = document.getElementById('stFeaturedArtistName');
  const countEl = document.getElementById('stFeaturedArtistCount');
  if (nameEl) nameEl.textContent = artistName;
  const sharePctAll = periodPlays.length ? Math.round(totalCount / periodPlays.length * 100) : 0;
  if (countEl) countEl.textContent = t('st_ch_artist_sub', { plays: tCount('plays', totalCount), pct: sharePctAll });

  // Banner photo — cleared first so a stale image from the previous artist
  // never lingers while the new one loads.
  const bannerEl = document.getElementById('stFeaturedBanner');
  if (bannerEl) {
    bannerEl.style.backgroundImage = '';
    getArtAuto('artist', artistName).then(url => {
      if (bannerEl.isConnected && document.getElementById('stFeaturedArtistName')?.textContent === artistName) {
        bannerEl.style.backgroundImage = url ? `url("${url}")` : '';
      }
    });
  }

  const aLower = artistName.toLowerCase();
  const isThisArtist = p => (p.artists || splitArtists(p.artist)).some(a => a.toLowerCase() === aLower);
  const artistPlays = periodPlays.filter(isThisArtist).slice().sort((a, b) => a.date - b.date);

  const pad2 = n => String(n).padStart(2, '0');
  const dayKey = d => { const tz = tzDate(d); return `${tz.getFullYear()}-${pad2(tz.getMonth() + 1)}-${pad2(tz.getDate())}`; };

  // Active days + the single day this artist was played most
  const dayCounts = {};
  for (const p of artistPlays) {
    const dk = dayKey(p.date);
    (dayCounts[dk] || (dayCounts[dk] = { count: 0, date: tzDateOf(p) })).count++;
  }
  const dayKeys = Object.keys(dayCounts).sort();
  let peakDayKey = null;
  for (const dk of dayKeys) { if (!peakDayKey || dayCounts[dk].count > dayCounts[peakDayKey].count) peakDayKey = dk; }

  // Longest run of consecutive calendar days with at least one play
  let longestDayStreak = dayKeys.length ? 1 : 0, curDayStreak = 1;
  for (let i = 1; i < dayKeys.length; i++) {
    const diff = Math.round((new Date(dayKeys[i]) - new Date(dayKeys[i - 1])) / 86400000);
    curDayStreak = diff === 1 ? curDayStreak + 1 : 1;
    if (curDayStreak > longestDayStreak) longestDayStreak = curDayStreak;
  }

  // Longest back-to-back run of plays by this artist within the full listening
  // timeline for the period (i.e. how many songs in a row before switching artist).
  // A collab track counts as a continuation as long as this artist is one of its
  // comma-separated credits.
  const allSorted = periodPlays.slice().sort((a, b) => a.date - b.date);
  let longestPlayStreak = 0, curPlayStreak = 0;
  for (const p of allSorted) {
    if (isThisArtist(p)) { curPlayStreak++; if (curPlayStreak > longestPlayStreak) longestPlayStreak = curPlayStreak; }
    else curPlayStreak = 0;
  }
  // Longest back-to-back run of plays matching a narrower predicate (e.g. "this
  // exact album" or "this exact song") — breaks on anything that doesn't match,
  // whether that's a different artist or this artist playing something else.
  const computeStreak = matchFn => {
    let longest = 0, cur = 0;
    for (const p of allSorted) { if (matchFn(p)) { cur++; if (cur > longest) longest = cur; } else cur = 0; }
    return longest;
  };
  // Longest run of consecutive calendar days present in a set of day keys
  const dayStreakFor = daySet => {
    const keys = Array.from(daySet).sort();
    let longest = keys.length ? 1 : 0, cur = 1;
    for (let i = 1; i < keys.length; i++) {
      const diff = Math.round((new Date(keys[i]) - new Date(keys[i - 1])) / 86400000);
      cur = diff === 1 ? cur + 1 : 1;
      if (cur > longest) longest = cur;
    }
    return longest;
  };

  // Distinct songs + albums (album may be blank for some data sources — skip those)
  const songSet = new Set(artistPlays.map(p => songKey(p)));
  const albumSet = new Set(artistPlays.filter(p => p.album && p.album !== '—').map(p => p.album));

  // Hour of day this artist gets played the most
  const hourCounts = new Array(24).fill(0);
  for (const p of artistPlays) hourCounts[tzDateOf(p).getHours()]++;
  let peakHour = 0;
  for (let h = 1; h < 24; h++) { if (hourCounts[h] > hourCounts[peakHour]) peakHour = h; }
  // "5 PM" in English; Spanish and Portuguese write the hour as 17:00
  const fmtHour = h => {
    if (currentLang !== 'en') return `${h}:00`;
    const per = h < 12 ? 'AM' : 'PM'; const h12 = h % 12 === 0 ? 12 : h % 12; return `${h12} ${per}`;
  };
  const fmtDate = d => `${t(ST_MONTH_KEYS[d.getMonth()]).substring(0, 3)} ${d.getDate()}`;

  // Favorite album: the one this artist was played from the most within the
  // period (by total plays, not by streak length), plus that specific album's
  // own play streak and day streak.
  const albumCounts = {};
  for (const p of artistPlays) {
    if (!p.album || p.album === '—') continue;
    const rec = albumCounts[p.album] || (albumCounts[p.album] = { count: 0, days: new Set() });
    rec.count++; rec.days.add(dayKey(p.date));
  }
  let topAlbum = null, topAlbumRec = null;
  for (const alb in albumCounts) { if (!topAlbum || albumCounts[alb].count > topAlbumRec.count) { topAlbum = alb; topAlbumRec = albumCounts[alb]; } }
  const albumPlayStreak = topAlbum ? computeStreak(p => isThisArtist(p) && p.album === topAlbum) : 0;
  const albumDayStreak = topAlbum ? dayStreakFor(topAlbumRec.days) : 0;

  // Favorite song: the one played the most within the period, plus its own
  // play streak and day streak.
  const songCounts = {};
  for (const p of artistPlays) {
    const sk = songKey(p);
    const rec = songCounts[sk] || (songCounts[sk] = { title: p.title, count: 0, days: new Set(), key: sk });
    rec.count++; rec.days.add(dayKey(p.date));
  }
  const topSong = Object.values(songCounts).sort((a, b) => b.count - a.count)[0] || null;
  const songPlayStreak = topSong ? computeStreak(p => isThisArtist(p) && songKey(p) === topSong.key) : 0;
  const songDayStreak = topSong ? dayStreakFor(topSong.days) : 0;

  const avgPerDay = dayKeys.length ? Math.round(totalCount / dayKeys.length * 10) / 10 : 0;

  // ── Under the band (phase 9 part 6, choice 2A) ──────────────────
  // One big fact (songs in a row) beside the favourite album and song as
  // cover rows, then the rest as small centred stats under a divider. The
  // share of all your plays is in the band's subline, so it isn't repeated.
  const favRow = (kind, labelKey, name, notes) => `
    <div class="st-fa-fav" data-kind="${kind}">
      <div class="st-fa-fav-art" id="stFaArt_${kind}"><div class="thumb-initials">${esc(initials(name))}</div></div>
      <div class="st-fa-fav-info">
        <div class="st-fa-fav-label">${esc(t(labelKey))}</div>
        <div class="st-fa-fav-name" title="${esc(name)}">${esc(name)}</div>
        <div class="st-fa-fav-note">${notes.map(esc).join(' · ')}</div>
      </div>
    </div>`;
  const favs = [
    topAlbum ? favRow('album', 'st_feat_label_favorite_album', topAlbum, [
      t('st_feat_total_plays', { plays: tCount('plays', topAlbumRec.count) }),
      t('st_feat_note_play_streak_row', { n: albumPlayStreak }),
      t('st_feat_note_day_streak', { n: albumDayStreak }),
    ]) : '',
    topSong ? favRow('song', 'st_feat_label_favorite_song', topSong.title, [
      t('st_feat_total_plays', { plays: tCount('plays', topSong.count) }),
      t('st_feat_note_play_streak_row', { n: songPlayStreak }),
      t('st_feat_note_day_streak', { n: songDayStreak }),
    ]) : '',
  ].join('');

  // small stats: value, label and an optional note, centred, coloured numbers
  const small = [
    { v: peakDayKey ? fmtDate(dayCounts[peakDayKey].date) : '—', l: t('st_feat_label_most_played_day'), n: peakDayKey ? tCount('plays', dayCounts[peakDayKey].count) : '' },
    { v: longestDayStreak.toLocaleString(), l: t('st_feat_label_day_streak'), n: t('st_feat_note_consecutive_days') },
    { v: dayKeys.length.toLocaleString(), l: t('st_feat_label_days_played') },
    { v: songSet.size.toLocaleString(), l: t('st_feat_label_songs_played') },
    { v: albumSet.size.toLocaleString(), l: t('st_feat_label_albums_played') },
    { v: avgPerDay.toLocaleString(), l: t('st_feat_label_avg_per_day') },
    { v: dayKeys.length ? fmtHour(peakHour) : '—', l: t('st_feat_label_peak_hour') },
  ];

  const gridEl = document.getElementById('stFeaturedStats');
  if (gridEl) {
    gridEl.innerHTML = `
      <div class="st-fa-top">
        <div class="st-fa-big">
          <div class="st-fa-big-num">${longestPlayStreak.toLocaleString()}</div>
          <div class="st-fa-big-label">${esc(t('st_feat_note_play_streak'))}</div>
        </div>
        <div class="st-fa-favs">${favs}</div>
      </div>
      <div class="st-fa-stats">${small.map(s => `
        <div class="st-fa-stat">
          <div class="st-fa-stat-v">${esc(String(s.v))}</div>
          <div class="st-fa-stat-l">${esc(s.l)}</div>
          ${s.n ? `<div class="st-fa-stat-n">${esc(s.n)}</div>` : ''}
        </div>`).join('')}
      </div>`;
    // covers for the two favourite rows
    if (topAlbum) queueImg(() => getArtAuto('album', topAlbum, artistName, topAlbum).then(url => {
      const el = document.getElementById('stFaArt_album');
      if (url && el && document.getElementById('stFeaturedArtistName')?.textContent === artistName) el.innerHTML = thumbHtml(url, topAlbum, false);
    }));
    if (topSong) queueImg(() => getArtAuto('song', topSong.title, artistName).then(url => {
      const el = document.getElementById('stFaArt_song');
      if (url && el && document.getElementById('stFeaturedArtistName')?.textContent === artistName) el.innerHTML = thumbHtml(url, topSong.title, false);
    }));
  }
}

// ── Monthly Activity ──────────────────────────────────────────
function stRenderActivity(plays) {
  const el = document.getElementById('stActivityBars');
  if (!el) return;
  if (!plays.length) { el.innerHTML = ''; return; }

  const byMonth = {};        // 'YYYY-MM' -> play count
  const artistsByMonth = {}; // 'YYYY-MM' -> { artist: count }, powers the tap-to-inspect panel below
  for (const p of plays) {
    const d = tzDateOf(p);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    byMonth[key] = (byMonth[key] || 0) + 1;
    const am = artistsByMonth[key] || (artistsByMonth[key] = {});
    am[p.artist] = (am[p.artist] || 0) + 1;
  }
  const months = Object.keys(byMonth).sort();
  if (!months.length) { el.innerHTML = ''; return; }

  const total = plays.length;
  const max = Math.max(...Object.values(byMonth));
  const peakKey = months.reduce((a, b) => byMonth[a] >= byMonth[b] ? a : b);
  const lowKey = months.length > 1 ? months.reduce((a, b) => byMonth[a] <= byMonth[b] ? a : b) : null;

  const monthLabel = (mk, withYear) => {
    const [y, m] = mk.split('-');
    const name = t(ST_MONTH_KEYS[parseInt(m) - 1]);
    return withYear && y !== String(stYear) ? `${name} ${y}` : name;
  };
  // most-played artist for a given month, surfaced in the detail panel on tap
  const topArtistOf = key => {
    const counts = artistsByMonth[key] || {};
    let best = null, bestN = 0;
    for (const a in counts) { if (counts[a] > bestN) { best = a; bestN = counts[a]; } }
    return best ? { name: best, count: bestN } : null;
  };

  const barsHTML = months.map((mk, i) => {
    const [y, m] = mk.split('-');
    const label = t(ST_MONTH_KEYS[parseInt(m) - 1]).substring(0, 3);
    const count = byMonth[mk];
    const pct = Math.round(count / max * 100);
    const isPeak = mk === peakKey;
    const cls = (isPeak ? ' st-peak' : mk === lowKey ? ' st-low' : '') + (isPeak ? ' is-selected' : '');

    // month-over-month change vs the previous bar, shown as a mini arrow + in the detail panel.
    // For the first bar in the period (e.g. January of a year view), the previous month lives
    // outside the filtered `plays` array — reach into allPlays for that one calendar month instead.
    let prevMk = i > 0 ? months[i - 1] : null;
    let prevCount = prevMk ? byMonth[prevMk] : null;
    if (!prevMk) {
      const [y0, m0] = mk.split('-').map(Number);
      const prevDate = new Date(y0, m0 - 2, 1);
      const lookbackKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      const lookbackCount = allPlays.reduce((n, p) => {
        const d = tzDateOf(p);
        return n + (`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}` === lookbackKey ? 1 : 0);
      }, 0);
      // No plays at all in that prior month (e.g. it predates the listening history) — treat as
      // flat 0% rather than leaving the chip blank, so every bar keeps the same layout.
      prevMk = lookbackKey;
      prevCount = lookbackCount || null;
    }
    const deltaPct = prevMk ? (prevCount ? Math.round((count - prevCount) / prevCount * 100) : 0) : null;
    const deltaDir = deltaPct === null ? '' : deltaPct > 0 ? 'up' : deltaPct < 0 ? 'down' : 'flat';
    const deltaChip = deltaPct !== null
      ? `<span class="st-activity-delta st-${deltaDir}">${deltaDir === 'up' ? '▲' : deltaDir === 'down' ? '▼' : '•'}${Math.abs(deltaPct)}%</span>`
      : '';

    const sharePct = Math.round(count / total * 100);
    const top = topArtistOf(mk);

    return `<button type="button" class="st-activity-col${cls}" style="--i:${i}"
      data-label="${esc(monthLabel(mk, true))}"
      data-count="${count}"
      data-share="${sharePct}"
      data-delta="${deltaPct === null ? '' : Math.abs(deltaPct)}"
      data-delta-dir="${deltaDir}"
      data-prev-label="${prevMk ? esc(monthLabel(prevMk, true)) : ''}"
      data-artist="${top ? esc(top.name) : ''}"
      data-artist-count="${top ? top.count : ''}"
      onclick="stActivitySelectMonth(this)">
      <div class="st-activity-bar-wrap"><div class="st-activity-bar" style="height:${Math.max(pct,2)}%"></div></div>
      ${deltaChip}
      <div class="st-activity-label">${label}${months.length > 12 ? '<br><span class="st-activity-year">' + y + '</span>' : ''}</div>
      <div class="st-activity-count">${count.toLocaleString()}</div>
    </button>`;
  }).join('');

  // momentum: back half of the period vs the front half, ±10% before it's worth calling out
  let momentum = null;
  if (months.length > 2) {
    const mid = Math.ceil(months.length / 2);
    const avg = keys => keys.reduce((s, k) => s + byMonth[k], 0) / keys.length;
    const change = (avg(months.slice(mid)) - avg(months.slice(0, mid))) / avg(months.slice(0, mid));
    momentum = change > 0.1 ? 'up' : change < -0.1 ? 'down' : 'flat';
  }

  let caption = '';
  if (months.length > 1) {
    const peakName = monthLabel(peakKey, true);
    const lowName = monthLabel(lowKey, true);
    const momentumHTML = momentum ? `<span class="st-momentum-label st-${momentum}">${stIco(momentum)} ${t('st_activity_momentum')}: <strong>${t('st_activity_momentum_' + momentum)}</strong></span>` : '';
    caption = `<div class="st-activity-caption">
      <span class="st-peak-label">${stIco('trophy')} ${t('st_activity_peak')}: <strong>${peakName}</strong> (${byMonth[peakKey].toLocaleString()} ${tUnit('plays', byMonth[peakKey])})</span>
      <span class="st-low-label">${stIco('moon')} ${t('st_activity_low')}: <strong>${lowName}</strong> (${byMonth[lowKey].toLocaleString()} ${tUnit('plays', byMonth[lowKey])})</span>
      ${momentumHTML}
    </div>`;
  }

  el.innerHTML = `<div class="st-activity-chart">${barsHTML}</div>${caption}<div class="st-activity-detail"></div>`;
  const peakTop = topArtistOf(peakKey);
  // the band names the month in full ("April", or "April 2024" outside this year)
  const [peakY, peakM] = peakKey.split('-');
  const peakLong = t(_CR_MON_LONG[+peakM - 1]) + (peakY !== String(stYear) || stPeriodType === 'alltime' ? ' ' + peakY : '');
  // the peak month's most-played songs, for the cover collage behind the band
  const peakSongCounts = {};
  for (const p of plays) {
    const d = tzDateOf(p);
    if (`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}` !== peakKey) continue;
    const sk = songKey(p);
    if (!peakSongCounts[sk]) peakSongCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    peakSongCounts[sk].count++;
  }
  const peakSongs = Object.values(peakSongCounts).sort((a, b) => b.count - a.count).slice(0, 16);
  _stFacts.activity = { peak: peakLong, plays: byMonth[peakKey], artist: peakTop ? peakTop.name : null, songs: peakSongs };

  // pre-fill the detail panel with the peak month so the tap interaction is discoverable, not empty
  const defaultBtn = el.querySelector('.st-activity-col.is-selected') || el.querySelector('.st-activity-col');
  if (defaultBtn) stActivitySelectMonth(defaultBtn);
}

// Populates the Monthly Activity detail panel when a bar is tapped/clicked;
// reads the data-* attributes stamped onto each button in stRenderActivity
// rather than recomputing, so this stays a cheap DOM-only update.
function stActivitySelectMonth(btn) {
  const root = btn.closest('#stActivityBars');
  if (!root) return;
  root.querySelectorAll('.st-activity-col.is-selected').forEach(c => c.classList.remove('is-selected'));
  btn.classList.add('is-selected');
  const panel = root.querySelector('.st-activity-detail');
  if (!panel) return;
  const d = btn.dataset;

  const deltaHTML = d.delta
    ? `<span class="st-activity-detail-delta st-${d.deltaDir}">${d.deltaDir === 'up' ? '▲' : d.deltaDir === 'down' ? '▼' : '•'} ${d.delta}% ${t('st_activity_vs_prev', { month: d.prevLabel })}</span>`
    : '';
  const artistHTML = d.artist
    ? `<div class="st-activity-detail-artist">${stIco('mic')} ${t('st_activity_top_artist')}: <strong>${esc(d.artist)}</strong> · ${tCount('plays', parseInt(d.artistCount))}</div>`
    : '';

  panel.innerHTML = `
    <div class="st-activity-detail-head">
      <div class="st-activity-detail-month">${esc(d.label)}</div>
      <div class="st-activity-detail-nums">
        <span class="st-activity-detail-count">${tCount('plays', parseInt(d.count))}</span>
        <span class="st-activity-detail-share">${d.share}% ${t('st_activity_share_of_total')}</span>
        ${deltaHTML}
      </div>
    </div>
    ${artistHTML}
  `;
}

// ── Line icons (phase 9 part 6): the Soundtrack's emoji, redrawn ──
const ST_ICO = {
  star: '<path d="m12 3.5 2.6 5.3 5.9.9-4.3 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8-4.3-4.1 5.9-.9Z"/>',
  trophy: '<path d="M7 4h10v5a5 5 0 0 1-10 0Z"/><path d="M7 6H4.5a2.5 2.5 0 0 0 2.6 3M17 6h2.5a2.5 2.5 0 0 1-2.6 3M12 14v3.5M8.5 20.5h7l-1-3h-5Z"/>',
  moon: '<path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5Z"/>',
  up: '<path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/>',
  down: '<path d="M3 7l6 6 4-4 8 8"/><path d="M15 17h6v-6"/>',
  flat: '<path d="M4 12h15"/><path d="M14 7l5 5-5 5"/>',
  mic: '<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21M9 21h6"/>',
  note: '<path d="M9 18V5l11-2v13"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="17.5" cy="16" r="2.5"/>',
  disc: '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="2.5"/>',
  repeat: '<path d="M17 2l3 3-3 3"/><path d="M4 11V9a4 4 0 0 1 4-4h12"/><path d="M7 22l-3-3 3-3"/><path d="M20 13v2a4 4 0 0 1-4 4H4"/>',
  gem: '<path d="M6 3h12l3 6-9 12L3 9Z"/><path d="M3 9h18M9 3l3 6 3-6M12 9v12"/>',
  check: '<path d="M5 12.5l4.5 4.5L19 7.5"/>',
};
function stIco(name) {
  return `<svg class="st-ico" viewBox="0 0 24 24" aria-hidden="true">${ST_ICO[name] || ''}</svg>`;
}

// ── Sideways rows (phase 9 part 6, choice 3A) ─────────────────
// Still in Rotation and the streak records are rows you swipe sideways; on
// a screen with a mouse, ‹ › step about a screen of cards. The arrows hide
// when everything fits and dim at either end.
const ST_ROW_PREV = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg>';
const ST_ROW_NEXT = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg>';
function stRowHtml(trackCls, inner) {
  return `<div class="st-row">
    <button type="button" class="dc-btn dc-btn-normal dc-btn-icon st-row-nav st-row-prev" onclick="stRowStep(this,-1)" aria-label="${esc(t('st_nav_prev'))}">${ST_ROW_PREV}</button>
    <div class="st-row-track ${trackCls}">${inner}</div>
    <button type="button" class="dc-btn dc-btn-normal dc-btn-icon st-row-nav st-row-next" onclick="stRowStep(this,1)" aria-label="${esc(t('st_nav_next'))}">${ST_ROW_NEXT}</button>
  </div>`;
}
function stRowStep(btn, dir) {
  const track = btn.parentElement.querySelector('.st-row-track');
  if (!track) return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  track.scrollBy({ left: dir * Math.max(220, track.clientWidth * 0.8), behavior: reduce ? 'auto' : 'smooth' });
}
function stRowsInit(root) {
  root.querySelectorAll('.st-row').forEach(row => {
    const track = row.querySelector('.st-row-track');
    const prev = row.querySelector('.st-row-prev'), next = row.querySelector('.st-row-next');
    const update = () => {
      const max = track.scrollWidth - track.clientWidth;
      row.classList.toggle('is-static', max <= 2);
      prev.disabled = track.scrollLeft <= 2;
      next.disabled = track.scrollLeft >= max - 2;
    };
    track.addEventListener('scroll', update, { passive: true });
    update();
  });
}
window.addEventListener('resize', () => {
  const v = document.getElementById('soundtrackView');
  if (v && v.style.display !== 'none') v.querySelectorAll('.st-row-track').forEach(tr => tr.dispatchEvent(new Event('scroll')));
}, { passive: true });

// ── Loyalty Score ─────────────────────────────────────────────
function stRenderLoyalty(plays) {
  const el = document.getElementById('stLoyaltyBody');
  if (!el) return;
  const prevYear = stYear - 1;
  const prevPlays = allPlays.filter(p => tzDateOf(p).getFullYear() === prevYear);

  if (!prevPlays.length || !plays.length) {
    el.innerHTML = `<div class="st-empty">${t('st_loyalty_no_prev', { year: prevYear })}</div>`;
    return;
  }

  const topCounts = ps => {
    const counts = {};
    for (const p of ps) counts[p.artist.toLowerCase()] = (counts[p.artist.toLowerCase()] || 0) + 1;
    return counts;
  };
  const topSet = counts => new Set(Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([a]) => a));

  const prevCounts = topCounts(prevPlays);
  const curCounts = topCounts(plays);
  const prevTop = topSet(prevCounts);
  const curTop = topSet(curCounts);
  const returningKeys = [...curTop].filter(a => prevTop.has(a));
  const returning = returningKeys.length;

  const total = Math.min(curTop.size, 10);
  const score = total ? Math.round(returning / total * 100) : 0;
  const label = score >= 80 ? t('st_loyalty_die_hard') : score >= 60 ? t('st_loyalty_loyal') : score >= 40 ? t('st_loyalty_mixed') : t('st_loyalty_explorer');

  // Original-cased display name for each lowercased artist key
  const nameByKey = {};
  for (const p of plays) { const ak = p.artist.toLowerCase(); if (!nameByKey[ak]) nameByKey[ak] = p.artist; }

  // For each returning artist: this period's top 5 songs with play counts
  const returningArtists = returningKeys
    .sort((a, b) => curCounts[b] - curCounts[a])
    .map(ak => {
      const name = nameByKey[ak] || ak;
      const songCounts = {};
      for (const p of plays) {
        if (p.artist.toLowerCase() !== ak) continue;
        const sk = songKey(p);
        if (!songCounts[sk]) songCounts[sk] = { title: p.title, count: 0 };
        songCounts[sk].count++;
      }
      const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 5);
      return { name, plays: curCounts[ak], topSongs };
    });

  _stFacts.loyalty = { score, verdict: label, sub: t('st_loyalty_sub', { n: returning, year: prevYear }), artist: returningArtists[0] ? returningArtists[0].name : null };
  el.innerHTML = `
    <div class="st-loyalty-score">
      <div class="st-loyalty-ring" style="--pct:${score}">
        <div class="st-loyalty-pct">${score}<span class="st-loyalty-pct-sign">%</span></div>
      </div>
      <div class="st-loyalty-text">
        <div class="st-loyalty-verdict">${label}</div>
        <div class="st-loyalty-sub">${t('st_loyalty_sub', { n: returning, year: prevYear })}</div>
        <div class="st-loyalty-tally" aria-hidden="true">
          ${Array.from({ length: total }, (_, i) => `<span class="st-loyalty-dot${i < returning ? ' is-on' : ''}"></span>`).join('')}
        </div>
      </div>
    </div>
    ${returningArtists.length ? `
    <div class="st-loyalty-artists-title">${t('st_loyalty_artists_title')}</div>
    ${stRowHtml('st-loyalty-artists', returningArtists.map((a, i) => `
        <div class="st-loyalty-artist" style="--i:${i}">
          <div class="st-loyalty-artist-badge" aria-hidden="true">↻</div>
          <div class="st-loyalty-artist-head">
            <div class="st-loyalty-artist-avatar" id="stLoyaltyImg${i}"></div>
            <div class="st-loyalty-artist-meta">
              <div class="st-loyalty-artist-name">${esc(a.name)}</div>
              <div class="st-loyalty-artist-plays">${a.plays.toLocaleString()} ${tUnit('plays', a.plays)}</div>
            </div>
          </div>
          <div class="st-loyalty-artist-songs">
            ${a.topSongs.map((s, j) => `<div class="st-loyalty-song"><span class="st-loyalty-song-idx">${j + 1}</span><span class="st-loyalty-song-title">${esc(s.title)}</span><span class="st-loyalty-song-count">${s.count.toLocaleString()}</span></div>`).join('')}
          </div>
        </div>`).join(''))}` : ''}`;
  stRowsInit(el);

  // Queued through the shared queueImg() (same one the chart tables and coverflow
  // use) instead of firing all requests at once — a synchronous burst against
  // the Deezer proxy gets rate-limited, silently downgrading art to lower-res
  // itunes/lastfm fallbacks.
  returningArtists.forEach((a, i) => {
    queueImg(() => getArtAuto('artist', a.name).then(url => {
      const imgEl = document.getElementById('stLoyaltyImg' + i);
      if (imgEl) imgEl.innerHTML = thumbHtml(url, a.name, false);
    }));
  });
}

// ── New Discoveries ───────────────────────────────────────────
function stRenderDiscoveries(plays) {
  const el = document.getElementById('stDiscoveriesBody');
  if (!el) return;
  const fsMap = stGetFirstSeenArtists();
  const discovered = [];
  const seen = new Set();

  // Each comma-split artist is its own discovery (honoring the hardwired
  // exceptions in splitArtists), not the raw "Artist A, Artist B" credit.
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      if (seen.has(artist)) continue;
      seen.add(artist);
      const fd = fsMap[artist];
      if (!fd) continue;
      const ftz = tzDate(fd);
      const inPeriod = stPeriodType === 'alltime' ? true :
        stPeriodType === 'year' ? ftz.getFullYear() === stYear :
        ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
      if (inPeriod) discovered.push({ artist, date: fd });
    }
  }

  discovered.sort((a, b) => a.date - b.date);

  if (!discovered.length) {
    el.innerHTML = `<div class="st-empty">${t('st_discoveries_none')}</div>`;
    return;
  }

  // Weight the top 20% of discoveries by this period's play count so their
  // bubbles reappear more often in the animated loop than the rest.
  const playCountByArtist = {};
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      playCountByArtist[artist] = (playCountByArtist[artist] || 0) + 1;
    }
  }
  discovered.forEach(d => { d.count = playCountByArtist[d.artist] || 0; });
  const topCutoff = Math.max(1, Math.round(discovered.length * 0.2));
  const featuredSet = new Set([...discovered].sort((a, b) => b.count - a.count).slice(0, topCutoff).map(d => d.artist));
  discovered.forEach(d => { d.weight = featuredSet.has(d.artist) ? 3 : 1; });
  _stFacts.discoveries = { n: discovered.length, top: [...discovered].sort((a, b) => b.count - a.count).slice(0, 5).map(d => d.artist) };

  el.innerHTML = `
    <div class="st-discoveries-count">${t('st_discoveries_count', { n: discovered.length })}</div>
    <div class="st-bubbles" id="stDiscoveriesBubbles"></div>`;

  // the pop-up's ‹ › order: most played first
  _stDiscovered = [...discovered].sort((a, b) => b.count - a.count || a.date - b.date).map(d => d.artist);
  stStartBubbles(discovered);
}

// ── Discoveries "bubble tank" — floating artist portraits that rise,
// fade out at the top, and get recycled so the whole discovered list
// (not just the first dozen) keeps cycling through for as long as the
// section stays on screen. ──────────────────────────────────────────
function stShuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Repeats each item `weight` times (default 1) before shuffling, so a
// weighted item comes up proportionally more often over one full cycle
// of the deck — used to make top-played discoveries reappear more.
function stBuildWeightedDeck(items) {
  const deck = [];
  for (const item of items) {
    const w = item.weight || 1;
    for (let i = 0; i < w; i++) deck.push(item);
  }
  return stShuffle(deck);
}

function stSpawnBubble(container, artist, isStatic) {
  const uid = 'stBubble' + (_stBubbleUid++);
  const size = 64 + Math.floor(Math.random() * 40);   // 64–104px, for a bit of depth variety
  const dur = (13 + Math.random() * 6).toFixed(1);     // 13–19s rise
  const drift = Math.round(Math.random() * 50 - 25);   // -25..25px sideways sway
  const x = (5 + Math.random() * 90).toFixed(1);       // keep clear of the edges

  const bubble = document.createElement('div');
  bubble.className = 'st-bubble';
  bubble.style.setProperty('--size', size + 'px');
  bubble.style.setProperty('--x', x + '%');
  bubble.style.setProperty('--drift', drift + 'px');
  bubble.style.setProperty('--dur', dur + 's');
  bubble.setAttribute('role', 'button');
  bubble.setAttribute('tabindex', '0');
  bubble.setAttribute('aria-label', artist);
  // Initials sit in the circle until the picture arrives (or if none is found),
  // so a bubble is never an empty ring.
  bubble.innerHTML = `<div class="st-bubble-avatar" id="${uid}"><div class="thumb-initials">${esc(initials(artist))}</div></div><div class="st-bubble-name">${esc(artist)}</div>`;
  container.appendChild(bubble);

  if (!isStatic) bubble.addEventListener('animationend', () => bubble.remove());

  bubble.addEventListener('click', () => stPopBubble(bubble, artist));
  bubble.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); stPopBubble(bubble, artist); }
  });

  // Queued through the shared queueImg() (see stLoyaltyImg above) — under
  // prefers-reduced-motion the initial static batch spawns up to 10 bubbles
  // in one synchronous forEach, which would otherwise fire 10 concurrent
  // Deezer lookups at once.
  queueImg(() => getArtAuto('artist', artist).then(url => {
    const avatarEl = document.getElementById(uid);
    if (!avatarEl) return;
    avatarEl.innerHTML = thumbHtml(url, artist, false);
    // a lazy picture inside a moving bubble can stay unloaded, leaving an
    // empty ring, so load it straight away
    avatarEl.querySelector('img')?.setAttribute('loading', 'eager');
  }));
}

// Tapping/clicking a bubble "pops" it (a quick scale-and-ring burst, skipped
// under prefers-reduced-motion) and opens the artist detail modal, scoped to
// whatever period is currently rendered (_stCurrentPlays) — a discovery and
// its stats should describe the same window.
function stPopBubble(bubble, artist) {
  if (bubble.dataset.popped) return;
  bubble.dataset.popped = '1';
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) {
    bubble.remove();
    stOpenArtistModal(artist);
    return;
  }
  bubble.classList.add('st-bubble-pop');
  setTimeout(() => bubble.remove(), 450);
  setTimeout(() => stOpenArtistModal(artist), 200);
}

/* ── Discovery pop-up (2026-10-25 redo) ─────────────────────────────────────
   Clicking a New Discoveries bubble opens this. Besides the numbers it lets
   the user do something with the artist:
     • ▶ store samples (the chart's ▶ — rows carry data-ea-* attributes, so
       the shared _eaPlaySample listeners serve them), and Spotify / YouTube /
       Last.fm searches for the artist, each song and each album
     • a plays-per-day chart since the discovery, with a trend word
     • "How you found them": the first play ever and what came right before
     • album covers, a next-goal bar (plays to the next top-N), similar
       artists from Deezer matched against the user's own library
     • ‹ › to step through the period's discoveries (also ← → keys)
     • a share card, drawn straight on a canvas (no html2canvas, so none of
       its colour / blur / letter-spacing traps)
   Works the same for Last.fm, Sheets and CSV: everything is read from plays. */

let _stDiscovered = [];            // the period's discoveries, most played first — the ‹ › order
let _stAmArtist = null;            // the artist the pop-up shows
let _stAmInfo = null;              // its numbers, kept for the share card
const _stAmRelated = new Map();    // lower-case artist → Promise of Deezer's similar artists (null = failed)
let _stAmLib = null, _stAmLibLen = -1;   // all-time plays per artist (lower-case name → { name, count })
let _stAmCard = null;              // { artist, file } share image ready ahead of a tap (touch screens)

const _ST_AM_YT_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M23 7.2a3 3 0 0 0-2.1-2.1C19 4.6 12 4.6 12 4.6s-7 0-8.9.5A3 3 0 0 0 1 7.2 31 31 0 0 0 .5 12a31 31 0 0 0 .5 4.8 3 3 0 0 0 2.1 2.1c1.9.5 8.9.5 8.9.5s7 0 8.9-.5a3 3 0 0 0 2.1-2.1 31 31 0 0 0 .5-4.8 31 31 0 0 0-.5-4.8zM9.7 15.1V8.9l5.8 3.1-5.8 3.1z"/></svg>';
const _ST_AM_LF_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M10.6 17.2l-.8-2.2s-1.3 1.5-3.3 1.5c-1.8 0-3-1.5-3-4 0-3.2 1.6-4.3 3.2-4.3 2.3 0 3 1.5 3.6 3.4l.8 2.6c.8 2.4 2.3 4.4 6.8 4.4 3.2 0 5.4-1 5.4-3.6 0-2.1-1.2-3.2-3.4-3.7l-1.6-.4c-1.1-.2-1.4-.7-1.4-1.4 0-.9.7-1.4 1.8-1.4 1.2 0 1.9.5 2 1.5l2.6-.3c-.2-2.3-1.8-3.3-4.4-3.3-2.3 0-4.5.9-4.5 3.6 0 1.7.8 2.8 2.9 3.3l1.7.4c1.3.3 1.7.8 1.7 1.5 0 .9-.9 1.3-2.6 1.3-2.5 0-3.6-1.3-4.2-3.2l-.8-2.6C12.4 7.4 10.9 6 7.6 6 4 6 .8 8.3.8 12.6c0 4.1 2.1 6.4 5.9 6.4 3.1 0 3.9-1.8 3.9-1.8z"/></svg>';
const _ST_AM_SHARE_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 15V3"/><path d="m7 8 5-5 5 5"/><path d="M20 15v4a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-4"/></svg>';

// Search links: Spotify, YouTube (and Last.fm for the artist). Plain links,
// so middle-click and open-in-new-tab work too.
function _stAmLinks(q, withLastfm) {
  const e = encodeURIComponent(q);
  const sp = esc(t('tm_action_spotify')), yt = esc(t('awx_yt')), lf = esc(t('st_am_lastfm'));
  return `<a class="st-am-link st-am-link--sp" href="https://open.spotify.com/search/${e}" target="_blank" rel="noopener" title="${sp}" aria-label="${sp}">${_EA_SP_SVG}</a>`
    + `<a class="st-am-link st-am-link--yt" href="https://www.youtube.com/results?search_query=${e}" target="_blank" rel="noopener" title="${yt}" aria-label="${yt}">${_ST_AM_YT_SVG}</a>`
    + (withLastfm ? `<a class="st-am-link st-am-link--lf" href="https://www.last.fm/music/${e}" target="_blank" rel="noopener" title="${lf}" aria-label="${lf}">${_ST_AM_LF_SVG}</a>` : '');
}

// Is the Soundtrack period still running? (a goal only makes sense then)
function _stAmPeriodRunning() {
  const now = tzNow();
  if (stPeriodType === 'alltime') return true;
  if (stPeriodType === 'year') return stYear === now.getFullYear();
  return stYear === now.getFullYear() && stMonth === now.getMonth() + 1;
}

// Last day of the Soundtrack period, or today while it is running
function _stAmPeriodEndDs() {
  if (_stAmPeriodRunning()) return localDateStr(tzNow());
  if (stPeriodType === 'year') return `${stYear}-12-31`;
  const last = new Date(stYear, stMonth, 0).getDate();
  return `${stYear}-${String(stMonth).padStart(2, '0')}-${String(last).padStart(2, '0')}`;
}

// Plays per day from the first play to the period's end, as small bars.
// Over ~4 months the bars become weeks so they stay readable.
function _stAmChartHtml(dayCounts, firstDs, peakDay) {
  const endDs = _stAmPeriodEndDs();
  const days = [];
  for (let d = new Date(firstDs + 'T12:00:00'); ; d.setDate(d.getDate() + 1)) {
    const ds = localDateStr(d);
    if (ds > endDs || days.length > 4000) break;
    days.push(ds);
  }
  if (!days.length) days.push(firstDs);
  const byWeek = days.length > 120;
  const vals = [];
  if (byWeek) for (let i = 0; i < days.length; i += 7) vals.push(days.slice(i, i + 7).reduce((s, ds) => s + (dayCounts[ds] || 0), 0));
  else days.forEach(ds => vals.push(dayCounts[ds] || 0));
  const max = Math.max(1, ...vals);
  const n = vals.length;
  const bars = vals.map((v, i) => {
    if (!v) return `<rect class="st-am-bar0" x="${i + 0.15}" y="99" width="0.7" height="1"/>`;
    const h = Math.max(6, v / max * 100);
    return `<rect class="st-am-bar" x="${i + 0.15}" y="${100 - h}" width="0.7" height="${h}"><title>${v}</title></rect>`;
  }).join('');

  // Trend: the later half against the earlier half of the days since the discovery
  let trend = 'new';
  if (days.length >= 14) {
    const half = Math.floor(days.length / 2);
    const a = days.slice(0, half).reduce((s, ds) => s + (dayCounts[ds] || 0), 0);
    const b = days.slice(half).reduce((s, ds) => s + (dayCounts[ds] || 0), 0);
    const recent = days.slice(-30).some(ds => dayCounts[ds]);
    trend = !recent ? 'quiet' : b > a * 1.25 ? 'up' : b < a * 0.8 ? 'down' : 'steady';
  }
  const fmt = ds => new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  return `
    <div class="st-am-card st-am-chart">
      <div class="st-am-card-head">
        <span class="st-am-h">${t('st_am_chart_title')}</span>
        <span class="st-am-trend st-am-trend--${trend}">${t('st_am_trend_' + trend)}</span>
      </div>
      <svg class="st-am-bars" viewBox="0 0 ${n} 100" preserveAspectRatio="none" role="img" aria-label="${esc(t('st_am_chart_title'))}">${bars}</svg>
      <div class="st-am-axis"><span>${fmt(days[0])}</span>${peakDay ? `<span class="st-am-peak">${t('st_am_best_day', { date: fmt(peakDay), n: dayCounts[peakDay], unit: tUnit('plays', dayCounts[peakDay]) })}</span>` : ''}<span>${fmt(days[days.length - 1])}</span></div>
    </div>`;
}

// Next goal: plays still needed to pass the artist at the next top-N mark
function _stAmGoalHtml(rank, totalPlays, ranked) {
  if (!rank) return '';
  const total = ranked.length;
  if (!_stAmPeriodRunning()) {
    return `<div class="st-am-card st-am-goal"><div class="st-am-goal-line"><span class="st-am-h">${t('st_am_goal_title')}</span><span class="st-am-goal-txt">${t('st_am_goal_done', { rank, total: total.toLocaleString() })}</span></div></div>`;
  }
  if (rank === 1) {
    return `<div class="st-am-card st-am-goal"><div class="st-am-goal-line"><span class="st-am-h">${t('st_am_goal_title')}</span><span class="st-am-goal-txt">${t('st_am_goal_top')}</span></div><div class="st-am-meter"><i style="width:100%"></i></div></div>`;
  }
  const TIERS = [1000, 500, 250, 100, 50, 25, 10, 5, 3, 1];
  const top = TIERS.find(n => n < rank);
  const need = Math.max(1, ranked[top - 1][1] - totalPlays + 1);
  const pct = Math.max(4, Math.min(100, totalPlays / (totalPlays + need) * 100));
  const txt = top === 1 ? t('st_am_goal_one', { n: need, unit: tUnit('plays', need) })
                        : t('st_am_goal', { n: need, unit: tUnit('plays', need), top });
  return `
    <div class="st-am-card st-am-goal">
      <div class="st-am-goal-line"><span class="st-am-h">${t('st_am_goal_title')}</span><span class="st-am-goal-txt">${txt}</span></div>
      <div class="st-am-meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><i style="width:${pct.toFixed(1)}%"></i></div>
      <div class="st-am-goal-sub"><span>${t('st_am_goal_now', { rank, total: total.toLocaleString() })}</span><span>${totalPlays.toLocaleString()} → ${(totalPlays + need).toLocaleString()}</span></div>
    </div>`;
}

// How they were found: the very first play (all time), whether it came in
// through a collab, and what played in the hour(s) just before it
function _stAmOriginHtml(artist) {
  let first = null;
  for (const p of allPlays) {
    if ((p.artists || splitArtists(p.artist)).includes(artist) && (!first || +p.date < +first.date)) first = p;
  }
  if (!first) return '';
  const t0 = +first.date;
  const before = [];
  let firstWeek = 0;
  for (const p of allPlays) {
    const d = +p.date;
    // same listening session = up to 3 hours before
    if (d < t0 && d >= t0 - 3 * 3600e3) before.push(p);
    if (d >= t0 && d < t0 + 7 * 86400e3 && (p.artists || splitArtists(p.artist)).includes(artist)) firstWeek++;
  }
  before.sort((a, b) => b.date - a.date);
  const when = tzDate(first.date);
  const dateTxt = when.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
  const timeTxt = when.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  const others = (first.artists || splitArtists(first.artist)).filter(a => a !== artist);
  const prev = before.slice(0, 3);
  return `
    <div class="st-am-card st-am-origin">
      <div class="st-am-h">${t('st_am_origin_title')}</div>
      <div class="st-am-origin-first">
        <span class="st-am-origin-dot" aria-hidden="true"></span>
        <div class="st-am-origin-txt">
          <div class="st-am-origin-song">${esc(first.title)}</div>
          <div class="st-am-origin-meta">${t('st_am_origin_when', { date: dateTxt, time: timeTxt })}${others.length ? ' · ' + t('st_am_origin_via', { names: esc(others.join(', ')) }) : ''}</div>
        </div>
      </div>
      ${prev.length ? `<div class="st-am-origin-label">${t('st_am_origin_before')}</div>
      <ol class="st-am-origin-prev">${prev.map(p => `<li><span class="st-am-origin-pt">${esc(p.title)}</span><span class="st-am-origin-pa">${esc(p.artist)}</span></li>`).join('')}</ol>`
      : `<div class="st-am-origin-label">${t('st_am_origin_fresh')}</div>`}
      <div class="st-am-origin-week">${t('st_am_origin_week', { n: firstWeek, unit: tUnit('plays', firstWeek) })}</div>
    </div>`;
}

// All-time plays per artist, built once per library size
function _stAmLibrary() {
  if (_stAmLib && _stAmLibLen === allPlays.length) return _stAmLib;
  const m = new Map();
  for (const p of allPlays) {
    for (const a of (p.artists || splitArtists(p.artist))) {
      const k = a.toLowerCase();
      const e = m.get(k);
      if (e) e.count++; else m.set(k, { name: a, count: 1 });
    }
  }
  _stAmLib = m; _stAmLibLen = allPlays.length;
  return m;
}

// Deezer's similar artists (through the deezer-proxy), memoised per artist.
// Only an exact name match is trusted: "MUNA" must not become "Muna".
function _stAmRelatedFor(artist) {
  const k = artist.toLowerCase();
  if (!_stAmRelated.has(k)) {
    _stAmRelated.set(k, (async () => {
      const r = await deezerFetch(`search/artist?q=${encodeURIComponent(artist)}&limit=10`);
      if (!r.ok) throw new Error('deezer ' + r.status);
      const list = (await r.json())?.data || [];
      const hit = list.filter(a => (a.name || '').toLowerCase() === k).sort((a, b) => (b.nb_fan || 0) - (a.nb_fan || 0))[0];
      if (!hit) return [];
      const r2 = await deezerFetch(`artist/${hit.id}/related?limit=40`);
      if (!r2.ok) throw new Error('deezer ' + r2.status);
      return ((await r2.json())?.data || []).map(a => ({ name: a.name, pic: a.picture_medium || '' }));
    })().catch(() => { _stAmRelated.delete(k); return null; }));
  }
  return _stAmRelated.get(k);
}

async function _stAmFillSimilar(artist) {
  const el = document.getElementById('stAmSimilar');
  if (!el) return;
  const rel = await _stAmRelatedFor(artist);
  if (_stAmArtist !== artist || !document.getElementById('stAmSimilar')) return;
  if (!rel || !rel.length) { el.innerHTML = `<div class="st-am-muted">${t('st_am_similar_none')}</div>`; return; }
  const lib = _stAmLibrary();
  const own = artist.toLowerCase();
  const loved = [], fresh = [];
  for (const a of rel) {
    const k = a.name.toLowerCase();
    if (k === own) continue;
    const mine = lib.get(k);
    if (mine) loved.push({ ...a, name: mine.name, count: mine.count }); else fresh.push(a);
  }
  loved.sort((a, b) => b.count - a.count);
  const pic = a => a.pic ? `<img src="${esc(a.pic)}" alt="" loading="lazy" referrerpolicy="no-referrer">` : `<span>${esc(initials(a.name))}</span>`;
  // Artists already in the library open their full profile; new ones search Spotify
  const lovedHtml = loved.slice(0, 6).map(a => `<button type="button" class="st-am-sim" data-st-am-profile="${esc(a.name)}" title="${esc(t('st_am_open_profile', { name: a.name }))}"><span class="st-am-sim-pic">${pic(a)}</span><span class="st-am-sim-name">${esc(a.name)}</span><span class="st-am-sim-sub">${a.count.toLocaleString()} ${tUnit('plays', a.count)}</span></button>`).join('');
  const freshHtml = fresh.slice(0, 6).map(a => `<a class="st-am-sim st-am-sim--new" href="https://open.spotify.com/search/${encodeURIComponent(a.name)}" target="_blank" rel="noopener" title="${esc(t('tm_action_spotify'))}"><span class="st-am-sim-pic">${pic(a)}</span><span class="st-am-sim-name">${esc(a.name)}</span><span class="st-am-sim-sub">${t('st_am_similar_new')}</span></a>`).join('');
  el.innerHTML = (lovedHtml ? `<div class="st-am-sub-h">${t('st_am_similar_love')}</div><div class="st-am-sims">${lovedHtml}</div>` : '')
    + (freshHtml ? `<div class="st-am-sub-h">${t('st_am_similar_try')}</div><div class="st-am-sims">${freshHtml}</div>` : '');
}

function stOpenArtistModal(artist) {
  const modal = document.getElementById('stArtistModal');
  if (!modal) return;
  if (_stAmArtist !== artist) _eaStopSample();
  _stAmArtist = artist;

  const artistPlays = _stCurrentPlays.filter(p => (p.artists || splitArtists(p.artist)).includes(artist));
  const totalPlays = artistPlays.length;

  // Songs keep what the ▶ sample needs (credited artist, album, key)
  const songCounts = {};
  for (const p of artistPlays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, album: p.album || '', key: sk, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 10);

  const albumCounts = {};
  for (const p of artistPlays) {
    if (!p.album || p.album === '—') continue;
    if (!albumCounts[p.album]) albumCounts[p.album] = { album: p.album, artist: albumArtist(p), count: 0 };
    albumCounts[p.album].count++;
  }
  const topAlbums = Object.values(albumCounts).sort((a, b) => b.count - a.count);

  const dayCounts = {};
  for (const p of artistPlays) {
    const dk = dayStrOf(p);
    dayCounts[dk] = (dayCounts[dk] || 0) + 1;
  }
  const days = Object.keys(dayCounts).sort();
  const activeDays = days.length;
  let longestStreak = days.length ? 1 : 0, curStreak = 1;
  for (let i = 1; i < days.length; i++) {
    const diff = Math.round((new Date(days[i]) - new Date(days[i - 1])) / 86400000);
    curStreak = diff === 1 ? curStreak + 1 : 1;
    if (curStreak > longestStreak) longestStreak = curStreak;
  }
  let peakDay = null;
  for (const dk of days) { if (!peakDay || dayCounts[dk] > dayCounts[peakDay]) peakDay = dk; }

  const discoveredDs = artistPlays.length ? localDateStr(tzDate(new Date(Math.min(...artistPlays.map(p => +p.date))))) : null;

  // Rank among all artists this period (individual, comma-split — same rule New Discoveries uses)
  const periodArtistCounts = {};
  for (const p of _stCurrentPlays) {
    for (const a of (p.artists || splitArtists(p.artist))) periodArtistCounts[a] = (periodArtistCounts[a] || 0) + 1;
  }
  const ranked = Object.entries(periodArtistCounts).sort((a, b) => b[1] - a[1]);
  const rank = ranked.findIndex(([a]) => a === artist) + 1;

  const fmtDay = ds => new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  _stAmInfo = { artist, totalPlays, activeDays, rank, discoveredDs, topSong: topSongs[0]?.title || '', period: stGetPeriodLabel() };

  // ── Hero: photo backdrop, name, found date + rank, actions ──
  document.getElementById('stArtistModalName').textContent = artist;
  document.getElementById('stArtistModalSub').textContent = t('st_am_kicker', { period: stGetPeriodLabel() });
  const meta = [];
  if (discoveredDs) meta.push(t('st_am_found', { date: fmtDay(discoveredDs) }));
  if (rank > 0) meta.push(t('st_am_rank', { n: rank }));
  document.getElementById('stArtistModalMeta').textContent = meta.join(' · ');

  const avatarEl = document.getElementById('stArtistModalAvatar');
  const bgEl = document.getElementById('stArtistModalBg');
  const setArt = url => {
    avatarEl.innerHTML = url ? thumbHtml(url, artist, false) : `<div class="thumb-initials">${esc(initials(artist))}</div>`;
    avatarEl.querySelector('img')?.setAttribute('loading', 'eager');
    bgEl.style.backgroundImage = url ? `url("${String(url).replace(/"/g, '%22')}")` : '';
    bgEl.classList.toggle('has-art', !!url);
  };
  const cachedImg = imgCache['artist:' + artist.toLowerCase() + ':deezer'];
  setArt(cachedImg || null);
  if (!cachedImg) {
    getArtAuto('artist', artist).then(url => { if (_stAmArtist === artist && url) setArt(url); });
  }

  // ▶ plays the top song's sample: the hero carries that song's data-ea-*
  // attributes, so it lights up together with the song's own row
  const top = topSongs[0];
  const play = top
    ? `<span class="st-am-play-wrap"${_eaAttrs('songs', { title: top.title, artist: top.artist, album: top.album, key: top.key })}>`
      + `<button type="button" class="ea-sample st-am-play" title="${esc(t('ea_sample'))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="ea-ic-play" d="M8 5v14l11-7z"/><path class="ea-ic-stop" d="M7 6h3.5v12H7zM13.5 6H17v12h-3.5z"/></svg>`
      + `<span class="st-am-play-lbl">${t('st_am_play')}</span></button></span>`
    : '';
  document.getElementById('stArtistModalActions').innerHTML = play
    + `<span class="st-am-hero-links">${_stAmLinks(artist, true)}</span>`
    + `<button type="button" class="st-am-share" onclick="stAmShare(this)">${_ST_AM_SHARE_SVG}<span>${t('st_am_share')}</span></button>`;

  // ‹ › through the period's discoveries
  const idx = _stDiscovered.indexOf(artist);
  const nav = document.getElementById('stArtistModalNav');
  nav.innerHTML = idx >= 0 && _stDiscovered.length > 1
    ? `<button type="button" class="st-am-nav-btn" onclick="stAmStep(-1)" title="${esc(t('st_am_prev'))}" aria-label="${esc(t('st_am_prev'))}">‹</button>`
      + `<span class="st-am-nav-pos">${t('st_am_pos', { i: idx + 1, n: _stDiscovered.length })}</span>`
      + `<button type="button" class="st-am-nav-btn" onclick="stAmStep(1)" title="${esc(t('st_am_next'))}" aria-label="${esc(t('st_am_next'))}">›</button>`
    : '';

  // ── Body ──
  const songRows = topSongs.map((s, i) => `
    <div class="st-am-row"${_eaAttrs('songs', { title: s.title, artist: s.artist, album: s.album, key: s.key })}>
      <span class="st-am-rank">${i + 1}</span>
      ${_eaSampleBtn('st-am-row-play')}
      <span class="st-am-title"><span class="st-am-t1">${esc(s.title)}</span>${s.album && s.album !== '—' ? `<span class="st-am-t2">${esc(s.album)}</span>` : ''}</span>
      <span class="st-am-count">${s.count.toLocaleString()}</span>
      <span class="st-am-links">${_stAmLinks(s.title + ' ' + artist)}</span>
    </div>`).join('');

  const albumRows = topAlbums.map((a, i) => `
    <div class="st-am-row st-am-row--album">
      <span class="st-am-cover" data-st-am-album="${i}"><span class="thumb-initials">${esc(initials(a.album))}</span></span>
      <span class="st-am-title"><span class="st-am-t1">${esc(a.album)}</span><span class="st-am-t2">${a.count.toLocaleString()} ${tUnit('plays', a.count)}</span></span>
      <span class="st-am-links">${_stAmLinks(a.album + ' ' + a.artist)}</span>
    </div>`).join('');

  const body = document.getElementById('stArtistModalBody');
  body.innerHTML = `
    <div class="modal-stats-strip st-am-stats">
      <div class="modal-stat"><div class="sv" data-countup="${totalPlays}">${totalPlays.toLocaleString()}</div><div class="sl">${t('stat_total_plays')}</div></div>
      <div class="modal-stat"><div class="sv" data-countup="${activeDays}">${activeDays}</div><div class="sl">${t('modal_calendar_days_played')}</div></div>
      <div class="modal-stat"><div class="sv" data-countup="${longestStreak}">${longestStreak}</div><div class="sl">${t('modal_listening_days_streak')}</div></div>
      <div class="modal-stat"><div class="sv" data-countup="${topAlbums.length}">${topAlbums.length}</div><div class="sl">${t('st_bubble_albums_title')}</div></div>
    </div>

    ${_stAmGoalHtml(rank, totalPlays, ranked)}
    ${days.length ? _stAmChartHtml(dayCounts, days[0], peakDay) : ''}

    <div class="st-am-cols">
      <div class="st-am-card st-am-list">
        <div class="st-am-h">${t('st_top_songs')}</div>
        ${songRows}
      </div>
      ${topAlbums.length ? `<div class="st-am-card st-am-list">
        <div class="st-am-h">${t('st_bubble_albums_title')}</div>
        ${albumRows}
      </div>` : ''}
    </div>

    ${_stAmOriginHtml(artist)}

    <div class="st-am-card">
      <div class="st-am-h">${t('st_am_similar_title')}</div>
      <div id="stAmSimilar"><div class="st-am-muted st-am-loading">${t('st_am_similar_loading')}</div></div>
    </div>`;

  // Album covers fill in as they arrive
  topAlbums.forEach((a, i) => {
    getArtAuto('album', a.album, a.artist).then(url => {
      if (_stAmArtist !== artist || !url) return;
      const slot = body.querySelector(`[data-st-am-album="${i}"]`);
      if (slot) slot.innerHTML = thumbHtml(url, a.album, false);
    }).catch(() => {});
  });
  _stAmFillSimilar(artist);
  _eaPaintSamples();

  animateModalCountup(body);
  // replay the fade when stepping to another discovery
  const box = modal.querySelector('.st-artist-modal-box');
  box.classList.remove('st-am-swap'); void box.offsetWidth; box.classList.add('st-am-swap');
  if (!modal.classList.contains('open')) modal.scrollTop = 0;
  modal.classList.add('open');

  // Touch screens share from a tap, which can't wait for the drawing — get it ready now
  _stAmCard = null;
  if (window.matchMedia && window.matchMedia('(hover: none)').matches && navigator.canShare) {
    _stAmRenderCard().then(file => { if (file && _stAmArtist === artist) _stAmCard = { artist, file }; }).catch(() => {});
  }
}

function stAmStep(dir) {
  const n = _stDiscovered.length;
  const i = _stDiscovered.indexOf(_stAmArtist);
  if (n < 2 || i < 0) return;
  stOpenArtistModal(_stDiscovered[(i + dir + n) % n]);
  document.getElementById('stArtistModal').scrollTop = 0;
}

function stCloseArtistModal() {
  document.getElementById('stArtistModal')?.classList.remove('open');
  _eaStopSample();
  _stAmArtist = null;
}

// ← → step, Esc closes (and stops the sample)
document.addEventListener('keydown', e => {
  const modal = document.getElementById('stArtistModal');
  if (!modal || !modal.classList.contains('open')) return;
  if (e.target.closest && e.target.closest('input, textarea, select, [contenteditable]')) return;
  if (e.key === 'ArrowLeft') { stAmStep(-1); e.preventDefault(); }
  else if (e.key === 'ArrowRight') { stAmStep(1); e.preventDefault(); }
  else if (e.key === 'Escape') stCloseArtistModal();
});

document.addEventListener('click', e => {
  const chip = e.target.closest && e.target.closest('[data-st-am-profile]');
  if (!chip) return;
  const name = chip.dataset.stAmProfile;
  stCloseArtistModal();
  openArtistModal(name);
});

// The chart rows' right-click menu would open under this pop-up: keep the browser's own
document.getElementById('stArtistModal')?.addEventListener('contextmenu', e => e.stopPropagation());

// ── Share card ────────────────────────────────────────────────────────────
// 1080×1350, drawn on a canvas: blurred photo, round portrait, name, three
// numbers, the most played song. Returns a PNG File.
async function _stAmRenderCard() {
  const info = _stAmInfo;
  if (!info) return null;
  const W = 1080, H = 1350;
  const cvs = document.createElement('canvas');
  cvs.width = W; cvs.height = H;
  const g = cvs.getContext('2d');
  const css = getComputedStyle(document.documentElement);
  const display = (css.getPropertyValue('--font-display') || 'sans-serif').trim();
  const sans = (css.getPropertyValue('--font-sans') || 'sans-serif').trim();
  try { await Promise.all([document.fonts.load(`800 100px ${display}`), document.fonts.load(`600 40px ${sans}`)]); } catch (e) {}

  // The photo, inlined so the canvas isn't tainted
  let img = null;
  try {
    const url = imgCache['artist:' + info.artist.toLowerCase() + ':deezer'] || await getArtAuto('artist', info.artist);
    const data = url && await _igToDataUrl(shHiResArt(url));
    if (data) {
      img = new Image();
      img.src = data;
      await img.decode();
    }
  } catch (e) { img = null; }

  const MINT = '#6ee7b7';
  // Background: the photo blurred by drawing it tiny and scaling it back up
  g.fillStyle = '#0a0f1c';
  g.fillRect(0, 0, W, H);
  const cover = (c, w, h) => {
    const k = Math.max(w / img.naturalWidth, h / img.naturalHeight);
    const sw = w / k, sh = h / k;
    c.drawImage(img, (img.naturalWidth - sw) / 2, (img.naturalHeight - sh) / 2, sw, sh, 0, 0, w, h);
  };
  if (img) {
    const tiny = document.createElement('canvas');
    tiny.width = 27; tiny.height = 34;
    cover(tiny.getContext('2d'), 27, 34);
    g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';
    g.globalAlpha = 0.85;
    g.drawImage(tiny, -40, -40, W + 80, H + 80);
    g.globalAlpha = 1;
  } else {
    const rg = g.createRadialGradient(W / 2, 380, 40, W / 2, 380, 900);
    rg.addColorStop(0, '#134e4a'); rg.addColorStop(1, '#0a0f1c');
    g.fillStyle = rg; g.fillRect(0, 0, W, H);
  }
  const shade = g.createLinearGradient(0, 0, 0, H);
  shade.addColorStop(0, 'rgba(6,10,20,0.45)');
  shade.addColorStop(0.5, 'rgba(6,10,20,0.72)');
  shade.addColorStop(1, 'rgba(6,10,20,0.94)');
  g.fillStyle = shade; g.fillRect(0, 0, W, H);

  g.textAlign = 'center';
  g.textBaseline = 'alphabetic';
  // Largest font size (down to `min`) at which `text` fits; clip() trims what still doesn't
  const fit = (text, font, size, min, maxW) => {
    let s = size;
    g.font = font(s);
    while (s > min && g.measureText(text).width > maxW) { s -= 4; g.font = font(s); }
    return s;
  };
  const clip = (text, maxW) => {
    if (g.measureText(text).width <= maxW) return text;
    let s = text;
    while (s.length > 1 && g.measureText(s + '…').width > maxW) s = s.slice(0, -1);
    return s + '…';
  };

  // Kicker
  g.font = `600 34px ${sans}`;
  g.fillStyle = MINT;
  g.fillText(('✦ ' + t('st_am_kicker', { period: info.period })).toUpperCase(), W / 2, 112);

  // Portrait with a glowing ring
  const cx = W / 2, cy = 400, r = 220;
  g.save();
  g.shadowColor = 'rgba(110,231,183,0.55)'; g.shadowBlur = 60;
  g.beginPath(); g.arc(cx, cy, r + 10, 0, Math.PI * 2); g.fillStyle = MINT; g.fill();
  g.restore();
  g.save();
  g.beginPath(); g.arc(cx, cy, r, 0, Math.PI * 2); g.clip();
  if (img) {
    g.translate(cx - r, cy - r);
    cover(g, r * 2, r * 2);
  } else {
    g.fillStyle = '#1f2e4a'; g.fillRect(cx - r, cy - r, r * 2, r * 2);
    g.fillStyle = '#fff'; g.font = `800 150px ${display}`; g.textBaseline = 'middle';
    g.fillText(initials(info.artist), cx, cy + 6);
    g.textBaseline = 'alphabetic';
  }
  g.restore();

  // Name, sized to fit
  const nameFont = s => `800 ${s}px ${display}`;
  fit(info.artist, nameFont, 128, 64, 960);
  g.fillStyle = '#ffffff';
  g.fillText(clip(info.artist, 960), W / 2, 790);

  // Found on …
  if (info.discoveredDs) {
    g.font = `500 36px ${sans}`;
    g.fillStyle = 'rgba(255,255,255,0.72)';
    const d = new Date(info.discoveredDs + 'T12:00:00').toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' });
    g.fillText(t('st_am_found', { date: d }), W / 2, 852);
  }

  // Three numbers
  const stats = [
    [info.totalPlays.toLocaleString(), t('stat_total_plays')],
    [String(info.activeDays), t('st_am_card_days')],
    [info.rank ? '#' + info.rank : '—', t('st_am_card_rank')],
  ];
  const colW = 300, x0 = W / 2 - colW;
  const boxY = 910, boxH = 170;
  g.fillStyle = 'rgba(255,255,255,0.07)';
  g.beginPath();
  if (g.roundRect) g.roundRect(90, boxY, W - 180, boxH, 28); else g.rect(90, boxY, W - 180, boxH);
  g.fill();
  stats.forEach(([v, l], i) => {
    const x = x0 + i * colW;
    g.font = `800 76px ${display}`;
    g.fillStyle = i === 2 ? MINT : '#ffffff';
    g.fillText(v, x, boxY + 98);
    g.font = `600 24px ${sans}`;
    g.fillStyle = 'rgba(255,255,255,0.6)';
    g.fillText(clip(l.toUpperCase(), colW - 30), x, boxY + 140);
  });

  // Most played song
  if (info.topSong) {
    g.font = `600 24px ${sans}`;
    g.fillStyle = 'rgba(255,255,255,0.6)';
    g.fillText(t('st_am_card_top').toUpperCase(), W / 2, 1150);
    g.font = `700 46px ${sans}`;
    g.fillStyle = '#ffffff';
    g.fillText(clip(info.topSong, 900), W / 2, 1210);
  }

  g.font = `600 30px ${sans}`;
  g.fillStyle = 'rgba(255,255,255,0.5)';
  g.fillText('dankcharts.fm', W / 2, 1300);

  const blob = await new Promise(res => cvs.toBlob(res, 'image/png'));
  if (!blob) return null;
  const name = 'discovery-' + info.artist.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() + '.png';
  return new File([blob], name, { type: 'image/png' });
}

// Share card button: the phone's share sheet when the image is ready
// (navigator.share needs the tap itself, so nothing may be awaited first),
// otherwise draw it and download it
async function stAmShare(btn) {
  const ready = _stAmCard && _stAmCard.artist === _stAmArtist ? _stAmCard.file : null;
  if (ready && navigator.canShare && navigator.canShare({ files: [ready] })) {
    navigator.share({ files: [ready] }).catch(() => {});
    return;
  }
  const lbl = btn.querySelector('span');
  const orig = lbl ? lbl.textContent : '';
  btn.disabled = true;
  if (lbl) lbl.textContent = t('st_am_saving');
  try {
    const file = await _stAmRenderCard();
    if (file) {
      const a = document.createElement('a');
      a.download = file.name;
      a.href = URL.createObjectURL(file);
      a.click();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    }
  } catch (e) { console.error('stAmShare', e); }
  btn.disabled = false;
  if (lbl) lbl.textContent = orig;
}

function stStartBubbles(discovered) {
  if (_stBubbleTimer) { clearInterval(_stBubbleTimer); _stBubbleTimer = null; }
  _stBubbleSeeds.forEach(clearTimeout);
  _stBubbleSeeds = [];
  _stBubbleQueue = [];
  if (!discovered.length) return;

  const container = document.getElementById('stDiscoveriesBubbles');
  if (!container) return;

  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) {
    container.classList.add('st-bubbles-static');
    stShuffle(discovered).slice(0, 10).forEach(item => stSpawnBubble(container, item.artist, true));
    return;
  }
  container.classList.remove('st-bubbles-static');

  const spawn = () => {
    if (currentPeriod !== 'soundtrack') { clearInterval(_stBubbleTimer); _stBubbleTimer = null; return; }
    const live = document.getElementById('stDiscoveriesBubbles');
    if (!live) { clearInterval(_stBubbleTimer); _stBubbleTimer = null; return; }
    if (!_stBubbleQueue.length) _stBubbleQueue = stBuildWeightedDeck(discovered);
    const item = _stBubbleQueue.pop();
    stSpawnBubble(live, item.artist);
  };

  for (let i = 0; i < 5; i++) _stBubbleSeeds.push(setTimeout(spawn, i * 400));
  _stBubbleTimer = setInterval(spawn, 1400);
}

// ── Milestones ────────────────────────────────────────────────
// Two independent kinds live here and are kept in separate sections
// so they never read as one connected timeline: "overall" tracks the
// listener's own cumulative play count, while "artist" tracks each
// artist's play count independently — an artist milestone can land
// on any date and has nothing to do with the listener's own totals.
function stRenderMilestones(plays) {
  const elOverall = document.getElementById('stMilestonesBody');
  const elArtist = document.getElementById('stArtistMilestonesBody');
  if (!elOverall && !elArtist) return;

  const OVERALL_MS = [100,500,1000,2500,5000,10000, ...Array.from({ length: 40 }, (_, i) => 25000 * (i + 1))];
  const ARTIST_MS  = [100, ...Array.from({ length: 1000 }, (_, i) => 500 * (i + 1))];
  const ARTIST_MS_SET = new Set(ARTIST_MS);
  const MS_NUM_TOKEN = '##N##'; // stands in for {{n}} — swapped for a live-counting <span> at render time

  const chron = [...allPlays].sort((a, b) => a.date - b.date);
  const overallMs = [];
  const artistMs = [];
  let total = 0, nextIdx = 0;
  const artistCounts = {};

  for (const p of chron) {
    total++;
    const d = tzDateOf(p);
    const inPeriod = stPeriodType === 'alltime' ? true :
      stPeriodType === 'year' ? d.getFullYear() === stYear :
      d.getFullYear() === stYear && (d.getMonth() + 1) === stMonth;

    // Overall milestones — the listener's own cumulative play count
    while (nextIdx < OVERALL_MS.length && total >= OVERALL_MS[nextIdx]) {
      if (inPeriod) overallMs.push({ icon: stIco('note'), text: t('st_milestone_overall', { n: MS_NUM_TOKEN }), sub: t('st_milestone_overall_sub', { title: esc(p.title), artist: esc(p.artist) }), date: p.date, rawTitle: p.title, rawArtist: p.artist, nTarget: OVERALL_MS[nextIdx] });
      nextIdx++;
    }

    // Per-artist milestones — independent of the totals above. Each
    // comma-split credited artist counts on its own (honoring the
    // hardwired exceptions in splitArtists, e.g. "Tyler, The Creator"),
    // same rule as New Discoveries and the Top Artists coverflow.
    for (const a of (p.artists || splitArtists(p.artist))) {
      const ak = a.toLowerCase();
      artistCounts[ak] = (artistCounts[ak] || 0) + 1;
      if (inPeriod && ARTIST_MS_SET.has(artistCounts[ak])) {
        artistMs.push({ icon: stIco('mic'), sub: t('st_milestone_artist_sub', { title: esc(p.title) }), text: t('st_milestone_artist', { n: MS_NUM_TOKEN, artist: esc(a) }), date: p.date, rawTitle: p.title, rawArtist: a, nTarget: artistCounts[ak] });
      }
    }
  }

  overallMs.sort((a, b) => a.date - b.date);
  artistMs.sort((a, b) => a.date - b.date);
  _stFacts.milestones = { overall: overallMs[overallMs.length - 1] || null, artistCount: artistMs.length, artist: artistMs[artistMs.length - 1] || null };

  _stMilestonesVisible.overall = ST_MS_PAGE;
  _stMilestonesVisible.artist = ST_MS_PAGE;
  stRenderMilestoneList(overallMs, 'stMilestonesBody', 'stMilestonesWrap', 'stMilestonesToggle', 'overall');
  stRenderMilestoneList(artistMs, 'stArtistMilestonesBody', 'stArtistMilestonesWrap', 'stArtistMilestonesToggle', 'artist');
}

const _stMilestonesCounts = { overall: 0, artist: 0 };
const _stMilestonesItems = { overall: [], artist: [] };
const ST_MS_PAGE = 25;
const _stMilestonesVisible = { overall: ST_MS_PAGE, artist: ST_MS_PAGE };

function stRenderMilestoneList(items, bodyId, wrapId, toggleId, kind) {
  const el = document.getElementById(bodyId);
  const wrap = document.getElementById(wrapId);
  const toggle = document.getElementById(toggleId);
  if (!el) return;

  _stMilestonesItems[kind] = items;
  _stMilestonesCounts[kind] = items.length;

  if (!items.length) {
    el.innerHTML = `<div class="st-empty">${t('st_milestones_none')}</div>`;
    if (toggle) toggle.style.display = 'none';
    if (wrap) wrap.classList.remove('st-scrollable', 'st-has-more');
    return;
  }

  const visibleCount = Math.min(_stMilestonesVisible[kind], items.length);
  const visibleItems = items.slice(0, visibleCount);

  el.innerHTML = visibleItems.map((m, i) => {
    // Written in words (11 Feb 2026), the same as Records and Events
    const ds = fmtDate(tzDate(m.date));
    const typeClass = kind === 'overall' ? ' st-milestone-overall' : ' st-milestone-artist';
    const numId = `ms-num-${kind}-${i}`;
    const numSpan = `<span class="st-milestone-num" id="${numId}" data-target="${m.nTarget}">0</span>`;
    const text = m.text.replace('##N##', numSpan);
    return `<div class="st-milestone${typeClass}" data-idx="${i}" style="--i:${i}">
      <span class="st-milestone-icon">${m.icon}</span>
      <span class="st-milestone-art-wrap" data-idx="${i}"></span>
      <div class="st-milestone-info">
        <div class="st-milestone-text">${text}</div>
        <div class="st-milestone-sub">${m.sub}</div>
      </div>
      <div class="st-milestone-date">${ds}</div>
    </div>`;
  }).join('');

  visibleItems.forEach((m, i) => {
    const rowEl = el.querySelector(`.st-milestone[data-idx="${i}"]`);
    if (!rowEl) return;

    // Fill in the row's art thumbnail with the triggering track's cover
    // art, once fetched — stays hidden (icon badge only) if art fails.
    // Queued (see stLoyaltyImg above) so a page of milestones doesn't fire
    // all its lookups in the same instant. Deezer alone misses plenty of
    // tracks, so walk the same itunes/lastfm fallback chain the
    // coverflow uses instead of giving up after one source.
    if (m.rawTitle) {
      const MS_ART_SOURCES = AUTO_IMG_SOURCES;
      queueImg(async () => {
        let url = null;
        for (const source of MS_ART_SOURCES) {
          try { url = await getTrackImage(m.rawTitle, m.rawArtist, source); } catch (e) { url = null; }
          if (url) break;
        }
        if (!url) return;
        const artWrapEl = rowEl.querySelector('.st-milestone-art-wrap');
        if (artWrapEl && !artWrapEl.querySelector('.st-milestone-art')) {
          artWrapEl.classList.add('st-has-art');
          artWrapEl.insertAdjacentHTML('beforeend', `<img class="st-milestone-art" src="${esc(url)}" alt="" loading="lazy" onerror="this.parentElement.classList.remove('st-has-art');this.remove()">`);
        }
      });
    }

    // Tap a row to open the same mini-card the Top Artists/Songs
    // coverflow opens on center-tap — the artist card for artist
    // milestones, the song card for overall (track-triggered) ones.
    rowEl.classList.add('st-milestone-tappable');
    rowEl.addEventListener('click', () => {
      if (kind === 'artist') stOpenArtistModal(m.rawArtist);
      else if (m.rawTitle) openSongModal(songKey({ title: m.rawTitle, artist: m.rawArtist }));
    });
  });

  // Count up each row's play-count number with a little pop the first
  // time it scrolls into view, instead of just appearing pre-filled.
  const numEls = Array.from(el.querySelectorAll('.st-milestone-num'));
  if (!('IntersectionObserver' in window)) {
    numEls.forEach(n => { n.textContent = (+n.dataset.target).toLocaleString(); });
  } else {
    const numObs = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (!e.isIntersecting) return;
        numObs.unobserve(e.target);
        e.target.classList.add('st-pop');
        stCountUp(e.target.id, +e.target.dataset.target);
      });
    }, { threshold: 0.4 });
    numEls.forEach(n => numObs.observe(n));
  }

  // Long lists live in a fixed-height scroll box so the page doesn't
  // open with a wall of rows, and only a page of ST_MS_PAGE items is
  // ever in the DOM at once; a button below loads the next page in.
  const needsScroll = items.length > 8;
  const remaining = items.length - visibleCount;
  if (wrap) {
    wrap.classList.toggle('st-scrollable', needsScroll);
    wrap.classList.toggle('st-has-more', needsScroll && remaining > 0);
  }
  if (toggle) {
    if (remaining > 0) {
      toggle.style.display = '';
      toggle.textContent = t('st_milestones_show_more', { n: Math.min(ST_MS_PAGE, remaining), total: items.length });
    } else if (items.length > ST_MS_PAGE) {
      toggle.style.display = '';
      toggle.textContent = t('st_milestones_show_less');
    } else {
      toggle.style.display = 'none';
    }
  }
}

function stToggleMilestones(kind) {
  kind = kind || 'overall';
  const bodyId = kind === 'artist' ? 'stArtistMilestonesBody' : 'stMilestonesBody';
  const wrapId = kind === 'artist' ? 'stArtistMilestonesWrap' : 'stMilestonesWrap';
  const toggleId = kind === 'artist' ? 'stArtistMilestonesToggle' : 'stMilestonesToggle';
  const items = _stMilestonesItems[kind] || [];
  const total = items.length;
  if (!total) return;

  const collapsing = _stMilestonesVisible[kind] >= total;
  _stMilestonesVisible[kind] = collapsing ? ST_MS_PAGE : Math.min(_stMilestonesVisible[kind] + ST_MS_PAGE, total);
  stRenderMilestoneList(items, bodyId, wrapId, toggleId, kind);

  const wrap = document.getElementById(wrapId);
  if (wrap && collapsing) { wrap.scrollTop = 0; wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
}

// ── Streaks ───────────────────────────────────────────────────
function stRenderStreaks(plays) {
  const el = document.getElementById('stStreaksBody');
  if (!el) return;
  if (!plays.length) { el.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`; return; }

  const pad2 = n => String(n).padStart(2, '0');
  const dayKey = d => { const tz = tzDate(d); return `${tz.getFullYear()}-${pad2(tz.getMonth()+1)}-${pad2(tz.getDate())}`; };
  // Day keys in words (11 Feb 2026), the same as Records and Events. Noon keeps
  // the date from slipping a day in timezones behind UTC.
  const fmtDay = ds => fmtDate(new Date(ds + 'T12:00:00'));
  // Pure UTC decrement on the calendar string — avoids mixing a UTC-parsed
  // Date with local setDate()/getDate(), which silently skips a day in
  // negative-UTC-offset timezones and undercounts the walk below.
  const prevDayKey = ds => { const d = new Date(ds + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - 1); return d.toISOString().slice(0, 10); };
  const nextDayKey = ds => { const d = new Date(ds + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 1); return d.toISOString().slice(0, 10); };
  const daysBetween = (a, b) => Math.round((new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / 86400000);
  // Every run of back-to-back days in a sorted list of day keys
  const runsOf = days => {
    const out = [];
    let s = days[0], prev = days[0];
    for (let i = 1; i <= days.length; i++) {
      const d = days[i];
      if (d && daysBetween(prev, d) === 1) { prev = d; continue; }
      if (s) out.push({ start: s, end: prev, n: daysBetween(s, prev) + 1 });
      s = prev = d;
    }
    return out;
  };

  // "Longest ever" means as of the period being looked at: a past year or
  // month only counts days up to its last day, so 2023 shows the record as
  // it stood at the end of 2023. All-Time has no cutoff.
  const cutoffKey = stPeriodType === 'year' ? `${stYear}-12-31`
    : stPeriodType === 'month' ? `${stYear}-${pad2(stMonth)}-${pad2(new Date(stYear, stMonth, 0).getDate())}`
    : null;
  const allDaySet = new Set();
  for (const p of allPlays) {
    const dk = dayKey(p.date);
    if (!cutoffKey || dk <= cutoffKey) allDaySet.add(dk);
  }
  const allDays = [...allDaySet].sort();

  // Longest streak ever (up to the cutoff)
  let longestAll = allDays.length ? 1 : 0, curAll = 1, longestStart = allDays[0] || '', longestEnd = allDays[0] || '', curStart = allDays[0] || '';
  for (let i = 1; i < allDays.length; i++) {
    const diff = Math.round((new Date(allDays[i]) - new Date(allDays[i-1])) / 86400000);
    if (diff === 1) {
      curAll++;
    } else {
      if (curAll > longestAll) { longestAll = curAll; longestStart = curStart; longestEnd = allDays[i-1]; }
      curAll = 1; curStart = allDays[i];
    }
  }
  if (curAll > longestAll) { longestAll = curAll; longestStart = curStart; longestEnd = allDays[allDays.length-1]; }

  // Current streak (today or yesterday)
  const now = tzNow();
  const todayKey = `${now.getFullYear()}-${pad2(now.getMonth()+1)}-${pad2(now.getDate())}`;
  const yd = new Date(now); yd.setDate(yd.getDate() - 1);
  const yestKey = `${yd.getFullYear()}-${pad2(yd.getMonth()+1)}-${pad2(yd.getDate())}`;
  let currentStreak = 0, currentStreakStart = '';
  // only a period that reaches today can have a live streak
  const reachesToday = !cutoffKey || cutoffKey >= todayKey;
  const anchorDay = !reachesToday ? null : allDaySet.has(todayKey) ? todayKey : (allDaySet.has(yestKey) ? yestKey : null);
  if (anchorDay) {
    let day = anchorDay;
    while (allDaySet.has(day)) {
      currentStreak++;
      currentStreakStart = day;
      day = prevDayKey(day);
    }
  }

  // A live streak that has reached or passed the historical best IS the new
  // record — fold it in rather than showing two contradictory numbers.
  const isNewRecord = currentStreak > 0 && currentStreak >= longestAll;
  if (isNewRecord) { longestAll = currentStreak; longestStart = currentStreakStart; longestEnd = anchorDay; }

  // Longest streak in period
  const periodDays = [...new Set(plays.map(p => dayKey(p.date)))].sort();
  let longestPeriod = periodDays.length ? 1 : 0, curPeriod = 1, periodStart = periodDays[0] || '', periodEnd = periodDays[0] || '', curPeriodStart = periodDays[0] || '';
  for (let i = 1; i < periodDays.length; i++) {
    const diff = Math.round((new Date(periodDays[i]) - new Date(periodDays[i-1])) / 86400000);
    if (diff === 1) {
      curPeriod++;
    } else {
      if (curPeriod > longestPeriod) { longestPeriod = curPeriod; periodStart = curPeriodStart; periodEnd = periodDays[i-1]; }
      curPeriod = 1; curPeriodStart = periodDays[i];
    }
  }
  if (curPeriod > longestPeriod) { longestPeriod = curPeriod; periodStart = curPeriodStart; periodEnd = periodDays[periodDays.length-1]; }

  // Active days coverage — recap-oriented replacement for the live "current
  // streak" counter, which doesn't belong in a retrospective summary. Denominator
  // is days elapsed so far for the current year/month, or the full length once past.
  const isCurrentYear = stPeriodType === 'year' && stYear === now.getFullYear();
  const isCurrentMonth = stPeriodType === 'month' && stYear === now.getFullYear() && stMonth === now.getMonth() + 1;
  let totalDaysInPeriod;
  if (stPeriodType === 'alltime') {
    totalDaysInPeriod = periodDays.length
      ? Math.round((new Date(periodDays[periodDays.length - 1]) - new Date(periodDays[0])) / 86400000) + 1
      : 0;
  } else if (stPeriodType === 'year') {
    totalDaysInPeriod = isCurrentYear
      ? daysBetween(`${stYear}-01-01`, todayKey) + 1 // calendar days, so the time of day can't add one
      : (new Date(stYear, 1, 29).getMonth() === 1 ? 366 : 365);
  } else {
    totalDaysInPeriod = isCurrentMonth ? now.getDate() : new Date(stYear, stMonth, 0).getDate();
  }
  const activeDays = periodDays.length;
  // 100% only when no day was missed (297 of 298 would round up to it)
  const activeDaysPct = totalDaysInPeriod ? Math.min(activeDays < totalDaysInPeriod ? 99 : 100, Math.round((activeDays / totalDaysInPeriod) * 100)) : 0;

  // The period's span as day keys. A year or month runs from its first day
  // (or your first play, if that's later) to its last day (or today, if
  // that's sooner); All-Time runs from the first play to the last.
  const pStart = stPeriodType === 'year' ? `${stYear}-01-01`
    : stPeriodType === 'month' ? `${stYear}-${pad2(stMonth)}-01` : periodDays[0];
  const firstEverDay = allDays[0] || periodDays[0];
  const rangeStart = firstEverDay > pStart ? firstEverDay : pStart;
  const lastPlayDay = periodDays[periodDays.length - 1];
  const rangeEnd = stPeriodType === 'alltime' ? (lastPlayDay < todayKey ? todayKey : lastPlayDay)
    : (cutoffKey < todayKey ? cutoffKey : todayKey);
  const inRange = periodDays.filter(d => d >= rangeStart && d <= rangeEnd);

  // The period's three longest streaks (the calendar picks them out)
  const topRuns = runsOf(periodDays).filter(r => r.n >= 2)
    .sort((a, b) => b.n - a.n || (a.start < b.start ? -1 : 1)).slice(0, 3);

  // Longest break: the most days in a row without music inside the span.
  // Today doesn't count as missed until it's over.
  const breakEnd = rangeEnd === todayKey && !periodDays.includes(todayKey) ? prevDayKey(todayKey) : rangeEnd;
  let brk = { n: 0, start: '', end: '' };
  {
    let prev = prevDayKey(rangeStart); // a day before the span, so a gap at its start counts
    for (const d of [...inRange.filter(x => x <= breakEnd), nextDayKey(breakEnd)]) {
      const gap = daysBetween(prev, d) - 1;
      if (gap > brk.n) brk = { n: gap, start: nextDayKey(prev), end: prevDayKey(d) };
      prev = d;
    }
  }

  // All the days without music in the span, not just the longest run of them
  // (same span as the break, so today only counts once it's over)
  const missedTotal = brk.n ? daysBetween(rangeStart, breakEnd) + 1 - inRange.filter(x => x <= breakEnd).length : 0;
  const missedKey = (stPeriodType === 'alltime' ? 'st_streak_break_total_all' : 'st_streak_break_total') + (missedTotal === 1 ? '_one' : '');

  // Every streak up to the cutoff: ranks the period's best, and finds the
  // record that a new record beat
  const allRuns = runsOf(allDays);
  // a streak running past the period's edges is the period's own streak, so it's skipped
  const periodRank = 1 + allRuns.filter(r => r.n > longestPeriod && !(r.start <= periodStart && r.end >= periodEnd)).length;
  let beatOld = 0;
  if (stPeriodType !== 'alltime' && longestStart >= pStart) {
    for (const r of allRuns) if (r.end < longestStart && r.n > beatOld) beatOld = r.n;
  }

  // The song played most during a streak, with its artist
  const topSongBetween = (from, to) => {
    if (!from) return null;
    const counts = new Map();
    for (const p of allPlays) {
      const dk = dayKey(p.date);
      if (dk < from || dk > to) continue;
      const k = songKey(p);
      const rec = counts.get(k) || { title: p.title, artist: p.artist, n: 0 };
      rec.n++; counts.set(k, rec);
    }
    let best = null;
    for (const rec of counts.values()) if (!best || rec.n > best.n) best = rec;
    return best;
  };
  const fuelText = song => song ? esc(t('st_streak_fuel', { song: song.title, artist: song.artist })) : '';

  // Days you listened, against the period before (for a running period,
  // against the same point of the period before)
  let vsLine = '';
  if (stPeriodType !== 'alltime') {
    let prevStart, prevEndKey, prevLabel;
    if (stPeriodType === 'year') {
      prevStart = `${stYear - 1}-01-01`; prevEndKey = `${stYear - 1}-12-31`; prevLabel = String(stYear - 1);
    } else {
      const py = stMonth === 1 ? stYear - 1 : stYear, pm = stMonth === 1 ? 12 : stMonth - 1;
      prevStart = `${py}-${pad2(pm)}-01`;
      prevEndKey = `${py}-${pad2(pm)}-${pad2(new Date(py, pm, 0).getDate())}`;
      prevLabel = t(ST_MONTH_KEYS[pm - 1]) + ' ' + py;
    }
    const soFar = reachesToday;
    if (soFar) {
      const d = new Date(prevStart + 'T00:00:00Z');
      d.setUTCDate(d.getUTCDate() + daysBetween(pStart, todayKey));
      const same = d.toISOString().slice(0, 10);
      if (same < prevEndKey) prevEndKey = same;
    }
    const prevCount = allDays.filter(d => d >= prevStart && d <= prevEndKey).length;
    if (prevCount) {
      const diff = activeDays - prevCount, sfx = soFar ? '_sofar' : '';
      const key = diff > 0 ? 'st_streak_vs_more' : diff < 0 ? 'st_streak_vs_fewer' : 'st_streak_vs_same';
      vsLine = esc(t(key + sfx, { n: Math.abs(diff), prev: prevLabel }));
    }
  }

  // Bigger streaks: music every week / month / year of the span
  const chips = [];
  {
    const spanDays = daysBetween(rangeStart, rangeEnd) + 1;
    const weeks = new Set(inRange.map(d => Math.floor(daysBetween(rangeStart, d) / 7)));
    const months = new Set(inRange.map(d => d.slice(0, 7)));
    const years = new Set(inRange.map(d => d.slice(0, 4)));
    const totalWeeks = Math.ceil(spanDays / 7);
    const totalMonths = (+rangeEnd.slice(0, 4) - +rangeStart.slice(0, 4)) * 12 + (+rangeEnd.slice(5, 7) - +rangeStart.slice(5, 7)) + 1;
    const totalYears = +rangeEnd.slice(0, 4) - +rangeStart.slice(0, 4) + 1;
    const chip = (n, total, keyAll, keyN) => {
      const all = n >= total;
      chips.push(`<span class="st-streak-chip${all ? ' is-full' : ''}">${all ? stIco('check') + ' ' : ''}${esc(all ? t(keyAll) : t(keyN, { n, total }))}</span>`);
    };
    if (totalWeeks > 1) chip(weeks.size, totalWeeks, 'st_streak_weeks_all', 'st_streak_weeks_n');
    if (stPeriodType !== 'month' && totalMonths > 1) chip(months.size, totalMonths, 'st_streak_months_all', 'st_streak_months_n');
    if (stPeriodType === 'alltime' && totalYears > 1) chip(years.size, totalYears, 'st_streak_years_all', 'st_streak_years_n');
  }

  // Key for the top streaks and the longest break (on All-Time, the whole list)
  const fmtSpan = (a, b) => a === b ? fmtDay(a) : `${fmtDay(a)} – ${fmtDay(b)}`; // one day: just its date
  const runLegend = topRuns.map((r, i) => `<span class="st-cal-key is-s${i + 1}"><i></i><b>${r.n}</b> ${esc(t('st_streak_days_unit'))} · ${fmtSpan(r.start, r.end)}</span>`).join('')
    + (brk.n ? `<span class="st-cal-key is-break"><i></i>${esc(t('st_streak_legend_break'))}: <b>${brk.n}</b> · ${fmtSpan(brk.start, brk.end)}</span>` : '');

  // The calendar: every day of a year (a week per column) or a month (one
  // row), lit by how much you played, with the top streaks and the longest
  // break picked out. All-Time spans too many days for one, so it has none.
  let calHtml = '';
  if (stPeriodType !== 'alltime') {
    const dayPlays = new Map();
    for (const p of plays) { const dk = dayKey(p.date); dayPlays.set(dk, (dayPlays.get(dk) || 0) + 1); }
    const maxN = Math.max(1, ...dayPlays.values());
    const isYear = stPeriodType === 'year';
    const cells = [];
    if (isYear) { // empty cells so Jan 1 sits on its weekday (Monday first)
      const wd = (new Date(pStart + 'T00:00:00Z').getUTCDay() + 6) % 7;
      for (let i = 0; i < wd; i++) cells.push('<span class="st-cal-day is-pad"></span>');
    }
    const monthCols = []; // the week column each month starts in, for the labels
    for (let d = pStart; d <= cutoffKey; d = nextDayKey(d)) {
      if (isYear && d.slice(8) === '01') monthCols.push(Math.floor(cells.length / 7));
      const n = dayPlays.get(d) || 0;
      const ri = topRuns.findIndex(r => d >= r.start && d <= r.end);
      const lv = n ? Math.max(1, Math.ceil(Math.sqrt(n / maxN) * 4)) : 0;
      const inBreak = brk.n && d >= brk.start && d <= brk.end;
      const cls = (d < rangeStart || d > rangeEnd) ? ' is-out'
        : n ? ` lv${lv}${ri >= 0 ? ' is-s' + (ri + 1) : ''}` : (inBreak ? ' is-break' : '');
      const tip = `${fmtDay(d)} · ${n ? (n === 1 ? t('st_streak_cal_play1') : t('st_streak_cal_plays', { n })) : t('st_streak_cal_none')}`;
      cells.push(`<span class="st-cal-day${cls}" data-d="${d}" title="${esc(tip)}">${isYear ? '' : `<em>${+d.slice(8)}</em>`}</span>`);
    }
    const monthRow = isYear
      ? `<div class="st-cal-months">${monthCols.map((c, m) => `<span style="grid-column:${c + 1}">${esc(t(ST_MONTH_KEYS[m]))}</span>`).join('')}</div>` : '';
    calHtml = `
    <div class="st-streak-subhead">${esc(t('st_streak_cal_title', { period: stGetPeriodLabel() }))}</div>
    <div class="st-cal-wrap"><div class="st-cal ${isYear ? 'st-cal--year' : 'st-cal--month'}" style="--cols:${isYear ? Math.ceil(cells.length / 7) : cells.length}">${monthRow}<div class="st-cal-grid">${cells.join('')}</div></div></div>`;
  } else if (runLegend) {
    calHtml = `<div class="st-streak-subhead">${esc(t('st_streak_top_title'))}</div>`;
  }
  if (runLegend) calHtml += `<div class="st-cal-legend">${runLegend}</div>`;
  if (chips.length) calHtml += `<div class="st-streak-chips">${chips.join('')}</div>`;

  // Longest streak reached by a single artist / album / song within the
  // current view (year, month, or all-time — whatever `plays` is scoped to).
  function bestEntityStreak(entryFn) {
    const map = {};
    for (const p of plays) {
      const dk = dayKey(p.date);
      for (const e of entryFn(p)) {
        let rec = map[e.key];
        if (!rec) rec = map[e.key] = { label: e.label, sub: e.sub, album: e.album, open: e.open, days: new Set() };
        rec.days.add(dk);
      }
    }
    let best = null;
    for (const rec of Object.values(map)) {
      const sorted = [...rec.days].sort();
      let mx = 1, cur = 1, mxStart = sorted[0], mxEnd = sorted[0], curStart2 = sorted[0];
      for (let i = 1; i < sorted.length; i++) {
        const diff = Math.round((new Date(sorted[i]) - new Date(sorted[i-1])) / 86400000);
        if (diff === 1) { cur++; } else { if (cur > mx) { mx = cur; mxStart = curStart2; mxEnd = sorted[i-1]; } cur = 1; curStart2 = sorted[i]; }
      }
      if (cur > mx) { mx = cur; mxStart = curStart2; mxEnd = sorted[sorted.length - 1]; }
      if (mx >= 2 && (!best || mx > best.count)) best = { label: rec.label, sub: rec.sub, album: rec.album, open: rec.open, count: mx, start: mxStart, end: mxEnd };
    }
    return best;
  }

  const bestArtist = bestEntityStreak(p => {
    const arts = (p.artists && p.artists.length) ? p.artists : [p.artist];
    return arts.map(a => ({ key: 'a:' + a, label: a, open: a }));
  });
  const bestAlbum = bestEntityStreak(p => {
    if (!p.album || p.album === '—') return [];
    const ar = albumArtist(p);
    return [{ key: 'al:' + ar + '|||' + p.album, label: p.album, sub: ar, open: albumKeyOf(p) }];
  });
  const bestSong = bestEntityStreak(p => ([{
    key: songKey(p), label: p.title, sub: p.artist, open: songKey(p),
    album: (p.album && p.album !== '—') ? p.album : null,
  }]));

  // Art-backed entity cards — an <img> layer fades in over an icon/initials
  // fallback once the async lookup below resolves, matching the lazy-art
  // pattern used by the main streak banner (_fetchStreakArt/_fetchPlayArt).
  const entityCard = (kind, icon, labelKey, best) => {
    if (!best) return '';
    const subject = best.sub ? `${esc(best.label)} · ${esc(best.sub)}` : esc(best.label);
    const fallback = initials(best.label);
    // the card opens that artist's, album's or song's page (see stOpenStreakEntity)
    return `<div class="st-streak-card st-streak-card--entity st-streak-card--link" role="button" tabindex="0"
        data-st-streak-open="${kind}" data-st-streak-key="${esc(best.open || '')}" title="${esc(t('st_streak_open'))}">
        <div class="st-streak-entity-art">
          <img id="stStreakArt_${kind}" class="st-streak-entity-bg" src="" alt=""
               onload="this.classList.add('loaded')">
          <div class="st-streak-entity-fallback">${esc(fallback)}</div>
        </div>
        <div class="st-streak-entity-overlay">
          <div class="st-streak-num-row">
            <span class="st-streak-num">${best.count}</span>
            <span class="st-streak-entity-unit">${t('st_streak_days_unit')}</span>
          </div>
          <div class="st-streak-subject" title="${subject}">${icon} ${subject}</div>
          <div class="st-streak-lbl">${t(labelKey)}</div>
          <div class="st-streak-dates">${fmtDay(best.start)} – ${fmtDay(best.end)}</div>
        </div>
      </div>`;
  };
  // All-Time has no "this period" streak, so its band uses the longest ever
  _stFacts.streak = stPeriodType === 'alltime'
    ? { n: longestAll, start: longestStart ? fmtDay(longestStart) : '', end: longestEnd ? fmtDay(longestEnd) : '', artist: bestArtist ? bestArtist.label : null }
    : { n: longestPeriod, start: periodStart ? fmtDay(periodStart) : '', end: periodEnd ? fmtDay(periodEnd) : '', artist: bestArtist ? bestArtist.label : null };
  const entityCardsHtml = entityCard('artist', stIco('mic'), 'st_streak_artist', bestArtist)
    + entityCard('album', stIco('disc'), 'st_streak_album', bestAlbum)
    + entityCard('song', stIco('repeat'), 'st_streak_song', bestSong);

  // ── The four cards: just a number, its unit and a short label. Clicking
  // one lights its days on the calendar and shows its details in the panel
  // under the cards (one panel, so the cards stay easy to read).
  const periodLabel = stGetPeriodLabel();
  const range = (a, b) => !a ? '' : a === b ? fmtDay(a) : `${fmtDay(a)} – ${fmtDay(b)}`; // one day: just its date
  // "1 day in a row" / "1 day without music", not "1 days"
  const unitFor = (n, key) => t(n === 1 ? key + '_one' : key);
  // When the period's best streak is the all-time record, one card says both
  const sameStreak = stPeriodType !== 'alltime' && longestPeriod === longestAll
    && periodStart === longestStart && periodEnd === longestEnd;
  const everLines = [
    range(longestStart, longestEnd),
    !reachesToday ? esc(t('st_streak_longest_asof', { period: periodLabel })) : '',
    beatOld ? esc(t('st_streak_beat', { n: beatOld })) : '',
    (stPeriodType === 'alltime' || sameStreak) ? fuelText(topSongBetween(longestStart, longestEnd)) : '',
  ];
  const picks = {
    days: {
      title: stPeriodType === 'alltime' ? t('st_streak_active_days') : t('st_streak_active_days_in', { period: periodLabel }),
      lines: [esc(t('st_streak_active_days_sub', { pct: activeDaysPct, total: totalDaysInPeriod })), vsLine],
      hl: 'on',
    },
    ever: { title: t('st_streak_longest'), lines: everLines, hl: { start: longestStart, end: longestEnd } },
    period: {
      title: t('st_streak_in_period', { period: periodLabel }),
      lines: [range(periodStart, periodEnd), periodRank > 1 ? esc(t('st_streak_rank', { n: periodRank })) : '',
        longestPeriod >= 2 ? fuelText(topSongBetween(periodStart, periodEnd)) : ''],
      hl: { start: periodStart, end: periodEnd },
    },
    break: {
      title: t('st_streak_break'),
      lines: [brk.n ? range(brk.start, brk.end) : esc(t('st_streak_break_none')),
        missedTotal ? esc(t(missedKey, { n: missedTotal, period: periodLabel })) : ''],
      hl: brk.n ? { start: brk.start, end: brk.end } : null,
    },
  };
  const card = (key, num, unit, label, extra, cls) => `<div class="st-streak-card${cls || ''}" data-st-pick="${key}" role="button" tabindex="0" aria-pressed="false">
        <div class="st-streak-num-stack">
          <span class="st-streak-num">${num}</span>
          <span class="st-streak-unit">${unit}</span>
        </div>
        <div class="st-streak-lbl">${label}</div>
        ${extra || ''}
      </div>`;
  const recordBadge = isNewRecord ? `<div class="st-streak-badge">${stIco('trophy')} ${t('st_streak_new_record')}</div>`
    : sameStreak ? `<div class="st-streak-badge">${stIco('trophy')} ${esc(t('st_streak_best_of', { period: periodLabel }))}</div>` : '';

  el.innerHTML = `
    <div class="st-streaks-grid">
      ${card('days', activeDays, esc(t('st_streak_of_days', { total: totalDaysInPeriod })), esc(t('st_streak_days_lbl')))}
      ${card('ever', longestAll, unitFor(longestAll, 'st_streak_days_unit'), esc(t('st_streak_alltime_best')), recordBadge, isNewRecord ? ' st-streak-card--record' : '')}
      ${stPeriodType !== 'alltime' && !sameStreak ? card('period', longestPeriod, unitFor(longestPeriod, 'st_streak_days_unit'), esc(t('st_streak_best_period', { period: periodLabel }))) : ''}
      ${card('break', brk.n, unitFor(brk.n, 'st_streak_break_unit'), esc(t('st_streak_break_short')), '', ' st-streak-card--break')}
    </div>
    <div class="st-streak-detail" aria-live="polite">${esc(t('st_streak_pick_hint'))}</div>
    ${calHtml}
    ${entityCardsHtml ? `
    <div class="st-streak-subhead">${stPeriodType === 'alltime' ? t('st_streak_category_title_all') : t('st_streak_category_title', { period: stGetPeriodLabel() })}</div>
    ${stRowHtml('st-streaks-grid--entity', entityCardsHtml)}` : ''}`;
  stRowsInit(el);

  // Picking a card: mark it, fill the panel, dim every other day on the
  // calendar. Clicking the picked card again puts the hint back.
  const panel = el.querySelector('.st-streak-detail');
  const cal = el.querySelector('.st-cal');
  const pick = key => {
    const cur = el.dataset.pick === key ? '' : key;
    el.dataset.pick = cur;
    let fc = '';
    el.querySelectorAll('[data-st-pick]').forEach(c => {
      const on = c.dataset.stPick === cur;
      c.classList.toggle('is-picked', on);
      c.setAttribute('aria-pressed', on);
      if (on) fc = getComputedStyle(c).getPropertyValue('--fc');
    });
    const info = picks[cur];
    panel.classList.toggle('is-open', !!info);
    panel.style.setProperty('--fc', fc || '');
    panel.innerHTML = info
      ? `<b>${esc(info.title)}</b>${info.lines.filter(Boolean).map(l => `<span>${l}</span>`).join('')}`
      : esc(t('st_streak_pick_hint'));
    if (!cal) return;
    let any = false;
    cal.querySelectorAll('.st-cal-day[data-d]').forEach(c => {
      const d = c.dataset.d, hl = info && info.hl;
      const on = !!hl && (hl === 'on' ? /\blv\d/.test(c.className) : d >= hl.start && d <= hl.end);
      c.classList.toggle('is-hl', on);
      if (on) any = true;
    });
    // nothing of it on this calendar (a record from an earlier year): don't dim it all
    cal.classList.toggle('has-pick', any);
  };
  el.dataset.pick = '';
  el.onclick = e => { const c = e.target.closest('[data-st-pick]'); if (c) pick(c.dataset.stPick); };
  el.onkeydown = e => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const c = e.target.closest('[data-st-pick]');
    if (c) { e.preventDefault(); pick(c.dataset.stPick); }
  };

  [['artist', bestArtist], ['album', bestAlbum], ['song', bestSong]].forEach(([kind, best]) => {
    if (!best) return;
    _fetchEntityStreakArt(kind, best).then(url => {
      if (!url) return;
      const img = document.getElementById('stStreakArt_' + kind);
      if (img) img.src = url;
    });
  });
}

// An artist / album / song streak card opens that one's page
function stOpenStreakEntity(card) {
  const key = card.dataset.stStreakKey;
  if (!key) return;
  const kind = card.dataset.stStreakOpen;
  if (kind === 'artist') openArtistModal(key);
  else if (kind === 'album') openAlbumModal(key);
  else if (kind === 'song') openSongModal(key);
}
document.addEventListener('click', e => {
  const card = e.target.closest && e.target.closest('[data-st-streak-open]');
  if (card) stOpenStreakEntity(card);
});
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  const card = e.target.closest && e.target.closest('[data-st-streak-open]');
  if (card) { e.preventDefault(); stOpenStreakEntity(card); }
});

async function _fetchEntityStreakArt(kind, best) {
  try {
    if (kind === 'artist') return await getArtAuto('artist', best.label);
    if (kind === 'album')  return await getArtAuto('album', best.label, best.sub, best.label);
    if (kind === 'song')   return best.album ? await getArtAuto('album', best.album, best.sub, best.album) : await getArtAuto('song', best.label, best.sub);
  } catch (e) { return null; }
}

// ── Award winners in your charts ──────────────────────────────
// Chapter 9: which of the period's top artists won an award that year — your
// own My Grammys picks plus the real shows held that year (Grammys, VMAs, AMAs,
// iHeartRadio, World Music, Billboard, ARIA, Juno, BRIT). A real show counts in
// the year it was held, even though it honours the year before, so a year's
// Soundtrack has its awards by the end of that year. Wins only.
let _stGrammyLoadToken = 0;
// Real wins already looked up, per period and set of artists, so a redraw
// (language switch, ballot sync) doesn't look them all up again.
//   "years|artist keys" → [{ ak, year, show, category, title }]
const _stRealWins = {};
const _stRealWinsBusy = new Set();
const ST_AW_TOP = 20;   // how many of the period's artists are checked

// The award years the Soundtrack period covers
function stGrammyYears() {
  if (stPeriodType !== 'alltime') return [stYear];
  if (!allPlays.length) return [];
  const minYear = tzDate(allPlays[allPlays.length - 1].date).getFullYear();
  const maxYear = tzNow().getFullYear();
  const out = [];
  for (let y = minYear; y <= maxYear; y++) out.push(y);
  return out;
}

// Redraws chapter 9 and its band once ballots or real wins arrive (or change
// in the cloud), without re-rendering the whole Soundtrack.
function stRefreshGrammys() {
  if (!document.getElementById('stGrammysBody') || !_stCurrentPlays) return;
  delete _stFacts.grammys;
  stRenderGrammys(_stCurrentPlays);
  stFillGrammysHead();
  stNumberChapters();
}

// The real awards these artists won at shows held in these years, from the
// same sources as Awards → Real-Life Awards: the Grammys through grammy-proxy
// (one call per artist covers every year) and the other eight shows from
// Wikipedia (one page per show and year, saved on the device for good).
// All-Time only reads the Wikipedia years already saved: fetching every show
// for every year at once would be a hundred-odd pages and could fill the
// device's storage. Resolves to { wins: [{ ak, year, show, category, title }], failed }.
async function stLoadRealWins(years, top, alltime) {
  const want = new Set(years);
  const wins = [];
  const seen = new Set();
  let failed = false;
  const add = w => {
    const k = [w.ak, w.year, w.show, w.category, w.title].join('|').toLowerCase();
    if (!seen.has(k)) { seen.add(k); wins.push(w); }
  };

  // Grammys: each artist's whole record, kept to the years asked for
  const records = await _grammyMapLimit(top, REAL_LIFE_CONCURRENCY, a => _grammyFetchArtist(a.artist));
  records.forEach((data, i) => {
    if (!data?.found) return;
    for (const e of data.entries || []) {
      if (e.won && want.has(e.year)) add({ ak: top[i].key, year: e.year, show: 'Grammys', category: e.category, title: e.title || '' });
    }
  });

  // The Wikipedia shows, only in years each one was held
  const byKey = new Map();   // _rlWikiKey(name) → top artist
  for (const a of top) {
    const k = _rlWikiKey(a.artist);
    if (k.length >= 2 && !byKey.has(k)) byKey.set(k, a);
  }
  const stored = alltime ? _rlWikiStored() : null;
  const jobs = [];
  for (const [id, show] of Object.entries(RL_WIKI_SHOWS)) {
    for (const y of years) {
      if (y < show.first || (show.years && !show.years.includes(y))) continue;
      if (stored && !stored[id + ':' + y]) continue;
      jobs.push([id, y]);
    }
  }
  // Two at a time: Wikipedia turns away a burst of requests
  await _grammyMapLimit(jobs, 2, async ([id, y]) => {
    const data = await _rlWikiFetchYear(id, y);
    if (data?.error) failed = true;
    if (!data?.found) return;
    // Producer / engineer / photographer awards name the winner first and the
    // artists they worked for after ("Cirkut: "APT.", Rosé and Bruno Mars; …"),
    // so there only the person named first counts as having won
    for (const cat of data.categories) for (const nom of cat.nominees) {
      if (!nom.won) continue;
      const hits = /producer|engineer|non-performing|photographer/i.test(cat.name)
        ? [byKey.get(_rlWikiKey((nom.who || '').split(/[:;,("]/)[0]))].filter(Boolean)
        : _rlWikiMatch(nom, byKey);
      for (const a of hits) add({ ak: a.key, year: y, show: RL_WIKI_SHOWS[id].short, category: cat.name, title: nom.title || '' });
    }
  });
  return { wins, failed };
}

function stRenderGrammys(plays) {
  const el = document.getElementById('stGrammysBody');
  if (!el) return;
  // With no winners the chapter is a quiet line with a way to Awards, not a
  // numbered chapter with a big "nothing" headline (stNumberChapters skips it).
  // While the real shows are still being checked, the line says so instead.
  const sec = document.getElementById('stGrammysSection');
  const quiet = checking => {
    sec?.classList.add('st-chap--quiet');
    const msg = checking ? t('st_aw_checking')
      : stPeriodType === 'alltime' ? t('st_aw_none_all') : t('st_aw_none', { period: stGetPeriodLabel() });
    el.innerHTML = `<p class="st-quiet">${stIco('trophy')}<span>${esc(msg)}</span>
      ${checking ? '' : `<button type="button" class="dc-btn dc-btn-normal dc-btn-sm" onclick="dcGoTab('awards')">${esc(t('st_grammys_open'))}</button>`}</p>`;
  };
  sec?.classList.remove('st-chap--quiet');
  if (!plays.length) { quiet(false); return; }

  const artistCounts = {}, artistNames = {};
  for (const p of plays) {
    const ak = p.artist.toLowerCase();
    artistCounts[ak] = (artistCounts[ak] || 0) + 1;
    if (!artistNames[ak]) artistNames[ak] = p.artist;
  }
  const topArtistKeys = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, ST_AW_TOP).map(([a]) => a);

  // Only the period's own year counts (a month uses its year); All-Time takes
  // every year since the first play.
  const years = stGrammyYears();
  // A ballot saved earlier lives on the device / in the cloud but only reaches
  // _awardsYearData once the Awards tab loads it. Load the missing years here so
  // the chapter never needs a trip to Awards first, then draw it again.
  const missing = years.filter(y => !_awardsYearData[y]);
  if (missing.length) {
    const token = ++_stGrammyLoadToken;
    Promise.all(missing.map(y => _awardsLoad(y).catch(() => null))).then(() => {
      if (token !== _stGrammyLoadToken) return;   // the period changed meanwhile
      stRefreshGrammys();
    });
  }

  // The real shows: looked up once per period, then drawn again when they land
  const realKey = years.join(',') + '|' + topArtistKeys.join('\u0001');
  const real = _stRealWins[realKey];
  if (!real && !_stRealWinsBusy.has(realKey)) {
    _stRealWinsBusy.add(realKey);
    const top = topArtistKeys.map(ak => ({ key: ak, artist: artistNames[ak] }));
    stLoadRealWins(years, top, stPeriodType === 'alltime')
      .catch(() => ({ wins: [], failed: true }))
      .then(({ wins, failed }) => {
        _stRealWinsBusy.delete(realKey);
        // Kept even if a show couldn't be reached, so the chapter still shows
        // what did come back; the next visit to the tab tries the rest again
        _stRealWins[realKey] = wins;
        if (failed) setTimeout(() => { delete _stRealWins[realKey]; }, 0);
        // Only redraw if this is still the period on screen
        if (_stCurrentPlays === plays) stRefreshGrammys();
      });
  }
  const checking = !real;

  // Every win per artist: your My Grammys picks for those years, then the real ones
  const grammyMap = {};
  const mine = t('awards_tab_mygrammys');
  if (typeof _awardsYearData !== 'undefined') {
    for (const yr of years) {
      const data = _awardsYearData[yr];
      if (!data || !data.categories) continue;
      for (const [catId, cat] of Object.entries(data.categories)) {
        if (!cat.enabled || !cat.winner || !cat.winner.artist) continue;
        const ak = cat.winner.artist.toLowerCase();
        if (!grammyMap[ak]) grammyMap[ak] = [];
        grammyMap[ak].push({ year: +yr, show: mine, category: AWARD_CATEGORIES.find(c => c.id === catId)?.label || catId, title: cat.winner.title || '' });
      }
    }
  }
  for (const w of real || []) {
    if (!grammyMap[w.ak]) grammyMap[w.ak] = [];
    grammyMap[w.ak].push({ year: w.year, show: w.show, category: w.category, title: w.title, real: true });
  }

  const withAwards = topArtistKeys
    .filter(ak => grammyMap[ak] && grammyMap[ak].length > 0)
    .map(ak => ({
      artist: artistNames[ak] || ak,
      plays: artistCounts[ak],
      entries: grammyMap[ak]
    }));

  if (!withAwards.length) { quiet(checking); return; }

  _stFacts.grammys = { n: withAwards.length, top: withAwards[0].artist };
  const shown = withAwards.slice(0, 8);
  el.innerHTML = `<div class="st-grammy-grid">${shown.map((item, i) => {
    // Real wins and your own My Grammys picks are told apart everywhere: the
    // gold ribbon counts only real wins, a star tag in the theme colour counts
    // your picks, and your picks' rows below take that colour too
    const wins = item.entries.filter(e => e.real).length;
    const picks = item.entries.length - wins;
    // Newest first; within a year the real shows before your own picks
    const sorted = [...item.entries].sort((a, b) => b.year - a.year || (b.real ? 1 : 0) - (a.real ? 1 : 0));
    return `<div class="st-grammy-card" style="--i:${i}" onclick="stToggleGrammyCard(this)">
      <div class="st-grammy-card-photo">
        <img id="stGrammyArt_${i}" class="st-grammy-card-bg" src="" alt="" onload="this.classList.add('loaded')">
        <div class="st-grammy-card-fallback">${esc(initials(item.artist))}</div>
        ${wins ? `<div class="st-grammy-ribbon">${stIco('trophy')} ${wins} ${wins === 1 ? t('st_grammy_win') : t('st_grammy_wins')}</div>` : ''}
        <div class="st-grammy-card-overlay">
          ${picks ? `<div class="st-grammy-mine">${stIco('star')} ${picks} · ${esc(t('awards_tab_mygrammys'))}</div>` : ''}
          <div class="st-grammy-card-artist" title="${esc(item.artist)}">${esc(item.artist)}</div>
          <div class="st-grammy-card-plays">${item.plays.toLocaleString()} ${tUnit('plays', item.plays)}</div>
        </div>
        <div class="st-grammy-card-chevron">▾</div>
      </div>
      <div class="st-grammy-detail">${sorted.map(e => `<div class="st-grammy-detail-row${e.real ? '' : ' is-mine'}">
        <span class="st-grammy-detail-year">${e.real ? '' : stIco('star')}${esc(String(e.year))} · ${esc(e.show)}</span>
        <span class="st-grammy-detail-cat">${esc(e.category)}</span>
        ${e.title ? `<span class="st-grammy-detail-work">${esc(e.title)}</span>` : ''}
      </div>`).join('')}</div>
    </div>`;
  }).join('')}</div>${checking ? `<p class="st-aw-checking">${esc(t('st_aw_checking'))}</p>` : ''}`;

  // Queued through the shared queueImg() (see stLoyaltyImg above) instead of
  // firing every card's lookup at once.
  shown.forEach((item, i) => {
    queueImg(() => getArtistImage(item.artist).then(url => {
      if (!url) return;
      const img = document.getElementById('stGrammyArt_' + i);
      if (img) img.src = url;
    }));
  });
}

function stToggleGrammyCard(card) {
  const wasOpen = card.classList.contains('st-grammy-card--open');
  card.parentElement.querySelectorAll('.st-grammy-card--open').forEach(c => { if (c !== card) c.classList.remove('st-grammy-card--open'); });
  card.classList.toggle('st-grammy-card--open', !wasOpen);
}

// ── Underrated Gem (Last.fm only) ─────────────────────────────
function stRenderGem(plays) {
  const gemSection = document.getElementById('stGemSection');
  if (!gemSection) return;
  const source = localStorage.getItem('dc_source') || '';
  if (source !== 'lastfm') { gemSection.style.display = 'none'; return; }
  gemSection.style.display = '';
  const el = document.getElementById('stGemBody');
  if (!plays.length) { el.innerHTML = ''; return; }

  const apiKey = localStorage.getItem('dc_lfm_api_key') || '';
  if (!apiKey) { gemSection.style.display = 'none'; return; }

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 8);

  el.innerHTML = `<div class="st-gem-loading">${t('st_gem_loading')}</div>`;

  const fetches = topSongs.slice(0, 5).map(s =>
    fetch(`https://ws.audioscrobbler.com/2.0/?method=track.getInfo&api_key=${encodeURIComponent(apiKey)}&artist=${encodeURIComponent(s.artist)}&track=${encodeURIComponent(s.title)}&format=json`)
      .then(r => r.json())
      .then(d => ({ ...s, listeners: parseInt(d?.track?.listeners || '0') || 0 }))
      .catch(() => ({ ...s, listeners: 0 }))
  );

  Promise.all(fetches).then(results => {
    const valid = results.filter(s => s.listeners > 100);
    if (!valid.length) { gemSection.style.display = 'none'; stNumberChapters(); return; }
    valid.sort((a, b) => (b.count / Math.log(b.listeners + 1)) - (a.count / Math.log(a.listeners + 1)));
    const gem = valid[0];
    stFillHead('gem', { label: t('st_gem_title'), title: esc(gem.title), sub: esc(gem.artist), bg: ['song', gem.title, gem.artist] });
    stNumberChapters();
    el.innerHTML = `
      <div class="st-gem-card">
        <div class="st-gem-icon">${stIco('gem')}</div>
        <div class="st-gem-info">
          <div class="st-gem-title">${esc(gem.title)}</div>
          <div class="st-gem-artist">${esc(gem.artist)}</div>
          <div class="st-gem-stats">
            <span>${t('st_gem_your_plays', { n: gem.count.toLocaleString() })}</span>
            <span class="st-gem-sep">·</span>
            <span>${t('st_gem_listeners', { n: gem.listeners.toLocaleString() })}</span>
          </div>
          <div class="st-gem-sub">${t('st_gem_sub')}</div>
        </div>
      </div>`;
  });
}

// ── Chart History Replay — "on-air countdown" broadcast ─────────
// Spells out the month like "July 19th" instead of "19/7" — English gets an
// ordinal suffix (native convention); other locales use Intl's own month/day
// ordering ("19 de julio") since ordinal date suffixes aren't idiomatic there.
function stReplayFormatWeekDate(dateObj) {
  const locale = currentLang === 'en' ? 'en-US' : currentLang;
  if (locale.startsWith('en')) {
    const month = dateObj.toLocaleDateString(locale, { month: 'long' });
    const day = dateObj.getDate();
    const suffix = (day % 10 === 1 && day !== 11) ? 'st'
      : (day % 10 === 2 && day !== 12) ? 'nd'
      : (day % 10 === 3 && day !== 13) ? 'rd' : 'th';
    return `${month} ${day}${suffix}`;
  }
  return dateObj.toLocaleDateString(locale, { month: 'long', day: 'numeric' });
}

// Movement badges compare each week's cumulative top5 against the previous
// week's so the replay reads like a real countdown-show rundown (▲/▼/NEW/—).
function stReplayMovementInfo(name, i, prevTop5) {
  if (!prevTop5) return { cls: '', text: '' };
  const prevIdx = prevTop5.findIndex(([n]) => n === name);
  if (prevIdx === -1) return { cls: 'st-replay-move-new', text: t('st_replay_new') };
  if (prevIdx === i) return { cls: 'st-replay-move-same', text: '—' };
  const diff = Math.abs(prevIdx - i);
  return prevIdx > i ? { cls: 'st-replay-move-up', text: '▲' + diff } : { cls: 'st-replay-move-down', text: '▼' + diff };
}

// FLIP-reorders the row elements from the previous week's positions to this
// week's, same technique as the main chart's play-by-play replay
// (replay.js) — rows are kept and moved/resized rather than
// wiped and redrawn, so entries visibly slide/grow instead of flashing.
function stReplayRenderRows(rowsEl, snap, prevTop5) {
  const newTop5 = snap.top5;
  const newKeys = new Set(newTop5.map(([name]) => name));
  const existingMap = new Map();
  for (const child of Array.from(rowsEl.children)) existingMap.set(child.dataset.artist, child);

  // FLIP read-1: freeze transitions, measure current positions of rows that survive
  const firstTops = new Map();
  for (const [key, el] of existingMap) {
    if (newKeys.has(key)) {
      el.style.transition = 'none';
      el.style.transform = '';
      firstTops.set(el, el.getBoundingClientRect().top);
    }
  }

  // Rows that fell out of the top5 fade out and get removed
  for (const [key, el] of existingMap) {
    if (!newKeys.has(key)) {
      el.style.transition = 'opacity 250ms ease, transform 250ms ease';
      el.style.transform = 'translateY(6px)';
      el.style.opacity = '0';
      el._removeTimer = setTimeout(() => el.remove(), 260);
    }
  }

  const newlyCreated = [];
  newTop5.forEach(([name, count], i) => {
    let el = existingMap.get(name);
    const isNew = !el;
    if (!isNew && el._removeTimer) { clearTimeout(el._removeTimer); el._removeTimer = null; el.style.opacity = '1'; } // rejoined before fade-out finished
    if (isNew) {
      el = document.createElement('div');
      el.dataset.artist = name;
      el.style.opacity = '0';
      el.innerHTML = `
        <span class="st-replay-rank"></span>
        <div class="st-replay-avatar">${thumbHtml(imgCache['artist:' + name.toLowerCase() + ':deezer'], name, false)}</div>
        <div class="st-replay-bar-wrap">
          <div class="st-replay-bar" style="width:0%"></div>
          <span class="st-replay-name">${esc(name)}</span>
        </div>
        <span class="st-replay-move"></span>
        <span class="st-replay-count"></span>`;
      // Queued through the shared queueImg() (see stLoyaltyImg above) — playback
      // can introduce several new artists per step, and fast stepping through
      // history shouldn't burst the Deezer proxy.
      queueImg(() => getArtAuto('artist', name).then(url => {
        if (!el.isConnected || !url) return;
        el.querySelector('.st-replay-avatar').innerHTML = thumbHtml(url, name, false);
      }));
      newlyCreated.push(el);
    }
    el.className = 'st-replay-row' + (i === 0 ? ' st-replay-row-top' : '');
    el.querySelector('.st-replay-rank').textContent = i + 1;
    el.querySelector('.st-replay-bar').style.width = Math.round(count / _stReplayMax * 100) + '%';
    el.querySelector('.st-replay-count').textContent = count.toLocaleString();
    const info = stReplayMovementInfo(name, i, prevTop5);
    const moveEl = el.querySelector('.st-replay-move');
    moveEl.className = 'st-replay-move ' + info.cls;
    moveEl.textContent = info.text;
    rowsEl.appendChild(el); // moves existing nodes into rank order, appends new ones at the end
  });

  // FLIP read-2 + play: measure the post-reorder position, apply the inverse
  // transform so rows appear unmoved, then release it into the CSS transition.
  requestAnimationFrame(() => {
    for (const [el, top] of firstTops) {
      if (!el.isConnected) continue;
      const dy = top - el.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) el.style.transform = `translateY(${dy}px)`;
    }
    requestAnimationFrame(() => {
      for (const [el] of firstTops) {
        if (!el.isConnected) continue;
        el.style.transition = '';
        el.style.transform = '';
      }
      for (const el of newlyCreated) { el.style.transition = ''; el.style.opacity = '1'; }
    });
  });
}

// Builds the static shell (controls + scrubber) once so the interval never
// destroys the buttons the user is trying to click — only stReplayRender's
// text/rows patch after this. Rebuilding the whole canvas every tick was the
// original bug: a click's mouseup could land on an already-detached button.
function stReplayBuildShell(canvas) {
  canvas.innerHTML = `
    <div class="st-replay-header">
      <div class="st-replay-week-label" id="stReplayWeekLabel"></div>
      <div class="st-replay-controls">
        <button class="st-replay-speed-btn" id="stReplaySpeedBtn" onclick="stReplayCycleSpeed()" title="${t('st_replay_speed_title')}"></button>
        <!-- ‹ / › step one week at a time; stepping pauses the auto-play -->
        <button class="st-replay-pause-btn st-replay-step-btn" id="stReplayPrevBtn" onclick="stReplayStep(-1)" title="${t('st_replay_prev_title')}" aria-label="${t('st_replay_prev_title')}">‹</button>
        <button class="st-replay-pause-btn" id="stReplayPauseBtn" onclick="stReplayTogglePause()" title="${t('st_replay_pause_title')}"></button>
        <button class="st-replay-pause-btn st-replay-step-btn" id="stReplayNextBtn" onclick="stReplayStep(1)" title="${t('st_replay_next_title')}" aria-label="${t('st_replay_next_title')}">›</button>
      </div>
    </div>
    <div class="st-replay-progress" id="stReplayProgress"></div>
    <input type="range" class="st-replay-scrubber" id="stReplayScrubber" min="0" max="${_stReplaySnapshots.length - 1}" value="0"
      oninput="stReplayScrub(this.value)" aria-label="${t('st_replay_scrub_label')}">
    <div class="st-replay-rows" id="stReplayRows"></div>`;
}

function stReplayRender() {
  const canvas = document.getElementById('stReplayCanvas');
  if (!canvas || !_stReplaySnapshots.length) return;
  if (!document.getElementById('stReplayRows')) stReplayBuildShell(canvas);
  if (_stReplayIdx >= _stReplaySnapshots.length) { _stReplayIdx = _stReplaySnapshots.length - 1; }
  const snap = _stReplaySnapshots[_stReplayIdx];
  const prevTop5 = _stReplaySnapshots[_stReplayIdx - 1]?.top5 || null;
  const atEnd = _stReplayIdx === _stReplaySnapshots.length - 1;

  document.getElementById('stReplayWeekLabel').textContent = t('st_replay_week_of', { date: stReplayFormatWeekDate(snap.date), year: stYear });
  document.getElementById('stReplayProgress').textContent = t('st_replay_progress', { n: _stReplayIdx + 1, total: _stReplaySnapshots.length });
  document.getElementById('stReplaySpeedBtn').textContent = ({300:'2',600:'1',1200:'0.5'})[_stReplaySpeedMs] + '×';
  document.getElementById('stReplayPauseBtn').textContent = _stReplayPaused ? (atEnd ? '↻' : '▶') : '⏸';
  // Step buttons grey out at the first / last week.
  document.getElementById('stReplayPrevBtn').disabled = _stReplayIdx === 0;
  document.getElementById('stReplayNextBtn').disabled = atEnd;
  stReplayRenderRows(document.getElementById('stReplayRows'), snap, prevTop5);
  const scrubberEl = document.getElementById('stReplayScrubber');
  if (scrubberEl && document.activeElement !== scrubberEl) scrubberEl.value = _stReplayIdx;
}

function stReplayAdvance() {
  _stReplayIdx++;
  if (_stReplayIdx >= _stReplaySnapshots.length) { stReplayTogglePause(true); _stReplayIdx = _stReplaySnapshots.length - 1; return; }
  stReplayRender();
}

function stReplayStartTimer() {
  if (_stReplayTimer) clearInterval(_stReplayTimer);
  _stReplayTimer = setInterval(stReplayAdvance, _stReplaySpeedMs);
}

function stReplayTogglePause(forcePause) {
  _stReplayPaused = forcePause === true ? true : !_stReplayPaused;
  if (_stReplayPaused) {
    if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  } else {
    // Resuming after the countdown finished starts it over from week 1.
    if (_stReplayIdx >= _stReplaySnapshots.length - 1) _stReplayIdx = 0;
    stReplayStartTimer();
  }
  stReplayRender();
}

function stReplayCycleSpeed() {
  // Cycle 1x → 2x → 0.5x, restarting the timer at the new cadence if playing.
  _stReplaySpeedMs = _stReplaySpeedMs === 600 ? 300 : _stReplaySpeedMs === 300 ? 1200 : 600;
  if (!_stReplayPaused) stReplayStartTimer();
  stReplayRender();
}

function stReplayScrub(val) {
  // Manual scrubbing pauses auto-advance so the user can inspect any week.
  _stReplayPaused = true;
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  _stReplayIdx = Math.max(0, Math.min(_stReplaySnapshots.length - 1, parseInt(val, 10) || 0));
  stReplayRender();
}

// Manual week-by-week stepping (‹ / › buttons). Pauses auto-advance like the
// scrubber does, so the user stays on the week they stepped to.
function stReplayStep(dir) {
  stReplayScrub(_stReplayIdx + dir);
}

function stStartReplay() {
  if (stPeriodType !== 'year' || !allPlays.length) return;
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  const canvas = document.getElementById('stReplayCanvas');
  if (!canvas) return;

  replayBtn.style.display = 'none';
  replayStop.style.display = '';
  canvas.style.display = '';
  canvas.innerHTML = `<div class="st-replay-loading">${t('st_replay_loading')}</div>`;

  // Build weekly snapshots for the selected year
  const yearPlays = allPlays.filter(p => tzDateOf(p).getFullYear() === stYear);
  if (!yearPlays.length) { canvas.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`; return; }

  // Group by week
  const weekMap = {};
  for (const p of yearPlays) {
    const wk = playWeekKeyOf(p);
    (weekMap[wk] || (weekMap[wk] = [])).push(p);
  }
  const weeks = Object.keys(weekMap).sort();

  // Build cumulative top artist per week snapshot
  const snapshots = [];
  const runningCounts = {};
  for (const wk of weeks) {
    for (const p of weekMap[wk]) {
      runningCounts[p.artist] = (runningCounts[p.artist] || 0) + 1;
    }
    const top5 = Object.entries(runningCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);
    const [wy, wm, wd] = wk.split('-').map(Number);
    snapshots.push({ week: wk, date: new Date(wy, wm - 1, wd), top5 });
  }

  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }

  _stReplaySnapshots = snapshots;
  _stReplayIdx = 0;
  _stReplayPaused = false;
  _stReplaySpeedMs = 1200;
  _stReplayMax = Math.max(...snapshots.map(s => s.top5[0]?.[1] || 0));

  stReplayRender();
  stReplayStartTimer();
}

function stStopReplay() {
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  _stReplaySnapshots = [];
  _stReplayPaused = false;
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  if (replayBtn) replayBtn.style.display = '';
  if (replayStop) replayStop.style.display = 'none';
}

// ── Shareable Card ────────────────────────────────────────────
// Built on the same share-card design system as the chart, chart-run and entry
// images (SHARE_FORMATS / SHARE_PALETTES / shShell / shCapture) — see the
// SHARE CARD DESIGN SYSTEM block for the primitives and the html2canvas rules.

const stCard = {
  format: 'story',
  template: 'recap',
  palette: 'app',
  textScale: 100,
  quality: 2,
  topN: 5,
  showStats: true,
  showArtists: true,
  showSongs: true,
  showPeak: true,
  showArt: true,
  showFooter: true,
  artSource: 'deezer',
};
const ST_CARD_KEYS = ['format', 'template', 'palette', 'textScale', 'quality', 'topN',
  'showStats', 'showArtists', 'showSongs', 'showPeak', 'showArt', 'showFooter', 'artSource'];
const stArtCache = {}; // `a:<artist>:<src>` / `s:<songKey>:<src>` → data URL or null

function stSaveCardSettings() {
  try {
    const out = {};
    ST_CARD_KEYS.forEach(k => { out[k] = stCard[k]; });
    localStorage.setItem('dc_stCardSettings', JSON.stringify(out));
  } catch {}
}

function stLoadCardSettings() {
  try {
    const saved = JSON.parse(localStorage.getItem('dc_stCardSettings') || 'null');
    if (saved && typeof saved === 'object') {
      ST_CARD_KEYS.forEach(k => { if (saved[k] !== undefined) stCard[k] = saved[k]; });
    }
  } catch {}
  if (!SH_ST_TEMPLATES[stCard.template]) stCard.template = 'recap';
  if (!SHARE_PALETTES.some(p => p.id === stCard.palette)) stCard.palette = 'app';
  if (!SHARE_FORMATS[stCard.format]) stCard.format = 'story';
}

// ── Data prep ─────────────────────────────────────────────────
// Everything a soundtrack template needs, resolved once. Artists are counted
// per comma-split credit, the same rule the rest of the Soundtrack view uses,
// so "Tyler, The Creator" stays one artist and a duet counts for both.
function stCardContext(opts) {
  const plays = _stCurrentPlays || [];
  if (!plays.length) return null;
  const fmt = SHARE_FORMATS[opts.format] ? opts.format : 'story';
  const d = shDims(fmt);
  const n = Math.max(3, Math.min(10, opts.topN || 5));
  const src = opts.artSource || 'deezer';

  const artistCounts = {};
  for (const p of plays) {
    for (const a of (p.artists || splitArtists(p.artist))) artistCounts[a] = (artistCounts[a] || 0) + 1;
  }
  const topArtists = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, n)
    .map(([name, count], i) => ({ rank: i + 1, name, count, art: opts.showArt ? (stArtCache['a:' + name + ':' + src] || null) : null }));

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { key: sk, title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, n)
    .map((s, i) => Object.assign({ rank: i + 1, art: opts.showArt ? (stArtCache['s:' + s.key + ':' + src] || null) : null }, s));

  // Days, distinct artists and the busiest single day.
  const dayCounts = {};
  for (const p of plays) {
    const dd = tzDateOf(p);
    const dk = `${dd.getFullYear()}-${dd.getMonth()}-${dd.getDate()}`;
    (dayCounts[dk] || (dayCounts[dk] = { count: 0, date: dd })).count++;
  }
  let peakKey = null;
  for (const k in dayCounts) if (!peakKey || dayCounts[k].count > dayCounts[peakKey].count) peakKey = k;
  const peakDate = peakKey ? dayCounts[peakKey].date : null;

  // New discoveries — artists whose first ever play lands inside this period.
  const fsMap = stGetFirstSeenArtists();
  const splitArtistSet = new Set(plays.flatMap(p => p.artists || splitArtists(p.artist)));
  let newCount = 0;
  for (const a of splitArtistSet) {
    const fd = fsMap[a];
    if (!fd) continue;
    const ftz = tzDate(fd);
    const inPeriod = stPeriodType === 'alltime' ? true
      : stPeriodType === 'year' ? ftz.getFullYear() === stYear
        : ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
    if (inPeriod) newCount++;
  }

  const heroArt = (topArtists[0] && topArtists[0].art) || (topSongs[0] && topSongs[0].art) || null;
  return {
    opts, fmt, W: d.w, H: d.h, n,
    p: shPalette(opts.palette, shDominant(heroArt)),
    S: (opts.textScale || 100) / 100,
    plays, topArtists, topSongs, heroArt,
    periodLabel: stGetPeriodLabel(),
    title: t('nav_soundtrack'),
    totalPlays: plays.length,
    days: Object.keys(dayCounts).length,
    artists: new Set(plays.map(p => p.artist.toLowerCase())).size,
    newCount,
    peakLabel: peakDate ? `${t(ST_MONTH_KEYS[peakDate.getMonth()]).substring(0, 3)} ${peakDate.getDate()}` : '—',
    peakCount: peakKey ? dayCounts[peakKey].count : 0,
    playsWord: tUnit('plays', plays.length),
    artistsWord: t('st_top_artists'),
    songsWord: t('st_top_songs'),
  };
}

// ── Artwork ───────────────────────────────────────────────────
// Reuses the chart card's source-fallback fetcher, then inlines each hit as a
// data URL so the export canvas stays untainted and the Cover palette can read
// pixels back out of the leading image.
async function stPrefetchArt() {
  const src = stCard.artSource || 'deezer';
  const ctx = stCardContext(Object.assign({}, stCard, { showArt: false }));
  if (!ctx) return;
  const jobs = [];
  ctx.topArtists.forEach(a => {
    const ck = 'a:' + a.name + ':' + src;
    if (ck in stArtCache) return;
    jobs.push((async () => {
      const url = await _igFetchArtWithFallback('artists', { name: a.name }, src);
      stArtCache[ck] = url ? await _igToDataUrl(url) : null;
    })());
  });
  ctx.topSongs.forEach(s => {
    const ck = 's:' + s.key + ':' + src;
    if (ck in stArtCache) return;
    jobs.push((async () => {
      const url = await _igFetchArtWithFallback('songs', { title: s.title, artist: s.artist }, src);
      stArtCache[ck] = url ? await _igToDataUrl(url) : null;
    })());
  });
  await Promise.all(jobs);
  const hero = stArtCache['a:' + (ctx.topArtists[0] ? ctx.topArtists[0].name : '') + ':' + src]
    || stArtCache['s:' + (ctx.topSongs[0] ? ctx.topSongs[0].key : '') + ':' + src] || null;
  if (hero) await Promise.all([shComputeDominant(hero), shComputeBlur(hero)]);
  if (document.getElementById('stCardModal').classList.contains('open')) stRenderCardPreview();
}

function setStArtSource(src) {
  stCard.artSource = src;
  document.querySelectorAll('.st-art-src-btn').forEach(b => b.classList.toggle('active', b.dataset.src === src));
  stSaveCardSettings();
  stPrefetchArt();
}

// ── Shared pieces ─────────────────────────────────────────────

// Masthead: "Your Soundtrack" over the period, with the brand kicker above.
function _stHeader(ctx, opt) {
  const o = opt || {};
  const p = ctx.p;
  const s = v => _shS(ctx, v);
  const padX = o.padX != null ? o.padX : 72;
  const big = o.titleSize || (ctx.fmt === 'story' ? 84 : ctx.fmt === 'portrait' ? 74 : 62);
  return `<div style="flex-shrink:0;padding:${shSafeTop(ctx.fmt)}px ${padX}px ${o.padBottom || 30}px;">
    ${shEyebrow(p, 'dankcharts.fm', { size: s(21), color: o.light ? p.text : p.accent })}
    <div style="margin-top:${s(18)}px;font-family:${SH_FONT.display};font-size:${s(big)}px;font-weight:800;line-height:1.0;color:${p.text};">${esc(ctx.title)}</div>
    <div style="margin-top:${s(14)}px;display:flex;align-items:center;gap:14px;">
      <span style="width:${s(46)}px;height:3px;background:${p.accent};border-radius:2px;flex-shrink:0;"></span>
      <span style="font-family:${SH_FONT.mono};font-size:${s(24)}px;letter-spacing:0.14em;color:${p.dim};text-transform:uppercase;white-space:nowrap;">${esc(ctx.periodLabel)}</span>
    </div>
  </div>`;
}

// The headline numbers. `compact` drops the tile chrome down to a plain row.
function _stStats(ctx, opt) {
  const o = opt || {};
  const p = ctx.p;
  const s = v => _shS(ctx, v);
  if (!ctx.opts.showStats) return '';
  const cells = [
    { v: ctx.totalPlays.toLocaleString(), l: tUnit('plays', ctx.totalPlays) },
    { v: ctx.days.toLocaleString(), l: t('st_stat_days') },
    { v: ctx.artists.toLocaleString(), l: t('st_stat_artists') },
  ];
  if (ctx.newCount) cells.push({ v: ctx.newCount.toLocaleString(), l: t('st_stat_new_discoveries') });
  if (ctx.opts.showPeak && ctx.peakCount) cells.push({ v: ctx.peakLabel, l: t('st_stat_peak_day'), small: true });
  const size = o.size || 42;
  if (o.compact) {
    return `<div style="display:flex;column-gap:${s(30)}px;row-gap:${s(18)}px;flex-wrap:wrap;align-items:flex-end;">${cells.map(c => `<div>
      <div style="font-family:${SH_FONT.display};font-size:${s(size)}px;font-weight:700;color:${c.small ? p.text : p.accent};line-height:1;">${esc(c.v)}</div>
      <div style="margin-top:${s(7)}px;font-family:${SH_FONT.mono};font-size:${s(16)}px;letter-spacing:0.12em;color:${p.dim};text-transform:uppercase;white-space:nowrap;">${esc(c.l)}</div>
    </div>`).join('')}</div>`;
  }
  return `<div style="display:flex;gap:${s(12)}px;">${cells.map(c => `<div style="flex:1;min-width:0;background:${_shA(p.text, p.dark ? 0.05 : 0.04)};border:1px solid ${p.line};border-radius:16px;padding:${s(18)}px ${s(14)}px;text-align:center;">
    <div style="font-family:${SH_FONT.display};font-size:${s(c.small ? size * 0.72 : size)}px;font-weight:700;color:${c.small ? p.text : p.accent};line-height:1;">${esc(c.v)}</div>
    <div style="margin-top:${s(8)}px;font-family:${SH_FONT.mono};font-size:${s(15)}px;letter-spacing:0.1em;color:${p.dim};text-transform:uppercase;">${esc(c.l)}</div>
  </div>`).join('')}</div>`;
}

// Row height that fills the leftover vertical space.
//   usedH  — everything above and below the lists (masthead, stats, footer…)
//   lists  — how many stacked lists share that space
function _stRowH(ctx, usedH, lists, cap) {
  const s = v => _shS(ctx, v);
  const n = Math.max(1, lists);
  const headingH = s(43); // section label + its margin
  const avail = ctx.H - usedH - headingH * n;
  const raw = Math.floor(avail / Math.max(1, ctx.n * n));
  return Math.max(s(52), Math.min(cap || s(120), raw));
}

// One ranked list — artists (round artwork) or songs (square artwork).
function _stList(ctx, rows, heading, opt) {
  const o = opt || {};
  const p = ctx.p;
  const s = v => _shS(ctx, v);
  if (!rows.length) return '';
  const rowH = o.rowH || s(78);
  const art = Math.min(rowH - s(16), s(78));
  const nameSize = o.nameSize || s(28);
  return `<div style="min-width:0;">
    <div style="font-family:${SH_FONT.mono};font-size:${s(19)}px;letter-spacing:0.18em;color:${p.accent};text-transform:uppercase;margin-bottom:${s(12)}px;">${esc(heading)}</div>
    ${rows.map(r => `<div style="display:flex;align-items:center;gap:${s(16)}px;height:${rowH}px;border-top:1px solid ${p.line};">
      <span style="flex-shrink:0;width:${s(34)}px;font-family:${SH_FONT.display};font-size:${s(30)}px;font-weight:700;color:${r.rank === 1 ? p.accent : _shA(p.dim, 0.9)};">${r.rank}</span>
      ${ctx.opts.showArt ? shArt(p, r.art, art, { initials: initials(r.name || r.title), radius: o.round ? Math.round(art / 2) : Math.round(art * 0.18), shadow: false }) : ''}
      <div style="flex:1;min-width:0;">
        <div style="font-family:${SH_FONT.sans};font-size:${nameSize}px;font-weight:600;color:${p.text};white-space:nowrap;overflow:hidden;line-height:1.2;">${esc(r.name || r.title)}</div>
        ${r.artist ? `<div style="font-family:${SH_FONT.sans};font-size:${Math.round(nameSize * 0.68)}px;color:${p.dim};white-space:nowrap;overflow:hidden;line-height:1.25;">${esc(r.artist)}</div>` : ''}
      </div>
      <span style="flex-shrink:0;font-family:${SH_FONT.mono};font-size:${Math.round(nameSize * 0.78)}px;font-weight:700;color:${p.text};">${r.count.toLocaleString()}</span>
    </div>`).join('')}
  </div>`;
}

// ── Templates ─────────────────────────────────────────────────
const SH_ST_TEMPLATES = {

  // RECAP — the default. Masthead, stat tiles, then both lists.
  recap(ctx) {
    const p = ctx.p, opts = ctx.opts;
    const s = v => _shS(ctx, v);
    const padX = 64;
    const sideBySide = ctx.fmt === 'post' && opts.showArtists && opts.showSongs;
    const stacked = (opts.showArtists ? 1 : 0) + (opts.showSongs ? 1 : 0);
    const headH = shSafeTop(ctx.fmt) + s(ctx.fmt === 'story' ? 84 : ctx.fmt === 'portrait' ? 74 : 62) + s(56) + 30;
    const usedH = headH + (opts.showFooter ? 42 : 0) + shSafeBottom(ctx.fmt) + (opts.showStats ? s(120) : 0) + s(96);
    const rowH = _stRowH(ctx, usedH, sideBySide ? 1 : stacked, s(ctx.fmt === 'post' ? 84 : 116));
    const lists = `<div style="display:flex;gap:${s(30)}px;flex-direction:${sideBySide ? 'row' : 'column'};">
      ${opts.showArtists ? _stList(ctx, ctx.topArtists, ctx.artistsWord, { round: true, rowH, nameSize: s(sideBySide ? 24 : 28) }) : ''}
      ${opts.showSongs ? _stList(ctx, ctx.topSongs, ctx.songsWord, { rowH, nameSize: s(sideBySide ? 24 : 28) }) : ''}
    </div>`;
    return shShell(p, ctx.fmt, `${_stHeader(ctx, { padX })}
      <div style="flex:1;min-height:0;padding:0 ${padX}px;display:flex;flex-direction:column;justify-content:center;gap:${s(26)}px;overflow:hidden;">
        ${_stStats(ctx)}
        ${lists}
      </div>
      ${shFooter(p, ctx.fmt, { show: opts.showFooter, padX })}`);
  },

  // WRAPPED — the #1 artist gets a hero portrait, the rest rides underneath.
  wrapped(ctx) {
    const p = ctx.p, opts = ctx.opts;
    const s = v => _shS(ctx, v);
    const padX = 64;
    const hero = ctx.topArtists[0];
    const heroSz = ctx.fmt === 'story' ? 380 : ctx.fmt === 'portrait' ? 330 : 280;
    const headH = shSafeTop(ctx.fmt) + s(ctx.fmt === 'story' ? 62 : 52) + s(56) + 26;
    const usedH = headH + heroSz + s(28) + (opts.showFooter ? 42 : 0) + shSafeBottom(ctx.fmt) + (opts.showStats ? s(86) : 0) + s(88);
    const rowH = _stRowH(ctx, usedH, 1, s(ctx.fmt === 'post' ? 76 : 104));
    const heroBlock = hero ? `<div style="flex-shrink:0;padding:0 ${padX}px ${s(28)}px;display:flex;align-items:center;gap:${s(28)}px;">
      ${shArt(p, hero.art, heroSz, { initials: initials(hero.name), radius: Math.round(heroSz / 2) })}
      <div style="flex:1;min-width:0;">
        <div style="font-family:${SH_FONT.mono};font-size:${s(19)}px;letter-spacing:0.2em;color:${p.accent};text-transform:uppercase;">${esc(t('st_stat_top_artist'))}</div>
        <div style="margin-top:${s(12)}px;font-family:${SH_FONT.display};font-size:${s(46)}px;font-weight:800;color:${p.text};line-height:1.04;${shClamp(2, s(46), 1.04)}">${esc(hero.name)}</div>
        <div style="margin-top:${s(14)}px;">${shChip(p, `${hero.count.toLocaleString()} ${esc(tUnit('plays', hero.count))}`, { size: s(21), color: p.accent })}</div>
      </div>
    </div>` : '';
    return shShell(p, ctx.fmt, `${_stHeader(ctx, { padX, titleSize: ctx.fmt === 'story' ? 62 : 52, padBottom: s(26) })}
      ${heroBlock}
      <div style="flex:1;min-height:0;padding:0 ${padX}px;display:flex;flex-direction:column;justify-content:center;gap:${s(24)}px;overflow:hidden;">
        ${_stStats(ctx, { compact: true, size: 38 })}
        ${opts.showSongs ? _stList(ctx, ctx.topSongs, ctx.songsWord, { rowH, nameSize: s(26) }) : ''}
        ${!opts.showSongs && opts.showArtists ? _stList(ctx, ctx.topArtists.slice(1), ctx.artistsWord, { round: true, rowH, nameSize: s(26) }) : ''}
      </div>
      ${shFooter(p, ctx.fmt, { show: opts.showFooter, padX })}`);
  },

  // COLLAGE — artwork first: artists as a row of portraits, songs as a grid.
  collage(ctx) {
    const p = ctx.p, opts = ctx.opts;
    const s = v => _shS(ctx, v);
    const padX = 56;
    const gap = 16;
    const aCols = Math.min(ctx.topArtists.length, 5) || 1;
    const aSz = Math.floor((ctx.W - padX * 2 - gap * (aCols - 1)) / aCols);
    const sCols = Math.min(ctx.topSongs.length, 5) || 1;
    const sSz = Math.floor((ctx.W - padX * 2 - gap * (sCols - 1)) / sCols);

    const artistTiles = ctx.topArtists.slice(0, aCols).map(a => `<div style="width:${aSz}px;">
      ${shArt(p, a.art, aSz, { initials: initials(a.name), radius: Math.round(aSz / 2), shadow: false })}
      <div style="margin-top:${s(10)}px;text-align:center;font-family:${SH_FONT.sans};font-size:${s(19)}px;font-weight:600;color:${p.text};line-height:1.2;${shClamp(2, s(19), 1.2)}">${esc(a.name)}</div>
      <div style="text-align:center;font-family:${SH_FONT.mono};font-size:${s(16)}px;color:${p.dim};">${a.count.toLocaleString()}</div>
    </div>`).join('');

    const songTiles = ctx.topSongs.slice(0, sCols).map(so => `<div style="width:${sSz}px;">
      <div style="position:relative;width:${sSz}px;height:${sSz}px;border-radius:${Math.round(sSz * 0.09)}px;overflow:hidden;background:${p.panel};box-shadow:inset 0 0 0 1px ${p.line2};">
        ${so.art ? `<img src="${so.art}" width="${sSz}" height="${sSz}" style="width:${sSz}px;height:${sSz}px;object-fit:cover;display:block;">`
          : `<div style="width:${sSz}px;height:${sSz}px;display:flex;align-items:center;justify-content:center;font-family:${SH_FONT.display};font-size:${Math.round(sSz * 0.3)}px;color:${_shA(p.text, 0.3)};">${esc(initials(so.title))}</div>`}
        <div style="position:absolute;left:0;bottom:0;width:${sSz}px;height:${Math.round(sSz * 0.45)}px;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,0.78));"></div>
        <div style="position:absolute;left:${Math.round(sSz * 0.08)}px;bottom:${Math.round(sSz * 0.05)}px;font-family:${SH_FONT.display};font-size:${Math.round(sSz * 0.26)}px;font-weight:800;color:#fff;line-height:0.95;text-shadow:0 2px 12px rgba(0,0,0,0.6);">${so.rank}</div>
      </div>
      <div style="margin-top:${s(10)}px;font-family:${SH_FONT.sans};font-size:${s(19)}px;font-weight:600;color:${p.text};line-height:1.2;${shClamp(1, s(19), 1.2)}">${esc(so.title)}</div>
      <div style="font-family:${SH_FONT.sans};font-size:${s(16)}px;color:${p.dim};line-height:1.2;${shClamp(1, s(16), 1.2)}">${esc(so.artist)}</div>
    </div>`).join('');

    return shShell(p, ctx.fmt, `${_stHeader(ctx, { padX, titleSize: ctx.fmt === 'story' ? 66 : 54, padBottom: s(26) })}
      <div style="flex:1;min-height:0;padding:0 ${padX}px;display:flex;flex-direction:column;justify-content:center;gap:${s(30)}px;overflow:hidden;">
        ${opts.showArtists && artistTiles ? `<div>
          <div style="font-family:${SH_FONT.mono};font-size:${s(19)}px;letter-spacing:0.18em;color:${p.accent};text-transform:uppercase;margin-bottom:${s(14)}px;">${esc(ctx.artistsWord)}</div>
          <div style="display:flex;gap:${gap}px;">${artistTiles}</div>
        </div>` : ''}
        ${_stStats(ctx, { compact: true, size: 40 })}
        ${opts.showSongs && songTiles ? `<div>
          <div style="font-family:${SH_FONT.mono};font-size:${s(19)}px;letter-spacing:0.18em;color:${p.accent};text-transform:uppercase;margin-bottom:${s(14)}px;">${esc(ctx.songsWord)}</div>
          <div style="display:flex;gap:${gap}px;">${songTiles}</div>
        </div>` : ''}
      </div>
      ${shFooter(p, ctx.fmt, { show: opts.showFooter, padX })}`);
  },

  // MINIMAL — no artwork. The numbers carry the card.
  minimal(ctx) {
    const p = ctx.p, opts = ctx.opts;
    const s = v => _shS(ctx, v);
    const padX = 88;
    const noArt = Object.assign({}, ctx, { opts: Object.assign({}, opts, { showArt: false }) });
    const stacked = (opts.showArtists ? 1 : 0) + (opts.showSongs ? 1 : 0);
    const headH = shSafeTop(ctx.fmt) + s(ctx.fmt === 'story' ? 76 : 60) + s(56) + 30;
    const usedH = headH + (opts.showFooter ? 42 : 0) + shSafeBottom(ctx.fmt) + (opts.showStats ? s(140) : 0) + s(96);
    const rowH = _stRowH(ctx, usedH, stacked, s(ctx.fmt === 'post' ? 80 : 110));
    return shShell(p, ctx.fmt, `${_stHeader(ctx, { padX, titleSize: ctx.fmt === 'story' ? 76 : 60 })}
      <div style="flex:1;min-height:0;padding:0 ${padX}px;display:flex;flex-direction:column;justify-content:center;gap:${s(30)}px;overflow:hidden;">
        ${_stStats(noArt, { compact: true, size: ctx.fmt === 'story' ? 42 : 36 })}
        ${opts.showArtists ? _stList(noArt, ctx.topArtists, ctx.artistsWord, { rowH, nameSize: s(30) }) : ''}
        ${opts.showSongs ? _stList(noArt, ctx.topSongs, ctx.songsWord, { rowH, nameSize: s(30) }) : ''}
      </div>
      ${shFooter(p, ctx.fmt, { show: opts.showFooter, padX })}`, { noBgImage: true });
  },

  // POSTER — the leading artwork blurred behind the whole card.
  poster(ctx) {
    const p = ctx.p, opts = ctx.opts;
    const s = v => _shS(ctx, v);
    const padX = 68;
    const blur = shBlurred(ctx.heroArt);
    const scrim = p.dark
      ? 'linear-gradient(180deg, rgba(4,5,8,0.42) 0%, rgba(4,5,8,0.76) 36%, rgba(4,5,8,0.95) 100%)'
      : 'linear-gradient(180deg, rgba(250,248,244,0.52) 0%, rgba(250,248,244,0.88) 40%, rgba(250,248,244,0.97) 100%)';
    const backdrop = `<div style="position:absolute;left:0;top:0;width:${ctx.W}px;height:${ctx.H}px;overflow:hidden;">
      ${blur ? `<img src="${blur}" width="${ctx.W}" height="${ctx.H}" style="width:${ctx.W}px;height:${ctx.H}px;object-fit:cover;display:block;">` : `<div style="width:${ctx.W}px;height:${ctx.H}px;background:${p.bg2};"></div>`}
      <div style="position:absolute;left:0;top:0;width:${ctx.W}px;height:${ctx.H}px;background:${scrim};"></div>
    </div>`;
    const stacked = (opts.showArtists ? 1 : 0) + (opts.showSongs ? 1 : 0);
    const headH = shSafeTop(ctx.fmt) + s(ctx.fmt === 'story' ? 76 : 62) + s(50) + 26;
    const usedH = headH + (opts.showFooter ? 42 : 0) + shSafeBottom(ctx.fmt) + (opts.showStats ? s(136) : 0) + s(92);
    const rowH = _stRowH(ctx, usedH, stacked, s(ctx.fmt === 'post' ? 80 : 110));
    const noArt = Object.assign({}, ctx, { opts: Object.assign({}, opts, { showArt: false }) });
    const content = `<div style="position:relative;width:${ctx.W}px;height:${ctx.H}px;display:flex;flex-direction:column;box-sizing:border-box;">
      <div style="flex-shrink:0;padding:${shSafeTop(ctx.fmt)}px ${padX}px ${s(26)}px;${p.dark ? 'text-shadow:0 2px 16px rgba(0,0,0,0.65);' : ''}">
        ${shEyebrow(p, 'dankcharts.fm', { size: s(21), color: p.text })}
        <div style="margin-top:${s(18)}px;font-family:${SH_FONT.display};font-size:${s(ctx.fmt === 'story' ? 76 : 62)}px;font-weight:800;line-height:1.0;color:${p.text};">${esc(ctx.title)}</div>
        <div style="margin-top:${s(12)}px;font-family:${SH_FONT.mono};font-size:${s(23)}px;letter-spacing:0.14em;color:${_shA(p.text, 0.76)};text-transform:uppercase;">${esc(ctx.periodLabel)}</div>
      </div>
      <div style="flex:1;min-height:0;padding:0 ${padX}px;display:flex;flex-direction:column;justify-content:center;gap:${s(28)}px;overflow:hidden;">
        ${_stStats(noArt, { compact: true, size: ctx.fmt === 'story' ? 44 : 38 })}
        ${opts.showArtists ? _stList(noArt, ctx.topArtists, ctx.artistsWord, { rowH, nameSize: s(28) }) : ''}
        ${opts.showSongs ? _stList(noArt, ctx.topSongs, ctx.songsWord, { rowH, nameSize: s(28) }) : ''}
      </div>
      ${shFooter(p, ctx.fmt, { show: opts.showFooter, padX, light: true })}
    </div>`;
    return shShell(p, ctx.fmt, backdrop + content, { noBgImage: true });
  },
};

const SH_ST_TEMPLATE_LIST = [
  { id: 'recap', name: 'Recap', glyph: '▤' },
  { id: 'wrapped', name: 'Wrapped', glyph: '◉' },
  { id: 'collage', name: 'Collage', glyph: '▦' },
  { id: 'minimal', name: 'Minimal', glyph: '≡' },
  { id: 'poster', name: 'Poster', glyph: '◧' },
];

function stBuildCardHTML(opts) {
  const ctx = stCardContext(opts);
  if (!ctx) return '';
  const tpl = SH_ST_TEMPLATES[opts.template] || SH_ST_TEMPLATES.recap;
  return tpl(ctx);
}

// ── Modal ─────────────────────────────────────────────────────
function stOpenCard() {
  if (!(_stCurrentPlays || []).length) return;
  stLoadCardSettings();
  shRenderDesignPickers('st');
  ['showStats', 'showArtists', 'showSongs', 'showPeak', 'showArt', 'showFooter'].forEach(k => {
    const el = document.getElementById('stOpt_' + k);
    if (el) el.checked = stCard[k];
  });
  document.querySelectorAll('.st-art-src-btn').forEach(b => b.classList.toggle('active', b.dataset.src === stCard.artSource));
  const topNEl = document.getElementById('stTopN');
  if (topNEl) topNEl.value = stCard.topN || 5;
  const tsEl = document.getElementById('stTextScale');
  if (tsEl) tsEl.value = stCard.textScale || 100;
  document.getElementById('stCardModal').classList.add('open');
  stPrefetchArt();
  stUpdateCardPreview();
}

function stCloseCard() {
  document.getElementById('stCardModal').classList.remove('open');
  document.getElementById('stCardCanvas').innerHTML = '';
}

function setStFormat(fmt) { stCard.format = fmt; shRenderDesignPickers('st'); stSaveCardSettings(); stUpdateCardPreview(); }
function setStTemplate(id) { stCard.template = id; shRenderDesignPickers('st'); stSaveCardSettings(); stUpdateCardPreview(); }
function setStPalette(id) { stCard.palette = id; shRenderDesignPickers('st'); stSaveCardSettings(); stUpdateCardPreview(); }
function setStQuality(q) { stCard.quality = q; shRenderDesignPickers('st'); stSaveCardSettings(); stSyncCardLabels(); }

function stSyncCardLabels() {
  const n = document.getElementById('stTopNLabel');
  if (n) n.textContent = stCard.topN;
  const ts = document.getElementById('stTextScaleLabel');
  if (ts) ts.textContent = (stCard.textScale || 100) + '%';
  const q = document.getElementById('stQualityNote');
  if (q) {
    const d = shDims(stCard.format);
    const m = Math.max(1, Math.min(2, stCard.quality || 2));
    q.textContent = `${d.w * m} × ${d.h * m} px`;
  }
}

function stUpdateCardPreview() {
  ['showStats', 'showArtists', 'showSongs', 'showPeak', 'showArt', 'showFooter'].forEach(k => {
    const el = document.getElementById('stOpt_' + k);
    if (el) stCard[k] = el.checked;
  });
  const topNEl = document.getElementById('stTopN');
  if (topNEl) stCard.topN = parseInt(topNEl.value) || 5;
  const tsEl = document.getElementById('stTextScale');
  if (tsEl) stCard.textScale = parseInt(tsEl.value) || 100;
  stSyncCardLabels();
  stSaveCardSettings();
  if (stCard.showArt || stCard.palette === 'cover' || stCard.template === 'poster') stPrefetchArt();
  stRenderCardPreview();
}

function stRenderCardPreview() {
  const html = stBuildCardHTML(stCard);
  if (!html) return;
  shFitPreview('stCardFrame', 'stCardInner', stCard.format, html);
  const canvas = document.getElementById('stCardCanvas');
  const d = shDims(stCard.format);
  canvas.innerHTML = html;
  canvas.style.width = d.w + 'px';
  canvas.style.height = d.h + 'px';
  shPrepareShare('stCardCanvas', 'stCardShareBtn', _stShareOpts);
}

function _stShareOpts() {
  return { format: stCard.format, quality: stCard.quality, fileName: _stFileName() };
}

function _stFileName() {
  const slug = stGetPeriodLabel().replace(/\s+/g, '-').toLowerCase();
  return `dankcharts_soundtrack_${slug}_${stCard.template}_${stCard.format}.png`;
}

async function stDownloadCard() {
  const btn = document.getElementById('stCardDownloadBtn');
  const orig = btn.textContent;
  btn.textContent = '⏳ …'; btn.disabled = true;
  try {
    const cvs = await shCapture('stCardCanvas', stCard.format, stCard.quality);
    const link = document.createElement('a');
    link.download = _stFileName();
    link.href = cvs.toDataURL('image/png');
    link.click();
  } catch (e) { console.error('Card download failed', e); }
  btn.textContent = orig; btn.disabled = false;
}

async function stCopyCard() {
  if (!navigator.clipboard?.write) { stDownloadCard(); return; }
  const btn = document.getElementById('stCardCopyBtn');
  const orig = btn.textContent;
  btn.textContent = '…'; btn.disabled = true;
  try {
    const cvs = await shCapture('stCardCanvas', stCard.format, stCard.quality);
    const blob = await shCanvasBlob(cvs);
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
    btn.textContent = '✓ ' + t('sh_copied');
    setTimeout(() => { btn.textContent = orig; btn.disabled = false; }, 1800);
  } catch (e) {
    btn.textContent = orig; btn.disabled = false;
    stDownloadCard();
  }
}

function stShareCard() {
  shShareNow('stCardCanvas', 'stCardShareBtn', _stShareOpts, stDownloadCard);
}

document.getElementById('stCardModal').addEventListener('click', e => {
  if (e.target === document.getElementById('stCardModal')) stCloseCard();
});

// ─── CURRENT STREAK BANNER ──────────────────────────────────
function computeCurrentStreak(plays) {
  if (!plays || plays.length < 3) return null;
  const p0 = plays[0];
  const sk0 = songKey(p0);

  // 1. Song Streak — same song 3+ consecutive (highest precedence)
  let songCount = 0;
  for (const p of plays) {
    if (songKey(p) === sk0) songCount++;
    else break;
  }
  if (songCount >= 3) return { type: 'song', count: songCount, title: p0.title, artist: p0.artist, album: p0.album };

  // 2. Album Streak — same album+artist 3+ consecutive
  if (p0.album && p0.album !== '—') {
    const primaryArtist0 = albumArtist(p0);
    const aa0 = p0.album.toLowerCase().trim() + '\x00' + primaryArtist0.toLowerCase().trim();
    let albumCount = 0;
    for (const p of plays) {
      if (p.album && p.album !== '—' &&
          p.album.toLowerCase().trim() + '\x00' + albumArtist(p).toLowerCase().trim() === aa0)
        albumCount++;
      else break;
    }
    if (albumCount >= 3) {
      const result = { type: 'album', count: albumCount, album: p0.album, artist: primaryArtist0 };
      // If the same artist's run extends past this album's boundary (e.g. a
      // full-discography binge), attach it so the banner can show both streaks.
      const a0lc = primaryArtist0.toLowerCase().trim();
      let artistCount = 0;
      for (const p of plays) {
        const pArtists = (p.artists || splitArtists(p.artist)).map(a => a.toLowerCase().trim());
        if (pArtists.includes(a0lc)) artistCount++;
        else break;
      }
      if (artistCount > albumCount) result.artistStreak = { count: artistCount, artist: primaryArtist0 };
      return result;
    }
  }

  // 3. Artist Streak — same artist (respecting comma-split rule) 3+ consecutive plays
  const artists0 = splitArtists(p0.artist);
  let bestStreakArtist = null, bestStreakCount = 0;
  for (const a0 of artists0) {
    const a0lc = a0.toLowerCase().trim();
    let cnt = 0;
    for (const p of plays) {
      const pArtists = (p.artists || splitArtists(p.artist)).map(a => a.toLowerCase().trim());
      if (pArtists.includes(a0lc)) cnt++;
      else break;
    }
    if (cnt > bestStreakCount) { bestStreakCount = cnt; bestStreakArtist = a0; }
  }
  if (bestStreakCount >= 3) return { type: 'artist', count: bestStreakCount, artist: bestStreakArtist };

  // 4. Shuffle Streak — 5+ plays with no artist appearing 3+ times in a row
  let shuffleCount = 1;
  let runArtist = plays[0].artist.toLowerCase().trim();
  let runLen = 1;
  for (let i = 1; i < plays.length; i++) {
    const a = plays[i].artist.toLowerCase().trim();
    if (a === runArtist) {
      runLen++;
      if (runLen > 2) break;
    } else {
      runArtist = a;
      runLen = 1;
    }
    shuffleCount++;
  }
  if (shuffleCount >= 5) return { type: 'shuffle', count: shuffleCount };

  return null;
}

function renderStreakBanner() {
  const el = document.getElementById('streakBanner');
  if (!el) return;
  const hide = () => { el.style.display = 'none'; el.innerHTML = ''; _nsStreak = null; dcSyncNowStrip(); };
  if (!allPlays.length) { hide(); return; }

  const streak = computeCurrentStreak(allPlays);
  if (!streak) { hide(); return; }

  // When an album streak is nested inside a longer same-artist run (e.g. a
  // discography binge), the artist run is the real streak — it leads with the
  // count, and the album becomes an inset "currently on" chip.
  const nested = streak.type === 'album' && streak.artistStreak;
  const displayType  = nested ? 'artist' : streak.type;
  const displayCount = nested ? streak.artistStreak.count : streak.count;
  _nsStreak = { type: displayType, count: displayCount };

  let subject = '';
  if (streak.type === 'song')        subject = `<em>${esc(streak.title)}</em> · ${esc(streak.artist)}`;
  else if (nested)                   subject = esc(streak.artistStreak.artist);
  else if (streak.type === 'album')  subject = `<em>${esc(streak.album)}</em> · ${esc(streak.artist)}`;
  else if (streak.type === 'artist') subject = esc(streak.artist);
  const typeLabel = esc(t('ns_type_' + displayType));
  const inARow    = esc(t('ns_in_a_row'));
  const nestedChip = nested
    ? `<span class="ns-nested">↳ 💿 <em>${esc(streak.album)}</em> · ${esc(t('ns_nested', { n: streak.count }))}</span>`
    : '';

  let artFallback = '';
  if (streak.type === 'artist') artFallback = initials(streak.artist);
  else if (streak.type === 'album') artFallback = initials(streak.album);
  else if (streak.type === 'song') artFallback = initials(streak.album && streak.album !== '—' ? streak.album : streak.title);
  else artFallback = initials(allPlays[0].artist);

  // The ribbon: one cover per play of the streak, oldest on the left so it runs
  // into the song on air (or the last play). Capped: past ~30 the oldest are
  // under the left-edge fade anyway, and each one is an artwork lookup.
  const NS_RIBBON_MAX = 30;
  const shown = Math.min(displayCount, NS_RIBBON_MAX);
  const thumbs = [];
  for (let i = shown - 1; i >= 0; i--) {
    const p = allPlays[i];
    thumbs.push(`<div class="ns-thumb" data-play="${i}" title="${esc(p.title)} · ${esc(p.artist)}"><span>${esc(artFallback)}</span></div>`);
  }

  // Shown instead of the live song while nothing is playing: the last play
  const p0 = allPlays[0];
  const p0Album = p0.album && p0.album !== '—';
  const ago = _nsAgo(p0.date);

  el.className = `ns-streak ns-type-${displayType}`;
  el.innerHTML = `
    <div class="ns-smeta">
      <div class="ns-count"><span class="ns-fire" aria-hidden="true">🔥</span><span class="ns-num">${displayCount}</span><span class="ns-unit">${inARow}</span></div>
      <div class="ns-typeline"><span class="ns-type">${typeLabel}</span>${subject ? `<span class="ns-subject">${subject}</span>` : ''}</div>
      ${nestedChip}
    </div>
    <div class="ns-mmeta">
      <span class="ns-fire" aria-hidden="true">🔥</span>
      <div class="ns-mmeta-text">
        <div class="ns-type">${typeLabel} · ${displayCount} ${inARow}</div>
        ${subject || nested ? `<div class="ns-msub">${subject}${nested ? ` · ↳ <em>${esc(streak.album)}</em>` : ''}</div>` : ''}
      </div>
    </div>
    <div class="ns-ribbon" title="${esc(t('ns_last_n_plays', { n: displayCount }))}">
      <div class="ns-thumbs">${thumbs.join('')}</div>
      <span class="ns-arrow" aria-hidden="true">→</span>
    </div>
    <div class="ns-last">
      <div class="ns-art ns-art-streak${displayType === 'artist' ? ' is-round' : ''}">
        <img id="streakArtImg" class="ns-art-img" src="" alt="" style="display:none;"
             onerror="this.style.display='none';document.getElementById('streakArtInit').style.display='flex'">
        <div id="streakArtInit" class="ns-art-init">${esc(artFallback)}</div>
      </div>
      <div class="ns-info">
        ${ago ? `<span class="ns-ago">${esc(t('ns_last_played', { when: ago }))}</span>` : ''}
        <div class="ns-title">${esc(p0.title)}</div>
        <div class="ns-artist">${esc(p0.artist)}${p0Album ? ` · <em>${esc(p0.album)}</em>` : ''}</div>
      </div>
    </div>
  `;
  el.style.display = '';
  dcSyncNowStrip();
  // Phones scroll the ribbon sideways; start at the newest end
  const rib = el.querySelector('.ns-thumbs');
  if (rib) requestAnimationFrame(() => { rib.scrollLeft = rib.scrollWidth; });

  _fetchStreakArt(streak).then(url => {
    const img = document.getElementById('streakArtImg');
    const init = document.getElementById('streakArtInit');
    if (img && init && url) {
      img.src = url;
      img.style.display = '';
      init.style.display = 'none';
      _nsStreakArt = url;
      dcSyncNowStrip();
    }
    // Per-play art for each ribbon cover, queued through the shared queueImg()
    // instead of firing every lookup at once.
    el.querySelectorAll('.ns-thumb').forEach(thumb => {
      const p = allPlays[+thumb.dataset.play];
      if (!p) return;
      queueImg(() => _fetchPlayArt(p).then(thumbUrl => {
        const src = thumbUrl || url;
        if (!src) return;
        const tImg = document.createElement('img');
        tImg.src = sizedArtUrl(src, 38); // the 30–38px ribbon tiles
        tImg.alt = '';
        tImg.onerror = () => tImg.remove();
        thumb.innerHTML = '';
        thumb.appendChild(tImg);
      }));
    });
  });
}

// "2 hours ago" in the interface language, for the last-play line
function _nsAgo(date) {
  if (!(date instanceof Date) || isNaN(date)) return '';
  // never "in 3 minutes": a clock a little ahead of this one reads as now
  const secs = Math.min(0, (date.getTime() - Date.now()) / 1000);
  const steps = [['year', 31536000], ['month', 2592000], ['week', 604800], ['day', 86400], ['hour', 3600], ['minute', 60]];
  try {
    const rtf = new Intl.RelativeTimeFormat(typeof currentLang !== 'undefined' ? currentLang : 'en', { numeric: 'auto' });
    for (const [unit, n] of steps) if (Math.abs(secs) >= n) return rtf.format(Math.round(secs / n), unit);
    return rtf.format(0, 'minute');
  } catch (e) { return ''; }
}

// ── NOW STRIP (phase 5 step 5) ──
// The card around #streakBanner and #nowPlayingBar. Shown when either has
// something; .is-live and .has-streak let the CSS lay out the four cases
// (live + streak, live only, streak only, neither = hidden). On phones it also
// builds the one-line summary that the card folds into.
// var, not let: hideNowPlaying() can run (and call dcSyncNowStrip) before
// this part of the file has been evaluated, which would hit let's dead zone.
var _nsStreak = null;     // { type, count } of the streak on screen
var _nsLiveArt = '';      // cover of the song on air, once loaded
var _nsStreakArt = '';    // cover of the streak subject, once loaded
var _nsDay = null;        // { count, pb, tier } of the day streak (#nsDayStreak)

function dcSyncNowStrip() {
  const strip = document.getElementById('nowStrip');
  if (!strip) return;
  const now = document.getElementById('nowPlayingBar');
  const stk = document.getElementById('streakBanner');
  const live = !!(now && now.style.display !== 'none' && npTrack);
  const hasStreak = !!(stk && stk.style.display !== 'none' && _nsStreak);
  const day = document.getElementById('nsDayStreak');
  const hasDay = !!(day && day.style.display !== 'none' && _nsDay);
  strip.hidden = !(live || hasStreak || hasDay);
  strip.classList.toggle('is-live', live);
  strip.classList.toggle('has-streak', hasStreak);
  strip.classList.toggle('has-day', hasDay);
  if (!live) _nsLiveArt = '';
  strip.className = strip.className.replace(/\bns-type-\w+/g, '').trim() + (hasStreak ? ' ns-type-' + _nsStreak.type : '');

  // Phone summary, two lines:  [cover] [eq] Song — Artist              ▾
  //                                    🔥 3 in a row · 201-day listening streak
  const sum = document.getElementById('nsSummary');
  if (!sum || strip.hidden) return;
  const p0 = allPlays && allPlays[0];
  const title  = live ? npTrack.title  : (p0 ? p0.title : '');
  const artist = live ? npTrack.artist : (p0 ? p0.artist : '');
  const art = live ? _nsLiveArt : _nsStreakArt;
  // Second line, only when there is a streak to show. Each streak says what it
  // is ("3 in a row", "201-day listening streak") so the two are not two
  // look-alike flame pills squeezing the song title.
  const subParts = [];
  if (hasStreak) subParts.push(`<span class="ns-sum-run">🔥 <b>${_nsStreak.count}</b> ${esc(t('ns_in_a_row'))}</span>`);
  if (hasDay) subParts.push(`<span class="ns-sum-day ns-tier-${_nsDay.tier}">${nsFlameSvg()}<span>${esc(t('ns_day_short', { n: _nsDay.count.toLocaleString() }))}</span></span>`);
  sum.innerHTML = `
    <span class="ns-sum-art${!live && _nsStreak && _nsStreak.type === 'artist' ? ' is-round' : ''}">${art ? `<img src="${esc(sizedArtUrl(art, 64))}" alt="">` : ''}</span>
    <span class="ns-sum-main">
      <span class="ns-sum-line">
        ${live ? `<span class="ns-eq" aria-hidden="true"><i></i><i></i><i></i><i></i></span>` : ''}
        <span class="ns-sum-text"><b>${esc(title)}</b> <span>— ${esc(artist)}</span></span>
      </span>
      ${subParts.length ? `<span class="ns-sum-sub">${subParts.join('<span class="ns-sum-dot" aria-hidden="true">·</span>')}</span>` : ''}
    </span>
    <span class="ns-sum-chev" aria-hidden="true">▾</span>`;
  sum.setAttribute('aria-label', (live ? t('np_onair') + ': ' : '') + title + ' — ' + artist);
}

(function initNowStrip() {
  const strip = document.getElementById('nowStrip');
  if (!strip) return;
  const KEY = 'dc_nowstrip_open';
  const setOpen = open => {
    strip.classList.toggle('is-open', open);
    document.getElementById('nsSummary')?.setAttribute('aria-expanded', open ? 'true' : 'false');
    try { localStorage.setItem(KEY, open ? '1' : '0'); } catch (e) {}
  };
  let saved = false;
  try { saved = localStorage.getItem(KEY) === '1'; } catch (e) {}
  strip.classList.toggle('is-open', saved);
  document.getElementById('nsSummary')?.addEventListener('click', () => setOpen(true));
  document.getElementById('nsLess')?.addEventListener('click', () => setOpen(false));
})();

async function _fetchPlayArt(p) {
  try {
    const primaryArtist = albumArtist(p);
    if (p.album && p.album !== '—') return await getArtAuto('album', p.album, primaryArtist, p.album);
    return await getArtAuto('song', p.title, primaryArtist);
  } catch (e) { return null; }
}

async function _fetchStreakArt(streak) {
  try {
    if (streak.type === 'song') {
      return (streak.album && streak.album !== '—')
        ? await getArtAuto('album', streak.album, streak.artist, streak.album)
        : await getArtAuto('song', streak.title, streak.artist);
    }
    if (streak.type === 'album')  return await getArtAuto('album', streak.album, streak.artist, streak.album);
    if (streak.type === 'artist') return await getArtAuto('artist', streak.artist);
    // Shuffle: most recent play's album art
    const p = allPlays[0];
    return (p.album && p.album !== '—')
      ? await getArtAuto('album', p.album, p.artist, p.album)
      : await getArtAuto('artist', p.artist);
  } catch (e) { return null; }
}

// Proactively wake the Render backend on page load so it's ready before the first play button click
_ytPrewarmBackend();

// ─── CHARTS GUIDE VIEW ─────────────────────────────────────────
/* ═══════════════════════════════════════════════════════════════════
   FIRST-RUN WELCOME GATE
   The Charts Guide only works as an onboarding surface if people
   actually reach it, and nothing on a freshly loaded Weekly chart
   suggests it exists. So the first visit is gated: a blocking overlay
   that offers the tour or the guide, and records that it was shown.

   dc_guide_seen stores the guide version the user was last introduced
   to, not a boolean — bumping CG_GUIDE_VERSION re-introduces everyone
   once after a substantial rewrite, then never again.
   ═══════════════════════════════════════════════════════════════════ */
const CG_GUIDE_VERSION = 2;

function dcGuideSeenVersion() {
  try { return parseInt(localStorage.getItem('dc_guide_seen') || '0', 10) || 0; } catch (e) { return 0; }
}

function dcMaybeShowWelcomeGate() {
  if (dcGuideSeenVersion() >= CG_GUIDE_VERSION) return;
  const gate = document.getElementById('cgWelcomeGate');
  if (!gate) return;

  _dcGateOpen(gate);
}

/* The live demo ("Play the live demo" on the landing screen) is just the
   sample Google Sheet loaded as a normal source — recognise it by its id. */
const _DC_DEMO_SHEET_ID = '1ulWuTKxreKLUWGBEI0g2d5iMgjHu6y02IFzg6A7BzVA';
function dcIsLiveDemo() {
  try {
    return getDataSource() === 'sheets' && (localStorage.getItem('dc_sheet_id') || '').includes(_DC_DEMO_SHEET_ID);
  } catch (e) { return false; }
}

/* Shared by the first-run path and the replay button: fill in the parts that
   depend on who's looking, then show the gate and start the example chart. */
function _dcGateOpen(gate) {
  const demo       = dcIsLiveDemo();
  const configured = !needsOnboarding();
  const srcLabel   = { lastfm: 'Last.fm', sheets: 'Google Sheets', file: 'CSV upload' }[getDataSource()] || 'Your source';
  gate.classList.toggle('is-demo', demo);

  // Status pill — someone who just picked a source shouldn't be told to pick one
  const srcEl  = document.getElementById('cgGateSrc');
  const noteEl = document.getElementById('cgGateSrcNote');
  if (srcEl)  srcEl.classList.toggle('on', configured);
  if (noteEl) noteEl.textContent = demo ? 'Live demo'
    : configured ? srcLabel + ' connected · loading your plays'
    : 'Connect a source to begin';

  // Demo visitors are looking at someone else's listening, so the copy says so
  // and the second button becomes the way to swap in their own history.
  const hook  = gate.querySelector('.cg-gate-hook');
  const sub   = gate.querySelector('.cg-gate-sub');
  const btn2  = gate.querySelector('.cg-gate-actions .cg-gate-btn:not(.cg-gate-btn-primary)');
  const skip  = gate.querySelector('.cg-gate-skip');
  if (demo) {
    if (hook) hook.innerHTML = 'You\'re in the live demo. <span class="cg-gate-hook-em">Every chart here is real.</span>';
    if (sub)  sub.textContent = 'This is one real listener\'s history, charted week by week since day one. Click around freely — nothing you do here is saved. When you\'re ready, swap in your own Last.fm, Google Sheet or CSV.';
    if (btn2) { btn2.innerHTML = '🎧&nbsp; Use my own listening'; btn2.setAttribute('onclick', "dcGateChoose('own')"); }
    if (skip) skip.textContent = 'Just let me explore the demo →';
  } else {
    if (hook) hook.innerHTML = 'Your listening, <span class="cg-gate-hook-em">charted like a real countdown.</span>';
    if (sub)  sub.textContent = 'Every play becomes a weekly, monthly, yearly and all-time chart — with climbers, debuts, peaks, records and awards.';
    if (btn2) { btn2.innerHTML = '📖&nbsp; Read the Charts Guide'; btn2.setAttribute('onclick', "dcGateChoose('guide')"); }
    if (skip) skip.textContent = 'Just take me to my charts →';
  }

  dcGateFillTiles(gate);
  gate.style.display = 'flex';
  document.body.classList.add('cg-gate-open');
  dcGateDemoStart();
  // preventScroll: on a phone the box is taller than the screen, and focusing
  // the button would otherwise open the gate scrolled past its own heading
  setTimeout(() => gate.querySelector('.cg-gate-btn-primary')?.focus({ preventScroll: true }), 80);
}

/* Shortcut tiles borrow their icons from the nav buttons they lead to, so the
   welcome window teaches the same pictures the nav bar uses. Wired once. */
function dcGateFillTiles(gate) {
  gate.querySelectorAll('.cg-gate-tile').forEach(tile => {
    const period = tile.dataset.go;
    const ic = tile.querySelector('.cg-gate-tile-ic');
    const navIc = document.querySelector('#periodNav button[data-period="' + period + '"] .nav-icon');
    // Ids inside the icon (gradients, masks) get a suffix: the nav's copies can
    // sit in a collapsed nav, and url(#id) pointing into a hidden SVG paints nothing.
    if (ic && navIc && !ic.childElementCount) {
      ic.innerHTML = navIc.innerHTML
        .replace(/id="([^"]+)"/g, 'id="$1-gate"')
        .replace(/url\(#([^)]+)\)/g, 'url(#$1-gate)');
    }
    if (!tile._wired) {
      tile._wired = true;
      tile.addEventListener('click', () => dcGateChoose('go:' + period));
    }
  });
}

/* ── Example chart ──
   Five rows out of six made-up songs, cycling through four "weeks". Each tick
   moves rows to their new slot with a transform, so the climb/fall is visible,
   and works out the movement tag (▲ ▼ = NEW RE) from the previous week. */
const _CG_DEMO_SONGS = [
  { t: 'Glass Summer',    a: 'Neon Harbor' },
  { t: 'Overpass',        a: 'The Lowlights' },
  { t: 'Paper Satellites', a: 'Mira Vale' },
  { t: 'Night Bus Home',  a: 'Coastline Kids' },
  { t: 'Velvet Static',   a: 'June Arcade' },
  { t: 'Holding Pattern', a: 'Sable & Fox' },
];
// Each week lists song indexes from #1 down; the song left out is off the chart
const _CG_DEMO_WEEKS = [
  [0, 1, 2, 3, 4],
  [2, 0, 5, 1, 3],
  [2, 5, 0, 4, 1],
  [5, 2, 3, 0, 4],
];
let _cgDemoWeek = 0;
let _cgDemoTimer = null;
let _cgDemoEverOn = new Set(); // songs seen on an earlier week, for RE tags

function dcGateDemoStart() {
  const wrap = document.getElementById('cgGateDemoRows');
  if (!wrap) return;
  clearInterval(_cgDemoTimer);
  _cgDemoWeek = 0;
  _cgDemoEverOn = new Set();
  wrap.innerHTML = _CG_DEMO_SONGS.map((s, i) =>
    '<div class="cg-gate-demo-row" data-i="' + i + '">' +
      '<span class="cg-gate-demo-pos"></span>' +
      '<span class="cg-gate-demo-art" style="--h:' + (i * 57 + 200) % 360 + '"></span>' +
      '<span class="cg-gate-demo-txt"><strong>' + s.t + '</strong><em>' + s.a + '</em></span>' +
      '<span class="cg-gate-demo-mv"></span>' +
    '</div>').join('');
  _dcGateDemoRender(null);
  // Reduced motion: show week 1 and leave it there
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  _cgDemoTimer = setInterval(() => {
    const prev = _CG_DEMO_WEEKS[_cgDemoWeek];
    _cgDemoWeek = (_cgDemoWeek + 1) % _CG_DEMO_WEEKS.length;
    if (_cgDemoWeek === 0) _cgDemoEverOn = new Set(); // loop restarts the story
    _dcGateDemoRender(_cgDemoWeek === 0 ? null : prev);
  }, 2600);
}

function _dcGateDemoStop() {
  clearInterval(_cgDemoTimer);
  _cgDemoTimer = null;
}

function _dcGateDemoRender(prev) {
  const wrap = document.getElementById('cgGateDemoRows');
  if (!wrap) return;
  const week = _CG_DEMO_WEEKS[_cgDemoWeek];
  const weekEl = document.getElementById('cgGateDemoWeek');
  if (weekEl) weekEl.textContent = 'Week ' + (_cgDemoWeek + 1);

  wrap.querySelectorAll('.cg-gate-demo-row').forEach(row => {
    const i = +row.dataset.i;
    const rank = week.indexOf(i);
    const mv = row.querySelector('.cg-gate-demo-mv');
    if (rank < 0) { row.classList.add('off'); row.style.setProperty('--slot', 5); return; }
    row.classList.remove('off');
    row.style.setProperty('--slot', rank);
    row.querySelector('.cg-gate-demo-pos').textContent = rank + 1;
    row.classList.toggle('top', rank === 0);

    // Movement against last week — on the very first week everything is a debut
    let tag = 'new', txt = 'NEW';
    const was = prev ? prev.indexOf(i) : -1;
    if (was >= 0) {
      const d = was - rank;
      tag = d > 0 ? 'up' : d < 0 ? 'down' : 'same';
      txt = d > 0 ? '▲' + d : d < 0 ? '▼' + (-d) : '=';
    } else if (_cgDemoEverOn.has(i)) { tag = 're'; txt = 'RE'; }
    mv.className = 'cg-gate-demo-mv mv-' + tag;
    mv.textContent = txt;
  });
  week.forEach(i => _cgDemoEverOn.add(i));
}

/* Every exit from the gate. Each one records the visit, so the overlay never
   blocks a second load regardless of which was chosen. Modes:
   skip · guide · tour · own (demo → Settings) · go:<period> (a shortcut tile) */
function dcGateChoose(mode) {
  try { localStorage.setItem('dc_guide_seen', String(CG_GUIDE_VERSION)); } catch (e) {}
  const gate = document.getElementById('cgWelcomeGate');
  if (gate) gate.style.display = 'none';
  document.body.classList.remove('cg-gate-open');
  _dcGateDemoStop();
  if (mode === 'skip') return;
  if (mode === 'own') { if (typeof openSourceModal === 'function') openSourceModal(); return; }
  if (mode.indexOf('go:') === 0) {
    document.querySelector('#periodNav button[data-period="' + mode.slice(3) + '"]')?.click();
    return;
  }

  document.querySelector('#periodNav button[data-period="chartsguide"]')?.click();
  // Let the guide paint before the tour starts driving the nav around
  if (mode === 'tour') setTimeout(() => dcStartChartsGuideTour(), 450);
}

/* Re-open the gate on demand (from the guide hero) — does not touch dc_guide_seen. */
function dcReplayWelcomeGate() {
  const gate = document.getElementById('cgWelcomeGate');
  if (!gate) return;
  _dcGateOpen(gate);
}

